/* 自動生成（tools/flash_to_js.py）。元＝career-master/research/gijutsushi-cards/flash/flash.json */
const NJ_PLAN_DATA = [{"f": "二次:計画", "q": "【第六次環境基本計画｜時期】第六次環境基本計画が閣議決定されたのはいつ（何年何月）？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2024年5月（5月21日）。第五次ではなくこの第六次が最新版である<br><br><b>解説</b>　2024年5月21日に閣議決定された環境基本計画で、根拠は環境基本法第15条である<br><br><b>答案に書くなら</b>　本計画は2024年5月に閣議決定された第六次環境基本計画であり、最新版に基づいて課題を整理する。<br><br><b>関連</b>　第五次はR2の題材で別の計画。目的規定は第1条で、策定根拠の第15条と混同しない。<br><br><b>答案での使い方</b>　書き出しで最新版を明示する。第五次(R2題材)と取り違えない<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223504.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜目標】第六次環境基本計画が掲げる2030年度の温室効果ガス削減目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2013年度比46%削減（さらに50%の高みに向け挑戦を続ける）<br><br><b>解説</b>　基準年の2013年度と比べた2030年度の削減率で、日本全体の温室効果ガスが対象である<br><br><b>答案に書くなら</b>　環境の観点から、2030年度に2013年度比46%削減という高い目標の達成に向け、対策の加速が課題である。<br><br><b>関連</b>　2035年度60%・2040年度73%は別計画（地球温暖化対策計画）の数字で、本計画は2030年度46%とCN2050のみ明記する。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 課題の大きさの根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223504.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜目標】第六次環境基本計画が掲げる30by30目標とは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2030年までに陸と海の30%以上を保全する目標。ネイチャーポジティブ実現の手段<br><br><b>解説</b>　30by30は、2030年までに陸と海の30%以上を保全地域やOECM（保護地域以外で生物多様性保全に資する地域）にする国際目標。ネイチャーポジティブの実現手段と位置づけられる<br><br><b>答案に書くなら</b>　生態系の保全の観点から、30by30の達成に向け保全地域とOECMの拡大を進めることが解決策である。<br><br><b>関連</b>　ネイチャーポジティブは損失を止めて反転させる考え方で、30by30はその手段である。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 生物多様性の解決策の到達点に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223504.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜目標】世界の年平均気温は産業革命前より何℃上昇した（2023年）？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　1.45℃上昇（2023年）。気候危機の背景として示されている<br><br><b>解説</b>　産業革命前を基準とした世界の年平均気温の上昇幅で、2023年に1.45℃と示されている。気候危機を課題の背景として説明するときの数字になる<br><br><b>答案に書くなら</b>　世界の年平均気温は2023年に産業革命前より1.45℃上昇しており、気候危機への対応が急務であることが課題の背景である。<br><br><b>関連</b>　パリ協定の1.5℃目標に近い水準だが、1.45℃は2023年時点の値であり将来目標ではない。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 冒頭で課題の背景を示す数字に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223504.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜柱】「環境・経済・社会の統合的向上」を実践する場と位置づけられた重点戦略は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　地域づくり。地域循環共生圏で地域脱炭素とネイチャーポジティブを同時に解決する<br><br><b>解説</b>　重点戦略の一つ「環境・経済・社会の統合的向上の実践・実装の場としての地域づくり」で、地域循環共生圏が中核の考え方。地域ごとに自然資本・経済・社会の課題が異なるため、地域単位の実践が要る<br><br><b>答案に書くなら</b>　地域の観点から、地域循環共生圏により地域脱炭素とネイチャーポジティブを同時に解決することが解決策である。<br><br><b>関連</b>　地域循環共生圏は自立・分散型の地域づくりで、近隣地域と資源を補完し合う。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 解決策の方向を国の言葉で言うときに<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223505.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜柱】「新たな成長」を導く重点戦略の中身は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　持続可能な生産と消費を実現するグリーンな経済システム。自然資本への投資拡大と環境価値の内部化<br><br><b>解説</b>　「新たな成長」は経済を高付加価値化する考え方で、自然資本への投資を拡大し、環境という非市場的価値を市場的価値に取り込む（内部化する）ことで実現を図る<br><br><b>答案に書くなら</b>　経済の観点から、自然資本への投資拡大と環境価値の内部化により、グリーンな経済システムを構築することが解決策である。<br><br><b>関連</b>　重点戦略は6つあり、他に国土・地域・暮らし・科学技術・国際がある。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 経済面の解決策の方向づけに<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223505.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜課題】第六次環境基本計画を根拠に、自然資本投資の課題を『制度・政策』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　環境価値を市場価値に内部化するため、成長志向型CP構想の実行と税制のグリーン化を、競争力を損なわず設計する必要がある<br><br><b>解説</b>　環境価値のような非市場的価値は価格に反映されにくく、市場で評価されない。成長志向型カーボンプライシングや税制のグリーン化は、その内部化の手段である<br><br><b>答案に書くなら</b>　制度・政策の観点から、環境価値の内部化に向け成長志向型カーボンプライシング構想と税制のグリーン化を、競争力を損なわずに設計する必要があることが課題である。<br><br><b>関連</b>　解決策側の用語は成長志向型カーボンプライシング構想（GX投資を先行させ炭素価格負担を段階導入）である。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 制度・政策の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223505.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜課題】自然資本投資の課題を『経済・資金』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　サステナブルファイナンスと地域金融のESG化による資金動員が不可欠だが、評価指標が未成熟で資金が循環しにくい<br><br><b>解説</b>　自然資本投資には民間資金の動員が欠かせないが、環境価値の評価指標が未成熟だと投資判断がしにくく、資金が自然資本に回りにくい<br><br><b>答案に書くなら</b>　経済・資金の観点から、サステナブルファイナンスと地域金融のESG化による資金動員が不可欠だが、評価指標が未成熟で資金が循環しにくいことが課題である。<br><br><b>関連</b>　サステナブルファイナンスは環境・社会課題の解決に資する事業へ資金を誘導する枠組みである。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 経済・資金の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223505.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜課題】計画の実践・実装の課題を『人材・担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　環境人材の育成や公正な移行への人的資本投資、地域循環共生圏を支える中間支援組織の担い手不足が制約になっている<br><br><b>解説</b>　計画を地域で実行するには、環境分野の専門人材と、主体間を橋渡しする中間支援組織が要る。担い手が不足すると実践・実装が進まない<br><br><b>答案に書くなら</b>　人材・担い手の観点から、環境人材の育成や公正な移行への人的資本投資と、中間支援組織の担い手不足が実践・実装の制約となっていることが課題である。<br><br><b>関連</b>　公正な移行（ジャスト・トランジション）は、転換で影響を受ける産業・労働者・地域に不利益が偏らないようにする考え方である。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 人材・担い手の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223505.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜解決策】地域ごとに異なる課題への解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　地域循環共生圏の形成で、地域の自然資本を活かし近隣と資源を補完し合う自立・分散型の地域づくりを進める<br><br><b>解説</b>　地域循環共生圏は、地域の自然資本を最大限活用し、近隣地域と資源を補完し合う自立・分散型の地域づくり。地域ごとに課題が違う問題への解決策として使える専門用語である<br><br><b>答案に書くなら</b>　地域の観点から、地域循環共生圏を形成し、地域の自然資本を活かして近隣と資源を補完し合う自立・分散型の地域づくりを進めることが解決策である。<br><br><b>関連</b>　地域固有の合意形成の例として水俣の「もやい直し」や福島の「未来志向」が挙げられる。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 地域系の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223505.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜解決策】環境価値の内部化に向けた解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　成長志向型カーボンプライシング構想で、先行投資を促しつつ炭素価格負担を段階的に導入し、脱炭素と競争力を両立する<br><br><b>解説</b>　成長志向型カーボンプライシング構想は、GX投資を先行させつつ将来の炭素価格負担を段階的に導入する構想。化石燃料依存の低減と産業競争力強化の両立を狙う<br><br><b>答案に書くなら</b>　制度の観点から、成長志向型カーボンプライシング構想により、先行投資を促しつつ炭素価格負担を段階的に導入し、脱炭素と競争力を両立することが解決策である。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 制度面の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223505.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜リスク】30by30を急ぐ地域共生型再エネ拡大で生じるリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　リスク：景観・生態系への新たな環境負荷。対策：洋上・陸上風力の環境配慮の制度検討を計画の初期段階から組み込む<br><br><b>解説</b>　再エネ・洋上風力の導入拡大は脱炭素に資する一方、景観や生態系に新たな負荷を与える可能性があり、脱炭素と自然共生のトレードオフになる<br><br><b>答案に書くなら</b>　リスクとして、再エネ導入拡大が景観・生態系に新たな環境負荷を生むおそれがあるため、洋上・陸上風力の環境配慮の制度検討を計画の初期段階から組み込む必要がある。<br><br><b>関連</b>　トレードオフを避けるには、導入計画の初期段階での環境配慮の組み込みが鍵である。<br><br><b>答案での使い方</b>　必須Ⅰ(3) 脱炭素と自然共生のトレードオフに<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223505.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜注意】2035年度60%・2040年度73%削減は第六次環境基本計画の数字か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　違う。地球温暖化対策計画（2025年2月）の数字。第六次が明記するのは2030年度46%とCN2050<br><br><b>解説</b>　2035年度60%・2040年度73%削減（2013年度比）は2025年2月閣議決定の地球温暖化対策計画の数字。第六次環境基本計画の本体・概要には明記されていない<br><br><b>答案に書くなら</b>　本計画が明記する削減目標は2030年度46%とカーボンニュートラル2050であり、2035年度60%・2040年度73%は地球温暖化対策計画の数字である。<br><br><b>関連</b>　連携する第五次循環型社会形成推進基本計画や生物多様性国家戦略2023-2030も別個の計画で、本計画の内容として引用しない。<br><br><b>答案での使い方</b>　両計画の数字を混同すると減点。書き分ける<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223504.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜時期】地球温暖化対策計画（現行）が閣議決定されたのはいつ（何年何月）？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2025年2月（2021年10月の前計画を改定）。2035・2040年度目標はこの改定で新設<br><br><b>解説</b>　地球温暖化対策推進法第8条第1項に基づく計画で、2021年10月の前計画を2025年2月18日に改定した。前計画は2030年度目標のみで、2035・2040年度目標が新設された<br><br><b>答案に書くなら</b>　本計画は2025年2月に改定された地球温暖化対策計画であり、2035・2040年度目標を含む最新版に基づいて課題を整理する。<br><br><b>関連</b>　根拠法は環境基本法第15条ではなく温対法第8条第1項で、第六次環境基本計画とは別の計画である。<br><br><b>答案での使い方</b>　書き出しで最新版を明示。旧計画(2030年度のみ)と区別<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜目標】地球温暖化対策計画の2030・2035・2040年度の削減目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2013年度比で2030年度46%（7.6億t）、2035年度60%（5.7億t）、2040年度73%（3.8億t）<br><br><b>解説</b>　削減率の基準は2013年度の排出・吸収量。2030年度は46%減（さらに50%の高みに挑戦）、2035年度は60%減、2040年度は73%減と段階的に深掘りし、2050年にネットゼロを目指す<br><br><b>答案に書くなら</b>　環境の観点から、2030年度46%、2035年度60%、2040年度73%という段階的な削減目標の達成に向け、対策の加速が課題である。<br><br><b>関連</b>　2030年度目標46%は旧計画から不変で、2035・2040年度が新設である。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 課題の大きさと(2)の到達点の根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜目標】2024年度の温室効果ガス排出・吸収量は何億t（2013年度比）？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　9.94億t（2013年度比28.7%減）。初めて10億tを下回った（2026年4月発表）<br><br><b>解説</b>　2024年度の排出・吸収量は9.94億トンで、2013年度以降の最低値。初めて10億トンを下回った。2030年度目標の7.6億トンまでは依然として差がある<br><br><b>答案に書くなら</b>　環境の観点から、2024年度の排出・吸収量は9.94億トン（2013年度比28.7%減）であり、2030年度目標の7.6億トンまでなお大きな差がある。<br><br><b>関連</b>　2022年度は10.8億トン（2013年度比22.9%減）、2023年度確報値は10.17億トン（27.1%減）である。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 現状と2030年度目標7.6億tとの差を示す<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜目標】家庭部門のエネルギー起源CO2の2030年度目安は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　71百万t（2013年度209百万tから66%減）<br><br><b>解説</b>　家庭部門のエネルギー起源CO2は、2013年度の209百万tから2030年度に71百万t（66%減）とする目安。全体目標の46%減より大幅に深い削減率である。R8 Ⅰ-2の題材でもある<br><br><b>答案に書くなら</b>　環境の観点から、家庭部門は2013年度209百万tから2030年度71百万t（66%減）へ、全体目標より深い削減が求められることが課題である。<br><br><b>関連</b>　2040年度は約40〜60百万t（71〜81%減）の目安で、運輸部門の2030年度目安は146百万t（35%減）である。<br><br><b>答案での使い方</b>　R8 Ⅰ-2の題材。全体目標46%と取り違えない<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜柱】地球温暖化対策計画の4本の柱は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　エネルギー転換／産業・業務・運輸等／地域・くらし／横断的取組<br><br><b>解説</b>　計画の柱はエネルギー転換、産業・業務・運輸等、地域・くらし、横断的取組の4つ。エネルギー転換は再エネ・原子力の最大活用、LNG火力の脱炭素化、非効率石炭のフェードアウトなどを含む<br><br><b>答案に書くなら</b>　解決策として、エネルギー転換、産業・業務・運輸等、地域・くらし、横断的取組の4分野で対策を一体的に進めることが必要である。<br><br><b>関連</b>　地域・くらしの柱は脱炭素先行地域100以上の創出や省エネ住宅、食品ロス削減を含む。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 解決策の分野を国の分類で言う<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜柱】横断的取組に位置づく施策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　成長志向型カーボンプライシング、循環経済移行、吸収源確保、国際貢献<br><br><b>解説</b>　横断的取組は、特定の部門に限らず全体に効く施策群である。成長志向型カーボンプライシングで投資を促し、循環経済で資源を循環させ、吸収源で排出を相殺し、国際貢献で世界の削減にも寄与する<br><br><b>答案に書くなら</b>　解決策として、成長志向型カーボンプライシング、循環経済移行、吸収源確保、国際貢献を部門横断で進めることが有効である。<br><br><b>関連</b>　吸収源対策は森林やブルーカーボンで、2040年度は約84百万t-CO2の吸収を見込む。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 横断的な解決策を挙げるときに<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜課題】温暖化対策計画を根拠に、脱炭素化が難しい分野の課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　水素・アンモニア・CCUS等による火力の脱炭素化や、航空・海運の次世代燃料の実用化に技術的ブレイクスルーが必要<br><br><b>解説</b>　火力や航空・海運は、電化や再エネだけでは脱炭素が難しい分野。水素・アンモニアやCCUS（CO2の回収・利用・貯留）、次世代燃料の実用化に技術的な突破が要る<br><br><b>答案に書くなら</b>　技術の観点から、水素・アンモニア・CCUS等による火力の脱炭素化や航空・海運の次世代燃料の実用化に、技術的ブレイクスルーが必要であることが課題である。<br><br><b>関連</b>　CCUSは発電所・工場等から排出されるCO2を分離・回収し、利用または地中に貯留する技術である。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜課題】脱炭素先行地域100以上の創出の課題を『人材・担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　計画策定・実施を担う自治体職員や事業者側の体制・人材の確保が課題<br><br><b>解説</b>　脱炭素先行地域は2030年度までに100以上の創出を目標とする。数が多いほど、計画の策定・実施を担う自治体職員や事業者側の体制が足りなくなりやすい<br><br><b>答案に書くなら</b>　人材・担い手の観点から、脱炭素先行地域の創出に向け、計画策定・実施を担う自治体職員や事業者側の体制・人材の確保が課題である。<br><br><b>関連</b>　小規模自治体では都道府県・連携中枢都市等との共同・連携策定が対策になる。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 人材・担い手の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜課題】2030年度目標とネットゼロを結ぶ道筋の課題を『経済・資金』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　中長期の予見可能性を高め、GX投資を加速する資金動員が課題<br><br><b>解説</b>　2030年度目標と2050年ネットゼロを直線的につなぐ経路には長期の巨額投資が必要。見通しが不透明だと企業は投資をためらうため、予見可能性の確保が資金動員の前提になる<br><br><b>答案に書くなら</b>　経済・資金の観点から、中長期の予見可能性を高め、GX投資を加速する資金動員が課題である。<br><br><b>関連</b>　制度面の対応が成長志向型カーボンプライシングで、エネルギー基本計画やGX2040ビジョンと一体的に運用する。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 経済・資金の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜解決策】火力発電の脱炭素化の解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　水素・アンモニア混焼やCCUSで火力を脱炭素化し、非効率石炭火力は計画的にフェードアウトする<br><br><b>解説</b>　火力の脱炭素化は、水素・アンモニア混焼やCCUSで排出を減らす手法。非効率石炭火力のフェードアウトは、発電効率の低い石炭火力を計画的に休廃止する対策である<br><br><b>答案に書くなら</b>　解決策として、水素・アンモニア混焼やCCUSで火力を脱炭素化し、非効率石炭火力を計画的にフェードアウトすることが有効である。<br><br><b>関連</b>　LNG火力はトランジション手段として位置づけられ、再エネ・原子力の最大活用と並行する。<br><br><b>答案での使い方</b>　必須Ⅰ(2) エネルギー転換の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜解決策】地域の脱炭素化の解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　脱炭素先行地域を2030年度までに100以上創出し、民生部門の電力CO2実質ゼロのモデルを全国へ広げる<br><br><b>解説</b>　脱炭素先行地域は、民生部門の電力消費に伴うCO2排出の実質ゼロ等を2030年度までに目指す先行モデルの地域。地域特性に応じた成功例を示し、横展開で全国の脱炭素化を進める<br><br><b>答案に書くなら</b>　解決策として、脱炭素先行地域を2030年度までに100以上創出し、民生部門の電力CO2実質ゼロのモデルを全国に広げることが有効である。<br><br><b>関連</b>　リスクは体制不足の小規模自治体で計画が形だけになることで、広域での人材支援が対策になる。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 地域・くらしの解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜リスク】石炭火力のフェードアウトを急ぐリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　リスク：代替電源の整備が追いつかず需給バランスに影響。対策：LNG火力を移行手段に使い、再エネ・原子力の最大活用を並行する<br><br><b>解説</b>　石炭火力を急に減らすと、代替電源が間に合わずに電力の需給バランス（供給の安定性）を崩すおそれがある。移行期間に使える電源を確保することが対策の骨格になる<br><br><b>答案に書くなら</b>　リスクとして、石炭火力のフェードアウトで電力の需給バランスに影響が出るおそれがあり、LNG火力を移行手段に用い、再エネ・原子力の最大活用を並行して進める必要がある。<br><br><b>関連</b>　JCM等の海外クレジット依存でも国内削減が希薄化するリスクがあり、国内削減を基本にフォローアップする。<br><br><b>答案での使い方</b>　必須Ⅰ(3) エネルギー転換のリスクと対策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜注意】2035・2040年度の部門別CO2数値は確定値か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　確定値ではない。複数シナリオ分析に基づく幅のある「目安」<br><br><b>解説</b>　2035・2040年度のエネルギー起源CO2の部門別数値は、複数シナリオの分析に基づく幅のある見通しで、確定した配分ではない。技術進展が遅れると目標と実績のギャップが広がり得る<br><br><b>答案に書くなら</b>　2035・2040年度の部門別数値は複数シナリオに基づく「目安」であり、毎年の進捗点検で対策を柔軟に見直す必要がある。<br><br><b>関連</b>　進捗点検は毎年1回、地球温暖化対策推進本部でフォローアップを行う。<br><br><b>答案での使い方</b>　答案で確定値のように書くと減点。「目安」と書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜時期】GX2040ビジョンと第7次エネルギー基本計画の閣議決定はいつ？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　いずれも2025年2月18日。別の文書で、GX2040は2023年7月の戦略の改訂版<br><br><b>解説</b>　GX2040ビジョンは脱炭素成長型経済構造移行推進法（GX推進法）に基づく戦略の改訂版、第7次エネルギー基本計画はエネルギー政策基本法第12条第1項に基づく計画で、根拠法が異なる別の文書である<br><br><b>答案に書くなら</b>　GX2040ビジョンと第7次エネルギー基本計画は2025年2月18日に閣議決定された最新版であり、これに基づいて課題を整理する。<br><br><b>関連</b>　GX2040ビジョンは2023年7月の脱炭素成長型経済構造移行推進戦略の改訂版である。<br><br><b>答案での使い方</b>　書き出しで最新版を明示。2文書を混ぜない<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜時期】排出量取引制度が本格稼働（義務化）する年度は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2026年度。2023年度開始の自主参加型GXリーグとは別<br><br><b>解説</b>　排出量取引制度は2026年度から本格稼働し、一定の排出規模以上の企業の参加を業種等を問わず義務化する。2023年度開始のGXリーグは自主参加型の第1段階で、本格稼働後は義務の制度に変わる<br><br><b>答案に書くなら</b>　制度の観点から、排出量取引制度は2026年度に本格稼働し、一定規模以上の排出企業に参加が義務化される。<br><br><b>関連</b>　義務化にはGX推進法改正案の国会提出が伴う。自主参加のGXリーグと時系列で混同しない。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰで「義務化済み」と書く根拠に<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜目標】2040年度の電源構成（目安）は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　再エネ4〜5割程度、火力3〜4割程度、原子力2割程度。2022年度は再エネ21.8%、火力72.6%<br><br><b>解説</b>　2040年度の電源構成は目安で、2022年度は火力が7割超と偏っていた。再エネを大きく伸ばし火力を減らす必要があり、現状との差が課題の大きさを示す<br><br><b>答案に書くなら</b>　環境・エネルギーの観点から、2022年度の再エネ21.8%・火力72.6%に対し、2040年度は再エネ4〜5割程度、火力3〜4割程度、原子力2割程度を目指す必要がある。<br><br><b>関連</b>　2040年度の数値は暫定値で確定した目標ではない。エネルギー自給率は3〜4割程度の見通し（2022年度は12.6%）である。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 現状との差で課題の大きさを示す<br><br>【出典】<a href=\"https://www.enecho.meti.go.jp/category/others/basic_plan/pdf/20250218_03.pdf\" target=\"_blank\" rel=\"noopener\">資源エネルギー庁（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜目標】GX経済移行債の規模と、呼び込む官民投資の規模は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　10年間で20兆円規模の先行投資支援により、150兆円規模の官民投資を呼び込む<br><br><b>解説</b>　GX経済移行債は先行投資支援の財源となる国債。国が先に投資を支えることで、民間の投資判断を後押しし、規模の大きい官民投資を引き出す<br><br><b>答案に書くなら</b>　資金面の解決策として、GX経済移行債による10年間で20兆円規模の先行投資支援で、150兆円規模の官民投資を呼び込むことが有効である。<br><br><b>関連</b>　支援の配分は、炭素価格の予見性を確保しつつ多排出産業の構造転換へ適切に行う必要がある。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 資金面の解決策の規模感に<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜柱】GX2040ビジョンの柱のうち、カーボンプライシングの柱は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　成長志向型カーボンプライシング構想。排出量取引制度の本格稼働と化石燃料賦課金（2028年度）で炭素価格を形成<br><br><b>解説</b>　カーボンプライシングは炭素に価格をつけて排出削減とGX投資を促す仕組み。この構想は排出量取引制度と化石燃料賦課金を組み合わせて、炭素価格を段階的に形成する<br><br><b>答案に書くなら</b>　制度の観点から、成長志向型カーボンプライシング構想により、排出量取引制度と化石燃料賦課金で炭素価格を段階的に形成することが解決策である。<br><br><b>関連</b>　化石燃料賦課金は化石燃料の輸入事業者等に課す賦課金で、2028年度から導入予定である。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 制度面の解決策の国の言葉に<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜柱】GX2040ビジョンの「GX産業立地」の考え方は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　脱炭素電源を見据えた産業集積の加速と、地域に利益が及ぶ地域GXを進める<br><br><b>解説</b>　GX産業立地は、脱炭素電源が使える場所に産業を集積させる考え方。電源の近くに企業を集めれば競争力と脱炭素を両立でき、利益を地域に及ぼす地域GXが合意形成の鍵になる<br><br><b>答案に書くなら</b>　地域の観点から、脱炭素電源を見据えた産業集積を進めつつ、利益が地域に及ぶ地域GXを進めることが解決策である。<br><br><b>関連</b>　データセンター立地では電力と通信のインフラ整備を効率的に連携させるワット・ビット連携の考え方もある。<br><br><b>答案での使い方</b>　必須Ⅰ・Ⅲ 地域系の解決策の方向づけに<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜課題】再エネ主力電源化（2040年度4〜5割）の課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　出力変動を調整する系統整備・蓄電池・次世代革新炉など複数技術の同時確立が必要で、単一技術では対応できない<br><br><b>解説</b>　再エネは天候で出力が変動するため、主力電源にするには需給を調整する手段が要る。系統整備、蓄電池、次世代革新炉などの複数技術がそろって初めて安定供給と両立できる<br><br><b>答案に書くなら</b>　技術の観点から、再エネ主力電源化には、出力変動に対応する系統整備・蓄電池・次世代革新炉など複数技術を同時に確立する必要があることが課題である。<br><br><b>関連</b>　次世代革新炉は安全性を高めた新型の原子炉技術で、原子力の活用と並行して検討される。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜課題】排出量取引制度の義務化の課題を『制度』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　公平性確保のため、業種別の無償割当ルールと価格安定化措置（上限・下限価格）の制度設計が課題<br><br><b>解説</b>　排出量取引は事業者に排出枠を割り当てる仕組みで、無償割当てのルールが不公平だと産業間の反発を招く。価格が乱高下すると投資計画も立てにくいため、上限・下限価格で安定させる<br><br><b>答案に書くなら</b>　制度の観点から、排出量取引制度の義務化にあたり、公平性確保のため業種別の無償割当ルールと上限・下限価格などの価格安定化措置の制度設計が課題である。<br><br><b>関連</b>　運営やGX投資へのファイナンス支援はGX推進機構（2024年7月業務開始）が担う。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 制度の観点の課題に<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜課題】中堅・中小企業のGX対応の課題を『人材・担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　大企業に比べ支援機関・資金・人材が不足し、排出量の見える化や設備高度化の対応力の差が広がりやすい<br><br><b>解説</b>　排出量の見える化や設備の高度化には、専門の支援機関、資金、人材が必要。大企業は自力で対応できるが、中堅・中小企業は不足しやすく、対応力の差が広がる<br><br><b>答案に書くなら</b>　人材・担い手の観点から、中堅・中小企業は大企業に比べ支援機関・資金・人材が不足し、排出量の見える化や設備高度化の対応力の差が広がりやすいことが課題である。<br><br><b>関連</b>　GX産業構造の柱では、GX価値の見える化や企業の成長投資・カーブアウトで産業競争力を両立する。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 人材・担い手の観点の課題に<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜解決策】排出量取引制度による解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　排出枠の無償割当てと取引で炭素価格を形成し、多排出産業の投資と構造転換を促す<br><br><b>解説</b>　排出量取引制度（GX-ETS）は、排出枠を割り当てて取引させることで炭素に価格をつける制度。排出に費用がかかるようになるため、多排出産業の投資や構造転換が促される<br><br><b>答案に書くなら</b>　制度面の解決策として、排出量取引制度で排出枠の無償割当てと取引により炭素価格を形成し、多排出産業の投資と構造転換を促すことが有効である。<br><br><b>関連</b>　リスクはコスト増による競争力低下と海外移転（カーボンリーケージ）で、対策は業種特性への配慮である。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 制度面の解決策に<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜解決策】再エネ主力電源化の解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　S+3Eを前提に、系統整備・蓄電池・次世代革新炉・火力の脱炭素化を並行して進める<br><br><b>解説</b>　S+3Eは、安全性を前提にエネルギー安定供給・経済効率性・環境適合の3つを同時に達成する基本視点。再エネだけに偏らず、系統整備や蓄電池、原子力、火力の脱炭素化を並行して進める根拠になる<br><br><b>答案に書くなら</b>　エネルギーの観点から、S+3Eを前提に、系統整備・蓄電池・次世代革新炉・火力の脱炭素化を並行して再エネ主力電源化を進めることが解決策である。<br><br><b>関連</b>　リスクは出力変動の増大による周波数・系統安定性の低下で、火力の調整力維持が対策になる。<br><br><b>答案での使い方</b>　必須Ⅰ(2) エネルギー面の解決策に<br><br>【出典】<a href=\"https://www.enecho.meti.go.jp/category/others/basic_plan/pdf/20250218_03.pdf\" target=\"_blank\" rel=\"noopener\">資源エネルギー庁（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜解決策】データセンター立地等の合意形成の解決策を、専門用語で言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　地域GX（地域裨益型・地域共生型）で、脱炭素電源の利益を地域に還元し、自治体と連携して地方創生につなげる<br><br><b>解説</b>　データセンターなどの立地は地域に雇用や税収をもたらす一方、電力需要の急増や住民の理解が課題になる。地域GXは、脱炭素電源の整備の利益を地域に還元し、自治体と連携して進めることで合意を得る考え方である<br><br><b>答案に書くなら</b>　地域の観点から、地域GXにより脱炭素電源の利益を地域に還元し、自治体と連携して地方創生につなげることが解決策である。<br><br><b>関連</b>　企業を誘致する自治体への支援と、住民への裨益を両立させることが課題とされる。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 地域系の解決策に<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜リスク】排出量取引制度の義務化で生じるリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　リスク：多排出産業の競争力低下と海外移転（カーボンリーケージ）。対策：政府指針による業種配慮の無償割当てと移行期の投資余力確保<br><br><b>解説</b>　義務化で炭素のコストが上がると、鉄鋼・化学などの多排出産業は国際競争で不利になり、規制の緩い国へ製造拠点が移る（カーボンリーケージ）おそれがある。業種ごとの事情を制度に反映することが対策になる<br><br><b>答案に書くなら</b>　リスクとして、多排出産業の競争力低下とカーボンリーケージが懸念されるため、政府指針で業種特性に配慮した無償割当てを行い、移行期の投資余力を確保する必要がある。<br><br><b>関連</b>　排出量取引や賦課金のコストは電気料金・製品価格に転嫁され、中小企業や家庭の負担増につながるおそれもある。<br><br><b>答案での使い方</b>　必須Ⅰ(3) 制度導入のリスクと対策に<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜注意】2035年度60%・2040年度73%削減と、R8 Ⅰ-2の家庭部門66%の違いは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　60%・73%は全体（2013年度比）、66%は家庭部門（2030年度）。母集団が違う<br><br><b>解説</b>　60%・73%は日本全体の温室効果ガス排出量の削減率（2013年度比、2035・2040年度）で、家庭部門の66%は地球温暖化対策計画の2030年度の目安。同じ数字でも、対象（母集団）と年度が違う<br><br><b>答案に書くなら</b>　2035年度60%・2040年度73%は全体の削減目標、家庭部門66%は地球温暖化対策計画の2030年度の目安であり、対象が異なる。<br><br><b>関連</b>　家庭部門の2040年度目安は71〜81%減で、いずれも2013年度が基準である。<br><br><b>答案での使い方</b>　数字は母集団とセットで書く。取り違えは減点<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜時期】気候変動適応計画の閣議決定と一部変更はいつ（何年何月）？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2021年10月に閣議決定、2023年5月に一部変更。一部変更で熱中症対策実行計画が第4章に追加<br><br><b>解説</b>　当初の計画は2021年10月22日に閣議決定され、2023年5月30日の一部変更で熱中症対策実行計画が第4章に追加された。実行計画は2023年4月改正の気候変動適応法第16条第1項に基づく<br><br><b>答案に書くなら</b>　本計画は2021年10月に閣議決定され、2023年5月の一部変更で熱中症対策実行計画が第4章に加わった気候変動適応計画である。<br><br><b>関連</b>　計画変更の根拠は第8条第1項、実行計画の根拠は第16条第1項で、条文番号を混同しない。<br><br><b>答案での使い方</b>　書き出しで版を明示。熱中症対策は第4章の内容として書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜時期】気候変動適応計画の次の改定の見通しは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2026年2月の第3次影響評価報告書を受け、2026年度内に改定予定。骨子は2026年6月<br><br><b>解説</b>　第3次気候変動影響評価報告書が2026年2月16日に公表され、気候変動適応計画の改定は2026年度に予定されている。影響評価はおおむね5年ごとに実施され、その結果を勘案して計画を改定する<br><br><b>答案に書くなら</b>　気候変動適応計画は、2026年2月公表の第3次影響評価報告書を受けて2026年度に改定が予定されている。<br><br><b>関連</b>　現行計画の計画期間はおおむね5年間で、「改定予定」と書き、現行版と区別する。<br><br><b>答案での使い方</b>　書き出しで「改定予定」と書き、旧版との取り違えを避ける<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜目標】熱中症対策実行計画の中期目標（2030年）は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　熱中症死亡者数（5年移動平均）を、令和4年概数の1,295名から半減<br><br><b>解説</b>　熱中症対策実行計画は、2030年までに熱中症による死亡者数（5年移動平均）を令和4年概数の1,295名から半減させる中期目標を置く。基準値と比べて到達度を測る数値目標になる<br><br><b>答案に書くなら</b>　解決策の到達点として、2030年までに熱中症死亡者数（5年移動平均）を令和4年概数1,295名から半減させることを目指す。<br><br><b>関連</b>　目標は死亡者数の5年移動平均で、単年の実績とは扱いが異なる。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 解決策の到達点の根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000136709.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜目標】熱中症死亡者数の実績は目標の基準値と比べてどうか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　令和5年1,651人、令和6年2,160人と、基準値1,295名を大きく上回り増加（人口動態統計確定数）<br><br><b>解説</b>　実績は目標と逆方向に動いており、人口動態統計（確定数）の熱中症死亡者数は令和5年に1,651人、令和6年に2,160人。基準値1,295名を大きく上回り、課題の大きさを示す<br><br><b>答案に書くなら</b>　健康の観点から、熱中症死亡者数は令和5年1,651人、令和6年2,160人と基準値1,295名を大きく上回って増加しており、対策の強化が課題である。<br><br><b>関連</b>　基準値の1,295名は令和4年の概数で、確定数ではなく概数の数字である。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 課題の大きさを示す数字に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000136709.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜柱】適応計画の7つの基本戦略は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　施策への組み込み、科学的知見、情報基盤、地域推進、事業者等の促進、国際貢献、関係機関連携<br><br><b>解説</b>　計画は、あらゆる施策に適応を組み込み、科学的知見に基づき、情報基盤を整備し、地域の実情に応じ、国民・事業者の理解を深め、途上国の能力向上に貢献し、関係機関が連携する、という7つの基本戦略を掲げる<br><br><b>答案に書くなら</b>　解決策として、あらゆる施策への適応の組み込みや科学的知見に基づく推進など、7つの基本戦略に沿って対策を進めることが有効である。<br><br><b>関連</b>　第2章の7分野（分野別施策）とは別物で、どちらも7個なので混同しない。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 解決策の方向を国の言葉で言う<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜柱】適応計画で「地域の実情に応じた適応」を進める仕組みは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　地域気候変動適応計画と地域適応センター。国立環境研究所が情報基盤A-PLATで支援<br><br><b>解説</b>　地域ごとに気候影響が違うため、地域単位で適応を進める。都道府県・市町村が地域気候変動適応計画を策定し、地域適応センターが影響情報の収集・提供を担い、国立環境研究所が情報基盤A-PLATで支える<br><br><b>答案に書くなら</b>　地域の観点から、地域気候変動適応計画と地域気候変動適応センターを軸に、A-PLATによる情報基盤で地域の実情に応じた適応を進めることが解決策である。<br><br><b>関連</b>　A-PLATは国内向け、AP-PLATはアジア太平洋の途上国向けの情報プラットフォームである。<br><br><b>答案での使い方</b>　必須Ⅰ・Ⅱ-2 地域施策の根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜課題】地域の適応推進の課題を『制度・政策』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　地域適応計画の策定が努力義務にとどまるため、地域適応センターの設置を含む制度的な推進力の確保が課題<br><br><b>解説</b>　地域気候変動適応計画の策定は都道府県・市町村の努力義務にとどまり、強制力が弱い。推進力を確保するには、地域適応センターの設置など制度面の枠組みが要る<br><br><b>答案に書くなら</b>　制度・政策の観点から、地域気候変動適応計画の策定が努力義務にとどまるため、地域適応センターの設置を含む制度的な推進力の確保が課題である。<br><br><b>関連</b>　国と地方が連携する場として、環境省が主導して気候変動適応広域協議会を組織する。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 制度・政策の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜課題】適応策の課題を『経済・資金』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　事業者の気候リスク対応投資を促し、適応ビジネスをどう資金面で後押しするかが課題<br><br><b>解説</b>　気候リスクが事業に与える影響への備えは、事業者の投資に頼る部分が大きい。適応ビジネスは、気候変動影響を事業機会として捉え、他者の適応を支援する製品・サービスを展開する事業活動で、これを資金面でどう支えるかが課題になる<br><br><b>答案に書くなら</b>　経済・資金の観点から、事業者の気候リスク対応投資を促し、適応ビジネスを資金面でどう後押しするかが課題である。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 経済・資金の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜課題】適応策の課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　農業の高温耐性品種の開発・普及と、流域治水やグリーンインフラによるハード・ソフト一体の防災技術の高度化が課題<br><br><b>解説</b>　気候の高温化で作物の品質低下や水害の激甚化が進む。高温耐性品種は耐暑性を高めた品種で、流域治水やグリーンインフラは自然の機能も使う防災手法である。複数の技術を高度化する必要がある<br><br><b>答案に書くなら</b>　技術の観点から、農業の高温耐性品種の開発・普及と、流域治水やグリーンインフラによるハード・ソフト一体の防災技術の高度化が課題である。<br><br><b>関連</b>　高温耐性品種はコメや果樹で導入が進む。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜解決策】水害リスクの解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　流域治水で、河川整備に加え流域全体の関係者が協働し、ハード・ソフト一体で水害リスクを下げる<br><br><b>解説</b>　流域治水は、河川整備だけでなく流域全体のあらゆる関係者が協働する治水の考え方。ハード（堤防等）とソフト（情報・避難等）を一体で進め、水害リスクを低減する<br><br><b>答案に書くなら</b>　解決策として、流域治水により、河川整備に加え流域全体の関係者が協働し、ハード・ソフト一体で水害リスクを下げることが有効である。<br><br><b>関連</b>　グリーンインフラは自然の機能を活用する社会資本整備の手法で、流域治水と組み合わせて使う。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 自然災害分野の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜解決策】熱中症の解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　熱中症警戒情報・特別警戒情報（WBGT基準）の発表と、指定暑熱避難施設の開放で、高齢者等の被害を防ぐ<br><br><b>解説</b>　熱中症警戒情報は、府県予報区内の1地点以上で日最高WBGTが33以上と予測される場合、特別警戒情報は都道府県内の全地点で35以上と予測される場合に発表される。特別警戒情報の発表時には指定暑熱避難施設が開放される<br><br><b>答案に書くなら</b>　解決策として、熱中症警戒情報・特別警戒情報の発表と指定暑熱避難施設の開放により、高齢者等の熱中症被害を防ぐことが有効である。<br><br><b>関連</b>　WBGT（暑さ指数）は気温・湿度・放射熱から算出する熱中症予防の指標である。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 健康分野の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000136709.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜リスク】流域治水の大規模投資で生じるリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　リスク：財政負担の拡大と生態系の分断など新たな環境影響。対策：グリーンインフラやNbSを組み合わせ環境配慮型の整備を優先する<br><br><b>解説</b>　堤防など大規模なハード整備は財政負担が重く、生態系の分断のような新たな環境影響も生む。グリーンインフラやNbS（自然を活用した解決策）を組み合わせれば環境への配慮と防災を両立しやすい<br><br><b>答案に書くなら</b>　リスクとして、流域治水の大規模投資は財政負担の拡大や生態系の分断を招くおそれがあり、グリーンインフラやNbSを組み合わせた環境配慮型の整備を優先する必要がある。<br><br><b>関連</b>　NbSは生態系の保全・再生など自然の機能を活用して社会課題を解決する手法である。<br><br><b>答案での使い方</b>　必須Ⅰ(3) ハード整備のリスクと対策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜リスク】地域適応計画が努力義務であることで生じるリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　リスク：小規模市町村で策定が進まず地域間の適応力が開く。対策：広域協議会を通じ都道府県が市町村を技術的・財政的に支援<br><br><b>解説</b>　努力義務のため、財政力や専門人材が乏しい小規模市町村で策定が進まず、自治体間の適応力の差が広がる。国と地方が連携する広域協議会を通じ、都道府県が市町村を技術的・財政的に支援する体制が対策になる<br><br><b>答案に書くなら</b>　リスクとして、努力義務のため小規模市町村で策定が進まず地域間の適応力が開くおそれがあり、気候変動適応広域協議会を通じて都道府県が市町村を技術的・財政的に支援する必要がある。<br><br><b>関連</b>　国立環境研究所も地方公共団体に技術的援助を行う。<br><br><b>答案での使い方</b>　必須Ⅰ(3)・Ⅱ-2 自治体支援の根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜注意】適応計画の「7分野」と「7つの基本戦略」は同じか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　別物。7分野は農林水産業・水環境・自然生態系・自然災害・健康・産業経済・国民生活の分野別施策<br><br><b>解説</b>　7分野は第2章の分野別施策で、農業・林業・水産業、水環境・水資源、自然生態系、自然災害・沿岸域、健康、産業・経済活動、国民生活・都市生活を指す。7つの基本戦略は施策への組み込みなど進め方の枠組みで、別の分類である<br><br><b>答案に書くなら</b>　分野別施策の7分野（農林水産業、水環境・水資源、自然生態系、自然災害・沿岸域、健康、産業・経済活動、国民生活・都市生活）と7つの基本戦略は別物であり、設問に応じて書き分ける。<br><br><b>関連</b>　気候変動適応計画は適応策の計画で、温室効果ガスの46%削減など緩和策の数値目標は地球温暖化対策計画のものである。<br><br><b>答案での使い方</b>　どちらも7個。分野を問う設問に戦略を書くと減点<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜時期】生物多様性国家戦略2023-2030が閣議決定されたのはいつ（何年何月）？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2023年3月（31日）。第六次環境基本計画（2024年5月）とは別の計画<br><br><b>解説</b>　2023年3月31日に閣議決定された戦略で、根拠は生物多様性基本法第12条第1項。環境基本計画を基本に策定するため協調関係にあるが、2024年5月閣議決定の第六次環境基本計画とは別の計画である<br><br><b>答案に書くなら</b>　本戦略は2023年3月に閣議決定された生物多様性国家戦略2023-2030であり、2030年のネイチャーポジティブ実現を目指す。<br><br><b>関連</b>　R6 Ⅰ-1とR8 Ⅰ-1で出題歴があり、「第六次」を付けて環境基本計画と取り違えない。<br><br><b>答案での使い方</b>　書き出しで版を明示。R6・R8 Ⅰ-1で出題<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜目標】30by30は国家戦略のどの目標に位置づく？その内容は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　行動目標1-1。2030年までに陸と海の30%以上を保護地域・OECMで保全<br><br><b>解説</b>　30by30は国家戦略全体の名称ではなく、行動目標1-1として位置づく国際目標の一つ。2030年までに陸と海それぞれの30%以上を保護地域とOECMで保全する<br><br><b>答案に書くなら</b>　生態系保全の観点から、行動目標1-1の30by30に基づき、2030年までに陸と海の30%以上を保護地域・OECMで保全することが解決策の到達点である。<br><br><b>関連</b>　ネイチャーポジティブは2030年に目指す状態で、30by30はその指標・手段である。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 解決策の到達点に。戦略そのものではない<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜目標】中間評価（2026年2月）の保護地域・OECM占有率は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　陸域21.0%（2025年時点）、海域13.3%（2021年以降変化なし）。目標は各30%<br><br><b>解説</b>　中間評価（2026年2月公表）では、保護地域とOECMが占める割合は陸域21.0%（2025年時点、2023年3月は20.5%）、海域13.3%（2021年以降変化なし）で、目標30%との差が大きい。特に海域は停滞している<br><br><b>答案に書くなら</b>　生態系保全の観点から、保護地域・OECMの割合は陸域21.0%、海域13.3%にとどまり、目標30%との差を埋めることが課題である。<br><br><b>関連</b>　陸域は20.5%から微増、海域は2021年以降変化がなく、海域の停滞が目立つ。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 目標との差で課題の大きさを示す<br><br>【出典】<a href=\"https://www.env.go.jp/content/000379260.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜柱】国家戦略の基本戦略1〜3は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　①生態系の健全性の回復、②自然を活用した社会課題の解決、③ネイチャーポジティブ経済の実現<br><br><b>解説</b>　基本戦略1は生息地の保全とネットワーク化、2は自然を活用した社会課題の解決、3は経済への自然資本の内部化に当たる。R6 Ⅰ-1ではこの3つの基本戦略が問われた<br><br><b>答案に書くなら</b>　解決策として、生態系の健全性の回復、自然を活用した社会課題の解決、ネイチャーポジティブ経済の実現の3つの基本戦略に沿って対策を進めることが有効である。<br><br><b>関連</b>　基本戦略は全部で5つで、4と5は暮らしの行動変容と基盤整備・国際連携である。<br><br><b>答案での使い方</b>　R6 Ⅰ-1の3戦略。解決策の方向を国の言葉で言う<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜柱】基本戦略4と5は？また目標の構成数は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　4：生活・消費活動での価値の認識と行動、5：基盤整備と国際連携。5基本戦略・15状態目標・25行動目標<br><br><b>解説</b>　基本戦略4は国民一人一人の行動変容を促す普及啓発・場づくり、5は生物多様性に係る取組を支える基盤整備（モニタリング基盤等）と国際連携である。戦略は全体で5つの基本戦略・15の状態目標・25の行動目標から成る<br><br><b>答案に書くなら</b>　解決策として、基本戦略4の生活・消費活動での価値の認識と行動、基本戦略5の基盤整備と国際連携を組み合わせて進めることが有効である。<br><br><b>関連</b>　R6 Ⅰ-1で問われた3戦略は全体の一部なので、設問の範囲を確認する。<br><br><b>答案での使い方</b>　3戦略は全体の一部。設問の範囲を確認する<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜課題】30by30達成の課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　OECMとして整理できる区域を見極める評価手法が未確立で、自然共生サイトの認定基準・モニタリング手法の標準化が課題<br><br><b>解説</b>　OECMは法的な保護地域以外で生物多様性の保全に資する管理が行われている区域。保護地域の拡張だけでは30%に届かないため、OECMを見極める評価手法と、自然共生サイトの認定基準・モニタリング手法の標準化が要る<br><br><b>答案に書くなら</b>　技術の観点から、OECMとして整理できる区域を見極める評価手法が未確立であり、自然共生サイトの認定基準・モニタリング手法の標準化が課題である。<br><br><b>関連</b>　自然共生サイトは日本版OECMで、国際データベース（Protected Planet）に登録される。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜課題】ネイチャーポジティブ経営の課題を『経済・資金』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　自然資本の損失の外部不経済を価格に反映する経済的手法が実証段階にとどまり、民間資金の誘導が不十分<br><br><b>解説</b>　自然資本の損失は外部不経済で、価格に反映されにくい。OECM認定地の環境価値の売買や税制優遇などの経済的手法が調査・実証段階にとどまるため、民間資金の誘導が不十分になる<br><br><b>答案に書くなら</b>　経済・資金の観点から、自然資本の損失の外部不経済を価格に反映する経済的手法が実証段階にとどまり、ネイチャーポジティブ経営への民間資金の誘導が不十分であることが課題である。<br><br><b>関連</b>　解決策の側ではTNFDによる情報開示とESG金融で自然資本を経済に内部化する。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 経済・資金の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜課題】里山・森林の保全の課題を『人材・担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　森林・農地・里山の管理の担い手が不足し、担い手の確保・育成と地域主体の取組を支えるインセンティブ設計が必要<br><br><b>解説</b>　森林・農地・里山の保全活動は、管理の担い手不足に直面している。担い手の確保・育成と、地域主体の取組を支えるインセンティブ設計がないと、保全活動を持続できない<br><br><b>答案に書くなら</b>　人材・担い手の観点から、森林・農地・里山の管理の担い手不足に対し、担い手の確保・育成と地域主体の取組を支えるインセンティブ設計が必要であることが課題である。<br><br><b>関連</b>　鳥獣との軋轢緩和など、農林水産業被害の防止と生態系保全の利害調整も地域の課題である。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 人材・担い手の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜解決策】民間の取組を生かす30by30の解決策を、専門用語で言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　自然共生サイト（日本版OECM）で、民間等が保全する区域を国が認定し、国際データベースに登録する<br><br><b>解説</b>　自然共生サイトは、民間等の取組で生物多様性が保全されている区域を国が認定する制度で、日本版OECMとして国際データベースに登録される。民間の土地を30by30の達成に取り込む手段になる<br><br><b>答案に書くなら</b>　解決策として、自然共生サイトにより民間等が保全する区域を国が認定し、日本版OECMとして国際データベースに登録して30by30の達成に寄与させることが有効である。<br><br><b>関連</b>　有志の企業・自治体が取組を促す生物多様性のための30by30アライアンスも枠組みとして使える。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 30by30の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜解決策】企業の自然資本対応の解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　TNFDによる自然関連リスク・機会の情報開示を促し、ESG金融と結び付けてネイチャーポジティブ経済へ移行する<br><br><b>解説</b>　TNFDは、企業・金融機関が自然資本・生物多様性に関するリスクと機会を評価して開示する国際的な民間主導の枠組み。開示を促してESG金融と結び付けると、資金がネイチャーポジティブ経営へ流れる<br><br><b>答案に書くなら</b>　経済の観点から、TNFDによる自然関連リスク・機会の情報開示を促し、ESG金融と結び付けてネイチャーポジティブ経済へ移行することが解決策である。<br><br><b>関連</b>　SBTs for Natureも企業が自然資本の科学に基づく目標を設定する民間主導の枠組みで、リスクは情報開示コストが中小企業に偏ることである。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 経済面の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜解決策】社会課題と自然保全を両立する解決策を、専門用語で言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　グリーンインフラや生態系ネットワークで、防災・気候変動対応と生物の移動・遺伝的多様性の維持を両立する<br><br><b>解説</b>　グリーンインフラは自然の多様な機能を活用する国土・都市・地域づくりの考え方、生態系ネットワークは森・里・川・海をつなぎ生物の移動や遺伝的多様性を支える国土構造である。防災や気候変動対応と保全を両立させる<br><br><b>答案に書くなら</b>　解決策として、グリーンインフラや生態系ネットワークにより、防災・気候変動対応と生物の移動・遺伝的多様性の維持を両立することが有効である。<br><br><b>関連</b>　ネットワークの連結性向上は、鳥獣の生息域拡大や外来種の拡散という負の波及効果を伴うため、個体群管理や防除の強化が要る。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 自然活用の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜リスク】30by30を急ぐリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　リスク：住民のなりわいとの調整不足で反発を招く。対策：自然共生サイト認定や保護地域拡張時に事前協議プロセスを制度化する<br><br><b>解説</b>　30by30で保護地域やOECMの指定を急ぐと、土地利用やなりわいとの調整が不十分なまま進み、地元の反発を招く。事前協議のプロセスを制度化しておけば、合意形成を図りながら拡張できる<br><br><b>答案に書くなら</b>　リスクとして、30by30の指定を急ぐと住民のなりわいとの調整不足で反発を招くおそれがあり、自然共生サイト認定や保護地域拡張の際に事前協議プロセスを制度化する必要がある。<br><br><b>関連</b>　中小企業へのTNFD対応コストの偏りも別のリスクで、国が段階的な導入支援や人材育成で後押しする。<br><br><b>答案での使い方</b>　必須Ⅰ(3) 合意形成のリスクと対策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜リスク】不適正な再エネ導入がもたらすリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　リスク：生態系への悪影響で脱炭素と保全がトレードオフに。対策：環境影響評価とゾーニング、地域共生型再エネの導入<br><br><b>解説</b>　再エネ設備の不適正な導入は、自然生態系に悪影響を及ぼし、脱炭素と生物多様性保全がトレードオフになる。環境影響評価やゾーニング（環境保全・事業性・社会的調整の情報の重ね合わせ）で適地を選び、地域共生型の導入を進める<br><br><b>答案に書くなら</b>　リスクとして、不適正な再エネ導入が生態系に悪影響を及ぼし脱炭素と保全がトレードオフになるおそれがあり、環境影響評価とゾーニング、地域共生型の再エネ導入で対応する必要がある。<br><br><b>関連</b>　第六次環境基本計画でも、洋上・陸上風力の環境配慮の制度検討が同様のリスク対策に挙げられる。<br><br><b>答案での使い方</b>　必須Ⅰ(3) 再エネとの両立のリスクと対策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜注意】OECMと自然共生サイトの違いは？また30by30は戦略の別名か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　OECMは国際的な保全区分、自然共生サイトは国が認定する日本版。30by30は目標の一つで戦略の別名ではない<br><br><b>解説</b>　OECMは国際的な保全区分の考え方、自然共生サイトはその日本版として国が認定する具体の制度。30by30は国家戦略が掲げる目標の一つで、戦略の別名ではなく、ネイチャーポジティブも戦略の別名ではない<br><br><b>答案に書くなら</b>　OECMは国際的な保全区分で、自然共生サイトはその日本版として国が認定する制度であり、両者を書き分ける。<br><br><b>関連</b>　ネイチャーポジティブは戦略が目指す2030年の状態を指す概念である。<br><br><b>答案での使い方</b>　定義の書き分けで減点を避ける<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜時期】第五次循環型社会形成推進基本計画が閣議決定されたのはいつ（何年何月）？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2024年8月（2日）。副題は「循環経済を国家戦略に」<br><br><b>解説</b>　2024年8月2日に閣議決定された計画で、根拠は循環型社会形成推進基本法第15条。副題は「循環経済を国家戦略に」で、旧計画（第四次）と区別して最新版であることを示す<br><br><b>答案に書くなら</b>　本計画は2024年8月に閣議決定された第五次循環型社会形成推進基本計画であり、循環経済を国家戦略に位置づけている。<br><br><b>関連</b>　根拠法は環境基本法や生物多様性基本法ではなく、循環型社会形成推進基本法である。<br><br><b>答案での使い方</b>　書き出しで最新版を明示。第四次と取り違えない<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜目標】2030年度の資源生産性・資源消費量・最終処分量の目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　資源生産性約60万円/t、一人当たり天然資源消費量約11t/人・年、最終処分量約1,100万t/年<br><br><b>解説</b>　資源生産性はGDP等を天然資源等投入量で割った指標で、少ない資源でどれだけ稼ぐかを示す。一人当たり天然資源消費量はマテリアルフットプリントと呼ぶ。最終処分量は埋立てに回る廃棄物の量で、いずれも2030年度が目標年次<br><br><b>答案に書くなら</b>　環境の観点から、2030年度に資源生産性約60万円/トン、一人当たり天然資源消費量約11トン/人・年、最終処分量約1,100万トン/年を目指す必要がある。<br><br><b>関連</b>　目標年次は2030年度で、他計画の2040年度などと混同しない。<br><br><b>答案での使い方</b>　必須Ⅰ(1)(2) 現状との差と到達点の根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜目標】2030年度の循環利用率と再生資源の投入割合の目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　入口側約19%、出口側約44%。再生可能資源・循環資源の投入割合は約34%<br><br><b>解説</b>　入口側は資源の投入段階（天然資源に対する再生資源の割合）、出口側は廃棄物等の発生段階（廃棄物等のうち循環利用に回る割合）の循環利用率を指す。2030年度に入口側約19%、出口側約44%を目指し、再生可能資源・循環資源の投入割合は約34%とする<br><br><b>答案に書くなら</b>　環境の観点から、2030年度に入口側循環利用率約19%、出口側約44%、再生可能資源・循環資源の投入割合約34%を目指す。<br><br><b>関連</b>　入口側と出口側の数字を逆に書かない。<br><br><b>答案での使い方</b>　入口と出口の数字を取り違えない<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜目標】循環経済関連ビジネスの市場規模目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2030年までに80兆円以上、2050年に120兆円（2020年は約50兆円）<br><br><b>解説</b>　循環経済関連ビジネスの市場規模は2000年の約40兆円から2020年に約50兆円へ拡大した。成長戦略フォローアップ工程表のKPIを踏襲し、2030年までに80兆円以上、2050年に120兆円を目標とする<br><br><b>答案に書くなら</b>　経済の観点から、循環経済関連ビジネスの市場規模を2020年の約50兆円から2030年までに80兆円以上へ拡大することが解決策の到達点である。<br><br><b>関連</b>　市場規模の目標年は2030年「度」ではなく「年」の表記で、2050年は120兆円である。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 経済面の解決策の到達点に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜柱】第五次循環基本計画の5つの重点分野は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　①循環経済への移行②事業者間連携③地域の循環システム④基盤強靱化⑤国際資源循環<br><br><b>解説</b>　5つの重点分野は2.1循環経済への移行による持続可能な地域と社会づくり、2.2事業者間連携、2.3地域の循環システム、2.4基盤強靱化と適正処理、2.5国際資源循環。R7 Ⅰ-2では事業者間連携、地域の循環システムと地方創生、国際資源循環の3つが問われた<br><br><b>答案に書くなら</b>　解決策として、事業者間連携、地域の循環システム構築、適正な国際資源循環体制の構築などの重点分野に沿って対策を進めることが有効である。<br><br><b>関連</b>　2.1と2.4はR7の問題文に含まれていなかった分野で、2.1は基盤方針である。<br><br><b>答案での使い方</b>　R7 Ⅰ-2は②③⑤の3つ。解決策の方向を国の言葉で<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜柱】動静脈連携とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　製造・小売の動脈産業と廃棄物処理・リサイクルの静脈産業が連携し、再生材利用の拡大と市場創出を図る取組<br><br><b>解説</b>　動脈産業は製造業・小売業など製品をつくる側、静脈産業は廃棄物処理・リサイクル業など使用後を担う側を指す。両者が連携することで、再生材の需要と供給をつなぎ、資源循環の市場を創出する<br><br><b>答案に書くなら</b>　解決策として、動脈産業と静脈産業が連携する動静脈連携により、再生材利用を拡大し資源循環市場を創出することが有効である。<br><br><b>関連</b>　この連携は重点分野2.2の事業者間連携によるライフサイクル全体での資源循環に当たる。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 事業者間連携の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜課題】動静脈連携の課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　再生材の品質の共通認識づくりと、デジタル製品パスポート対応のデータベースなど、循環性を計測・開示する技術基盤が未整備<br><br><b>解説</b>　再生材を使う製造側は品質への不安を持ちやすく、再生材の品質に関する共通認識がないと使われない。循環性を計測・開示するデータ基盤（デジタル製品パスポート対応のデータベース等）も整備途上である<br><br><b>答案に書くなら</b>　技術の観点から、再生材の品質に関する共通認識の醸成と、デジタル製品パスポート対応のデータベースなど循環性を計測・開示する技術基盤が未整備であることが課題である。<br><br><b>関連</b>　デジタル製品パスポート（DPP）は製品の原材料・成分・リサイクル性等をデジタルで記録・開示する欧州発の仕組みである。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜課題】資源循環の課題を『人材・担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　人口減少で廃棄物処理・資源循環のエッセンシャルワーカーが不足し、中小企業が大半の処理業者への影響が大きい<br><br><b>解説</b>　廃棄物処理や資源循環は現場の労働力に支えられ、エッセンシャルワーカーと呼ばれる。人口減少・少子高齢化で担い手が減り、事業者の大半が中小企業のため影響が大きい<br><br><b>答案に書くなら</b>　人材・担い手の観点から、人口減少で廃棄物処理・資源循環のエッセンシャルワーカーが不足し、中小企業が大半を占める処理業者への影響が大きいことが課題である。<br><br><b>関連</b>　重点分野2.4はDXと人材育成で担い手不足と災害廃棄物対応を強化する。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 人材・担い手の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜課題】市場規模80兆円の課題を『経済・資金』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　短期的には経済合理的でない動静脈連携への投資を、GX投資等で後押しする資金誘導が必要<br><br><b>解説</b>　動静脈連携は、短期的には既存ルートより費用がかかり経済合理性に乏しい場合がある。市場規模を2030年に80兆円以上へ拡大するには、その投資をGX投資等の資金誘導で後押しする必要がある<br><br><b>答案に書くなら</b>　経済・資金の観点から、短期的には経済合理的でない動静脈連携への投資を、GX投資等で後押しする資金誘導が必要であることが課題である。<br><br><b>関連</b>　80兆円は成長戦略フォローアップ工程表のKPIを踏襲した目標である。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 経済・資金の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜解決策】再生材の利用拡大の解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　動静脈連携で再生材利用を広げ、デジタル製品パスポート（DPP）で原材料・リサイクル性の情報を開示する<br><br><b>解説</b>　動静脈連携は製造と処理の事業者が連携して再生材利用を広げる取組、DPPは情報開示で循環を促す仕組み。両者を組み合わせれば、品質への不安を下げつつ再生材を流通させられる<br><br><b>答案に書くなら</b>　解決策として、動静脈連携で再生材利用を拡大し、デジタル製品パスポート（DPP）で原材料・リサイクル性の情報を開示することが有効である。<br><br><b>関連</b>　DPPは欧州発の制度的仕組みで、国内制度化が追いついていないことが制度面の課題である。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 技術・制度面の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜解決策】地域の循環の解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　地域の資源の地産地消・循環を進め、製造業・処理業と自治体・市民が連携する地域の循環システムで地方創生につなげる<br><br><b>解説</b>　地域の循環システムは、地域資源の地産地消・循環で地方創生と生態系保全を同時に進める重点分野2.3の考え方。製造業・処理業と自治体・市民など各主体の主体的な連携が要る<br><br><b>答案に書くなら</b>　地域の観点から、地域資源の地産地消・循環を進め、製造業・処理業と自治体・市民が連携する地域の循環システムで地方創生につなげることが解決策である。<br><br><b>関連</b>　参画の枠組みづくりが地域ごとに異なる点が、合意形成面の課題とされる。<br><br><b>答案での使い方</b>　必須Ⅰ・Ⅱ-2 地域施策の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜リスク】動静脈連携で再生材を急拡大するリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　リスク：品質管理や有害物質管理が不十分なまま流通。対策：製品安全・有害物質のリスク管理・不法投棄防止を伴う適正な取組を求める<br><br><b>解説</b>　再生材の利用を急に増やすと、品質管理や有害物質の管理が追いつかないまま流通し、製品安全上の懸念が出る。利用拡大と同時に、製品の安全性確保・有害物質のリスク管理・不法投棄の防止を各主体に求める必要がある<br><br><b>答案に書くなら</b>　リスクとして、再生材の急拡大で品質管理や有害物質管理が不十分なまま流通するおそれがあり、製品安全・有害物質のリスク管理・不法投棄防止を伴う適正な取組を各主体に求める必要がある。<br><br><b>関連</b>　国際資源循環では、輸出先での不適正処理への懸念があり、バーゼル条約等に基づく適正な輸出管理を徹底する。<br><br><b>答案での使い方</b>　必須Ⅰ(3) 再生材拡大のリスクと対策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜注意】第五次の数値目標の年次と、第四次との違いは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　目標年次は2030年度。第四次は指標が151あったが、第五次は指標数を絞り込んだ<br><br><b>解説</b>　数値目標の目標年次は2030年度。第四次計画は指標が151あったが、第五次は指標数を絞り込んだ。旧計画の指標数や目標値を使って答案を書かない<br><br><b>答案に書くなら</b>　本計画の数値目標は2030年度を目標年次としており、第四次計画の指標や目標値ではなく第五次の目標値で答案を書く。<br><br><b>関連</b>　地球温暖化対策計画の2030・2040年度目標や家庭部門の目標年とは別の計画の数字である。<br><br><b>答案での使い方</b>　旧計画の指標数・目標値で答案を書かない<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜時期】地域脱炭素ロードマップの決定はいつで、決定主体は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2021年6月9日、国・地方脱炭素実現会議の決定。閣議決定ではない<br><br><b>解説</b>　地域脱炭素ロードマップは2021年6月9日の国・地方脱炭素実現会議（第3回）の決定文書で、閣議決定でも法定計画でもない。制度的な裏付けは2021年改正の地球温暖化対策推進法（地方公共団体実行計画・地域脱炭素化促進事業）である<br><br><b>答案に書くなら</b>　地域脱炭素ロードマップは2021年6月に国・地方脱炭素実現会議で決定された文書であり、地方からの脱炭素の移行戦略を示している。<br><br><b>関連</b>　第六次環境基本計画等は閣議決定で、決定主体が異なる点を書き分ける。R6 Ⅰ-2で出題された。<br><br><b>答案での使い方</b>　R6 Ⅰ-2で出題。書き出しで決定主体を正確に書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜時期】脱炭素先行地域の現在の年限の整理は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2025年度までに少なくとも100か所を選定し、2030年度までに実行<br><br><b>解説</b>　当初（2021年）は「2030年度までに少なくとも100か所をつくる」と表現されたが、現在の整理は「2025年度までに少なくとも100か所を選定し、2030年度までに実行」。選定の期限と実行の期限が別である<br><br><b>答案に書くなら</b>　脱炭素先行地域は、2025年度までに少なくとも100か所を選定し、2030年度までに実行することを目標としている。<br><br><b>関連</b>　当初の表現と現在の整理の2段階があり、選定年と実行年を取り違えない。<br><br><b>答案での使い方</b>　選定年と実行年を取り違えない。当初は「2030年度までに100か所」<br><br>【出典】<a href=\"https://www.env.go.jp/content/000376957.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜定義】脱炭素先行地域の定義の核は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　民生部門（家庭部門及び業務その他部門）の電力消費に伴うCO2排出の実質ゼロ。運輸・熱利用等は地域特性に応じて実施<br><br><b>解説</b>　脱炭素先行地域は、民生部門の電力消費に伴うCO2排出の実質ゼロを実現する地域。民生部門は家庭部門と業務その他部門を指し、運輸部門・熱利用等は地域特性に応じて排出削減する付随的な対策である<br><br><b>答案に書くなら</b>　脱炭素先行地域とは、民生部門（家庭部門及び業務その他部門）の電力消費に伴うCO2排出の実質ゼロを実現し、運輸・熱利用等も地域特性に応じて削減する地域である。<br><br><b>関連</b>　先行モデルを全国に伝搬させて2050年を待たずに脱炭素を実現する考え方を脱炭素ドミノという。<br><br><b>答案での使い方</b>　必須Ⅰ・Ⅱ-1 定義を問われたときの書き出しに<br><br>【出典】<a href=\"https://www.env.go.jp/content/000376957.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜目標】脱炭素先行地域の選定状況は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　第7回（2026年2月）までに45道府県133市町村の102提案が選定。3提案が辞退<br><br><b>解説</b>　第1回〜第7回（2026年2月13日時点）で、全国45道府県133市町村の102提案が選定され、選定後に3提案が辞退した。数の上では目標の100か所に届いたが、辞退が出ている点が実行上の課題である<br><br><b>答案に書くなら</b>　地域の観点から、脱炭素先行地域は102提案が選定された一方で3提案が辞退しており、選定後の実行可能性の確保が課題である。<br><br><b>関連</b>　辞退の背景はコスト増大や地元合意の難航で、計画段階での協議の徹底が対策になる。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 目標100か所との差・辞退を課題の根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000376957.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜目標】重点対策①自家消費型太陽光の導入目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2030年に設置可能な建築物の約50%、2040年に100%<br><br><b>解説</b>　重点対策①は屋根置きなどの自家消費型太陽光発電で、2030年に設置可能な建築物の約50%、2040年に100%への導入を目指す。再エネを地域内で消費して、エネルギー代金の域外流出を減らす考え方である<br><br><b>答案に書くなら</b>　解決策として、自家消費型の太陽光発電を2030年に設置可能な建築物の約50%、2040年に100%へ導入することが有効である。<br><br><b>関連</b>　環境省の試算では、約9割の市町村でエネルギー代金の域内外収支は域外支出が上回っている（2015年度）。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 太陽光の解決策の到達点に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜柱】ロードマップの8つの重点対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　①自家消費型太陽光②地域共生型再エネ③業務ビルZEB化④住宅省エネ⑤ゼロカーボン・ドライブ⑥資源循環⑦まちづくり⑧農林水産業<br><br><b>解説</b>　8つの重点対策は再エネ・省エネ・移動・循環・まちづくり・食農を網羅する。①自家消費型太陽光②地域共生型再エネ③業務ビルZEB化④住宅省エネ⑤ゼロカーボン・ドライブ⑥資源循環⑦まちづくり⑧農林水産業<br><br><b>答案に書くなら</b>　解決策として、自家消費型太陽光、地域共生型再エネ、ZEB・ZEH、ゼロカーボン・ドライブなど8つの重点対策を組み合わせることが有効である。<br><br><b>関連</b>　新築住宅はZEH、新築建築物はZEBの2030年平均実現、乗用車新車は2035年電動車100%を目指す。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 解決策を国の分類で言う<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜課題】地域脱炭素の課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　太陽光自家消費・ZEB・ZEH・電動車を全国に普及させるには、低圧需要での経済性確保と初期投資ゼロの導入モデルの確立が課題<br><br><b>解説</b>　太陽光自家消費・ZEB・ZEH・電動車は、全国津々浦々に広げる段階で、低圧需要での経済性が課題になる。初期投資ゼロの導入ビジネスモデルは、導入側の負担をなくして普及を加速させる手段である<br><br><b>答案に書くなら</b>　技術の観点から、太陽光自家消費・ZEB・ZEH・電動車を全国に普及させるため、低圧需要での経済性の確保と初期投資ゼロの導入ビジネスモデルの確立が課題である。<br><br><b>関連</b>　ゼロカーボン・ドライブは再エネ電力とEV/PHEV/FCVの組合せで、車両の蓄電機能を地域のレジリエンス向上にも使う。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜課題】地域脱炭素の課題を『人材・担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　先行地域の計画策定・実施を担う自治体職員や地元企業・金融機関の体制確保が、地域間の取組差を生んでいる<br><br><b>解説</b>　先行地域の計画策定や実施には、自治体職員の専門性に加え、地元企業や金融機関の関与が必要。体制が整う自治体と整わない自治体で差が生まれ、地域間の取組差につながる<br><br><b>答案に書くなら</b>　人材・担い手の観点から、脱炭素先行地域の計画策定・実施を担う自治体職員や地元企業・金融機関の体制確保が、地域間の取組差を生む要因となっていることが課題である。<br><br><b>関連</b>　リスク面でも、体制が不十分な地域では選定後に取組を辞退する例が出ている。<br><br><b>答案での使い方</b>　必須Ⅰ(1)・Ⅱ-2 人材の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜課題】再エネ促進区域設定の課題を『合意形成』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　地域協議会の開催等による合意形成が必要で、環境配慮や地域貢献の要件設定を円滑に進める仕組みが課題<br><br><b>解説</b>　再エネ促進区域の設定には、地域協議会の開催などで住民や事業者との合意形成が要る。環境配慮や地域貢献の要件を設ける作業が重いと、区域設定が進まなくなる<br><br><b>答案に書くなら</b>　合意形成・地域の観点から、再エネ促進区域の設定には地域協議会の開催等による合意形成が必要であり、環境配慮や地域貢献の要件設定を円滑に進める仕組みが課題である。<br><br><b>関連</b>　制度面では、洋上・陸上風力の特性に応じた環境アセスメントの最適化も改革課題である。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 合意形成・地域の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜解決策】合意形成が進まない課題への解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　促進区域の設定（ポジティブゾーニング）で、環境配慮と地域貢献の要件を付けて適地を事前に示す<br><br><b>解説</b>　ポジティブゾーニングは、市町村が再エネの導入目標を設定し、環境配慮や地域貢献の要件を付けた上で再エネ事業を促進する区域を選ぶ仕組み。適地を事前に示すことで、地域に裨益する再エネの立地と合意形成を進めやすくする<br><br><b>答案に書くなら</b>　解決策として、ポジティブゾーニングで環境配慮と地域貢献の要件を付した促進区域を設定し、適地を事前に示して地域共生型の再エネ立地を進めることが有効である。<br><br><b>関連</b>　重点対策②の地域共生・地域裨益型再エネの立地を支える仕組みである。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 再エネ立地の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜解決策】自治体の取組を後押しする解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　重点対策加速化事業（地域脱炭素移行・再エネ推進交付金）で、重点対策を組み合わせた複数年の計画を5年間支援する<br><br><b>解説</b>　重点対策加速化事業は、重点対策①〜⑤を複合的に組み合わせた複数年の計画を実施する自治体を、交付期間5年間で支援する交付金制度。令和8年5月1日時点で全国170自治体が採択されている<br><br><b>答案に書くなら</b>　解決策として、地域脱炭素移行・再エネ推進交付金（重点対策加速化事業）により、重点対策を組み合わせた複数年の計画を5年間支援することが有効である。<br><br><b>答案での使い方</b>　必須Ⅰ(2)・Ⅱ-2 財政支援の根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜リスク】先行地域の選定数を優先して生じるリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　リスク：コスト増や地元合意の難航で辞退が出る。対策：計画段階から地域協議会と要件明確化を徹底し、実行可能性を精査して選定<br><br><b>解説</b>　先行地域の選定数という目標を優先すると、実行可能性の吟味が甘くなり、コスト増や地元合意の難航で、選定後に辞退が出る。計画策定段階から協議と要件明確化を徹底して実現性を確認する必要がある<br><br><b>答案に書くなら</b>　リスクとして、選定数を優先するとコスト増や地元合意の難航で辞退する地域が生じるおそれがあり、計画段階から地域協議会と要件の明確化を徹底し、実行可能性を精査して選定する必要がある。<br><br><b>関連</b>　第7回時点で3提案が辞退している。<br><br><b>答案での使い方</b>　必須Ⅰ(3) 目標優先のリスクと対策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜リスク】促進区域の設定を急ぐリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　リスク：合意形成が不十分なまま区域指定が進み、住民と対立。対策：地域協議会で環境保全と地域の経済・社会課題の解決を併せて検討<br><br><b>解説</b>　促進区域の設定を急ぐと、住民の理解が得られないまま区域指定が進み、地域住民との対立を招く。地域協議会を開き、環境の保全と地域の経済・社会課題の解決を併せて検討することで対立を避けられる<br><br><b>答案に書くなら</b>　リスクとして、促進区域の設定を急ぐと合意形成が不十分なまま住民との対立を招くおそれがあり、地域協議会で環境保全と地域の経済・社会課題の解決を併せて検討する必要がある。<br><br><b>関連</b>　風力・地熱の開発では、海域の鳥類や温泉事業者への影響に配慮し、環境アセスメントの最適化や温泉モニタリングを行う。<br><br><b>答案での使い方</b>　必須Ⅰ(3)・Ⅱ-2 合意形成のリスクと対策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜注意】重点対策加速化事業の交付対象は、8つの重点対策のどれか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　①〜⑤のみ。⑥資源循環・⑦まちづくり・⑧農林水産業は対象外<br><br><b>解説</b>　加速化事業の交付対象は、8つの重点対策のうち①〜⑤（太陽光・地域共生型再エネ・業務ビルZEB化・住宅省エネ・ゼロカーボンドライブ）のみ。⑥資源循環・⑦まちづくり・⑧農林水産業は対象外で、他の制度で対応する<br><br><b>答案に書くなら</b>　重点対策加速化事業の交付対象は①〜⑤の重点対策に限られ、⑥〜⑧は対象外であるため、「すべて交付金対象」とは書かない。<br><br><b>関連</b>　⑥は食品ロスを2030年度までに2000年度比半減、⑧はみどりの食料システム戦略で2050年に有機農業取組面積25%を目指す。<br><br><b>答案での使い方</b>　「重点対策＝すべて交付金対象」と書くと減点<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜時期】令和8年版の環境白書等が閣議決定されたのはいつ？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2026年6月（5日）。環境の日に合わせて公表された、3白書の合冊<br><br><b>解説</b>　令和8年版は2026年6月5日に閣議決定され、環境の日に合わせて公表された。環境白書（環境基本法第12条）、循環型社会白書（循環基本法第14条）、生物多様性白書（生物多様性基本法第10条）を1冊に合冊したものである<br><br><b>答案に書くなら</b>　令和8年版の環境白書・循環型社会白書・生物多様性白書は2026年6月に閣議決定された最新版であり、これに基づいて現状を整理する。<br><br><b>関連</b>　第五次循環型社会形成推進基本計画（循環基本法第15条の計画そのもの）とは別の文書である。<br><br><b>答案での使い方</b>　書き出しで最新版を明示。令和7年版と取り違えない<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/index.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜時期】令和8年版白書のテーマは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　循環経済（サーキュラーエコノミー）で日本列島を強く豊かに<br><br><b>解説</b>　令和8年版のテーマは「循環経済（サーキュラーエコノミー）で日本列島を強く豊かに」。令和7年版は「新たな成長」を導くグリーンな経済システム、令和6年版は自然資本充実と環境価値、令和5年版はネットゼロ・循環経済・ネイチャーポジティブの統合だった<br><br><b>答案に書くなら</b>　令和8年版白書は「循環経済で日本列島を強く豊かに」をテーマに、循環経済への移行加速化を位置づけている。<br><br><b>関連</b>　年版ごとにテーマが異なるため、年版とテーマの対応を確認して書く。<br><br><b>答案での使い方</b>　令和7年版（グリーンな経済システム）と取り違えると減点<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜目標】循環経済行動計画が目指す2030年までの投資規模は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　再資源化拠点等の構築・ネットワーク形成に向け、官民で約1兆円<br><br><b>解説</b>　循環経済行動計画は2026年4月に関係閣僚会議で決定された計画。再資源化拠点等の構築・ネットワーク形成に向け、2030年までに官民で約1兆円の投資を目指す。再資源化拠点は再生資源を安定供給する基盤である<br><br><b>答案に書くなら</b>　経済・資金の観点から、再資源化拠点等の構築・ネットワーク形成に向け、2030年までに官民で約1兆円の投資を促進することが解決策の規模感である。<br><br><b>関連</b>　1兆円は循環経済行動計画の数字で、GX全体の150兆円とは母集団が異なる。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 資金面の解決策の規模感に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜目標】令和8年版白書の保護地域・OECM指定割合（2025年8月）は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　陸地約21.0%、海洋約13.3%。目標は2030年までに各30%以上<br><br><b>解説</b>　保護地域・OECMの指定割合は、2025年8月現在で陸地約21.0%、海洋約13.3%。目標は2030年までにいずれも30%以上で、特に海洋の差が大きい<br><br><b>答案に書くなら</b>　生態系保全の観点から、保護地域・OECMの指定は陸地約21.0%、海洋約13.3%にとどまり、2030年までの30%以上という目標との差が課題である。<br><br><b>関連</b>　自然共生サイトは2026年3月時点で569ヶ所が認定されている。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 目標との差で課題の大きさを示す<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜柱】循環経済行動計画（2026年4月決定）の2つの柱は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　再生資源供給サプライチェーンの強靱化と、日本をハブとする国際資源循環ネットワークの構築<br><br><b>解説</b>　循環経済行動計画は、資源の海外依存と経済安全保障の観点から、国内で再生資源を確保し日本の製錬技術等を活かす狙いを持つ。柱は再生資源供給サプライチェーンの強靱化と、日本をハブとする国際資源循環ネットワークの構築である<br><br><b>答案に書くなら</b>　解決策として、再生資源供給サプライチェーンの強靱化と、日本をハブとする国際資源循環ネットワークの構築を進めることが有効である。<br><br><b>関連</b>　企業の資源循環の情報開示スキームであるグローバル循環プロトコル（GCP）1.0も国際標準化が進められている。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 資源循環の解決策を国の言葉で言う<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜柱】大規模太陽光（メガソーラー）の対策パッケージの考え方は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　不適切事案への法的規制の強化と、地域共生型への支援強化を両立させる<br><br><b>解説</b>　メガソーラーは再エネ導入に資する一方、無秩序な開発などの不適切事案が地域との摩擦を生む。対策パッケージは、不適切事案を抑える規制強化と、望ましい導入を支える地域共生型への支援強化を同時に行う考え方である<br><br><b>答案に書くなら</b>　解決策として、大規模太陽光発電事業について、不適切事案への法的規制の強化と地域共生型への支援強化を両立させることが有効である。<br><br><b>関連</b>　ペロブスカイト太陽電池は軽量・柔軟で、耐荷重性の低い屋根や壁面にも設置できる。<br><br><b>答案での使い方</b>　必須Ⅰ(2)・Ⅲ 再エネ立地の方向づけに<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜課題】重要鉱物・金属の再生資源供給の課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　重要鉱物・金属を質・量・コスト面で安定供給するための再資源化・製錬技術の確立が必要で、動脈と静脈をつなぐ技術基盤が不足<br><br><b>解説</b>　再生資源の供給拠点をつくるには、重要鉱物・金属を質・量・コストの面で安定して供給できる再資源化・製錬技術が必要。製造側（動脈）と再資源化側（静脈）をつなぐ技術基盤が不足していることが課題である<br><br><b>答案に書くなら</b>　技術の観点から、重要鉱物・金属を質・量・コストの面で安定供給するための再資源化・製錬技術の確立と、動脈産業と静脈産業をつなぐ技術基盤の整備が課題である。<br><br><b>関連</b>　再資源化事業等の高度化に関する法律（2025年11月施行）は、高度な再資源化事業者を認定する制度を創設した。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜課題】再資源化拠点の整備の課題を『経済・資金』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　官民で約1兆円の投資を目指すが、再生材需要の創出を起点とした自律的な市場形成の設計が課題<br><br><b>解説</b>　再資源化拠点の整備は、投資の規模だけでなく、投資が回収される市場がなければ続かない。再生材の需要を創出・拡大して、自律的に回る市場形成をどう設計するかが資金循環の課題である<br><br><b>答案に書くなら</b>　経済・資金の観点から、再資源化拠点等に官民で約1兆円の投資を目指す一方、再生材需要の創出を起点とした自律的な市場形成の設計が課題である。<br><br><b>関連</b>　太陽光パネルの大量廃棄に備えたリサイクル義務化の法案（2026年4月国会提出）も、制度面の枠組みを整える。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 経済・資金の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜課題】メガソーラーの課題を『合意形成』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　不適切事案への規制強化と地域共生型への支援を両立させる必要があり、地域住民との合意形成が課題<br><br><b>解説</b>　メガソーラーに関する対策では、不適切事案を規制しつつ、地域共生型の導入も支援する。両方を進めるには、地域住民の納得を得る合意形成が欠かせない。住民が反対すると、規制強化と支援の両方が機能しにくくなる<br><br><b>答案に書くなら</b>　合意形成・地域の観点から、大規模太陽光発電事業で不適切事案への規制強化と地域共生型への支援を両立させるため、地域住民との合意形成が課題である。<br><br><b>関連</b>　クマ被害対策や不適切事案対応では、自治体の体制・人材不足も課題になる。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 合意形成・地域の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜解決策】資源循環の解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　再生資源供給サプライチェーンの強靱化で、再資源化拠点を構築・ネットワーク化し、再生材を質・量・コスト面で安定供給する<br><br><b>解説</b>　再生資源供給サプライチェーンの強靱化は、再資源化拠点を構築してネットワークでつなぎ、重要鉱物・金属等の再生材を質・量・コスト面で安定供給する取組。資源の海外依存を減らし、経済安全保障にも寄与する<br><br><b>答案に書くなら</b>　解決策として、再生資源供給サプライチェーンの強靱化により、再資源化拠点を構築・ネットワーク化し、再生材を質・量・コスト面で安定供給することが有効である。<br><br><b>関連</b>　同じ計画の柱として、日本をハブとする国際資源循環ネットワークの構築がある。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 資源循環の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜解決策】自然再興の解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　自然共生サイトの認定（地域生物多様性増進法、2025年4月施行）で、民間等の保全区域を国が認定し30by30を進める<br><br><b>解説</b>　自然共生サイトは、民間等の取組で生物多様性が保全されている区域を国が認定する制度で、2026年3月時点で569ヶ所。地域生物多様性増進法（2025年4月施行）に基づく認定を含み、民間の保全区域を30by30の達成に取り込む手段である<br><br><b>答案に書くなら</b>　解決策として、地域生物多様性増進法に基づく自然共生サイトの認定により、民間等の保全区域を国が認定して30by30の達成を進めることが有効である。<br><br><b>関連</b>　国立公園満喫プロジェクトは保護と利用の好循環を目指す別の取組で、2026年3月に2026年以降の方針を策定した。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 生物多様性の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜リスク】再資源化拠点の構築を急ぐリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　リスク：環境対策が不十分なスクラップヤード経由で循環資源が海外へ流出。対策：許可制導入とバーゼル法手続の適正化で監視強化<br><br><b>解説</b>　再資源化拠点の構築や国際資源循環ネットワーク化を急ぐと、環境対策が不十分なスクラップヤード事業者を通じて、循環資源が海外へ流出するおそれがある。許可制の導入と、バーゼル法に基づく輸入手続の適正化で監視を強める<br><br><b>答案に書くなら</b>　リスクとして、スクラップヤード経由で循環資源が海外へ流出するおそれがあり、スクラップヤード事業の許可制導入とバーゼル法手続の適正化で監視を強化する必要がある。<br><br><b>関連</b>　自治体アンケートで全国4,000件超の事業場が確認されている。<br><br><b>答案での使い方</b>　必須Ⅰ(3) 資源循環のリスクと対策に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜リスク】メガソーラー拡大のリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　リスク：自然再興と土地利用で競合し、不適切な開発を招く。対策：対策パッケージで規制を強化し、地域共生型への支援を重点化<br><br><b>解説</b>　メガソーラーの導入拡大は、土地利用で自然再興（ネイチャーポジティブ）の目標と競合し、無秩序な開発などの不適切事案を招くおそれがある。規制と支援を組み合わせた対策パッケージで両立を図る<br><br><b>答案に書くなら</b>　リスクとして、メガソーラーの拡大が自然再興と土地利用で競合し不適切な開発を招くおそれがあり、対策パッケージで法的規制を強化し、地域共生型への支援を重点化する必要がある。<br><br><b>関連</b>　クマ等の個体数管理は生物多様性保全と住民の安全確保のトレードオフがあり、クマ被害対策ロードマップで両立を図る。<br><br><b>答案での使い方</b>　必須Ⅰ(3) 再エネと自然保全の両立に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜注意】令和8年版の「約1兆円」と、GX2040の「150兆円」の違いは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　1兆円は循環経済行動計画（再資源化拠点）、150兆円はGX全体の官民投資。母集団が違う<br><br><b>解説</b>　令和8年版白書の「約1兆円」は、循環経済行動計画が再資源化拠点等の構築・ネットワーク形成で2030年までに目指す官民投資。GX2040ビジョンの「150兆円」は、GX全体で10年間に呼び込む官民投資で、対象が違う<br><br><b>答案に書くなら</b>　約1兆円は循環経済行動計画の再資源化拠点等への官民投資、150兆円はGX全体の官民投資であり、母集団が異なるので混同しない。<br><br><b>関連</b>　2035年度60%・2040年度73%削減も、家庭部門の66%等とは母集団が異なる全体のNDCの数字である。<br><br><b>答案での使い方</b>　数字は何の目標かとセットで書く<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}];
const NJ_TERM_DATA = [{"f": "二次:用語", "q": "【排出量取引制度（GX-ETS）｜時期】排出量取引制度は本格稼働しているか。何年度からか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2026年度（2026年4月1日施行）。2023年度開始の自主参加型GXリーグとは別の、法定の制度<br><br><b>解説</b>　2026年4月1日に改正GX推進法が施行され、排出量取引は試行から法定の本格稼働に移った。2023年度開始のGXリーグは自主参加の試行で別物<br><br><b>答案に書くなら</b>　排出量取引制度は2026年度から本格稼働しており、法に基づく制度として運用が始まっている。<br><br><b>関連</b>　初年度は届出と移行計画のみで、排出枠の割当ては2027年度（2026年度に割当てではない）。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで「施行済み」と示す。GXリーグと区別<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【排出量取引制度（GX-ETS）｜定義】排出量取引制度とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　政府が排出枠（CO2 1t＝1枠）を無償割当てし、排出実績量と同量の枠の保有を義務づけ、過不足を事業者間で取引できる制度<br><br><b>解説</b>　排出枠（CO2 1t＝1枠）を無償で割り当て、排出実績量と同量の保有を義務づけると、枠が不足する事業者と余る事業者の間で取引が生まれる<br><br><b>答案に書くなら</b>　排出量取引制度とは、政府が無償割当てした排出枠を排出実績量と同量保有する義務を課し、過不足を事業者間で取引できる制度である。<br><br><b>関連</b>　成長志向型カーボンプライシング構想の柱の1つで、もう1つの柱が化石燃料賦課金。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【排出量取引制度（GX-ETS）｜制度】排出量取引制度の対象事業者の要件は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　CO2の直接排出量の直近3年度平均が10万トン以上の事業者。事業者単位で判定する<br><br><b>解説</b>　判定は事業者単位で、直近3年度の平均で見るため単年の増減に左右されにくい。子会社等は別事業者として扱う<br><br><b>答案に書くなら</b>　対象はCO2の直接排出量が直近3年度平均で10万トン以上の事業者であり、事業者単位で判定する。<br><br><b>関連</b>　初年度（2026年度）のみ、判定は2023〜2025年度の平均で行う特例がある。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。数字は「3年度平均10万t」<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505CO0000000379\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【排出量取引制度（GX-ETS）｜制度】排出量取引制度の価格安定の仕組みは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　参考上限取引価格と調整基準取引価格を毎年度設定。償却不足分は「未償却量×参考上限価格×1.1」の負担金<br><br><b>解説</b>　枠の価格が乱高下すると企業は投資計画を立てにくい。そこで価格の目安を年度開始前に定め、枠は投機的取引の対象にしてはならないとされる<br><br><b>答案に書くなら</b>　解決策は、参考上限取引価格と調整基準取引価格を毎年度設定し、償却不足分に未償却量×参考上限価格×1.1の負担金を課して価格を安定させることである。<br><br><b>関連</b>　GX推進機構が排出枠取引市場の設置・運営と価格調整の買入れを担う。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。価格の予見性の論点に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【排出量取引制度（GX-ETS）｜課題】排出量取引制度の課題を『技術・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　排出目標量・実績量は登録確認機関の確認が必須で、算定・確認の体制づくりが初年度から必要になる<br><br><b>解説</b>　排出量は自己申告のままでは信頼できないため、第三者の登録確認機関の確認が必須とされる。事業者側は算定の仕組みを整えないと報告・枠の保有に支障が出る<br><br><b>答案に書くなら</b>　技術・運用の観点から、課題は排出目標量・実績量の算定に登録確認機関の確認が必須で、算定・確認の体制づくりが初年度から必要になることである。<br><br><b>関連</b>　確認が必要なのは目標量と実績量の両方。<br><br><b>答案での使い方</b>　Ⅱ-1の課題。「確認体制」を観点つきで書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【排出量取引制度（GX-ETS）｜解決策】排出量取引制度で国際競争力への影響を抑える仕組みを、専門用語で言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　原単位の改善率を用いた無償割当てで、事業分野間の均衡と国際競争力に配慮する<br><br><b>解説</b>　無償割当てなら事業者の負担が急に重くならず、原単位の改善率を使えば分野ごとの事情の差も調整できる。法も割当ての勘案事項に国際競争力の維持向上を挙げる<br><br><b>答案に書くなら</b>　経済・競争力の観点から、解決策は原単位の改善率を用いて無償割当てを行い、事業分野間の均衡と国際競争力に配慮することである。<br><br><b>関連</b>　発電事業者への有償割当ては2033年度から。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 競争力対策の解決策に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【排出量取引制度（GX-ETS）｜解決策】排出量の算定・確認の体制づくりの解決策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　確認を担う登録確認機関を国の登録制とし、ERMSとマニュアルで算定・報告の手続きを整える<br><br><b>解説</b>　算定・確認がばらつくと制度の信頼が揺らぐ。そこで確認を担う登録確認機関を国の登録制とし、ERMSとマニュアルで手続きを標準化する<br><br><b>答案に書くなら</b>　技術・運用の観点から、解決策は登録確認機関を国の登録制とし、ERMSとマニュアルで算定・報告の手続きを整えることである。<br><br><b>関連</b>　登録確認機関の登録申請は制度の施行前から可能とされている。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 運用面の解決策に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【排出量取引制度（GX-ETS）｜注意】排出量取引2026年度、化石燃料賦課金、発電の有償割当ての開始年度は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　排出量取引は2026年度、化石燃料賦課金は2028年度、発電事業者の有償割当ては2033年度<br><br><b>解説</b>　3つの制度は段階的に始まる。まず企業の排出に枠を課す排出量取引、次に燃料の採取・輸入に課す賦課金、最後に発電の有償化という順で負担が広がる<br><br><b>答案に書くなら</b>　排出量取引は2026年度、化石燃料賦課金は2028年度、発電事業者の有償割当ては2033年度から始まる。<br><br><b>関連</b>　賦課金は令和10年度、発電の有償割当ては令和15年度とも書かれる。<br><br><b>答案での使い方</b>　年度の取り違えは減点。順序で覚える<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【化石燃料賦課金・成長志向型カーボンプライシング構想｜時期】化石燃料賦課金の徴収開始はいつか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2028年度（令和10年度）から徴収する予定で、まだ始まっていない<br><br><b>解説</b>　賦課金は法で令和10年度（2028年度）からの徴収と決まっているが、まだ始まっておらず予定の段階。2026年度開始の排出量取引とは時期が違う<br><br><b>答案に書くなら</b>　化石燃料賦課金は2028年度から徴収する予定であり、現時点では導入前の段階である。<br><br><b>関連</b>　既に採取・引取りをしている事業者の届出期限は令和10年3月31日。<br><br><b>答案での使い方</b>　Ⅱ-1で予定段階と示す。排出量取引(2026)と区別<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【化石燃料賦課金・成長志向型カーボンプライシング構想｜定義】成長志向型カーボンプライシング構想とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　GX先行投資を促しつつ炭素価格の負担を段階的に導入し、脱炭素と産業競争力を両立させる構想<br><br><b>解説</b>　構想は、先行投資支援・カーボンプライシング・新たな金融手法を組み合わせる。企業にGXに取り組む期間を設けてから導入し、徐々に引き上げる方針を事前に示す<br><br><b>答案に書くなら</b>　成長志向型カーボンプライシング構想とは、GX先行投資を促しつつ炭素価格の負担を段階的に導入し、脱炭素と産業競争力を両立させる構想である。<br><br><b>関連</b>　先行投資支援は20兆円規模で、GX経済移行債を財源とする。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しの定義に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【化石燃料賦課金・成長志向型カーボンプライシング構想｜制度】化石燃料賦課金は誰が納め、どう計算されるか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　化石燃料の採取・輸入事業者が納付。賦課額は「単価×CO2排出量（t）」で、最終消費者には直接課さない<br><br><b>解説</b>　徴収の手間を減らすため、課税の入口である化石燃料の採取・輸入事業者に課す。最終消費者には直接課さない<br><br><b>答案に書くなら</b>　化石燃料賦課金は採取・輸入事業者が納付し、賦課額は単価にCO2排出量（t）を乗じて計算する。<br><br><b>関連</b>　もう1つの財源である特定事業者負担金は、排出量の多い発電事業者に2033年度から課される。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。納付義務者の取り違え防止<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【化石燃料賦課金・成長志向型カーボンプライシング構想｜制度】GX経済移行債の発行期間と償還の仕組みは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　令和5〜14年度に発行。賦課金と特定事業者負担金の収入で令和32年度（2050年度）までに償還<br><br><b>解説</b>　先行投資を前倒しで行うため、GX経済移行債で資金を調達し、将来の賦課金などの収入で返す設計にしている<br><br><b>答案に書くなら</b>　GX経済移行債は令和5〜14年度に発行し、賦課金と特定事業者負担金の収入で令和32年度までに償還する。<br><br><b>関連</b>　発行期間（令和5〜14年度）と償還期限（令和32年度）を混同しない。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。財源の裏付けとして<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【化石燃料賦課金・成長志向型カーボンプライシング構想｜課題】化石燃料賦課金導入の課題を『経済』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　負担が産業・家計のエネルギーコストに及ぶ。法は「中長期的なエネルギー負担の抑制」「公正な移行」を基本理念とする<br><br><b>解説</b>　賦課金は燃料価格に上乗せされるため、産業のコストや家計の光熱費に波及しうる。法も基本理念に負担の抑制と公正な移行を掲げる<br><br><b>答案に書くなら</b>　経済の観点から、課題は賦課金の負担が産業・家計のエネルギーコストに及ぶことであり、法は中長期的な負担の抑制と公正な移行を基本理念とする。<br><br><b>関連</b>　単価は政令で定める。<br><br><b>答案での使い方</b>　Ⅱ-1の課題。観点名を明記して書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【化石燃料賦課金・成長志向型カーボンプライシング構想｜解決策】賦課金の負担を抑える仕組みを、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　単価を上限・下限の算定式の範囲内で政令により定め、エネルギー施策との整合等に応じて減額・還付を認める<br><br><b>解説</b>　単価を青天井にしないよう法が上限と下限の算定式を置き、その範囲内で政令により単価を決める。さらに産業への影響を考えて減額・還付も認める<br><br><b>答案に書くなら</b>　解決策は、単価を上限・下限の算定式の範囲内で政令により定め、エネルギー施策との整合等に応じた減額・還付を認めることで負担を抑えることである。<br><br><b>関連</b>　上限は石油石炭税等の減収見込みを踏まえて算定される。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 負担抑制の解決策に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【化石燃料賦課金・成長志向型カーボンプライシング構想｜解決策】企業の早期投資を促す設計を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　徴収開始時期と段階的に引き上げる方針を事前に示し、早く取り組むほど将来の負担が軽くなる設計にする<br><br><b>解説</b>　価格シグナルが働くには、企業が事前に負担の見通しを持てることが要る。開始時期と引上げ方針を先に示すと、早く動くほど有利になる<br><br><b>答案に書くなら</b>　解決策は、徴収開始時期と段階的に引き上げる方針を事前に示し、早期に取り組むほど将来の負担が軽くなる設計にして企業の早期投資を促すことである。<br><br><b>関連</b>　対策の3本目は20兆円規模の先行投資支援。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 予見性の解決策に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【化石燃料賦課金・成長志向型カーボンプライシング構想｜注意】賦課金の単価は法律本文で定められているか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　定められていない。単価は政令で決め、法律が定めるのは上限・下限の算定式と徴収開始年度<br><br><b>解説</b>　法律が決めるのは骨格（上限・下限の算定式と徴収開始年度）で、具体的な単価は状況に応じて動かせるよう政令に委ねる<br><br><b>答案に書くなら</b>　賦課金の単価は法律本文では定められておらず、法の上限・下限の算定式の範囲内で政令により定める。<br><br><b>関連</b>　納付義務者も取り違えない（最終消費者ではなく採取・輸入事業者）。<br><br><b>答案での使い方</b>　「法律で単価を定める」と書くと減点<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【CCS事業法（二酸化炭素の貯留事業に関する法律）｜時期】CCS事業法の施行状況は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　段階施行で、探査は2024年8月、試掘は2024年11月、貯留事業・導管輸送は2026年5月22日に完全施行<br><br><b>解説</b>　事業が段階的に始まるため、法も3段階で施行された。探査は2024年8月、試掘は2024年11月、貯留事業と導管輸送は2026年5月22日で、現在は完全施行済み<br><br><b>答案に書くなら</b>　CCS事業法は段階施行され、2026年5月22日に貯留事業・導管輸送事業の規定まで完全施行された。<br><br><b>関連</b>　施行は探査→試掘→貯留事業の3段階。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで「施行済み」と示す<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000038\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【CCS事業法（二酸化炭素の貯留事業に関する法律）｜定義】CCS事業法とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　CO2を地下に貯蔵する貯留事業と、導管輸送事業に、許可制・届出制、保安規制、事業終了後の管理を定めた法律<br><br><b>解説</b>　CCSは電化や水素等では脱炭素化が難しい分野の排出を減らす手段。地下にCO2を長期貯蔵するため、事業の許可と保安、終了後の管理を法で定める必要がある<br><br><b>答案に書くなら</b>　CCS事業法とは、CO2の貯留事業と導管輸送事業について、許可制・届出制、保安規制、事業終了後の管理を定めた法律である。<br><br><b>関連</b>　国は2030年までに民間事業者がCCS事業を始める事業環境を整える方針。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.env.go.jp/council/content/i_18/000393953.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【CCS事業法（二酸化炭素の貯留事業に関する法律）｜制度】貯留事業の許可の仕組みは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　経産大臣が「特定区域」を指定して募集し、貯留区域ごとに許可。海域の指定は環境大臣の同意が必要<br><br><b>解説</b>　貯留層は特定の区域にしかなく、誰でも自由に掘れては困る。国が区域を指定して事業者を募集し、貯留区域ごとに許可する。海域は環境への影響があるので環境大臣の同意が必要になる<br><br><b>答案に書くなら</b>　経産大臣が特定区域を指定して募集し、貯留区域ごとに貯留事業を許可する。海域の指定には環境大臣の同意を要する。<br><br><b>関連</b>　貯留権は物権とみなされる。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。海域は経産・環境の共管<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000038\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【CCS事業法（二酸化炭素の貯留事業に関する法律）｜制度】注入終了後の管理の仕組みは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　事業者が引当金を積み、閉鎖措置の確認・廃止許可後は管理がJOGMECへ移り、事業者はJOGMECへ拠出金を納付<br><br><b>解説</b>　CO2は注入後も長期の監視が必要で、事業者が撤退しても管理は途切れさせられない。そこで事業者が引当金を積み、廃止後はJOGMECが管理を引き継ぐ<br><br><b>答案に書くなら</b>　事業者が引当金を積み、閉鎖措置の確認・廃止許可後は管理がJOGMECへ移り、事業者はJOGMECへ拠出金を納付する。<br><br><b>関連</b>　拠出金は少なくとも30年間分の管理費用を確保できる算定基準とする省令内容が整理されている。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。長期管理の資金確保<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000038\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【CCS事業法（二酸化炭素の貯留事業に関する法律）｜制度】漏えい等による損害の賠償責任は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　損害発生時の貯留事業者等が負う無過失責任。過失を立証されなくても責任を負う<br><br><b>解説</b>　漏えいが起きても、被害者が事業者の過失を証明するのは困難である。そのため無過失責任として被害者の救済を確実にする<br><br><b>答案に書くなら</b>　貯留事業者等は、漏えい等による損害について過失を立証されなくても賠償責任を負う無過失責任を負う。<br><br><b>関連</b>　賠償義務者は損害発生時の貯留事業者等。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の留意点に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000038\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【CCS事業法（二酸化炭素の貯留事業に関する法律）｜課題】CCSの課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　注入CO2が長期に安定して貯蔵され漏えいがないことの確認が要り、モニタリング・閉鎖措置の詳細設計が必要<br><br><b>解説</b>　CO2は地下に長期間とどまることが前提で、漏えいがないと確認できなければ温暖化対策の意味が薄れる。そのため監視と閉鎖措置の設計が課題になる<br><br><b>答案に書くなら</b>　技術の観点から、課題は注入したCO2が長期に安定して貯蔵され漏えいがないことの確認であり、モニタリング・閉鎖措置の詳細設計が必要なことである。<br><br><b>関連</b>　詳細は省令・ガイドラインで整理されている。<br><br><b>答案での使い方</b>　Ⅱ-1の課題。観点名を明記して書く<br><br>【出典】<a href=\"https://www.env.go.jp/council/content/i_18/000393953.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【CCS事業法（二酸化炭素の貯留事業に関する法律）｜解決策】CCSの漏えいリスクへの解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　貯留層の温度・圧力等の監視と報告を義務づけ、漏えい時は直ちに応急措置、閉鎖措置を確認して廃止を許可する<br><br><b>解説</b>　漏えいを早く見つけ、起きたら被害を拡げない手順を法で決めておく。注入後も監視・報告を義務づけ、廃止は安全確認後にのみ許可する<br><br><b>答案に書くなら</b>　技術・保安の観点から、解決策は貯留層の温度・圧力等の監視と報告を義務づけ、漏えい時は直ちに応急措置を講じ、閉鎖措置を確認して廃止を許可することである。<br><br><b>関連</b>　応急措置は法第48条、閉鎖措置の確認は第53条。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 保安面の解決策に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000038\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【CCS事業法（二酸化炭素の貯留事業に関する法律）｜注意】海底下CCSの許可は、海洋汚染等防止法と本法のどちらか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　本法に一元化され、経産大臣と環境大臣の共管となった<br><br><b>解説</b>　従来は海洋汚染等防止法の許可で海底下CCSを扱っていたが、事業の許可と保安を一体で扱うため、CCS事業法に一元化された<br><br><b>答案に書くなら</b>　海底下CCSの許可は本法に一元化されており、経済産業大臣と環境大臣の共管である。<br><br><b>関連</b>　海洋汚染等防止法の許可制度は本法へ一元化された（旧制度と混同しない）。<br><br><b>答案での使い方</b>　旧制度（海洋汚染等防止法の許可）と混同しない<br><br>【出典】<a href=\"https://www.env.go.jp/council/content/i_18/000393953.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【水素社会推進法｜時期】水素社会推進法の施行状況は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　令和6年法律第37号。2024年5月公布、2024年10月23日に施行済み。所管は経済産業省<br><br><b>解説</b>　水素社会推進法は令和6年法律第37号で、2024年5月に公布され10月23日に施行済み。所管は経産省で、価格差支援などの具体策は施行後に動いている<br><br><b>答案に書くなら</b>　水素社会推進法は2024年10月23日に施行済みであり、経済産業省が所管する。<br><br><b>関連</b>　施行後5年を目途に検討する規定がある。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで「施行済み」と示す<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000037\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【水素社会推進法｜定義】「低炭素水素等」とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　水素とアンモニア・合成メタン・合成燃料等で、製造時のCO2排出量が一定値以下と認められるもの（法第2条）<br><br><b>解説</b>　水素は燃やしてもCO2が出ないが、作る段階で出る場合がある。そこで製造時のCO2排出量が一定値以下のものだけを支援対象とする<br><br><b>答案に書くなら</b>　低炭素水素等とは、水素とアンモニア・合成メタン・合成燃料等であって、製造時のCO2排出量が一定値以下と認められるものをいう。<br><br><b>関連</b>　具体の化合物種と排出量の値は経産省令に委任されている。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000037\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【水素社会推進法｜制度】水素社会推進法の計画認定の仕組みは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　供給・利用事業者が計画を作り、主務大臣が認定。価格差支援は両者連名の共同計画で、供給の継続が要件<br><br><b>解説</b>　作る側だけ支援しても使う側がいないと続かず、逆も同じ。そこで供給と利用の両事業者が連名の共同計画を作って主務大臣が認定する<br><br><b>答案に書くなら</b>　供給・利用事業者が計画を作り主務大臣が認定する。価格差支援は両者連名の共同計画で、供給が継続することが要件である。<br><br><b>関連</b>　計画は単独でも共同でも作れる。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。需給一体で支援する点を書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000037\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【水素社会推進法｜制度】水素社会推進法の支援の実施主体は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　JOGMECが、継続的な供給に必要な資金や共用設備整備の資金として、認定事業者へ助成金を交付する<br><br><b>解説</b>　国が直接交付する形ではなく、専門機関のJOGMECを通じて助成する。助成を受けるのは認定を受けた事業者である<br><br><b>答案に書くなら</b>　支援の実施主体はJOGMECであり、認定事業者に対し、継続的な供給に必要な資金や共用設備整備の資金として助成金を交付する。<br><br><b>関連</b>　助成の根拠は法第10条。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。国が直接交付と書かない<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000037\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【水素社会推進法｜課題】低炭素水素等の課題を『制度・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　大規模な利用ニーズの創出と、サプライチェーン構築に資する拠点の整備、保安規制の合理化が必要<br><br><b>解説</b>　低炭素水素は使う場所と作る場所が離れやすく、設備や保安の規制も壁になる。需要と供給網と規制の3点がそろって初めて自立する<br><br><b>答案に書くなら</b>　制度・運用の観点から、課題は大規模な利用ニーズの創出、サプライチェーン構築に資する拠点の整備、保安規制の合理化が必要なことである。<br><br><b>関連</b>　価格差の課題もある。<br><br><b>答案での使い方</b>　Ⅱ-1の課題。観点名を明記して書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000037\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【水素社会推進法｜解決策】供給拠点づくりの解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　拠点整備支援（助成）と、港湾法・高圧ガス保安法・道路占用の特例を、規制緩和と一体で進める<br><br><b>解説</b>　拠点を作るには資金と規制の壁がある。そこで助成と、港湾法・高圧ガス保安法・道路占用の特例をセットで進める<br><br><b>答案に書くなら</b>　制度の観点から、解決策は拠点整備支援（助成）と、港湾法・高圧ガス保安法・道路占用の特例を規制緩和と一体で進めることである。<br><br><b>関連</b>　特例は法第四章に置かれている。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 制度面の解決策に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000037\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【水素社会推進法｜解決策】国際サプライチェーンの解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　炭素集約度で評価する基準を日本が主導して策定し、国際標準と相互認証の認証スキームの構築を進める<br><br><b>解説</b>　水素等は国際的に取引されるため、製造方法ごとのCO2排出量を測る共通のものさしが必要になる<br><br><b>答案に書くなら</b>　国際面の観点から、解決策は炭素集約度で評価する基準を日本が主導して策定し、国際標準と相互認証の認証スキームの構築を進めることである。<br><br><b>関連</b>　認証スキームの構築は進められている段階で、国際サプライチェーンの活発化に向けた整備が要る。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 国際面の解決策に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000037\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【水素社会推進法｜注意】水素社会推進法の対象は水素だけか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　水素だけでなく、アンモニア・合成メタン・合成燃料等を含む「水素等」<br><br><b>解説</b>　対象を水素だけとすると誤り。アンモニアや合成メタン、合成燃料も含めて「水素等」と呼び、これらが脱炭素化の難しい分野の燃料・原料になる<br><br><b>答案に書くなら</b>　本法の対象は水素だけでなく、アンモニア・合成メタン・合成燃料等を含む水素等である。<br><br><b>関連</b>　支援の実施主体はJOGMEC（国が直接交付するのではない）。<br><br><b>答案での使い方</b>　対象を水素のみと書くと減点<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000037\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ペロブスカイト太陽電池（次世代型太陽電池戦略）｜時期】次世代型太陽電池戦略はいつ策定され、どの計画に目標が反映されたか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2024年11月に官民協議会が策定。第7次エネルギー基本計画とGX2040ビジョン（2025年2月）に目標を反映<br><br><b>解説</b>　日本はフィルム型の研究で世界をリードしてきたが、中国が量産に動いている。そこで官民協議会が2024年11月に戦略を作り、国の計画に目標を反映した<br><br><b>答案に書くなら</b>　次世代型太陽電池戦略は2024年11月に官民協議会が策定し、第7次エネルギー基本計画とGX2040ビジョンに目標が反映された。<br><br><b>関連</b>　GX2040ビジョンは2025年2月に閣議決定。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで時期と位置づけを示す<br><br>【出典】<a href=\"https://www.nedo.go.jp/content/800032923.pdf\" target=\"_blank\" rel=\"noopener\">NEDO（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ペロブスカイト太陽電池（次世代型太陽電池戦略）｜定義】ペロブスカイト太陽電池とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　軽量・柔軟で、従来のシリコン系では難しかった耐荷重性の低い屋根や壁面にも設置できる次世代型太陽電池<br><br><b>解説</b>　シリコン系は重く硬く、耐荷重性の低い屋根や壁面には置けなかった。軽く曲がる電池ならそうした場所も使え、日本の適地制約を和らげる<br><br><b>答案に書くなら</b>　ペロブスカイト太陽電池とは、軽量・柔軟で、耐荷重性の低い屋根や壁面にも設置できる次世代型太陽電池である。<br><br><b>関連</b>　日本はフィルム型の研究開発で世界をリードしてきた。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.nedo.go.jp/content/800032923.pdf\" target=\"_blank\" rel=\"noopener\">NEDO（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ペロブスカイト太陽電池（次世代型太陽電池戦略）｜目標】ペロブスカイト太陽電池の発電コスト目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2025年20円/kWh、2030年14円/kWh、2040年に自立化可能な10〜14円/kWh以下<br><br><b>解説</b>　量産とコスト低減を年次で示し、民間が投資判断できるようにしている。単位は円/kWhで、コストが下がるほど補助なしで普及する<br><br><b>答案に書くなら</b>　発電コストの目標は、2025年20円/kWh、2030年14円/kWh、2040年に自立化可能な10〜14円/kWh以下である。<br><br><b>関連</b>　数字は技術確立の目標で、実際の販売価格や発電実績ではない。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の数字。年次とセットで書く<br><br>【出典】<a href=\"https://www.nedo.go.jp/content/800032923.pdf\" target=\"_blank\" rel=\"noopener\">NEDO（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ペロブスカイト太陽電池（次世代型太陽電池戦略）｜注意】ペロブスカイト太陽電池の「約20GW」は何の目標か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2040年の導入目標。2030年の目標は導入量ではなく、GW級の量産体制と14円/kWh<br><br><b>解説</b>　量の目標（GW）と、コストや量産体制の目標は年次によって違う。20GWは最終年次の2040年の導入量<br><br><b>答案に書くなら</b>　約20GWは2040年の導入目標であり、2030年の目標は導入量ではなくGW級の量産体制と14円/kWhである。<br><br><b>関連</b>　政府施設の導入目標（2035年50〜70MW・2040年100MW以上）は別の数字。<br><br><b>答案での使い方</b>　年次の取り違えは減点。2030年は量産体制と書く<br><br>【出典】<a href=\"https://www.nedo.go.jp/content/800032923.pdf\" target=\"_blank\" rel=\"noopener\">NEDO（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ペロブスカイト太陽電池（次世代型太陽電池戦略）｜課題】ペロブスカイト太陽電池の課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　長期に安定した性能を保つ耐久性の確立、製品サイズへの大型化・モジュール化、発電コストの低減が必要<br><br><b>解説</b>　新しい電池は、屋外で長期に使える耐久性、大きなサイズの製品化、価格の3点がそろわないと実用化できない<br><br><b>答案に書くなら</b>　技術の観点から、課題は長期に安定した性能を保つ耐久性の確立、製品サイズへの大型化・モジュール化、発電コストの低減が必要なことである。<br><br><b>関連</b>　GI基金の計画もこの3点を課題として整理している。<br><br><b>答案での使い方</b>　Ⅱ-1の課題。観点名を明記して書く<br><br>【出典】<a href=\"https://www.nedo.go.jp/content/800032923.pdf\" target=\"_blank\" rel=\"noopener\">NEDO（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ペロブスカイト太陽電池（次世代型太陽電池戦略）｜課題】ペロブスカイト太陽電池の課題を『産業競争力』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　中国など諸外国の研究開発・量産化が激化し、製品化と市場獲得の速度が競争力を左右する<br><br><b>解説</b>　日本が先行した技術でも、量産と市場獲得で負ければ産業にならない。中国など諸外国が研究開発・量産化を急いでおり、速度が競争力を左右する<br><br><b>答案に書くなら</b>　産業競争力の観点から、課題は中国など諸外国の研究開発・量産化が激化し、製品化と市場獲得の速度が競争力を左右することである。<br><br><b>関連</b>　戦略は「規模とスピード」を掲げる。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 経済・産業の観点の課題に<br><br>【出典】<a href=\"https://www.nedo.go.jp/content/800032923.pdf\" target=\"_blank\" rel=\"noopener\">NEDO（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ペロブスカイト太陽電池（次世代型太陽電池戦略）｜解決策】技術課題への解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　GI基金で量産技術と社会実証を支援し、2030年に14円/kWhを目指す。タンデム型の開発も加速する<br><br><b>解説</b>　GI基金は、民間だけでは難しい研究開発と実証を国が支える仕組み。タンデム型は別の材料と重ねて発電効率を上げる方式で、将来の効率向上の鍵になる<br><br><b>答案に書くなら</b>　技術の観点から、解決策はGI基金で量産技術と社会実証を支援して2030年に14円/kWhを目指し、タンデム型の開発も加速することである。<br><br><b>関連</b>　タンデム型は変換効率30%以上が目標。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 技術面の解決策に<br><br>【出典】<a href=\"https://www.nedo.go.jp/content/800032923.pdf\" target=\"_blank\" rel=\"noopener\">NEDO（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ペロブスカイト太陽電池（次世代型太陽電池戦略）｜解決策】初期需要づくりの解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　政府機関・自治体・環境価値を重視する民間企業が初期需要を牽引し、導入補助で投資の予見性を確保する<br><br><b>解説</b>　新技術は最初は高く需要が小さい。そこで政府機関・自治体・環境価値を重視する民間企業が先に買い、補助で投資の予見性を確保して量産を後押しする<br><br><b>答案に書くなら</b>　需要面の観点から、解決策は政府機関・自治体・環境価値を重視する民間企業が初期需要を牽引し、導入補助で投資の予見性を確保することである。<br><br><b>関連</b>　導入補助は2025年度から始まっている。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 需要面の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000389653.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【洋上風力のEEZ拡大（再エネ海域利用法改正）｜時期】再エネ海域利用法の改正の公布と施行はいつ？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2025年6月11日公布、2026年4月1日施行（施行済み）。閣議決定は2025年3月7日<br><br><b>解説</b>　再エネ海域利用法の改正は2025年6月11日公布、2026年4月1日施行で、現在は施行済み。2025年3月7日の閣議決定は法案を決めた日で、公布・施行とは別<br><br><b>答案に書くなら</b>　改正再エネ海域利用法は2025年6月に公布、2026年4月1日に施行済みであり、EEZでの洋上風力の設置が許可制の対象になった。<br><br><b>関連</b>　閣議決定（2025年3月7日）と取り違えない。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで施行済みと示す。閣議決定と混同しない<br><br>【出典】<a href=\"https://www.mlit.go.jp/report/press/port01_hh_000291.html\" target=\"_blank\" rel=\"noopener\">国土交通省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【洋上風力のEEZ拡大（再エネ海域利用法改正）｜定義】EEZへの洋上風力拡大とは何が変わったのか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　従来は領海・内水のみが対象。改正でEEZでの設置を許可する制度と、海洋環境保全のため国が調査する仕組みを新設<br><br><b>解説</b>　EEZ（排他的経済水域）は領海の外側の海域。従来の法は領海と内水にしか適用されず、EEZの設置ルールがなかった。改正で許可制度と、海洋環境保全のための国の調査が新設された<br><br><b>答案に書くなら</b>　EEZへの拡大とは、従来の領海・内水に限られた洋上風力の対象を広げ、EEZでの設置を許可する制度と国による海洋環境調査を新設したことである。<br><br><b>関連</b>　案件形成目標の達成が目的。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.mlit.go.jp/report/press/port01_hh_000291.html\" target=\"_blank\" rel=\"noopener\">国土交通省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【洋上風力のEEZ拡大（再エネ海域利用法改正）｜制度】EEZでの設置許可の流れは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　経産大臣が募集区域を指定→申請→経産・国交大臣が仮許可（5年以内）→協議会→許可<br><br><b>解説</b>　沖合は先行利用者や環境への影響が大きいため、国が区域を決めて募集し、仮許可で確認してから許可する二段階にしている<br><br><b>答案に書くなら</b>　経産大臣が募集区域を指定し、申請を受けて経産・国交大臣が仮許可（5年以内）を出し、協議会での協議を経て許可する二段階審査である。<br><br><b>関連</b>　許可の有効期間は法が数値を定めず個別に定める。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。二段階審査と書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/430AC0000000089\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【洋上風力のEEZ拡大（再エネ海域利用法改正）｜目標】洋上風力の案件形成目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2030年までに1,000万kW、2040年までに3,000万〜4,500万kW<br><br><b>解説</b>　洋上風力は2030年と2040年で段階的に増やす計画で、数字を取り違えやすい。EEZを開くのも、この目標に届かせるため<br><br><b>答案に書くなら</b>　洋上風力の案件形成目標は、2030年までに1,000万kW、2040年までに3,000万〜4,500万kWである。<br><br><b>関連</b>　2030年と2040年を取り違えない。<br><br><b>答案での使い方</b>　Ⅱ-1の数字。2030年と2040年を取り違えない<br><br>【出典】<a href=\"https://www.mlit.go.jp/report/press/port01_hh_000291.html\" target=\"_blank\" rel=\"noopener\">国土交通省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【洋上風力のEEZ拡大（再エネ海域利用法改正）｜課題】EEZ洋上風力の課題を『制度・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　漁業・航路・港湾・系統との調整。許可基準に漁業・航路への支障がないこと、基地港湾の利用、電線路との接続がある<br><br><b>解説</b>　沖合でも漁場、船の航路、港湾、送電網との関係は避けて通れない。法は許可基準にこれらへの支障がないことを入れて調整する<br><br><b>答案に書くなら</b>　制度・運用の観点から、課題は漁業・航路・港湾・系統との調整であり、許可基準に漁業・航路への支障がないこと、基地港湾の利用、電線路との接続が置かれている。<br><br><b>関連</b>　先行利用者との調整は協議会が担う。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅲ 先行利用者との調整の観点の課題に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/430AC0000000089\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【洋上風力のEEZ拡大（再エネ海域利用法改正）｜課題】EEZ洋上風力の課題を『環境』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　区域指定の前に海洋環境の情報を把握すること。このため環境大臣が募集区域の海洋環境を調査し、結果を踏まえて区域を指定する仕組みが新設された<br><br><b>解説</b>　従来の再エネ海域利用法は領海・内水だけが対象で、EEZで区域ごとに海洋環境を調べる仕組みがなかった。改正で、環境大臣が調査して結果を経産大臣に通知・公表し、それを受けて区域を指定する<br><br><b>答案に書くなら</b>　環境の観点から、課題は、沖合の募集区域で海洋環境の情報を事前に把握し、区域指定に適切に反映することである。<br><br><b>関連</b>　調査を担うのは環境大臣。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅲ 環境影響の観点の課題に<br><br>【出典】<a href=\"https://www.mlit.go.jp/report/press/port01_hh_000291.html\" target=\"_blank\" rel=\"noopener\">国土交通省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【洋上風力のEEZ拡大（再エネ海域利用法改正）｜解決策】利害関係者の調整の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　協議会で利害関係者を含め協議し、その結果を尊重する。仮許可と許可の二段階審査で事業の確実性を担保<br><br><b>解説</b>　沖合の海は多くの人が使っており、一度に全員の合意を取るのは難しい。そこで協議の場を作って尊重し、仮許可・許可の二段階審査で、実行できる案件に絞る<br><br><b>答案に書くなら</b>　合意形成の観点から、解決策は協議会で利害関係者を含めて協議してその結果を尊重し、仮許可と許可の二段階審査で事業の確実性を担保することである。<br><br><b>関連</b>　協議会は両大臣が組織する。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅲ 合意形成の解決策に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/430AC0000000089\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【洋上風力のEEZ拡大（再エネ海域利用法改正）｜注意】領海・内水とEEZでは、洋上風力の仕組みは同じか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　別。領海・内水は「促進区域」（公募占用計画の認定）、EEZは「募集区域」（仮許可→許可）。EEZの許可は経産・国交の共管<br><br><b>解説</b>　領海・内水の制度は先に作られ、EEZは改正で新しく加わった別の仕組み。用語が似ているが、公募方式も許可権者も違う<br><br><b>答案に書くなら</b>　領海・内水は促進区域（公募占用計画の認定）、EEZは募集区域（仮許可から許可）であり、EEZの許可は経産・国交両大臣の共管である。<br><br><b>関連</b>　環境大臣は調査を担う。<br><br><b>答案での使い方</b>　用語の取り違えは減点。環境大臣は調査を担う<br><br>【出典】<a href=\"https://www.mlit.go.jp/kowan/content/001879078.pdf\" target=\"_blank\" rel=\"noopener\">国土交通省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【二国間クレジット制度（JCM）｜時期】JCMのパートナー国は何か国か（2026年5月時点）？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　32か国（2026年5月29日時点）。2013年1月のモンゴルとの署名に始まり、法制化は令和6年の温対法改正<br><br><b>解説</b>　JCMは2013年1月のモンゴルとの署名に始まり、パートナー国が広がってきた。令和6年の温対法改正で法制化され、登録簿と指定実施機関が法に規定された<br><br><b>答案に書くなら</b>　JCMのパートナー国は2026年5月29日時点で32か国であり、2013年1月のモンゴルとの署名に始まる。<br><br><b>関連</b>　直近の追加はオマーン（2026年4月）。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで現状を示す<br><br>【出典】<a href=\"https://www.env.go.jp/content/000377659.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【二国間クレジット制度（JCM）｜定義】JCMとは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　日本とパートナー国が協力して実施した対策による排出削減・吸収量を、両国の貢献度に応じて配分する仕組み<br><br><b>解説</b>　途上国での対策に日本が技術・資金で協力し、得られた削減量を両国で分け合う。日本はNDCに計上でき、相手国は排出削減のための技術導入が進む<br><br><b>答案に書くなら</b>　JCMとは、日本とパートナー国が協力して実施した対策による排出削減・吸収量を、両国の貢献度に応じて配分する仕組みである。<br><br><b>関連</b>　パリ協定第6条2項に整合する制度。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000377659.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【二国間クレジット制度（JCM）｜目標】JCMの削減量の目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　官民連携で2030年度までの累積1億t-CO2程度、2040年度までの累積2億t-CO2程度<br><br><b>解説</b>　日本の排出削減目標の一部を、海外での削減で積み増す計画。官民連携で年度ごとに累積量を目標にしている<br><br><b>答案に書くなら</b>　JCMの削減量目標は、官民連携で2030年度までの累積1億t-CO2程度、2040年度までの累積2億t-CO2程度である。<br><br><b>関連</b>　地球温暖化対策計画とNDCに位置づく。<br><br><b>答案での使い方</b>　Ⅱ-1の数字。「累積」「年度まで」を落とさない<br><br>【出典】<a href=\"https://www.env.go.jp/content/000377659.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【二国間クレジット制度（JCM）｜制度】JCMの「相当調整」とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　日本が無効化した量を日本の排出量から差し引き、同量をパートナー国の排出量に上乗せして二重計上を防ぐ<br><br><b>解説</b>　同じ削減量を日本と相手国の双方が数えると二重計上になる。そこで日本が無効化した量を日本の排出量から差し引き、同量を相手国の排出量に上乗せして調整する<br><br><b>答案に書くなら</b>　相当調整とは、日本が無効化した量を日本の排出量から差し引き、同量をパートナー国の排出量に上乗せして二重計上を防ぐ仕組みである。<br><br><b>関連</b>　クレジットを取消すとNDCに計上されない。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。パリ協定第6条の肝<br><br>【出典】<a href=\"https://www.env.go.jp/content/000377659.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【二国間クレジット制度（JCM）｜制度】JCMのクレジット量はどう算定するか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　BaU排出量を十分に下回る「リファレンス排出量」と比較して保守的に算定し、両国政府が承認する<br><br><b>解説</b>　何もしない場合（BaU）より少なく見積もると、削減量が水増しになる。そこで基準を十分に下回るリファレンス排出量を使って控えめに算定し、両国が承認する<br><br><b>答案に書くなら</b>　クレジット量はBaU排出量を十分に下回るリファレンス排出量と比較して保守的に算定し、両国政府が承認する。<br><br><b>関連</b>　第6条の手続でクレジット移転量を承認する。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。環境十全性の根拠<br><br>【出典】<a href=\"https://www.env.go.jp/content/000377659.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【二国間クレジット制度（JCM）｜課題】JCMの課題を『環境十全性』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　二重計上の防止と保守的算定の確保。相手国のインベントリの整備状況によっては、削減量が反映されない場合がある<br><br><b>解説</b>　削減量が過大だったり二重に数えられたりすると、地球全体の排出は減らない。これを防ぐのが環境十全性で、相手国の排出量の把握体制も関わる<br><br><b>答案に書くなら</b>　環境十全性の観点から、課題は二重計上の防止と保守的算定の確保であり、相手国のインベントリの整備状況によっては削減量が反映されない場合がある。<br><br><b>関連</b>　解決は相当調整と第6条報告で担保。<br><br><b>答案での使い方</b>　Ⅱ-1の課題。観点名を明記して書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000377659.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【二国間クレジット制度（JCM）｜解決策】JCMの事務の効率化の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　指定実施機関（JCMA）が多数の国と同時に調整し、クレジット発行までの事務をワンストップ化する<br><br><b>解説</b>　多くの国と同時に進めると手続きが膨らむ。温対法の改正で指定実施機関を規定し、公益財団法人地球環境センターがJCMAとして指定されている<br><br><b>答案に書くなら</b>　運用面の観点から、解決策は指定実施機関（JCMA）が多数の国と同時に調整し、クレジット発行までの事務をワンストップ化して効率化・迅速化することである。<br><br><b>関連</b>　根拠は令和6年の温対法改正。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 運用面の解決策に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/410AC0000000117\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【二国間クレジット制度（JCM）｜注意】JCMの1億tと2億tは、単年の削減量か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　単年ではない。1億tは2030年度までの累積、2億tは2040年度までの累積<br><br><b>解説</b>　2030年度や2040年度は期限で、それまでに積み上げる累積量の目標。毎年の削減量と読み違えると、規模感が大きく狂う<br><br><b>答案に書くなら</b>　JCMの1億tは2030年度までの累積、2億tは2040年度までの累積であり、単年の削減量ではない。<br><br><b>関連</b>　「累積」「年度まで」を落とさない。<br><br><b>答案での使い方</b>　数字の読み違えは減点。累積と書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000377659.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【SSBJ基準と有価証券報告書での開示義務化｜時期】SSBJ基準の有報での義務化はいつからか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　プライム市場の平均時価総額3兆円以上は2027年3月期、1兆円以上は2028年3月期、5,000億円以上は2029年3月期（予定）<br><br><b>解説</b>　開示義務は、時価総額が大きい企業から順に広げる。プライム市場の平均時価総額（過去5事業年度末の平均）で3段階に分け、準備期間を確保する<br><br><b>答案に書くなら</b>　SSBJ基準の義務化は、プライム市場の平均時価総額3兆円以上が2027年3月期、1兆円以上が2028年3月期、5,000億円以上が2029年3月期（予定）である。<br><br><b>関連</b>　5,000億円未満は今後検討。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで段階適用と時期を示す<br><br>【出典】<a href=\"https://www.fsa.go.jp/news/r7/shouken/20260220/20260220.html\" target=\"_blank\" rel=\"noopener\">金融庁を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【SSBJ基準と有価証券報告書での開示義務化｜定義】SSBJ基準とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　日本初のサステナビリティ開示基準。ISSB基準を踏まえ、サステナビリティ基準委員会が2025年3月に公表<br><br><b>解説</b>　有価証券報告書のサステナビリティ記載は、比較可能性と有用性に課題があった。そこで国際基準（ISSB基準）を踏まえ、日本の基準を作った<br><br><b>答案に書くなら</b>　SSBJ基準とは、ISSB基準を踏まえてサステナビリティ基準委員会が2025年3月に公表した、日本初のサステナビリティ開示基準である。<br><br><b>関連</b>　原則としてISSB基準の要求事項をすべて取り入れる。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.ssb-j.jp/jp/wp-content/uploads/sites/6/2026_07.pdf\" target=\"_blank\" rel=\"noopener\">SSBJ（サステナビリティ基準委員会）（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【SSBJ基準と有価証券報告書での開示義務化｜制度】SSBJ基準を構成する3つの基準は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　ユニバーサル基準「適用基準」、第1号「一般開示基準」、第2号「気候関連開示基準」<br><br><b>解説</b>　共通のルールを置く適用基準と、全テーマに共通の一般開示基準、気候テーマの基準で構成する。気候関連はその中の1つである<br><br><b>答案に書くなら</b>　SSBJ基準は、ユニバーサル基準の適用基準、テーマ別第1号の一般開示基準、同第2号の気候関連開示基準の3つで構成される。<br><br><b>関連</b>　2025年3月5日に3基準を公表。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。構成を1文で言う<br><br>【出典】<a href=\"https://www.ssb-j.jp/jp/wp-content/uploads/sites/6/2026_07.pdf\" target=\"_blank\" rel=\"noopener\">SSBJ（サステナビリティ基準委員会）（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【SSBJ基準と有価証券報告書での開示義務化｜制度】義務化の経過措置と保証の定めは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　義務化の翌年から第三者保証。最初の2年は訂正報告書での記載（二段階開示）、スコープ3は初年度免除<br><br><b>解説</b>　企業には算定・開示の準備が必要で、第三者保証も体制づくりに時間がかかる。そこで、最初の2年は訂正報告書での記載を認め、保証は義務化の翌年から始める<br><br><b>答案に書くなら</b>　義務化の翌年から第三者保証を義務づけ、最初の2事業年度は訂正報告書での記載（二段階開示）を認め、スコープ3は初年度免除とする。<br><br><b>関連</b>　保証の範囲は当初2年間は限定。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の留意点。段階的導入の根拠<br><br>【出典】<a href=\"https://www.fsa.go.jp/singi/singi_kinyu/tosin/20260108/02.pdf\" target=\"_blank\" rel=\"noopener\">金融庁（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【SSBJ基準と有価証券報告書での開示義務化｜課題】SSBJ義務化の課題を『技術・信頼性』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　開示の比較可能性・有用性の向上と、第三者保証がなければ確保しにくい信頼性<br><br><b>解説</b>　開示情報は企業ごとに差が出やすく、保証がないと投資家が信頼しにくい。そのため比較可能性・有用性と信頼性の確保が課題になる<br><br><b>答案に書くなら</b>　技術・信頼性の観点から、課題は開示の比較可能性・有用性の向上と、第三者保証がなければ確保しにくい信頼性の確保である。<br><br><b>関連</b>　有報の記載欄は2023年から。<br><br><b>答案での使い方</b>　Ⅱ-1の課題。観点名を明記して書く<br><br>【出典】<a href=\"https://www.fsa.go.jp/singi/singi_kinyu/tosin/20260108/02.pdf\" target=\"_blank\" rel=\"noopener\">金融庁（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【SSBJ基準と有価証券報告書での開示義務化｜課題】SSBJ義務化の課題を『担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　保証業務の実施者の確保。監査法人以外にも登録の道を開く必要がある<br><br><b>解説</b>　保証には専門性が必要で、担える機関が限られると義務化に支障が出る。従来は監査法人が中心だったため、担い手の裾野を広げる必要がある<br><br><b>答案に書くなら</b>　担い手の観点から、課題は保証業務の実施者の確保であり、監査法人以外にも登録の道を開く必要がある。<br><br><b>関連</b>　保証業務実施者は登録制（法人）。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 人材の観点の課題に<br><br>【出典】<a href=\"https://www.fsa.go.jp/singi/singi_kinyu/tosin/20260108/02.pdf\" target=\"_blank\" rel=\"noopener\">金融庁（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【SSBJ基準と有価証券報告書での開示義務化｜解決策】開示の信頼性の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　国際基準と整合する保証基準で第三者保証を義務づけ、保証業務実施者を登録制にする<br><br><b>解説</b>　国際的に通用する保証にするため、国際基準と整合する保証基準を用い、担い手は登録制にして質を担保する<br><br><b>答案に書くなら</b>　制度面の観点から、解決策は国際基準と整合する保証基準で第三者保証を義務づけ、保証業務実施者を登録制にして開示の信頼性を確保することである。<br><br><b>関連</b>　国際基準にはISSA5000がある。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 制度面の解決策に<br><br>【出典】<a href=\"https://www.fsa.go.jp/singi/singi_kinyu/tosin/20260108/02.pdf\" target=\"_blank\" rel=\"noopener\">金融庁（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【SSBJ基準と有価証券報告書での開示義務化｜注意】SSBJ基準は法令そのものか？義務化はいつ保証までか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　法令ではない。金融庁長官の告示指定で有報の基準になる。最初の義務化は2027年3月期で、保証はその翌年<br><br><b>解説</b>　SSBJ基準は民間の基準設定主体が作った基準で、そのままでは法的効力がない。金融庁長官が告示で指定すると、有報で従うべき基準になる<br><br><b>答案に書くなら</b>　SSBJ基準は法令そのものではなく、金融庁長官の告示指定により有報の基準となり、最初の義務化は2027年3月期、保証はその翌年である。<br><br><b>関連</b>　2026年3月に3基準を改正（2027年1月1日以後開始の期間から適用）。<br><br><b>答案での使い方</b>　基準の位置づけと保証の時期を取り違えない<br><br>【出典】<a href=\"https://www.fsa.go.jp/news/r7/shouken/20260220/20260220.html\" target=\"_blank\" rel=\"noopener\">金融庁を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【トランジション・ファイナンス｜時期】クライメート・トランジション・ファイナンスに関する基本指針はいつ策定・改訂されたか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2021年に策定、2025年3月に改訂（2025年版）。金融庁・経産省・環境省が策定<br><br><b>解説</b>　基本指針は2021年に策定され、国際資本市場協会（ICMA）のハンドブック改訂などを受けて2025年3月に改訂された。金融庁・経産省・環境省の3省庁が策定する<br><br><b>答案に書くなら</b>　クライメート・トランジション・ファイナンスに関する基本指針は2021年に策定され、2025年3月に改訂された2025年版が現行である。<br><br><b>関連</b>　2026年8月の検討会で改訂の項目が立てられている。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで最新版を示す<br><br>【出典】<a href=\"https://www.env.go.jp/content/000304405.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【トランジション・ファイナンス｜定義】トランジション・ファイナンスとは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　気候変動対策を検討する企業が長期戦略に沿ってGHG削減に取り組む場合に、その取組を支える金融手法。長期戦略の信頼性に着目<br><br><b>解説</b>　排出削減が難しい産業の移行には、個別の使途だけでなく、企業の長期戦略への資金が要る。そこで企業レベルの長期戦略の信頼性に着目して、資金供給を後押しする<br><br><b>答案に書くなら</b>　トランジション・ファイナンスとは、長期戦略に沿ってGHG削減に取り組む企業の取組を支える金融手法であり、長期戦略の信頼性に着目する点が特徴である。<br><br><b>関連</b>　2050年カーボンニュートラルとパリ協定に整合する移行が前提。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000304405.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【トランジション・ファイナンス｜制度】基本指針が資金調達者に開示を推奨する4要素は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　①戦略とガバナンス②環境面のマテリアリティ③科学的根拠に基づく戦略と目標④実施の透明性<br><br><b>解説</b>　資金を出す側が、企業の戦略が本物かを見極める手がかりが必要。そこで4つの要素の開示を推奨し、国際原則とそろえる<br><br><b>答案に書くなら</b>　資金調達者に、戦略とガバナンス、環境面のマテリアリティ、科学的根拠に基づく戦略と目標、実施の透明性の4要素の開示を推奨する。<br><br><b>関連</b>　ICMAのハンドブックと整合する。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。ICMAハンドブックと整合<br><br>【出典】<a href=\"https://www.env.go.jp/content/000304405.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【トランジション・ファイナンス｜制度】分野別技術ロードマップはどの分野を対象にしているか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　鉄鋼・化学・電力・ガス・石油・紙パルプ・セメント・自動車に海運・航空を加えた10分野。日本の排出量の8割強<br><br><b>解説</b>　資金供給側が個別企業の戦略を評価するのは大変なため、分野ごとの道筋を国が示す。鉄鋼・化学など排出の多い産業を中心に、国交省策定の海運・航空を加えた10分野で、日本の排出量の8割強をカバーする<br><br><b>答案に書くなら</b>　分野別技術ロードマップは10分野を対象とし、資金調達者の戦略策定と資金供給者の評価の参照先となる。<br><br><b>関連</b>　基本指針は対象産業を限定しない。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。評価の参照先として書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000304405.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【トランジション・ファイナンス｜課題】トランジション・ファイナンスの課題を『経済・金融』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　実行した金融機関の投融資先の排出量（ファイナンスド・エミッション）が、一時的に増加する<br><br><b>解説</b>　排出の多い企業に融資すれば、その企業の排出が金融機関の投融資先の排出量として積み上がる。移行を支える融資は、短期的には金融機関の数字を悪化させることがある<br><br><b>答案に書くなら</b>　経済・金融の観点から、課題は実行した金融機関の投融資先の排出量（ファイナンスド・エミッション）が一時的に増加することである。<br><br><b>関連</b>　2023年に考え方を公表している。<br><br><b>答案での使い方</b>　Ⅱ-1の課題。観点名を明記して書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000304405.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【トランジション・ファイナンス｜課題】トランジション・ファイナンスの課題を『信頼性』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　国際的な共通認識の醸成は途上で、信頼性の確保のため良質な事例の積み上げが重要<br><br><b>解説</b>　トランジション・ファイナンスは、国際的な関心が高まる一方、定義を様々な機関が整理しており、共通認識の形成は途上である<br><br><b>答案に書くなら</b>　信頼性の観点から、課題は国際的な共通認識の醸成が途上であり、信頼性の確保のため良質な事例の積み上げが重要なことである。<br><br><b>関連</b>　資金供給者による戦略評価の難しさも課題。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 制度・信頼性の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000304405.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【トランジション・ファイナンス｜解決策】信頼性確保の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　4要素の開示を求めてICMAハンドブックと整合を図り、フォローアップガイダンスで資金供給後の確認を整える<br><br><b>解説</b>　資金が出た後に戦略が実行されなければ意味がない。そこで開示要素を示して国際原則とそろえ、資金供給後の確認方法も整える<br><br><b>答案に書くなら</b>　制度面の観点から、解決策は4要素の開示を求めてICMAハンドブックと整合を図り、フォローアップガイダンスで資金供給後の確認を整えることである。<br><br><b>関連</b>　フォローアップガイダンスは2023年。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 制度面の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000304405.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【トランジション・ファイナンス｜注意】クライメート・トランジション利付国債は、基本指針と同じ枠組みか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　別枠組み。2024年2月に国が発行を始めた世界初の国によるトランジションボンド<br><br><b>解説</b>　国のトランジションボンドは、国が移行債でリーディングマーケットを作る別の取組である。基本指針は民間の資金調達の考え方で、役割が違う<br><br><b>答案に書くなら</b>　クライメート・トランジション利付国債は基本指針とは別枠組みで、2024年2月に国が発行を始めた世界初の国によるトランジションボンドである。<br><br><b>関連</b>　基本指針は金融庁・経産省・環境省が策定。<br><br><b>答案での使い方</b>　基本指針（金融庁・経産省・環境省）と混同しない<br><br>【出典】<a href=\"https://www.fsa.go.jp/singi/transition_finance/siryou/20260821/014_03_00.pdf\" target=\"_blank\" rel=\"noopener\">金融庁（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【熱中症特別警戒情報｜時期】熱中症特別警戒情報はいつから運用され、発表実績は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2024年4月（改正気候変動適応法の全面施行）から運用。令和6・7年度とも発表0回<br><br><b>解説</b>　熱中症対策を気候変動適応の一分野として強化するため、2023年に改正された気候変動適応法が2024年4月に全面施行された。特別警戒情報はその時から運用されているが、基準が厳しく実績がない<br><br><b>答案に書くなら</b>　熱中症特別警戒情報は2024年4月から運用が始まっているが、令和6・7年度とも発表実績は0回である。<br><br><b>関連</b>　令和8年度も2026年8月6日時点で0回。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで運用開始時期を示す<br><br>【出典】<a href=\"https://www.wbgt.env.go.jp/about_special_alert.php\" target=\"_blank\" rel=\"noopener\">環境省 熱中症予防情報サイトを開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【熱中症特別警戒情報｜定義】熱中症特別警戒情報とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　気温が特に著しく高く、熱中症による人の健康への重大な被害が生ずるおそれがある場合に、環境大臣が発表する情報（法第19条）<br><br><b>解説</b>　警戒情報（アラート）より一段上の、重大な被害のおそれがある場合の情報。環境大臣が都道府県知事へ通知し、知事・市町村長を通じて住民へ伝わる<br><br><b>答案に書くなら</b>　熱中症特別警戒情報とは、気温が特に著しく高く、熱中症による人の健康への重大な被害が生ずるおそれがある場合に、環境大臣が発表する情報である。<br><br><b>関連</b>　根拠は気候変動適応法第19条。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/430AC0000000050\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【熱中症特別警戒情報｜制度】警戒情報と特別警戒情報の発表基準は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　警戒：府県予報区内の1地点以上で日最高WBGT33以上。特別警戒：都道府県内の全地点で35以上<br><br><b>解説</b>　警戒情報は広めに注意を促し、特別警戒は極端な場合に限る設計。地点数の条件が違うため、特別警戒は発表されにくい<br><br><b>答案に書くなら</b>　警戒情報は府県予報区内の1地点以上で日最高WBGT33以上、特別警戒情報は都道府県内の全地点で35以上と予測される場合に発表する。<br><br><b>関連</b>　WBGTは暑さ指数。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。基準と範囲を書き分ける<br><br>【出典】<a href=\"https://www.wbgt.env.go.jp/about_special_alert.php\" target=\"_blank\" rel=\"noopener\">環境省 熱中症予防情報サイトを開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【熱中症特別警戒情報｜制度】指定暑熱避難施設（クーリングシェルター）の仕組みは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　市町村長が冷房設備のある施設を指定し、特別警戒情報の発表時に開放する<br><br><b>解説</b>　暑い日に避難できる涼しい場所がないと、熱中症弱者が守れない。市町村長が冷房のある施設を指定し、特別警戒情報の発表時に開放する<br><br><b>答案に書くなら</b>　市町村長が適当な冷房設備を有する施設を指定暑熱避難施設に指定し、特別警戒情報の発表時に住民へ開放する。<br><br><b>関連</b>　管理者が開放義務を負うのは特別警戒情報の発表時で、公表した開放可能日等に限られる。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。自治体の役割として書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/430AC0000000050\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【熱中症特別警戒情報｜課題】熱中症対策の課題を『社会・担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　高齢者やこども等の熱中症弱者は自助による予防が難しく、家族や身近な人の見守り・声かけ（共助）と公助が要る<br><br><b>解説</b>　高齢者やこどもは自分で暑さを避けにくく、気づきも遅れがち。自助だけに頼れず、周囲の見守りや行政の対応が欠かせない<br><br><b>答案に書くなら</b>　社会・担い手の観点から、課題は高齢者やこども等の熱中症弱者は自助による予防が難しく、家族や身近な人の見守り・声かけ（共助）と公助が必要なことである。<br><br><b>関連</b>　熱中症対策普及団体は市町村長が指定する。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 社会・担い手の観点の課題に<br><br>【出典】<a href=\"https://www.wbgt.env.go.jp/about_special_alert.php\" target=\"_blank\" rel=\"noopener\">環境省 熱中症予防情報サイトを開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【熱中症特別警戒情報｜解決策】熱中症の共助を強める解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　熱中症対策普及団体や福祉関係団体を通じた見守り・声かけの強化と、エアコン利用の有効性の周知<br><br><b>解説</b>　共助は身近な人の見守りが基本だが、きっかけがないと広がらない。普及団体や福祉関係団体の力を借り、エアコンの有効性も周知する<br><br><b>答案に書くなら</b>　担い手面の観点から、解決策は熱中症対策普及団体や福祉関係団体を通じた見守り・声かけの強化と、エアコン利用の有効性の周知である。<br><br><b>関連</b>　普及団体は啓発・広報や相談対応を行う。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 担い手面の解決策に<br><br>【出典】<a href=\"https://www.wbgt.env.go.jp/about_special_alert.php\" target=\"_blank\" rel=\"noopener\">環境省 熱中症予防情報サイトを開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【熱中症特別警戒情報｜解決策】極端な高温時の体制整備の解決策を、専門用語で言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　指定暑熱避難施設の指定・確保と、極端な高温時の自治体内の役割分担の明確化<br><br><b>解説</b>　極端な高温の日に自治体が混乱しないよう、避難施設を確保し役割分担を事前に決めておく。市町村が住民に伝える仕組みの実効性にも関わる<br><br><b>答案に書くなら</b>　解決策は指定暑熱避難施設の指定・確保と、極端な高温時の自治体内の役割分担の明確化である。<br><br><b>関連</b>　実行計画は令和8年度を目途に見直す予定。<br><br><b>答案での使い方</b>　Ⅱ-2 自治体の手順・調整事項に<br><br>【出典】<a href=\"https://www.wbgt.env.go.jp/about_special_alert.php\" target=\"_blank\" rel=\"noopener\">環境省 熱中症予防情報サイトを開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【熱中症特別警戒情報｜注意】熱中症対策実行計画の「半減」は、何を基準にした目標か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　令和4年（概数）の5年移動平均1,295名を基準に、2030年に熱中症死亡者数を半減<br><br><b>解説</b>　熱中症の死亡者数は年ごとに変動が大きいため、5年移動平均で目標を置く。基準は令和4年（概数）の1,295名で、この数字から2030年に半減をめざす<br><br><b>答案に書くなら</b>　熱中症対策実行計画は、令和4年（概数）の5年移動平均1,295名を基準に、2030年に熱中症死亡者数を半減する目標である。<br><br><b>関連</b>　目標は2023年5月30日に閣議決定。<br><br><b>答案での使い方</b>　基準年・基準値を落とすと減点<br><br>【出典】<a href=\"https://www.wbgt.env.go.jp/about_special_alert.php\" target=\"_blank\" rel=\"noopener\">環境省 熱中症予防情報サイトを開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【気候変動影響評価報告書（第3次）｜時期】気候変動影響評価報告書の第3次はいつ公表されたか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2026年2月16日に公表。第2次は令和2年12月。おおむね5年ごとに作成する（法第10条）<br><br><b>解説</b>　気候変動適応法の定めで、おおむね5年ごとに最新の知見で評価する。第3次は2026年2月16日に公表され、第2次は令和2年12月だった<br><br><b>答案に書くなら</b>　気候変動影響評価報告書の第3次は2026年2月16日に公表され、法に基づきおおむね5年ごとに作成される。<br><br><b>関連</b>　根拠は気候変動適応法第10条。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで最新版を示す<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_02915.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【気候変動影響評価報告書（第3次）｜定義】気候変動影響評価報告書とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　気候変動適応法に基づき、最新の科学的知見でおおむね5年ごとに行う影響の総合的評価。適応計画の変更時に勘案する<br><br><b>解説</b>　適応策は、どの分野でどの程度の影響が出るかを把握して初めて立てられる。そこで科学的知見をもとに影響を総合評価し、計画の見直しに使う<br><br><b>答案に書くなら</b>　気候変動影響評価報告書とは、気候変動適応法に基づき、最新の科学的知見でおおむね5年ごとに影響を総合的に評価する報告書である。<br><br><b>関連</b>　適応計画の変更時に勘案する。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/430AC0000000050\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【気候変動影響評価報告書（第3次）｜制度】影響評価の3つの観点は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　重大性、緊急性、確信度<br><br><b>解説</b>　影響は大きさだけでなく、いつ現れるか、どれだけ確かか、で対応の優先度が変わる。そこで重大性・緊急性・確信度の3つの物差しで評価する<br><br><b>答案に書くなら</b>　影響評価は、重大性・緊急性・確信度の3つの観点で行う。<br><br><b>関連</b>　重大性は社会・経済・環境の3観点で見る。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。評価の物差しとして書く<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_02915.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【気候変動影響評価報告書（第3次）｜制度】第3次報告書の改善点は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　重大性を3段階（レベル1〜3）に細分化し、現状・1.5〜2℃上昇時・3〜4℃上昇時で評価。「特に強い影響を受ける地域・対象」を追加<br><br><b>解説</b>　影響の大きさは気温上昇の程度で変わるため、3段階に細分化し、上昇幅別に評価することで、対策の優先度が分かりやすくなる<br><br><b>答案に書くなら</b>　第3次では重大性を3段階に細分化し、現状・1.5〜2℃上昇時・3〜4℃上昇時で評価し、特に強い影響を受ける地域・対象を追加した。<br><br><b>関連</b>　最も高いレベル3は特に重大な影響が認められる。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。第2次との違い<br><br>【出典】<a href=\"https://www.env.go.jp/content/000380482.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【気候変動影響評価報告書（第3次）｜制度】第3次が特に優先的に対応が必要とした項目は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　水稲の収量・品質低下、果樹の栽培適地の変化、洪水・内水、サンゴの白化、暑熱、インフラ・ライフラインの寸断など<br><br><b>解説</b>　重大性・緊急性が高い項目は、対応を急ぐ必要がある。農業、水害、生態系、暑熱、インフラと分野をまたいで挙げられている<br><br><b>答案に書くなら</b>　第3次は水稲の収量・品質低下、果樹の栽培適地の変化、洪水・内水、サンゴの白化、暑熱、インフラ・ライフラインの寸断を優先して対応が必要な項目とした。<br><br><b>関連</b>　暑熱は熱中症による救急搬送者・死亡者数の増加。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 課題の根拠に。分野を挙げるときに<br><br>【出典】<a href=\"https://www.env.go.jp/content/000380482.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【気候変動影響評価報告書（第3次）｜課題】影響評価の課題を『科学的知見』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　適応策の効果を定量的・具体的に整理できたのは小項目全体の3割程度で、複数の適応策を比較できる知見は非常に限られる<br><br><b>解説</b>　適応策の効果を数字で示せなければ、どの策を優先するか決めにくい。第3次でも定量的・具体的に整理できたのは小項目の3割程度にとどまる<br><br><b>答案に書くなら</b>　科学的知見の観点から、課題は適応策の効果を定量的・具体的に整理できたのが小項目全体の3割程度で、複数の適応策を比較できる知見が非常に限られることである。<br><br><b>関連</b>　特に強い影響を受ける地域を整理できたのは4割程度。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 技術・知見の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000380482.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【気候変動影響評価報告書（第3次）｜解決策】評価結果をどう使うか（解決策）？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2026年度の気候変動適応計画の改定と、自治体・事業者による影響の把握・適応策の検討に活用する<br><br><b>解説</b>　評価は作って終わりではなく、国の計画と地域・事業者の判断に使われて初めて意味を持つ。2026年度に適応計画が改定される予定である<br><br><b>答案に書くなら</b>　解決策は、評価結果を2026年度の気候変動適応計画の改定に活用し、自治体・事業者による影響の把握・適応策の検討にも活用することである。<br><br><b>関連</b>　計画改定は2026年度の予定で、公表年（2026年2月）とは別。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 調査検討事項の根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000380482.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【気候変動影響評価報告書（第3次）｜注意】「80項目」とは何か？公表年と計画改定の年度は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　7分野を細分化した小項目の数で第2次より9項目増。公表は2026年2月、適応計画の改定は2026年度の予定<br><br><b>解説</b>　80項目は評価の細かさを示す数字で、7分野を細分化した小項目の数。第2次より9項目増え、細かく見る方向に進んでいる<br><br><b>答案に書くなら</b>　80項目は7分野を細分化した小項目の数で、第2次より9項目増えた。公表は2026年2月、適応計画の改定は2026年度の予定である。<br><br><b>関連</b>　公表年と改定年度を取り違えない。<br><br><b>答案での使い方</b>　数字と年度の取り違えは減点<br><br>【出典】<a href=\"https://www.env.go.jp/content/000380482.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【再資源化事業等高度化法｜時期】再資源化事業等高度化法はいつ全面施行されたか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　2025年11月21日に全面施行（一部は2025年2月1日）。公布は2024年5月29日<br><br><b>解説</b>　法は2024年5月29日に公布され、一部が2025年2月1日、全面施行が2025年11月21日と段階的に施行された。全面施行後は認定制度が動いている<br><br><b>答案に書くなら</b>　再資源化事業等高度化法は2025年11月21日に全面施行されており、認定制度が運用される段階にある。<br><br><b>関連</b>　公布日（2024年5月29日）と区別。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで施行済みと示す。公布日と区別<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000041\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【再資源化事業等高度化法｜定義】再資源化事業等高度化法とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　再資源化のための廃棄物の収集・運搬・処分と、再資源化の技術・設備の高度化を促し、GHG削減効果の高い資源循環を促進する法律<br><br><b>解説</b>　従来の廃棄物行政は適正処理が中心で、再生材の質と量を高める施策が不足していた。そこで再資源化の事業と技術・設備の高度化を促す<br><br><b>答案に書くなら</b>　再資源化事業等高度化法とは、再資源化のための廃棄物の収集・運搬・処分と技術・設備の高度化を促し、温室効果ガスの削減効果の高い資源循環を促進する法律である。<br><br><b>関連</b>　基本方針は環境大臣が策定する。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000041\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【再資源化事業等高度化法｜制度】再資源化事業等高度化法の認定3類型は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　①高度再資源化事業計画②高度分離・回収事業計画③再資源化工程高度化計画（既存施設向け）。環境大臣が認定<br><br><b>解説</b>　事業の形によって必要な支援が違うため、3つの類型に分ける。新設の事業、分離・回収の高度化、既存施設の高度化で、認定は環境大臣が行う<br><br><b>答案に書くなら</b>　認定は①高度再資源化事業計画、②高度分離・回収事業計画、③再資源化工程高度化計画（既存施設向け）の3類型で、環境大臣が認定する。<br><br><b>関連</b>　認定を受けると廃棄物処理法の許可の特例がある。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。3類型を番号で書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000041\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【再資源化事業等高度化法｜制度】判断基準と報告・公表の仕組みは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　廃棄物処分業者の判断基準を環境省令で定め、特定産業廃棄物処分業者が処分量・再資源化量を毎年度報告し、環境大臣が公表<br><br><b>解説</b>　認定を受けた事業者だけでなく、廃棄物処分業者全体の水準を引き上げる必要がある。基準を示し、処分量と再資源化量を報告・公表させる<br><br><b>答案に書くなら</b>　廃棄物処分業者の判断基準を環境省令で定め、特定産業廃棄物処分業者に処分量・再資源化量を毎年度報告させ、環境大臣が公表して全体の底上げを図る。<br><br><b>関連</b>　報告義務は処分量の多い特定産業廃棄物処分業者。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。底上げの仕組みとして書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000041\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【再資源化事業等高度化法｜課題】資源循環の課題を『制度・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　製造（動脈）と廃棄物処分（静脈）の連携。再生資源の利用目標の共有と、トレーサビリティのためのデータ連携が要る<br><br><b>解説</b>　動脈（製造）と静脈（廃棄物処分）がつながらないと、再生材が製造側の求める質・量で流れない。情報の共有とトレーサビリティも要る<br><br><b>答案に書くなら</b>　制度・運用の観点から、課題は動脈と静脈の連携であり、再生資源の利用目標の共有とトレーサビリティのためのデータ連携が必要なことである。<br><br><b>関連</b>　動脈は製造、静脈は廃棄物処分を指す。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 制度の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000360673.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【再資源化事業等高度化法｜課題】資源循環の課題を『経済・担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　製造業が求める量・質の再生材を安定供給できる事業が不足している。再資源化工程自体の脱炭素化も求められる<br><br><b>解説</b>　製造業は品質の安定した再生材を大量に求める。ところがそれに応える事業者が不足しており、再資源化の工程自体にも脱炭素化が求められる<br><br><b>答案に書くなら</b>　経済・担い手の観点から、課題は製造業が求める量・質の再生材を安定供給できる事業が不足していることであり、再資源化工程自体の脱炭素化も求められる。<br><br><b>関連</b>　目標は施行から3年間で100件以上の事業認定。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 経済の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000360673.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【再資源化事業等高度化法｜解決策】製造側と処分側をつなぐ解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　高度再資源化事業の認定で、製造側の需要に応じた質・量の再生材確保を図り、製造事業者と処分業者のマッチングを促す<br><br><b>解説</b>　製造側が求める再生材と、処分側の供給のギャップを埋める必要がある。高度再資源化事業の認定により、製造側の需要を前提とした事業を支援する<br><br><b>答案に書くなら</b>　連携面の観点から、解決策は高度再資源化事業の認定で製造側の需要に応じた質・量の再生材確保を図り、製造事業者と処分業者のマッチングを促すことである。<br><br><b>関連</b>　認定は環境大臣が国で一括して行う。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 連携面の解決策に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000041\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【再資源化事業等高度化法｜注意】認定は誰が行い、廃棄物処理法との関係は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　環境大臣が国で一括して認定し、廃掃法の許可の特例を与える。廃掃法そのものを置き換えるものではない<br><br><b>解説</b>　廃棄物処理法の許可は都道府県知事が出す。本法は環境大臣が国で一括認定し、廃掃法の許可手続の特例を与える仕組みで、廃掃法自体は残る<br><br><b>答案に書くなら</b>　認定は環境大臣が国で一括して行い、廃棄物処理法の許可に代わる特例を与えるが、廃棄物処理法そのものを置き換えるものではない。<br><br><b>関連</b>　登録調査機関が認定の調査業務を担う。<br><br><b>答案での使い方</b>　都道府県知事の認定と書くと減点<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000041\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽電池廃棄物の再資源化等の推進に関する法律｜時期】太陽電池廃棄物の再資源化等推進法は施行されているか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　令和8年法律第33号。2026年6月5日公布で未施行。施行は公布から1年6か月以内の政令日（2027年秋〜冬の予定）<br><br><b>解説</b>　本法は令和8年法律第33号で、2026年6月5日に公布された。施行日は政令で定める日で、公布から1年6か月以内。環境省は施行を2027年秋〜冬頃と見込む<br><br><b>答案に書くなら</b>　太陽電池廃棄物の再資源化等推進法は2026年6月に公布済みだが未施行であり、施行は政令で定める日である。<br><br><b>関連</b>　政省令の公布は2027年春頃の予定。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで「公布済み・未施行」と示す<br><br>【出典】<a href=\"https://www.env.go.jp/content/000404704.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽電池廃棄物の再資源化等の推進に関する法律｜定義】太陽電池廃棄物の再資源化等推進法とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　多量の事業用パネルの廃棄者からリサイクル規制を段階的に強化し、幅広い排出者への義務化に向けた環境整備を行う法律<br><br><b>解説</b>　パネルの排出量は2030年代後半以降に顕著に増え、年間最大50万t程度に達する見込みで、最終処分場の残余容量を圧迫するおそれがある。そこで排出が多い者から順に規制を強める<br><br><b>答案に書くなら</b>　太陽電池廃棄物の再資源化等推進法とは、多量の事業用パネルの廃棄者からリサイクル規制を段階的に強化し、幅広い排出者への義務化に向けた環境整備を行う法律である。<br><br><b>関連</b>　50万tは見込みで実績ではない。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000404704.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽電池廃棄物の再資源化等の推進に関する法律｜制度】義務づけの対象と、勧告・命令の対象は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　事業用パネルの廃棄者に、判断基準に基づくリサイクルの取組を義務づけ。勧告・命令の対象は多量廃棄者<br><br><b>解説</b>　全員に一律に課すのではなく、段階的に進める設計。事業用の廃棄者は基準に基づくリサイクルが義務で、勧告・命令は多量廃棄者に限る<br><br><b>答案に書くなら</b>　事業用パネルの廃棄者に判断基準に基づくリサイクルの取組を義務づけ、勧告・命令の対象は多量廃棄者とする。<br><br><b>関連</b>　指導・助言は全ての事業用廃棄者が対象。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。全面義務化と書かない<br><br>【出典】<a href=\"https://www.env.go.jp/content/000404704.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽電池廃棄物の再資源化等の推進に関する法律｜制度】多量事業用太陽電池廃棄者に課される手続は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　廃棄前に実施計画を国へ届出し、原則、受理から30日経過後でなければ排出できない<br><br><b>解説</b>　多量に出す者は、その処理が地域の処分能力を圧迫しやすい。そこで廃棄前に実施計画を届け出させて、国が事前に把握・関与できるようにする<br><br><b>答案に書くなら</b>　多量事業用太陽電池廃棄者は、廃棄前に実施計画を国へ届出し、原則として受理から30日経過後でなければ排出できない。<br><br><b>関連</b>　計画が著しく不十分なら変更等を勧告・命令。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。排出前の事前届出と書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000404704.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽電池廃棄物の再資源化等の推進に関する法律｜課題】パネルのリサイクルの課題を『技術・体制』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　専用施設の処理能力は約13万t/年で今後の排出見込量に不足し、8府県に施設がない<br><br><b>解説</b>　専用のリサイクル施設は能力も立地も足りない。2025年11月時点で専用施設は87件、処理能力は約13万t/年で、将来の排出見込みに対して不足している<br><br><b>答案に書くなら</b>　技術・体制の観点から、課題は専用施設の処理能力が約13万t/年で今後の排出見込量に不足し、8府県に施設がないことである。<br><br><b>関連</b>　パネルの種類によっては技術的・経済的に困難。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 技術・体制の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000404704.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽電池廃棄物の再資源化等の推進に関する法律｜課題】パネルのリサイクルの課題を『経済』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　埋立とリサイクルの費用差が大きい（リサイクル8,000〜12,000円/kW、埋立2,000円/kW程度〜）<br><br><b>解説</b>　埋立のほうが安いと、排出者は埋立を選びやすい。費用差が大きいと、義務づけがない限りリサイクルは進まない<br><br><b>答案に書くなら</b>　経済の観点から、課題は埋立とリサイクルの費用差が大きく、リサイクルが8,000〜12,000円/kW、埋立が2,000円/kW程度〜であることである。<br><br><b>関連</b>　6割以上の事業者は実質的にリサイクルを検討していない。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 経済の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000404704.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽電池廃棄物の再資源化等の推進に関する法律｜解決策】リサイクル促進の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　設備・保管施設の導入支援に加え、国の認定制度（廃掃法の許可の特例）で広域的・効率的な処理を進めコストを下げる<br><br><b>解説</b>　リサイクルのコストが高い主因は、処理能力の不足と手続きの重さ。設備の支援と、都道府県ごとの許可が不要になる特例でコストを下げる<br><br><b>答案に書くなら</b>　制度・設備面の観点から、解決策は設備・保管施設の導入支援に加え、国の認定制度（廃掃法の許可の特例）で広域的・効率的な処理を進めてコストを下げることである。<br><br><b>関連</b>　認定の対象は費用効率的なリサイクル事業の計画。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 制度・設備面の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000404704.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽電池廃棄物の再資源化等の推進に関する法律｜注意】この法律は、全てのパネルにリサイクルを義務づけるか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　一律ではない。義務づけは事業用の廃棄者への判断基準の取組で、住宅用を含む全面義務化は附則の検討規定にとどまる<br><br><b>解説</b>　まず多量の事業用から始め、住宅用などの幅広い排出者への義務化は、将来の課題として附則の検討規定に置いた。一律義務化と書くと誤り<br><br><b>答案に書くなら</b>　本法の義務づけは事業用の廃棄者への判断基準に基づく取組であり、住宅用を含む全面義務化は附則の検討規定にとどまる。<br><br><b>関連</b>　製造・輸入業者の環境配慮設計は努力義務。<br><br><b>答案での使い方</b>　「全パネル義務化」と書くと減点<br><br>【出典】<a href=\"https://www.env.go.jp/content/000404704.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック資源循環促進法｜時期】プラスチック資源循環促進法の施行はいつか？また見直しの時期は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　2021年6月公布、2022年4月施行。附則で施行後5年の検討を定め、2027年4月以降に見直しが可能<br><br><b>解説</b>　本法は2021年6月に公布、2022年4月に施行された。附則で施行後5年の検討を定めており、2027年4月以降に見直しが可能だが、見直しが決まったわけではない<br><br><b>答案に書くなら</b>　プラスチック資源循環促進法は2022年4月に施行済みで、附則の検討規定により2027年4月以降に見直しが可能である。<br><br><b>関連</b>　見直しは未決定。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで施行済みと示す。見直しは未決定<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/503AC0000000060\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック資源循環促進法｜定義】プラスチック資源循環促進法とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　製品の設計から廃棄物処理まで、あらゆる主体のプラスチック資源循環の取組を促す法律。3R+Renewableが基本原則<br><br><b>解説</b>　海洋プラごみ、気候変動、アジア諸国の廃棄物輸入規制を背景に、2019年にプラスチック資源循環戦略を作った。本法はその実装で、製品の設計から廃棄までの全主体を対象とする<br><br><b>答案に書くなら</b>　プラスチック資源循環促進法とは、製品の設計から廃棄物処理まで、あらゆる主体の資源循環の取組を促す法律であり、3R+Renewableが基本原則である。<br><br><b>関連</b>　戦略は2019年5月に策定された。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/503AC0000000060\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック資源循環促進法｜制度】同法の措置の5本柱は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　設計指針・認定、使用の合理化、市町村の分別収集・再商品化、自主回収・再資源化、排出事業者の排出抑制・再資源化<br><br><b>解説</b>　プラスチックのライフサイクルを、設計から排出事業者までの5段階で押さえる。製造、使用、回収、再資源化と流れに沿って措置を置く<br><br><b>答案に書くなら</b>　措置は、設計指針・認定、使用の合理化、市町村の分別収集・再商品化、自主回収・再資源化、排出事業者の排出抑制・再資源化の5本柱である。<br><br><b>関連</b>　法の章立てに対応する。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。5段階で書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/503AC0000000060\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック資源循環促進法｜制度】特定プラスチック使用製品とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　無償提供される12製品（スプーン・ストロー・ヘアブラシ・歯ブラシ・ハンガー等）。提供量5t以上の事業者が勧告等の対象<br><br><b>解説</b>　使い捨てになりやすい無償提供の製品に絞り、提供量が多い事業者から取組を求める。対象は12製品で、前年度の提供量が5トン以上の事業者が多量提供事業者となる<br><br><b>答案に書くなら</b>　特定プラスチック使用製品とは無償で提供される12製品であり、提供量5t以上の事業者が、取組が著しく不十分な場合に勧告等の対象となる。<br><br><b>関連</b>　法施行後に特定12品目の提供量は11%減った。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。12製品と5tの数字<br><br>【出典】<a href=\"https://plastic-circulation.env.go.jp/pro/gorika\" target=\"_blank\" rel=\"noopener\">環境省 プラスチック資源循環を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック資源循環促進法｜目標】プラスチック資源循環戦略のマイルストーンは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　2030年までにワンウェイプラを累積25%排出抑制、2035年までに使用済プラを100%有効利用<br><br><b>解説</b>　戦略は2019年に策定され、削減・再利用の目標を年次で示している。排出抑制は2030年、使用済みの有効利用は2035年で、年次が違う<br><br><b>答案に書くなら</b>　プラスチック資源循環戦略は、2030年までにワンウェイプラを累積25%排出抑制し、2035年までに使用済プラを100%有効利用することを掲げる。<br><br><b>関連</b>　ほかに2030年までに再生利用を倍増。<br><br><b>答案での使い方</b>　Ⅱ-1の数字。年次とセットで書く<br><br>【出典】<a href=\"https://plastic-circulation.env.go.jp/about/senryaku\" target=\"_blank\" rel=\"noopener\">環境省 プラスチック資源循環を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック資源循環促進法｜課題】プラ資源循環の課題を『制度・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　プラ資源の回収量の拡大が課題。容リ協の入札量は令和4年度約69万tから令和7年度約66万tへ微減した<br><br><b>解説</b>　リサイクルは回収量が増えなければ進まない。容リ協の入札量は令和4年度約69万tから令和7年度約66万tへ微減し、回収量の拡大が課題とされる<br><br><b>答案に書くなら</b>　制度・運用の観点から、課題はプラ資源の回収量の拡大であり、容リ協の入札量が令和4年度約69万tから令和7年度約66万tへ微減したことである。<br><br><b>関連</b>　製品プラも一括回収できる仕組みがある。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 回収の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/council/content/i_03/000433372.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック資源循環促進法｜解決策】再生材の需要づくりの解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　再生材・バイオプラの価値創出（GHG削減効果の評価、マスバランス方式）を検討し、再生プラ利用計画で需要を創出<br><br><b>解説</b>　再生材は新品より割高で、需要がなければ回収が進んでも使われない。そこで環境価値を見える化して需要を創り、再生プラ利用計画で利用を促す<br><br><b>答案に書くなら</b>　需要面の観点から、解決策は再生材・バイオプラの価値創出（GHG削減効果の評価、マスバランス方式）を検討し、再生プラ利用計画で需要を創出することである。<br><br><b>関連</b>　再生プラの利用計画提出は2027年度から。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 需要面の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/council/content/i_03/000433372.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック資源循環促進法｜注意】特定プラ12品目の要件と、レジ袋有料化との関係は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　要件は「無償提供」。レジ袋有料化（2020年7月）は本法施行（2022年4月）より前の別の施策<br><br><b>解説</b>　レジ袋は2020年7月から有料化され、本法の施行（2022年4月）より前の別施策。12品目は有料のものではなく、無償提供が要件である<br><br><b>答案に書くなら</b>　特定プラスチック使用製品12品目の要件は無償提供であり、レジ袋有料化（2020年7月）は本法施行（2022年4月）より前の別の施策である。<br><br><b>関連</b>　有償提供品や時期を取り違えない。<br><br><b>答案での使い方</b>　有償提供品や時期を取り違えない<br><br>【出典】<a href=\"https://plastic-circulation.env.go.jp/pro/gorika\" target=\"_blank\" rel=\"noopener\">環境省 プラスチック資源循環を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【食品ロス削減推進法と2030年度目標｜時期】食品ロス削減推進法と基本方針の時期は？また最新推計は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　法は2019年5月公布・10月施行。基本方針は2025年3月閣議決定。最新推計は令和6年度（2026年6月公表）<br><br><b>解説</b>　食品ロス削減推進法は国・自治体・事業者・消費者の責務を定め、政府が基本方針で数値目標を置く法律。推計は年度ごとに更新されるため年度を明記する<br><br><b>答案に書くなら</b>　食品ロス削減推進法は2019年10月に施行され、2025年3月閣議決定の基本方針の下、令和6年度推計が最新である。<br><br><b>関連</b>　10月は食品ロス削減月間、10月30日は食品ロス削減の日。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで最新版を示す<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/501AC1000000019\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【食品ロス削減推進法と2030年度目標｜定義】食品ロスとは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　まだ食べることができるのに廃棄される食品（可食部）。食品廃棄物全体とは別（法第2条第2項）<br><br><b>解説</b>　食品ロスは食べられるのに捨てられた分（可食部）だけを指し、食べられない部分も含む食品廃棄物全体とは範囲が違う<br><br><b>答案に書くなら</b>　食品ロスとは、まだ食べることができるのに廃棄される食品であり、食品廃棄物全体とは区別される。<br><br><b>関連</b>　SDGsは2030年までに世界全体の一人当たり食料廃棄の半減を掲げる。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/501AC1000000019\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【食品ロス削減推進法と2030年度目標｜目標】基本方針が定める食品ロス削減の2030年度目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　家庭系は2000年度比で半減、事業系は2000年度比で60%削減<br><br><b>解説</b>　基本方針（2025年3月）は2000年度を基準に、家庭系と事業系で削減率を変えて総量目標を置いている。家庭系は早期達成も求める<br><br><b>答案に書くなら</b>　基本方針は2030年度までに2000年度比で家庭系を半減、事業系を60%削減する目標を掲げている。<br><br><b>関連</b>　目標値は家庭系433万tから216万t、事業系547万tから219万t。<br><br><b>答案での使い方</b>　Ⅱ-1の数字。家庭系と事業系の割合を書き分ける<br><br>【出典】<a href=\"https://www.env.go.jp/content/000408175.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【食品ロス削減推進法と2030年度目標｜制度】令和6年度の食品ロス発生量は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　461万t（事業系237万t、家庭系224万t）。前年度の464万tから約3万t減<br><br><b>解説</b>　発生量は農林水産省・環境省が毎年度推計し、事業系と家庭系に分けて公表する。最新は令和6年度で、年度を取り違えると数字が変わる<br><br><b>答案に書くなら</b>　令和6年度の食品ロス発生量は461万tで、事業系237万t、家庭系224万tである。<br><br><b>関連</b>　前年度比で事業系は約6万t増、家庭系は約9万t減。<br><br><b>答案での使い方</b>　Ⅱ-1の数字。年度とセットで書く<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05155.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【食品ロス削減推進法と2030年度目標｜課題】食品ロス削減の課題を『事業系』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　外食産業の食品ロスが増加傾向で、令和6年度は事業系全体が前年度比で増えた<br><br><b>解説</b>　事業系の内訳は食品製造業46%、外食産業30%、食品小売業20%、卸売業4%。外食産業の増加が全体を押し上げた<br><br><b>答案に書くなら</b>　事業系の観点から、課題は外食産業の食品ロスが増加傾向にあり、令和6年度は事業系全体が前年度比で増えたことである。<br><br><b>関連</b>　事業系では食品製造業110万tが最大の内訳。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 事業系の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05155.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【食品ロス削減推進法と2030年度目標｜課題】食品ロス削減の課題を『家庭系』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　削減率48.3%で半減目標に届かず、直接廃棄と食べ残しが大半を占める<br><br><b>解説</b>　家庭系の内訳は直接廃棄43%、食べ残し41%、過剰除去16%。削減率は2024年度時点で48.3%<br><br><b>答案に書くなら</b>　家庭系の観点から、課題は削減率が48.3%で半減目標に届かず、直接廃棄と食べ残しが大半を占めることである。<br><br><b>関連</b>　事業系の削減率は56.7%で、家庭系と事業系は進み方が違う。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 家庭系の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05155.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【食品ロス削減推進法と2030年度目標｜解決策】食品ロス削減の解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　外食の食べ残し持ち帰り（mottECO）の導入支援と、デコ活による家庭の行動変容の後押し<br><br><b>解説</b>　mottECOは外食での食べ残し持ち帰りの導入手引きと伴走支援の事業。デコ活は家庭の行動変容を後押しする取組で、事業系と家庭系に対応する<br><br><b>答案に書くなら</b>　解決策として、事業系は外食の食べ残し持ち帰り（mottECO）の導入を支援し、家庭系はデコ活で行動変容を後押しする。<br><br><b>関連</b>　自治体向けにフードドライブ実施の手引きや取組事例集（29事例）がある。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 事業系・家庭系の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05155.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【食品ロス削減推進法と2030年度目標｜注意】令和5年度と令和6年度の食品ロス量、世界目標と国内目標の違いは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　令和5年度464万t、令和6年度461万t（最新）。世界は一人当たり食料廃棄の半減、国内は2000年度比の総量<br><br><b>解説</b>　令和5年度と6年度は値が違い、削減率も年度で変わる。また世界目標と国内目標は対象が別（世界は一人当たり、国内は総量）<br><br><b>答案に書くなら</b>　最新は令和6年度の461万tであり、世界の一人当たり食料廃棄の半減目標と国内の2000年度比の総量目標は別物である。<br><br><b>関連</b>　2024年度は発生量全体で旧目標（2000年度比半減）を達成した。<br><br><b>答案での使い方</b>　年度と目標の母集団を取り違えない<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05155.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域生物多様性増進法と自然共生サイト｜時期】地域生物多様性増進法はいつ施行されたか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　2024年4月公布、2025年4月1日施行（施行済み）。主務大臣は環境・農林水産・国土交通大臣<br><br><b>解説</b>　増進法は企業等による増進活動を促すため、基本方針・計画認定・許可手続の特例を設けた法律。2024年4月19日公布、2025年4月1日施行<br><br><b>答案に書くなら</b>　地域生物多様性増進法は2025年4月1日に施行済みで、環境・農林水産・国土交通の3大臣が主務大臣である。<br><br><b>関連</b>　平成22年の旧法は本法の附則で廃止された。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで施行済みと示す<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000018\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域生物多様性増進法と自然共生サイト｜定義】OECMとは何か？自然共生サイトとの関係は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　OECMは保護地域以外で生物多様性の保全に資する管理が行われている区域。自然共生サイトはその日本版を国が認定する制度<br><br><b>解説</b>　OECMは保護地域ではないが、民間の取組等で生物多様性が保たれている区域。自然共生サイトは国が認定し、保護地域と重複しない部分が国際データベースに登録される<br><br><b>答案に書くなら</b>　OECMとは保護地域以外で生物多様性の保全に資する区域であり、自然共生サイトはその日本版として国が認定する制度である。<br><br><b>関連</b>　自然共生サイトとOECMは同一ではない。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000018\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域生物多様性増進法と自然共生サイト｜制度】地域生物多様性増進法の仕組みは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　基本方針と、増進活動実施計画の認定制度。認定活動は自然公園法・森林法等の許可・届出の特例（ワンストップ化）を受ける<br><br><b>解説</b>　許認可が複数の法律にまたがる活動を、認定1回で進めやすくする仕組み。事業者は増進活動実施計画を作り主務大臣が認定する<br><br><b>答案に書くなら</b>　制度の中身は、主務大臣が基本方針を定め、増進活動実施計画を認定し、認定活動には自然公園法・森林法等の許可・届出の特例（ワンストップ化）を設けることである。<br><br><b>関連</b>　土地所有者等全員の合意で生物多様性維持協定を結べる。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。認定と特例の2点を書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000018\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域生物多様性増進法と自然共生サイト｜制度】自然共生サイトの累計認定数は？（2026年10月時点）", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　700か所（2026年10月30日の令和8年度第2回認定で到達。法施行前の328か所を含む累計）<br><br><b>解説</b>　自然共生サイトは2023年度に認定を開始し、2024年度までに328か所、2025年4月から法定の認定に移行した。累計は法施行前を含む<br><br><b>答案に書くなら</b>　自然共生サイトは2026年10月30日の認定で累計700か所に達し、法施行前の328か所を含む累計である。<br><br><b>関連</b>　令和8年度の認定数（第2回の122か所など）とは数え方が別。<br><br><b>答案での使い方</b>　Ⅱ-1の数字。累計の起点を明示する<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05720.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域生物多様性増進法と自然共生サイト｜課題】30by30の課題を『制度・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　30by30は主にOECMの設定で達成する計画だが、OECMは陸域で0.2%にとどまる（2026年8月時点）<br><br><b>解説</b>　30by30は保護地域とOECMで陸と海の30%以上を保全する目標。計画は主にOECMの設定で達成する方針だが、OECMの面積が伸びていない<br><br><b>答案に書くなら</b>　制度・運用の観点から、課題は30by30を主にOECMの設定で達成する計画だが、OECMが陸域で0.2%にとどまることである。<br><br><b>関連</b>　保護地域の拡張も国立公園等の候補地14か所で調整が進行中。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 制度の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05386.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域生物多様性増進法と自然共生サイト｜課題】生物多様性の取組の課題を『技術・科学』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　生物多様性の状況と保全活動の効果の「見える化」が必要。見える化システムで国土全体の状況を可視化している<br><br><b>解説</b>　保全活動の効果や生物多様性の状況が見えないと、優先地域の判断や活動の評価がしにくい。国土全体を可視化する見える化システムを運用している<br><br><b>答案に書くなら</b>　技術・科学の観点から、課題は生物多様性の状況と保全活動の効果を見える化する必要があることである。<br><br><b>関連</b>　2026年度に30by30ロードマップの中間評価を実施する。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05386.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域生物多様性増進法と自然共生サイト｜解決策】OECMを増やす解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　自然共生サイトの認定を進め、保護地域との重複を除いてOECM国際データベースに登録する。支援証明書制度で企業の参画を促す<br><br><b>解説</b>　OECMの登録は、自然共生サイトを認定し、保護地域と重複する部分を除いて国際データベースに載せる流れ。支援証明書は支援した企業等に発行される<br><br><b>答案に書くなら</b>　解決策として、自然共生サイトの認定を進めて保護地域と重複しない区域をOECM国際データベースに登録し、支援証明書制度で企業の参画を促す。<br><br><b>関連</b>　支援証明書は2025年9月から本格運用。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 30by30の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05720.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域生物多様性増進法と自然共生サイト｜注意】自然共生サイトとOECMは同じか？保護地域との合計割合は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　同じではない。国際DBへの登録は保護地域と重複しない区域のみ。合計は陸域約21.0%、海域約13.3%で目標30%未満<br><br><b>解説</b>　自然共生サイトは国の認定、OECM登録は重複を除いた区域のみ。保護地域とOECMを合わせても目標の30%に届いていない<br><br><b>答案に書くなら</b>　自然共生サイトとOECMは同一ではなく、保護地域とOECMの合計は陸域約21.0%、海域約13.3%で目標の30%に届いていない。<br><br><b>関連</b>　OECMの登録面積は2026年8月時点で累計64.6千ha。<br><br><b>答案での使い方</b>　定義の書き分けで減点を避ける<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05386.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ネイチャーポジティブ経済移行戦略｜時期】ネイチャーポジティブ経済移行戦略はいつ誰が策定したか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　2024年3月に環境省・農水省・経産省・国交省が策定。2025年7月にロードマップ（2025-2030年）を策定<br><br><b>解説</b>　生物多様性国家戦略2023-2030の基本戦略3の重点施策で、企業が自然資本の保全を経営に組み込むのを後押しする。策定主体は4省庁<br><br><b>答案に書くなら</b>　ネイチャーポジティブ経済移行戦略は2024年3月に環境・農水・経産・国交の4省庁が策定し、2025年7月にロードマップ（2025-2030年）が策定された。<br><br><b>関連</b>　戦略は法律ではなく4省庁の戦略。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで策定主体と時期を示す<br><br>【出典】<a href=\"https://www.env.go.jp/content/000298927.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ネイチャーポジティブ経済移行戦略｜定義】ネイチャーポジティブ経営とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　自然資本の保全を価値創造のマテリアリティに据えて、ネイチャーポジティブを目指す経営。実現した経営の意味ではない<br><br><b>解説</b>　マテリアリティは企業にとって重要な経営課題のこと。ネイチャーポジティブは生物多様性の損失を止めて反転させる考え方で、経営は「目指す」姿勢を指す<br><br><b>答案に書くなら</b>　ネイチャーポジティブ経営とは、自然資本の保全を価値創造プロセスのマテリアリティに据え、ネイチャーポジティブを目指す経営である。<br><br><b>関連</b>　実現した経営という意味ではない（戦略の脚注）。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000298927.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ネイチャーポジティブ経済移行戦略｜制度】ネイチャーポジティブ移行による2030年のビジネス機会は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　世界で年1,372兆円（WEF2020年推計）、日本では環境省試算で年47兆円<br><br><b>解説</b>　世界経済フォーラム（WEF）の2020年推計を日本に当てはめて環境省が試算した値で、いずれも2030年時点で増える機会額。うち4分の3以上が炭素中立・循環経済と強く関連する<br><br><b>答案に書くなら</b>　ネイチャーポジティブ移行による2030年のビジネス機会は、世界で年1,372兆円、日本では環境省試算で年47兆円と見込まれる。<br><br><b>関連</b>　世界では年約368兆円の投資が必要とされる。<br><br><b>答案での使い方</b>　Ⅱ-1の数字。世界と日本を書き分ける<br><br>【出典】<a href=\"https://www.env.go.jp/content/000298927.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ネイチャーポジティブ経済移行戦略｜制度】国の施策の4つの構成は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　①リスク・機会の認識②機会の特定・創出③開示・対話を通じた資金呼び込み④基盤環境整備（DX・研究開発）<br><br><b>解説</b>　国の施策は、認識、機会創出、資金呼び込み、基盤整備の順に企業の移行を後押しする構成<br><br><b>答案に書くなら</b>　国の施策は、リスク・機会の認識、機会の特定・創出、開示・対話を通じた資金呼び込み、DX・研究開発等の基盤環境整備の4つで構成される。<br><br><b>関連</b>　戦略の3本柱（ビジネス機会の具体例、押さえる要素、国の施策）とは別の整理。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。4段階で書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000298927.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ネイチャーポジティブ経済移行戦略｜課題】ネイチャーポジティブの課題を『技術・評価』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　自然資本への負荷を定量評価する指標・手法の整備が途上で、効果の見える化と、場所に紐づくデータが必要<br><br><b>解説</b>　自然資本は場所ごとに状態が異なるため、負荷を測る指標・手法の整備が追いついていない。効果の見える化と場所に紐づくデータが要る<br><br><b>答案に書くなら</b>　技術・評価の観点から、課題は自然資本への負荷を定量評価する指標・手法が途上で、効果の見える化と場所に紐づくデータが必要なことである。<br><br><b>関連</b>　評価手法の基本的な考え方を2026年3月に作成している。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000298927.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ネイチャーポジティブ経済移行戦略｜課題】ネイチャーポジティブの課題を『制度・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　自然資本の保全・再生が他の課題より劣後されがち。経団連調査（2022年度）で25%の企業が事業との関連性がわからないと回答<br><br><b>解説</b>　自然資本の保全・再生は他の課題より後回しにされがちで、国外の自然資本への依存が大きく危機を感じにくい。企業の認識不足が背景にある<br><br><b>答案に書くなら</b>　制度・運用の観点から、課題は保全・再生が劣後されがちで、経団連調査（2022年度）で25%の企業が事業との関連性がわからないと回答したことである。<br><br><b>関連</b>　国外の自然資本への依存も課題に挙がる。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 企業認識の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000298927.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ネイチャーポジティブ経済移行戦略｜解決策】企業の取組を促す解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　TNFD等による開示の促進と、調達ガイドライン（2026年7月）・ネイチャーファイナンス実践ガイドライン（同9月）の普及<br><br><b>解説</b>　TNFDは自然関連の情報開示の枠組み。ガイドラインは調達と投融資それぞれの実践を示す任意の指針で、法的拘束力はない<br><br><b>答案に書くなら</b>　解決策として、TNFD等による開示を促し、調達ガイドライン（2026年7月）とネイチャーファイナンス実践ガイドライン（同9月）を普及させる。<br><br><b>関連</b>　TNFDアダプター企業数は日本が219社で世界最多（2026年3月）。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 開示・金融の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/pdf/full.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ネイチャーポジティブ経済移行戦略｜注意】年1,372兆円と年47兆円の違い、戦略と法律・ロードマップの関係は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　1,372兆円は世界、47兆円は日本。戦略は4省庁の戦略で法律ではなく、ロードマップは別文書<br><br><b>解説</b>　1,372兆円は世界、47兆円は日本で、母集団が違う。戦略は4省庁の戦略で法律ではなく、ロードマップは別の文書<br><br><b>答案に書くなら</b>　年1,372兆円は世界、年47兆円は日本の2030年のビジネス機会であり、戦略は法律ではなくロードマップは別文書である。<br><br><b>関連</b>　ロードマップは2025年7月の策定で、期間は2025-2030年。<br><br><b>答案での使い方</b>　数字は母集団とセットで書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000298927.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【クマ類の指定管理鳥獣追加と緊急銃猟｜時期】クマ類の指定管理鳥獣追加と緊急銃猟の規定はいつか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　クマ類（四国を除く）の追加は2024年4月。緊急銃猟の規定は令和7年法律第28号で、2025年9月1日施行<br><br><b>解説</b>　ヒグマ・ツキノワグマの分布が人の生活圏周辺まで拡大して人身被害が増え、ニホンジカ・イノシシに続き指定管理鳥獣に追加された。四国の個体群は絶滅のおそれから対象外<br><br><b>答案に書くなら</b>　クマ類は2024年4月に指定管理鳥獣に追加され、緊急銃猟の規定は2025年9月1日に施行済みである。<br><br><b>関連</b>　緊急銃猟の条文は鳥獣保護管理法第34条の2〜6。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで時期を示す。四国個体群は除く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/414AC0000000088\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【クマ類の指定管理鳥獣追加と緊急銃猟｜定義】指定管理鳥獣とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　希少鳥獣以外で集中的かつ広域的な管理が必要として環境大臣が指定する鳥獣。都道府県または国が捕獲等事業を実施できる<br><br><b>解説</b>　希少鳥獣以外で、集中的かつ広域的な管理が必要な鳥獣を環境大臣が指定する仕組み。実施計画に位置付ければ、捕獲の禁止などの特例が受けられる<br><br><b>答案に書くなら</b>　指定管理鳥獣とは、集中的かつ広域的な管理が必要として環境大臣が指定する鳥獣で、都道府県または国が捕獲等事業を実施できる。<br><br><b>関連</b>　認定鳥獣捕獲等事業者制度とは別の制度。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/414AC0000000088\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【クマ類の指定管理鳥獣追加と緊急銃猟｜目標】クマ被害の現状を示す数字は？（令和7年度）", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　人身被害216件・被害者238人・死亡13人（速報値の年度計、いずれも過去最多）<br><br><b>解説</b>　クマの分布域は拡大し、ヒグマの推定個体数は令和5年度に12,180頭と30年間で2倍以上になった。被害の大きさが対策強化の根拠<br><br><b>答案に書くなら</b>　クマ被害は令和7年度に人身被害216件・被害者238人・死亡13人と、いずれも過去最多であり、対策の緊急性は高い。<br><br><b>関連</b>　数字は速報値の年度計で、年度途中の値とは単純比較できない。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 課題の大きさを示す数字に<br><br>【出典】<a href=\"https://www.env.go.jp/nature/choju/effort/effort12/effort12.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【クマ類の指定管理鳥獣追加と緊急銃猟｜制度】緊急銃猟の4要件は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　危険鳥獣の侵入（おそれ含む）、人の生命・身体への危害防止の緊急性、銃猟以外が困難、弾丸到達のおそれなし<br><br><b>解説</b>　緊急銃猟は市街地等での危険な状況に限り、市町村長の判断で銃猟を実施させる制度。住民の安全確保が前提のため要件が厳しい<br><br><b>答案に書くなら</b>　緊急銃猟は、危険鳥獣の侵入（おそれ含む）、人の生命・身体への危害防止の緊急性、銃猟以外が困難、弾丸到達のおそれなしの4要件をすべて満たす場合に実施できる。<br><br><b>関連</b>　ガイドラインは2025年7月に公表（2026年4月改訂）。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。4要件すべて必要と書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/414AC0000000088\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【クマ類の指定管理鳥獣追加と緊急銃猟｜制度】クマ被害対策ロードマップ（2026年3月）の2030年度目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　緊急対応体制の確保率100%、推定個体数・捕獲目標数の明確化率100%、ゾーニング管理計画の策定率100%<br><br><b>解説</b>　ロードマップは2030年度までの計画で、体制確保・個体数把握・ゾーニングの3点を自治体ごとに100%とする目標。恒常的生息域の自治体が対象<br><br><b>答案に書くなら</b>　クマ被害対策ロードマップは2030年度までに、緊急対応体制の確保率、推定個体数・捕獲目標数の明確化率、ゾーニング管理計画の策定率をいずれも100%とする。<br><br><b>関連</b>　策定は2026年3月27日。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。3つの100%<br><br>【出典】<a href=\"https://www.env.go.jp/nature/choju/reinforce/index.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【クマ類の指定管理鳥獣追加と緊急銃猟｜課題】クマ対策の課題を『技術・科学』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　個体数管理のため、統一的な手法による個体数推定と捕獲目標数の精緻化が必要<br><br><b>解説</b>　個体数の推定方法が地域でばらつくと、捕獲目標数を科学的に決められない。ロードマップは個体数調査・推定を東北から全国へ広げる方針<br><br><b>答案に書くなら</b>　技術・科学の観点から、課題は個体数管理のため統一的な手法による個体数推定と捕獲目標数の精緻化が必要なことである。<br><br><b>関連</b>　統一的な個体数推定はクマ被害対策パッケージ（2025年11月）にも含まれる。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/council/content/i_09/000378789.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【クマ類の指定管理鳥獣追加と緊急銃猟｜解決策】出没防止と緊急対応の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　誘引物（放任果樹等）の管理、はこわな・電気柵の整備、ゾーニング管理計画の作成支援、緊急銃猟の体制整備<br><br><b>解説</b>　被害を減らすには、人里に引き寄せない出没防止と、出没時の緊急対応の両面が要る。ゾーニングは人とクマの生息域を分けて管理する考え方<br><br><b>答案に書くなら</b>　解決策として、放任果樹等の誘引物の管理、はこわな・電気柵の整備、ゾーニング管理計画の作成支援、緊急銃猟の体制整備を進める。<br><br><b>関連</b>　人材面ではガバメントハンターの人件費支援や捕獲技術者の養成がある。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 自治体施策の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/nature/choju/reinforce/index.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【クマ類の指定管理鳥獣追加と緊急銃猟｜注意】緊急銃猟を実施させる主体は誰か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　市町村長（都道府県ではない）。通行制限・避難指示、応援要請、損失補償も市町村長が行う<br><br><b>解説</b>　緊急銃猟は住民に最も近い市町村長が迅速に判断する仕組み。都道府県は応援要請を受ける側で、実施主体ではない<br><br><b>答案に書くなら</b>　緊急銃猟を実施させる主体は市町村長であり、通行制限・避難指示、都道府県知事への応援要請、損失補償も市町村長が行う。<br><br><b>関連</b>　4要件はすべて満たす必要がある。<br><br><b>答案での使い方</b>　実施主体の取り違えは減点<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/414AC0000000088\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【外来生物法の2022年改正｜時期】外来生物法の2022年改正の公布と施行はいつか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　2022年5月18日公布。2022年7月1日に規制権限の拡充、2023年4月1日にその他が施行（全面施行済み）<br><br><b>解説</b>　ヒアリの侵入防止強化と、広く飼育されるアカミミガメ等への規制手法の整備が改正の柱。施行は2段階で、全面施行済み<br><br><b>答案に書くなら</b>　外来生物法の2022年改正は同年5月18日に公布され、2022年7月に規制権限の拡充、2023年4月にその他が施行され、全面施行済みである。<br><br><b>関連</b>　ヒアリ類の指定は2023年4月1日、対処指針の施行は同6月1日。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで施行済みと示す。2段階を落とさない<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/416AC0000000078\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【外来生物法の2022年改正｜定義】要緊急対処特定外来生物とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　まん延すると著しく重大な被害が生じ、発見時に検査・防除等を緊急に行う必要があるものとして政令で定める生物。ヒアリ類を指定<br><br><b>解説</b>　特定外来生物の中でも、まん延すると著しく重大な被害が出て、発見時に緊急対応が要る種を政令で指定する区分。ヒアリを含むトフシアリ属4種群と交雑種が該当<br><br><b>答案に書くなら</b>　要緊急対処特定外来生物とは、まん延すると著しく重大な被害が生じ、発見時に検査・防除等を緊急に行う必要があるとして政令で定める生物で、ヒアリ類が指定されている。<br><br><b>関連</b>　ヒアリは特定外来生物でもある。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/416AC0000000078\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【外来生物法の2022年改正｜制度】要緊急対処特定外来生物の主務大臣の権限は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　通関後も物品・土地・施設への立入検査、消毒・廃棄命令、移動の制限・禁止命令ができる<br><br><b>解説</b>　通常の特定外来生物では通関後の検査権限が弱いため、要緊急対処種については主務大臣の権限を強めた。水際で止めきれない場合の備え<br><br><b>答案に書くなら</b>　要緊急対処特定外来生物については、主務大臣が通関後も物品等・土地・施設への立入検査、消毒・廃棄命令、移動の制限・禁止命令を行える。<br><br><b>関連</b>　事業者向けの対処指針（ヒアリ類に係る対処指針）に従わない場合は勧告・命令の対象。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。水際強化の根拠<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/416AC0000000078\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【外来生物法の2022年改正｜制度】条件付特定外来生物とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　アカミミガメとアメリカザリガニ（2023年6月指定）。家庭での飼養と少数への無償譲渡は適用除外。販売・購入・放出は原則禁止<br><br><b>解説</b>　アカミミガメ（幼体はミドリガメ）とアメリカザリガニは全国に定着し家庭で広く飼育されているため、通常の全面禁止とは別の線引きにした<br><br><b>答案に書くなら</b>　条件付特定外来生物はアカミミガメとアメリカザリガニの2種で、家庭での飼養と少数への無償譲渡は適用除外とし、販売・購入・野外放出は原則禁止である。<br><br><b>関連</b>　指定は2023年6月1日。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。規制の線引きを書く<br><br>【出典】<a href=\"https://www.env.go.jp/nature/intro/2outline/regulation/jokentsuki.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【外来生物法の2022年改正｜課題】条件付き規制にした理由（課題）は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　全て禁止にすると手続きの負担から野外放出が増えるおそれがある。終生飼養と放出禁止の周知が必要<br><br><b>解説</b>　全面禁止にすると手続きの負担を嫌った飼育者が野外に放出するおそれがある。そのため、飼育は認めつつ放出を禁じる設計にした<br><br><b>答案に書くなら</b>　制度・運用の観点から、課題は全て禁止にすると手続きの負担から野外放出が増えるおそれがあり、終生飼養と放出禁止を周知する必要があることである。<br><br><b>関連</b>　被害予防三原則は「入れない・捨てない・拡げない」。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 制度・運用の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/nature/intro/2outline/regulation/jokentsuki.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【外来生物法の2022年改正｜課題】ヒアリ対策の課題を『技術・水際』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　輸入品に付着して非意図的に侵入する生物が増え、ヒアリの確認は2025年度に36件で過去最多。探知・検査の高度化が要る<br><br><b>解説</b>　ヒアリは輸入品に付着して非意図的に侵入する。2017年の初確認以降、毎年港湾等で発見され、2025年度は確認件数が過去最多となった<br><br><b>答案に書くなら</b>　技術・水際の観点から、課題は輸入品に付着して侵入する生物が増え、ヒアリの確認が2025年度に36件と過去最多で、探知・検査の高度化が要ることである。<br><br><b>関連</b>　累計は20都道府県で171事例（2025年度時点）。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 水際の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/pdf/full.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【外来生物法の2022年改正｜解決策】水際対策の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　全国65港湾でのモニタリング・駆除と、ヒアリ探知犬など新たな対策技術の実証<br><br><b>解説</b>　港湾はヒアリの主な侵入口で、定期的なモニタリングと駆除で定着を防ぐ。探知犬など新しい技術の実証は令和8年度の取組<br><br><b>答案に書くなら</b>　解決策として、全国65港湾でのモニタリング・駆除と、ヒアリ探知犬など新たな対策技術の実証を進める。<br><br><b>関連</b>　環境省ウェブサイトとコールセンターで規制内容や終生飼養を周知する。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 水際施策の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/pdf/full.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【外来生物法の2022年改正｜注意】条件付特定外来生物は、法律上、特定外来生物ではないのか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　特定外来生物のまま。適用除外は飼養・譲渡しの一部で、放出・輸入・販売・頒布・購入は原則禁止のまま<br><br><b>解説</b>　条件付特定外来生物は特定外来生物の一部規制を種ごとに適用除外としたもので、特定外来生物の地位は変わらない。放出・輸入・販売等は禁止のまま<br><br><b>答案に書くなら</b>　条件付特定外来生物も法律上は特定外来生物であり、適用除外は飼養・譲渡しの一部に限られ、放出・輸入・販売・頒布・購入は原則禁止である。<br><br><b>関連</b>　アメリカザリガニ以外の外国産ザリガニは全種が通常の特定外来生物。<br><br><b>答案での使い方</b>　「規制対象外」と書くと減点<br><br>【出典】<a href=\"https://www.env.go.jp/nature/intro/2outline/regulation/jokentsuki.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【PFOS・PFOAの水道水質基準化｜時期】PFOS・PFOAの水質基準化はいつか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　2025年6月30日公布、2026年4月1日施行（施行済み）。水質基準52項目の1つとなった<br><br><b>解説</b>　PFOS・PFOAは2020年に水質管理目標設定項目（暫定目標値50ng/L）だったが、食品安全委員会の2024年6月の評価を踏まえ水質基準へ格上げされた。施行日は対応期間を確保するため公布から遅らせた<br><br><b>答案に書くなら</b>　PFOS・PFOAは2025年6月30日に公布、2026年4月1日に施行済みの水質基準52項目の1つである。<br><br><b>関連</b>　改正は水道法に基づく省令で、告示ではない。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで施行済みと示す<br><br>【出典】<a href=\"https://www.env.go.jp/content/000334172.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【PFOS・PFOAの水道水質基準化｜定義】PFOS・PFOAとは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　有機フッ素化合物（PFAS）の一種。化学的に極めて安定で難分解性。化審法で原則製造・輸入禁止（第一種特定化学物質）<br><br><b>解説</b>　PFASは有機フッ素化合物の総称。PFOS・PFOAは分解されにくく環境に長く残るため、化審法で原則製造・輸入が禁止されている<br><br><b>答案に書くなら</b>　PFOS・PFOAは化学的に極めて安定で難分解性のPFASの一種であり、化審法の第一種特定化学物質として原則製造・輸入が禁止されている。<br><br><b>関連</b>　PFOSは2010年、PFOAは2021年に第一種特定化学物質に指定。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.env.go.jp/water/pfas/faq003.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【PFOS・PFOAの水道水質基準化｜制度】PFOS・PFOAの水道水質基準値は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　PFOSとPFOAの合算で50ng/L（0.00005mg/L）以下。水道事業者等に遵守・検査の義務がある<br><br><b>解説</b>　基準値は食品安全委員会のTDIから算出。PFOS・PFOAは同じ影響を指標とし同時に検出されるため、安全側に合算で50ng/Lとした<br><br><b>答案に書くなら</b>　水道水質基準はPFOSとPFOAの合算で50ng/L（0.00005mg/L）以下であり、水道事業者等に遵守・検査の義務がある。<br><br><b>関連</b>　検査は原則3か月に1回で、簡易水道・専用水道には頻度の特例がある。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の数字。合算と単位を書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000334172.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【PFOS・PFOAの水道水質基準化｜制度】公共用水域・地下水のPFOS・PFOAの扱いは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　環境基準ではなく要監視項目の指針値（50ng/L合算）。2025年6月に「暫定」を外した<br><br><b>解説</b>　水道水は水道法の水質基準で義務があるが、公共用水域・地下水は環境基準ではなく、知見の集積を続ける要監視項目として指針値を置く<br><br><b>答案に書くなら</b>　公共用水域・地下水のPFOS・PFOAは環境基準ではなく要監視項目の指針値（合算50ng/L）であり、遵守義務のある水道水質基準とは位置づけが異なる。<br><br><b>関連</b>　2025年6月30日に「指針値（暫定）」の「暫定」を外した（値は同じ）。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。水道水との違いを書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000405361.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【PFOS・PFOAの水道水質基準化｜課題】PFOS対策の課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　濃度低減の対策技術の知見の充実が必要。使用済み活性炭の不適切な保管から流出した事案もあり、活性炭の管理が課題<br><br><b>解説</b>　浄水に使う活性炭はPFOS等を吸着するが、使用済みの活性炭の管理が不適切だと再び流出する。濃度を下げる対策技術の知見も十分でない<br><br><b>答案に書くなら</b>　技術の観点から、課題は濃度低減の対策技術の知見の充実が必要で、使用済み活性炭の不適切な保管から流出した事案もあり活性炭の管理が課題である。<br><br><b>関連</b>　環境省は実証事業を行い、対策技術集を公表している。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000405361.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【PFOS・PFOAの水道水質基準化｜課題】PFOS対策の課題を『制度』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　PFOS・PFOA以外のPFASは毒性評価が定まらず、要検討項目に据え置かれている<br><br><b>解説</b>　PFASには多くの種類があるが、毒性評価が定まった物質は限られる。評価が定まらない物質は基準にできず、要検討項目に据え置かれる<br><br><b>答案に書くなら</b>　制度の観点から、課題はPFOS・PFOA以外のPFASは毒性評価が定まらず、要検討項目に据え置かれていることである。<br><br><b>関連</b>　2025年6月30日にPFHxSに加え7物質を要検討項目に追加し、計8物質となった。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 制度の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000405361.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【PFOS・PFOAの水道水質基準化｜解決策】PFOS低減の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　対策技術の実証事業と対策技術集の活用、使用済み活性炭の適正な保管・取扱いの周知<br><br><b>解説</b>　低減対策は技術面（実証・技術集）と運用面（活性炭の保管・取扱い）の両方から進める。自治体には対応の手引き（第3版）も通知されている<br><br><b>答案に書くなら</b>　解決策として、対策技術の実証事業と対策技術集の活用を進め、使用済み活性炭の適正な保管・取扱いを周知する。<br><br><b>関連</b>　「PFOS及びPFOAに関する対応の手引き（第3版）」は2026年6月5日に通知。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 技術面の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000405361.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【PFOS・PFOAの水道水質基準化｜注意】50ng/Lは基準化で変わった値か？合算か個別か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　値は暫定目標値から変わらず、変わったのは位置づけ（義務のある基準へ）。PFOSとPFOAの合算<br><br><b>解説</b>　基準化は、暫定目標値だった50ng/Lを守る義務のある水質基準に格上げしたもの。値を厳しくしたのではない<br><br><b>答案に書くなら</b>　50ng/Lは暫定目標値から変わらず、変わったのは義務のある基準へという位置づけで、PFOSとPFOAの合算値である。<br><br><b>関連</b>　食品安全委員会のTDIは両物質とも20ng/kg/日。<br><br><b>答案での使い方</b>　「基準値が厳しくなった」と書くと減点<br><br>【出典】<a href=\"https://www.env.go.jp/content/000334172.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【底層溶存酸素量の環境基準｜時期】底層溶存酸素量はいつ環境基準になり、類型指定はどこまで進んだか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　2016年3月に生活環境項目に追加。琵琶湖・東京湾（2021年）、伊勢湾・大阪湾（2022年）、霞ケ浦等（2024年）を指定<br><br><b>解説</b>　従来の環境基準だけでは湖底の貧酸素化や魚介類の減少が伝わりにくいとの指摘から、2015年12月の中環審答申を受けて導入された。国が県際水域から類型指定を進める<br><br><b>答案に書くなら</b>　底層溶存酸素量は2016年3月に生活環境項目に追加され、琵琶湖・東京湾（2021年）、伊勢湾・大阪湾（2022年）、霞ケ浦等（2024年）で類型指定が進んだ。<br><br><b>関連</b>　複数県にまたがる水域は国が指定する。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで時期と実績を示す<br><br>【出典】<a href=\"https://www.env.go.jp/press/102287.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【底層溶存酸素量の環境基準｜定義】底層溶存酸素量とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　魚介類等の生息や藻場等の生育への直接的な影響を判断できる指標。底層を利用する生物の生息・再生産に重要<br><br><b>解説</b>　水底付近の酸素が不足する貧酸素化は、底を利用する魚介類や藻場に直接影響する。底層の酸素量はその影響を直接判断できる指標<br><br><b>答案に書くなら</b>　底層溶存酸素量とは、魚介類等の生息や藻場等の生育への直接的な影響を判断できる指標であり、底層を利用する生物の生息・再生産に重要である。<br><br><b>関連</b>　同時期の沿岸透明度は環境基準ではなく、地域が設定する目標。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.env.go.jp/press/102287.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【底層溶存酸素量の環境基準｜制度】底層溶存酸素量の3つの類型と基準値は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　生物1は4.0mg/L以上、生物2は3.0mg/L以上、生物3は2.0mg/L以上（日間平均値）<br><br><b>解説</b>　生物の貧酸素への耐性に応じて、守る水域の目的を3段階に分けた。数字が小さい類型ほど耐性の低い生物を守る<br><br><b>答案に書くなら</b>　類型は生物1が4.0mg/L以上、生物2が3.0mg/L以上、生物3が2.0mg/L以上（いずれも日間平均値）で、耐性の低い生物の場ほど厳しい値である。<br><br><b>関連</b>　生物3は耐性の高い生物の場、または無生物域を解消する水域。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の数字。類型と値を対で書く<br><br>【出典】<a href=\"https://www.env.go.jp/press/102287.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【底層溶存酸素量の環境基準｜制度】大阪湾の底層溶存酸素量の類型指定の範囲は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　湾奥部のみ（生物3）。湾全域ではない。東京湾などは水域ごとに生物1〜3が混在<br><br><b>解説</b>　類型は水域ごとに指定するため、同じ湾の中でも区域により類型が異なる。大阪湾は湾奥部だけで、東京湾や伊勢湾は複数の類型が混在する<br><br><b>答案に書くなら</b>　大阪湾の類型指定は湾奥部のみ（生物3）であり、湾全域ではなく、東京湾などでは水域ごとに生物1〜3が混在する。<br><br><b>関連</b>　伊勢湾は名古屋港が生物2、伊勢湾央部が生物3、その他が生物1。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。指定は水域ごと<br><br>【出典】<a href=\"https://www.env.go.jp/press/110371.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【底層溶存酸素量の環境基準｜課題】底層の貧酸素化の課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　湖沼では底質からの栄養塩溶出（内部負荷）や鉄・マンガン溶出による水道水の障害にもつながり、要因解析と対策技術の選定が要る<br><br><b>解説</b>　湖沼では底層の酸素が減ると底質から栄養塩が溶け出し（内部負荷）、さらに鉄・マンガンの溶出が水道水の障害にもなる。原因解析をして対策を選ぶ必要がある<br><br><b>答案に書くなら</b>　技術の観点から、課題は底層の貧酸素化が内部負荷や鉄・マンガンの溶出による水道水の障害にもつながり、要因解析と対策技術の選定が必要なことである。<br><br><b>関連</b>　湖沼の対策の手引き（2020年3月）が対策を整理している。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/900544873.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【底層溶存酸素量の環境基準｜解決策】貧酸素化の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　外部負荷削減に加え、内部負荷削減（浚渫・覆砂）と、曝気・酸素水供給による底層への酸素供給を組み合わせる<br><br><b>解説</b>　外部負荷（流入する汚濁）の削減だけでは底質に溜まった栄養塩の溶出は止まらないため、内部負荷の削減と底層への酸素供給を組み合わせる<br><br><b>答案に書くなら</b>　解決策として、外部負荷削減に加え、浚渫・覆砂による内部負荷削減と、曝気・酸素水供給による底層への酸素供給を組み合わせる。<br><br><b>関連</b>　対策の選定は水域の特性、改善目標、費用を踏まえ、副次的な影響にも留意する。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 水環境の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/900544873.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【底層溶存酸素量の環境基準｜注意】底層溶存酸素量の基準値は何の値か？どの類型が最も厳しいか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　日間平均値。生物1（4.0mg/L以上）が最も厳しい。1つの湾・湖でも類型は混在する<br><br><b>解説</b>　基準は1日の平均値で評価する。類型は守る生物の耐性で決まり、数値が大きい生物1が最も厳しい。1つの水域に複数類型が混在する<br><br><b>答案に書くなら</b>　底層溶存酸素量の基準値は日間平均値であり、生物1（4.0mg/L以上）が最も厳しく、1つの湾・湖でも類型は混在する。<br><br><b>関連</b>　令和8年度の方針で、達成率と達成期間の目標を設定するとされる。<br><br><b>答案での使い方</b>　基準値の種類と類型の取り違えは減点<br><br>【出典】<a href=\"https://www.env.go.jp/press/102287.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック汚染の国際条約交渉（INC）｜時期】プラスチック汚染条約は成立したか？交渉の現状は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　未成立。2022年のUNEA5.2決議でINCを設置したが、2024年末の策定目標は未達。INC5.4は2027年3月に開催予定<br><br><b>解説</b>　プラスチック汚染は国境を越えるため、世界全体で対策が必要。UNEA5.2の決議でINCを設置して条約策定の交渉が続いている<br><br><b>答案に書くなら</b>　プラスチック汚染条約は未成立であり、2024年末の策定目標は未達のまま、INC5.4が2027年3月に開催予定である。<br><br><b>関連</b>　INC5は「INC5.1」とも呼ばれ、5.2・5.3は同じ第5回の再開会合。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで「交渉中」と示す<br><br>【出典】<a href=\"https://www.env.go.jp/water/inc.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック汚染の国際条約交渉（INC）｜定義】大阪ブルー・オーシャン・ビジョンとは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　2019年のG20大阪サミットで共有された、2050年までに海洋プラごみによる追加的な汚染をゼロにする目標。日本が提唱<br><br><b>解説</b>　日本が提唱し、2019年のG20大阪サミットで共有された目標。条約交渉でも日本が積極的に関わる根拠になる<br><br><b>答案に書くなら</b>　大阪ブルー・オーシャン・ビジョンとは、2050年までに海洋プラスチックごみによる追加的な汚染をゼロにする目標で、日本が提唱国である。<br><br><b>関連</b>　2023年G7広島サミットでは2040年までにゼロにする野心にコミット。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し・日本の取組の根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_02873.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック汚染の国際条約交渉（INC）｜課題】条約交渉の課題を『制度・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　INC5.2（2025年8月）で、生産、プラスチック製品（第4条）、資金（第10条）は各国の意見の隔たりが大きく合意に至らなかった<br><br><b>解説</b>　INC5.2では条文交渉は進んだが、生産・製品・資金など利害の対立が大きい論点は合意できなかった。国際制度づくりが課題<br><br><b>答案に書くなら</b>　制度・運用の観点から、課題はINC5.2（2025年8月）で生産、プラスチック製品（第4条）、資金（第10条）の意見の隔たりが大きく、合意に至らなかったことである。<br><br><b>関連</b>　製品設計（第5条）や廃棄物管理（第7条）などは文言交渉が進展した。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 国際制度の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/water/inc.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック汚染の国際条約交渉（INC）｜課題】条約実施の課題を『経済・担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　途上国の廃棄物管理の能力構築とインフラ整備が必要。日本は人材育成（2025年までに1万人）等を表明している<br><br><b>解説</b>　条約を実施するには各国の廃棄物管理が前提で、途上国は能力とインフラが不足しがち。日本は人材育成で支援を表明している<br><br><b>答案に書くなら</b>　経済・担い手の観点から、課題は途上国の廃棄物管理の能力構築とインフラ整備が必要なことで、日本は人材育成（2025年までに1万人）等を表明している。<br><br><b>関連</b>　日本の支援の枠組みはマリーン・イニシアティブ。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 国際協力の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/council/content/i_03/000433372.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック汚染の国際条約交渉（INC）｜解決策】途上国支援の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　ASEAN各国を中心とした国別行動計画の策定支援、海洋ごみモニタリング能力の強化、地域ナレッジセンターの設置<br><br><b>解説</b>　国別行動計画は各国が自国の対策を定める計画。モニタリング能力の強化と地域ナレッジセンターは、海洋ごみの実態把握と知見共有を支える<br><br><b>答案に書くなら</b>　解決策として、ASEAN各国を中心とした国別行動計画の策定支援、海洋ごみモニタリング能力の強化、地域ナレッジセンターの設置を進める。<br><br><b>関連</b>　条約の国別計画は第13条で定める。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 国際協力の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/council/content/i_03/000433372.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック汚染の国際条約交渉（INC）｜解決策】国内でできる解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　プラスチック資源循環促進法による設計・使用の合理化・回収・再資源化と、海洋プラごみの回収・流出防止を進める<br><br><b>解説</b>　国内対策は条約とは別の枠組みで、国内法で設計から回収・再資源化まで進める。海洋への流出の防止も並行して行う<br><br><b>答案に書くなら</b>　国内の解決策として、プラスチック資源循環促進法による設計・使用の合理化・回収・再資源化と、海洋プラスチックごみの回収・流出防止を進める。<br><br><b>関連</b>　条約は法的拘束力のある国際文書で、国内法とは別。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 国内施策の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/council/content/i_03/000433372.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック汚染の国際条約交渉（INC）｜注意】「2050年ゼロ」と「2040年ゼロ」は同じ目標か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　別。2050年は大阪ブルー・オーシャン・ビジョン（2019年）、2040年は2023年G7広島サミットでの野心<br><br><b>解説</b>　2050年は日本が提唱した大阪ブルー・オーシャン・ビジョン（2019年）、2040年はG7広島サミット（2023年）の野心で、出どころも年次も別<br><br><b>答案に書くなら</b>　2050年ゼロは大阪ブルー・オーシャン・ビジョン、2040年ゼロは2023年G7広島サミットの野心であり、別の目標である。<br><br><b>関連</b>　大阪ブルー・オーシャン・ビジョンは追加的な汚染をゼロにする目標。<br><br><b>答案での使い方</b>　年次の取り違えは減点<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_02873.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック汚染の国際条約交渉（INC）｜注意】INC5.3（2026年2月）では条文交渉をしたか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　していない。前議長の辞任を受けた新議長の選出などを行う、組織的・事務的事項の会合<br><br><b>解説</b>　INC5.3（2026年2月7日）は前議長の辞任を受けた新議長（チリ）の選出など、実質的な交渉をしない事務的会合。5.2が条文交渉、5.4が次の交渉<br><br><b>答案に書くなら</b>　INC5.3は条文交渉を行わず、新議長の選出などを行う組織的・事務的事項の会合であり、実質的な交渉はINC5.2と5.4で行う。<br><br><b>関連</b>　INC5.4は2027年3月13〜24日の期間内に開催予定で、場所は未定。<br><br><b>答案での使い方</b>　INC5.2・5.3・5.4の役割を混同しない<br><br>【出典】<a href=\"https://www.env.go.jp/water/inc.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【マイクロプラスチックの実態調査と調査ガイドライン｜時期】河川・湖沼マイクロプラスチック調査ガイドラインはいつ策定されたか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　河川版は2021年6月、湖沼を加えた現名称は2023年3月30日。その後改訂され、令和8年4月版が最新<br><br><b>解説</b>　河川版ガイドライン（2021年6月）に湖沼の調査方法を加え、「河川・湖沼」版として2023年3月30日に公開した。知見の集積に応じて見直されるため、版の表記に注意<br><br><b>答案に書くなら</b>　河川・湖沼マイクロプラスチック調査ガイドラインは2023年3月に河川・湖沼版として公開され、その後改訂されて令和8年4月版が最新である。<br><br><b>関連</b>　資料により版の表記が異なる。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで時期と最新版を示す<br><br>【出典】<a href=\"https://www.env.go.jp/water/marine_litter/post_118.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【マイクロプラスチックの実態調査と調査ガイドライン｜定義】マイクロプラスチックとは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　一般的に5mm未満の微細なプラスチック。海洋プラごみの約8割は陸域発生とされ、河川を経由して流出する<br><br><b>解説</b>　5mm未満は一般的な定義で、調査では1mm以上5mm未満と1mm未満を分ける場合もある。海洋プラごみの約8割は陸域発生とされ、河川が流出経路になる<br><br><b>答案に書くなら</b>　マイクロプラスチックとは一般的に5mm未満の微細なプラスチックであり、海洋プラスチックごみの約8割は陸域から発生し河川を経由して流出するとされる。<br><br><b>関連</b>　個数密度の単位は個/m3、質量濃度はmg/m3。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.env.go.jp/water/marine_litter/post_118.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【マイクロプラスチックの実態調査と調査ガイドライン｜制度】マイクロプラスチックに法的基準値はあるか？ガイドラインの位置づけは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　ない。ガイドラインは調査方法の手引きで、結果を基に自治体が関係機関と連携して発生源対策を進める<br><br><b>解説</b>　環境基準・排出基準のような法的基準値はなく、ガイドラインは調査方法を示す手引き。結果を基に自治体が発生源対策を進める<br><br><b>答案に書くなら</b>　マイクロプラスチックに法的基準値はなく、ガイドラインは調査方法の手引きであり、結果を基に自治体が関係機関と連携して発生源対策を進める。<br><br><b>関連</b>　環境省は事業者の自主的な取組の後押しも行う。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。規制ではないと書く<br><br>【出典】<a href=\"https://www.env.go.jp/water/marine_litter/post_118.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【マイクロプラスチックの実態調査と調査ガイドライン｜制度】令和4年度の河川調査（一級水系7水系）の結果は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　長径1〜5mmの平均個数密度は0.1〜0.8個/m3。人口密度・市街化率と強い正の相関<br><br><b>解説</b>　令和4年度の調査は一級水系7水系の下流域で、長径1mm以上5mm未満を対象にした。人口が多く市街化が進んだ地域ほど個数密度が高い<br><br><b>答案に書くなら</b>　令和4年度の河川調査では、1〜5mmの平均個数密度は0.1〜0.8個/m3で、人口密度・市街化率と強い正の相関があった。<br><br><b>関連</b>　最高は阿武隈川水系の槻木大橋、最低は留萌川水系と吉野川水系。<br><br><b>答案での使い方</b>　Ⅱ-1の数字。個数密度の単位は個/m3<br><br>【出典】<a href=\"https://www.env.go.jp/content/000220901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【マイクロプラスチックの実態調査と調査ガイドライン｜課題】マイクロプラスチックの課題を『技術・科学』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　添加剤や吸着した化学物質が生物・生態系に及ぼす影響の科学的知見が、まだ十分に蓄積されていない<br><br><b>解説</b>　マイクロプラスチックに含まれる添加剤や、表面に吸着する化学物質が生物に与える影響は、まだ科学的に十分わかっていない<br><br><b>答案に書くなら</b>　技術・科学の観点から、課題は添加剤や吸着した化学物質が生物・生態系に及ぼす影響の科学的知見がまだ十分に蓄積されていないことである。<br><br><b>関連</b>　モニタリング手法の国際的な調和も課題。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 科学的知見の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/water/marine_litter/post_118.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【マイクロプラスチックの実態調査と調査ガイドライン｜解決策】科学的知見の不足への解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　生物・生態系への影響評価手法の検討と、調和ガイドラインに沿ったデータ収集、AOMIによる国際共有<br><br><b>解説</b>　影響評価手法の検討、調和ガイドラインによる比較可能なデータ収集、国際データベースAOMI（Atlas of Ocean Microplastics）での共有が、知見不足を埋める流れ<br><br><b>答案に書くなら</b>　解決策として、生物・生態系への影響評価手法を検討し、調和ガイドラインに沿ってデータを収集し、AOMIで国際的に共有する。<br><br><b>関連</b>　AOMIは2024年5月に公表されたデータベース。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 調査検討事項の根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/water/marine_litter/post_118.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【マイクロプラスチックの実態調査と調査ガイドライン｜解決策】事業者との連携の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　マイクロプラスチック・スマート懇話会で業界団体・事業者と普及啓発を検討し、グッド・プラクティス集で先進事例を発信<br><br><b>解説</b>　発生抑制・流出抑制・回収・代替素材の開発は事業者の取組に依存する面があるため、業界団体・事業者との連携が要る。先進事例の発信で自主的な取組を後押しする<br><br><b>答案に書くなら</b>　解決策として、マイクロプラスチック・スマート懇話会で業界団体・事業者と普及啓発を検討し、グッド・プラクティス集で先進事例を発信する。<br><br><b>関連</b>　グッド・プラクティス集は第3版を2025年4月に公表。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 事業者連携の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/water/marine_litter/post_118.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【マイクロプラスチックの実態調査と調査ガイドライン｜注意】マイクロプラスチックの個数密度は他の調査の数値と比べられるか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　直接比べられない。調査年度・地点・サイズ範囲（1mm以上5mm未満など）で大きく変わる<br><br><b>解説</b>　個数密度は調査年度・地点・サイズ範囲（1mm以上5mm未満など）で大きく変わる。条件が違う数字を並べても比較にならない<br><br><b>答案に書くなら</b>　マイクロプラスチックの個数密度は調査年度・地点・サイズ範囲で大きく変わるため、他の調査の数値とは条件を揃えずに直接比較できない。<br><br><b>関連</b>　東京湾周辺の河川では0.3〜35.2個/m3という別の調査結果がある。<br><br><b>答案での使い方</b>　数字を比較に使うときは条件を揃える<br><br>【出典】<a href=\"https://www.env.go.jp/content/000220901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域気候変動適応計画・地域気候変動適応センター｜時期】気候変動適応法の施行と、次期適応計画の改定時期は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2018年6月公布、同12月施行。2023年に熱中症対策を強化。次期計画は2026年度内に改定予定<br><br><b>解説</b>　気候変動の影響は地域で異なるため、適応法が国・自治体・事業者・国民の役割を定めた。施行後も改正で熱中症対策を強化し、国の計画は影響評価を受けて改定中<br><br><b>答案に書くなら</b>　気候変動適応法は2018年12月に施行され、2023年の改正で熱中症対策が強化され、次期計画は2026年度内に改定予定である。<br><br><b>関連</b>　2026年2月に第3次の気候変動影響評価報告書を公表。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで時期を示す<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/430AC0000000050\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域気候変動適応計画・地域気候変動適応センター｜定義】地域気候変動適応センターとは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　都道府県・市町村が、影響・適応の情報の収集・整理・分析・提供と技術的助言を行う拠点機能を担う体制（第13条、努力義務）<br><br><b>解説</b>　地域の適応策を進めるには、気候変動影響・適応に関する情報の収集・分析・提供と技術的助言を担う拠点が要る。努力義務で、国立環境研究所と情報を共有する<br><br><b>答案に書くなら</b>　地域気候変動適応センターとは、都道府県・市町村が影響・適応の情報の収集・整理・分析・提供と技術的助言を行う拠点機能を担う体制であり、確保は努力義務である（第13条）。<br><br><b>関連</b>　複数自治体の共同設置は1件と数える。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 自治体の体制の定義に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/430AC0000000050\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域気候変動適応計画・地域気候変動適応センター｜制度】地域気候変動適応計画の根拠と義務の程度は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　法第12条。都道府県・市町村が国の適応計画を勘案して策定するよう努める努力義務<br><br><b>解説</b>　地域計画は都道府県・市町村が国の適応計画を勘案して作る計画で、義務ではなく努力義務。温対法の地方公共団体実行計画（緩和）とは別の計画<br><br><b>答案に書くなら</b>　地域気候変動適応計画は気候変動適応法第12条に基づき、都道府県・市町村が国の計画を勘案して策定するよう努める努力義務の計画である。<br><br><b>関連</b>　異なる計画を一体的に策定することは可能。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 自治体計画の書き出しに<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/430AC0000000050\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域気候変動適応計画・地域気候変動適応センター｜制度】気候変動適応広域協議会とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　国の地方行政機関・都道府県・市町村・センター・事業者等で組織でき、全国7ブロックで広域アクションプランを策定<br><br><b>解説</b>　広域協議会は、複数の自治体にまたがる課題を関係者で調整する場。全国7ブロックに置かれ、地域の課題に応じた広域アクションプランを作る<br><br><b>答案に書くなら</b>　気候変動適応広域協議会は国の地方行政機関・都道府県・市町村・センター・事業者等で組織でき、全国7ブロックで広域アクションプランを策定する。<br><br><b>関連</b>　根拠は適応法第14条で、2023年3月にプランを策定・公開。<br><br><b>答案での使い方</b>　Ⅱ-2 関係者調整（広域連携）の根拠に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/430AC0000000050\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域気候変動適応計画・地域気候変動適応センター｜目標】地域適応計画とセンターの現状（2026年3月）は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　491自治体が計画を策定し、センターは70か所。491は自治体数、70はセンター数（共同設置は1件）<br><br><b>解説</b>　2026年3月現在、計画は491自治体、センターは70か所。センター数は共同設置を1件と数えるため、自治体数とは一致しない<br><br><b>答案に書くなら</b>　2026年3月現在で491自治体が地域気候変動適応計画を策定し、地域適応センターは70か所確保されている。<br><br><b>関連</b>　491は自治体数、70はセンター数で、数え方が異なる。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 現状の数字。自治体数とセンター数を書き分ける<br><br>【出典】<a href=\"https://www.env.go.jp/content/000427991.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域気候変動適応計画・地域気候変動適応センター｜課題】地域適応の課題を『制度・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　市町村の計画策定の促進と計画の質の向上、センターの地域適応のハブとしての機能強化が必要<br><br><b>解説</b>　市区町村は人材不足の中で計画を作る必要があり、策定が進みにくい。センターは地域適応のハブとして機能を強める必要がある<br><br><b>答案に書くなら</b>　制度・運用の観点から、課題は市町村の計画策定の促進と計画の質の向上、センターの地域適応のハブとしての機能強化が必要なことである。<br><br><b>関連</b>　市区町村では人材不足等が負担になっている。<br><br><b>答案での使い方</b>　Ⅱ-2・必須Ⅰ(1) 自治体の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000191251.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域気候変動適応計画・地域気候変動適応センター｜解決策】自治体の適応を支える解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　A-PLATでの影響予測・優良事例の共有、国立環境研究所の専門家派遣（オンライン可）、策定マニュアルの改訂とツール提供<br><br><b>解説</b>　A-PLATは影響予測や優良事例を共有する情報基盤。国立環境研究所の専門家派遣や策定マニュアルの改訂で、自治体の負担を軽くして策定を支える<br><br><b>答案に書くなら</b>　解決策として、A-PLATで影響予測・優良事例を共有し、国立環境研究所の専門家をオンラインも含め派遣し、策定マニュアルの改訂とツール提供を行う。<br><br><b>関連</b>　策定マニュアルは2018年11月に策定、2023年3月に改訂。<br><br><b>答案での使い方</b>　Ⅱ-2 自治体支援の手順に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000427991.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域気候変動適応計画・地域気候変動適応センター｜注意】地域適応計画・センターの100%目標は、誰が対象か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　都道府県・政令指定都市が対象で、市町村は対象外。計画もセンターも努力義務（2026年度目標）<br><br><b>解説</b>　100%目標は都道府県・政令指定都市が対象で、市町村は含まれない。計画もセンターも法律上は努力義務なので、「義務」と書かない<br><br><b>答案に書くなら</b>　計画・センターの2026年度100%目標は都道府県・政令指定都市が対象で、市町村は対象外であり、いずれも努力義務である。<br><br><b>関連</b>　令和6年1月時点で全ての都道府県・政令指定都市は計画を策定済み。<br><br><b>答案での使い方</b>　義務と書くと減点。対象自治体も明記<br><br>【出典】<a href=\"https://www.env.go.jp/content/000191251.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【循環経済行動計画｜時期】循環経済行動計画はいつ、どの会議のどんな形の決定で決まった？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2026年4月21日、循環経済に関する関係閣僚会議（第4回）の決定。閣議決定ではない<br><br><b>解説</b>　世界で資源の獲得競争が激化し、国内の再生可能な資源が海外流出や焼却・埋立てされる現状を受けた。関係閣僚会議は2024年7月の設置<br><br><b>答案に書くなら</b>　循環経済行動計画は2026年4月21日の循環経済に関する関係閣僚会議（第4回）の決定であり、閣議決定ではない。<br><br><b>関連</b>　基本計画（第五次）は2024年8月の閣議決定で別物。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで時期と決定主体を示す<br><br>【出典】<a href=\"https://www.env.go.jp/guide/photo_report/report_01160.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【循環経済行動計画｜定義】行動計画は、循環経済への移行をどう位置づけたか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　環境保全にとどまらない経済安全保障の課題と位置づけ、日本の「勝ち筋」として再生資源供給サプライチェーンの強靱化を急ぐ<br><br><b>解説</b>　資源獲得競争が激しく、再生資源の確保は国の経済安全保障に関わる。重要鉱物・金属資源のリサイクルと再生材の活用が軸<br><br><b>答案に書くなら</b>　行動計画は、循環経済への移行を環境保全にとどまらない経済安全保障の課題と位置づけ、再生資源供給サプライチェーンの強靱化を日本の勝ち筋として急ぐ。<br><br><b>関連</b>　構成は、サプライチェーン強靱化、国際資源循環ネットワーク、地域活性化・国際ルール・国民運動の3節。<br><br><b>答案での使い方</b>　Ⅱ-1 定義・背景の1〜2文目に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/html/hj26010401.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【循環経済行動計画｜制度】行動計画が掲げた投資の目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　再資源化拠点の構築等に、2030年までに官民で約1兆円の投資を目指す（国の予算額ではない）<br><br><b>解説</b>　再資源化拠点の整備には大きな設備投資が必要で、民間の資金を呼び込むことが狙い。数字は官民合わせた投資目標で、国の予算額ではない<br><br><b>答案に書くなら</b>　行動計画は、再資源化拠点の構築等に2030年までに官民で約1兆円の投資を目指すとしている。<br><br><b>関連</b>　官民ファンドの脱炭素化支援機構（JICN）等の活用で後押しする。<br><br><b>答案での使い方</b>　Ⅱ-1 制度の本文。数字の主語を官民と書く<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/pdf/full.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【循環経済行動計画｜制度】メタルリサイクル推進戦略の2030年の再生材供給目標を、品目別に言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　鉄は高品位スクラップ化の処理能力約200万t/年を追加確保。アルミ展伸材約4割、電解銅約3割、永久磁石の原料約3割を再生資源由来に<br><br><b>解説</b>　メタルリサイクル推進戦略は、品目ごとに指標を変えて2030年の再生材供給目標を置く。鉄は処理能力、アルミ・銅・磁石は国内に占める割合で測る<br><br><b>答案に書くなら</b>　2030年の再生材供給目標は、鉄が高品位スクラップ化の処理能力約200万t/年の追加確保、アルミ展伸材約4割、電解銅約3割、永久磁石の原料約3割である。<br><br><b>関連</b>　品目ごとに指標が違うため同じ尺度で比べられない。<br><br><b>答案での使い方</b>　Ⅱ-1 制度の目標。品目ごとに指標が違う点に注意<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/html/hj26010401.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【循環経済行動計画｜課題】循環経済行動計画を根拠に、資源循環の課題を『担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　静脈産業は小規模分散で長期・大口契約を結べる事業者が少なく、設備投資の回収も長いため民間融資を受けにくい<br><br><b>解説</b>　静脈産業（回収・再資源化側）は地域ごとに小規模で分散し、製造業と長期・大口の契約を結びにくい。高度リサイクルの設備は投資回収も長く、民間融資を受けにくい<br><br><b>答案に書くなら</b>　担い手の観点から、課題は静脈産業が小規模分散で長期・大口契約を結べる事業者が少なく、投資回収も長いため民間融資を受けにくいことである。<br><br><b>関連</b>　動静脈連携は製造業（動脈）と静脈産業の連携のこと。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 担い手の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/pdf/full.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【循環経済行動計画｜課題】行動計画が挙げる資源循環の課題を『制度・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　不適正なスクラップヤードが環境対策のコストをかけず高値で資源を買い集め、公正な競争を阻害している<br><br><b>解説</b>　不適正なスクラップヤードは環境対策のコストをかけず高値で買えるため、適正な事業者との公正な競争を妨げる。100以上の都道府県等が国レベルの規制を望んでいる<br><br><b>答案に書くなら</b>　制度・運用の観点から、課題は不適正なスクラップヤードが環境対策のコストをかけず高値で資源を買い集め、公正な競争を阻害していることである。<br><br><b>関連</b>　対策は廃棄物処理法の改正（2026年6月公布）で許可制を導入。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 制度・運用の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/html/hj26010401.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【循環経済行動計画｜解決策】動静脈連携を進める解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　再資源化事業等高度化法の大臣認定を3年で100件以上目指し、官民ファンド（JICN）等の活用で投資を後押しする<br><br><b>解説</b>　再資源化事業等高度化法は、再資源化事業の高度化を認定する制度で、2025年11月に全面施行された。認定制度に官民ファンドの出資を組み合わせて投資を促す<br><br><b>答案に書くなら</b>　解決策として、再資源化事業等高度化法の大臣認定を3年で100件以上目指し、官民ファンド（JICN）等の活用で投資を後押しする。<br><br><b>関連</b>　同法は令和6年法律第41号。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 解決策の1つに。認定制度とファンドを併記<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/pdf/full.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【循環経済行動計画｜注意】行動計画と第五次循環型社会形成推進基本計画の違いは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　第五次基本計画は2024年8月閣議決定で別物。資源生産性約60万円/トン（2030年度）等の指標は基本計画のもの<br><br><b>解説</b>　第五次循環基本計画（2024年8月閣議決定）は循環型社会形成推進基本法に基づく別の計画で、行動計画はその上乗せ施策群。指標は基本計画のものを混ぜない<br><br><b>答案に書くなら</b>　行動計画は関係閣僚会議の決定で、第五次基本計画（2024年8月閣議決定）とは別であり、資源生産性約60万円/トン（2030年度）等の指標は基本計画のものである。<br><br><b>関連</b>　2023年度の資源生産性は約50.9万円/トン。<br><br><b>答案での使い方</b>　Ⅱ-1 留意点。基本計画の指標を行動計画の目標と混ぜない<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/pdf/full.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【廃棄物処理法の2026年改正｜時期】令和8年法律第43号（廃棄物処理法等の改正）の公布日と、ヤード許可制の施行時期は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　2026年6月19日公布。ヤードの許可制は公布から2年6か月以内（令和10年12月19日より前）に施行で、未施行<br><br><b>解説</b>　許可制本体は公布から2年6か月以内の政令で定める日に施行するため、2026年11月28日時点では施行日が未確定・未施行。災害廃棄物関係は先行施行<br><br><b>答案に書くなら</b>　令和8年法律第43号は2026年6月19日公布で、ヤードの許可制は公布から2年6か月以内（令和10年12月19日より前）に施行する未施行の規定である。<br><br><b>関連</b>　施行済み・未施行を書き分ける。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し。施行済みか予定かを書き分ける<br><br>【出典】<a href=\"https://www.env.go.jp/content/000419110.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【廃棄物処理法の2026年改正｜注意】2026年の改正で、すでに施行されている部分はどこか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　災害廃棄物関係は施行期日政令により令和8年9月16日に施行済み。許可制本体とは時期が異なる<br><br><b>解説</b>　本改正は許可制（ヤード）と災害廃棄物対策の2本立てで、部分ごとに施行期日が異なる。災害廃棄物関係は令和8年9月16日に施行済み<br><br><b>答案に書くなら</b>　2026年の改正のうち災害廃棄物関係は令和8年9月16日に施行済みで、スクラップヤードの許可制本体とは施行時期が異なる。<br><br><b>関連</b>　許可申請の準備行為の規定も施行済み。<br><br><b>答案での使い方</b>　Ⅱ-1 留意点。全部施行済みと書かない<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05564.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【廃棄物処理法の2026年改正｜定義】スクラップヤードを規制する法改正の背景は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　有価物は廃棄物処理法の規制対象外で、廃棄物を有価物と称して規制を逃れる事業者がいた。この隙間を埋める許可制を導入<br><br><b>解説</b>　有価物は原則として廃棄物処理法の対象外のため、廃棄物を有価物と称して規制を逃れる事業者がいた。騒音・悪臭・水質土壌汚染・火災などの問題が一部で生じていた<br><br><b>答案に書くなら</b>　背景として、有価物は廃棄物処理法の規制対象外で、廃棄物を有価物と称して規制を逃れる事業者がいたため、この隙間を埋める許可制を導入した。<br><br><b>関連</b>　実態は令和7年度調査で全国4,625事業場。<br><br><b>答案での使い方</b>　Ⅱ-1 定義・背景の書き出しに<br><br>【出典】<a href=\"https://www.env.go.jp/content/000419110.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【廃棄物処理法の2026年改正｜制度】スクラップヤードの許可制の対象と義務を言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　使用済金属・プラスチック物品の保管又は再生を行う事業者が都道府県知事の許可を要し、保管・再生の基準の遵守と帳簿作成を義務付け<br><br><b>解説</b>　対象は廃棄物ではない有価物（使用済金属・プラスチック物品）で、雑品スクラップや使用済基板が典型。既存の許可業者は許可を受けたものとみなす<br><br><b>答案に書くなら</b>　制度として、使用済金属・プラスチック物品の保管又は再生を行う事業者は都道府県知事の許可を要し、保管・再生の基準の遵守と帳簿の作成が義務付けられる。<br><br><b>関連</b>　小規模事業場や国・自治体等は許可不要。<br><br><b>答案での使い方</b>　Ⅱ-1 制度の中身の本文に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000427424.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【廃棄物処理法の2026年改正｜制度】バーゼル法に関わる物品の輸出の規制を言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　使用済鉛蓄電池・廃電子基板等は国内再生が原則で、輸出には環境大臣の確認が要る。無確認輸出は罰則で未遂罪・予備罪もある<br><br><b>解説</b>　バーゼル法の特定有害廃棄物等は、輸出先での不適正処理を防ぐため国内再生を原則とする。輸出には環境大臣の確認が必要で、無確認の輸出は罰則の対象<br><br><b>答案に書くなら</b>　使用済鉛蓄電池・廃電子基板等は国内再生が原則で、輸出には環境大臣の確認が要り、無確認輸出は未遂罪・予備罪を含む罰則の対象である。<br><br><b>関連</b>　バーゼル条約のPIC手続は2028年度から電子化を目指す。<br><br><b>答案での使い方</b>　Ⅱ-1 制度の本文。国内資源循環の観点で<br><br>【出典】<a href=\"https://www.env.go.jp/content/000427424.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【廃棄物処理法の2026年改正｜課題】適正な事業者への影響という観点で、ヤード規制の課題を1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　不適正ヤードは環境対策のコストを省き買取価格を高く設定でき、適正事業者との公正な競争が妨げられている<br><br><b>解説</b>　不適正ヤードは環境対策のコストを省けるぶん買取価格を高く設定でき、適正事業者の仕入れが不利になる。環境面だけでなく経済面の公正さが問題<br><br><b>答案に書くなら</b>　経済の観点から、課題は不適正ヤードが環境対策のコストを省いて買取価格を高く設定でき、適正事業者との公正な競争が妨げられていることである。<br><br><b>関連</b>　資源の海外流出にもつながる。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 経済の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000427424.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【廃棄物処理法の2026年改正｜解決策】不適正なヤードへの解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　許可制と基準・帳簿の義務付けを軸に、基準違反に改善命令・措置命令・事業停止命令・許可取消しで対応し、許可を失った者の放置にも措置命令<br><br><b>解説</b>　許可制と基準・帳簿の義務で入口を絞り、違反には段階的な命令・取消しで対応する。許可を失った者が放置したスクラップにも措置命令が使える<br><br><b>答案に書くなら</b>　解決策として、許可制と基準・帳簿の義務付けを軸に、基準違反に改善命令・措置命令・事業停止命令・許可取消しで対応し、許可を失った者の放置にも措置命令を出す。<br><br><b>関連</b>　無許可営業は最大5年の拘禁刑等の罰則。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 解決策の1つに。罰則まで書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000427424.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【廃棄物処理法の2026年改正｜解決策】災害廃棄物の処理を強くする解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　処理計画への記載と協定締結の努力義務、非常災害廃棄物最終処分場の「指定」、JESCOの事業追加による自治体への専門的支援<br><br><b>解説</b>　災害時は自治体の人員・ノウハウが不足するため、平時の計画と協定で備える。最終処分場は許可でなく「指定」で、JESCOが専門的支援を担う<br><br><b>答案に書くなら</b>　解決策として、処理計画への記載と協定締結の努力義務、非常災害廃棄物最終処分場の指定、JESCOの事業追加による自治体への専門的支援を進める。<br><br><b>関連</b>　指定の更新期間は5年（政令）。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 官民連携の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000427424.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽光発電の環境アセス対象拡大｜時期】環境影響評価法施行令の太陽光規模見直しは、いつ決まっていつ施行か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2026年7月17日に閣議決定（令和8年政令第230号）。施行は令和9年（2027年）4月1日で、決定済みだが未施行<br><br><b>解説</b>　2025年12月23日の関係閣僚会議の対策パッケージを受けた政令改正。政令は決定済みだが、施行日は令和9年4月1日で未施行<br><br><b>答案に書くなら</b>　環境影響評価法施行令の太陽光規模見直しは2026年7月17日に閣議決定され、2027年4月1日施行で、決定済みだが未施行である。<br><br><b>関連</b>　意見募集（2026年6月2日〜7月1日）は政令案についてだった。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し。案ではなく決定済みと書く<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05279.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽光発電の環境アセス対象拡大｜定義】環境アセスの第一種事業と第二種事業の違いは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　第一種は規模が大きくアセス必須。第二種は個別にスクリーニングで要否を判定する。太陽電池発電所は2020年4月に対象化<br><br><b>解説</b>　第一種は規模が大きくアセスが必須、第二種はスクリーニングで個別に要否を判定する。太陽電池発電所は2020年4月に対象に追加された<br><br><b>答案に書くなら</b>　第一種事業は規模が大きくアセス必須で、第二種事業は個別にスクリーニングで要否を判定し、太陽電池発電所は2020年4月に対象事業へ追加された。<br><br><b>関連</b>　従来は第一種が4万kW以上、第二種が3万kW以上4万kW未満。<br><br><b>答案での使い方</b>　Ⅱ-1 定義の書き出しに<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05279.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽光発電の環境アセス対象拡大｜制度】太陽電池発電所の第一種・第二種の規模は、どう変わるか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　第一種は4万kW以上から2万kW以上へ。第二種は3万kW以上4万kW未満から1.5万kW以上2万kW未満へ（出力、交流）<br><br><b>解説</b>　規模の指標は出力（交流側）で、面積ではない。土地改変の影響を踏まえて、第一種・第二種とも下限を引き下げる<br><br><b>答案に書くなら</b>　太陽電池発電所は、第一種が4万kW以上から2万kW以上へ、第二種が3万kW以上4万kW未満から1.5万kW以上2万kW未満へ見直される。<br><br><b>関連</b>　第二種の下限の見直しと第一種の下限の見直しは別の改正点。<br><br><b>答案での使い方</b>　Ⅱ-1 制度の本文。新旧の数字を並べる<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05279.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽光発電の環境アセス対象拡大｜制度】施行時に手続中の事業を守る経過措置を言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　施行前に法手続を始めた3〜4万kWは第二種のまま継続。新たに対象となる事業は条例等の図書を相当書類とみなし途中から法手続へ<br><br><b>解説</b>　施行直前に手続を進めている事業者が、規模の見直しで手戻りしないよう、経過措置を置く。条例アセスの図書を法の図書とみなして途中から移れる<br><br><b>答案に書くなら</b>　施行前に法手続を始めた3〜4万kWの事業は第二種のまま継続でき、新たに対象となる事業は条例等の図書を相当書類とみなして途中から法手続へ移れる。<br><br><b>関連</b>　根拠は環境影響評価法第54条。<br><br><b>答案での使い方</b>　Ⅱ-1 制度の留意点。Ⅱ-2 手戻り防止の調整に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000416630.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽光発電の環境アセス対象拡大｜課題】太陽光アセスの規模要件の課題を『技術・科学』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　影響が大きいのは土地の面的改変だが、出力と面積の関係は蓄電池の併設や発電効率の向上で変わりうる。2019年答申は5年程度での見直しを求めた<br><br><b>解説</b>　影響が大きいのは土地の面的な改変だが、出力と面積の関係は蓄電池の併設や発電効率の向上で変わりうる。2019年答申は5年程度での見直しを求めていた<br><br><b>答案に書くなら</b>　技術・科学の観点から、課題は出力と面積の関係が蓄電池の併設や発電効率の向上で変わりうるため、規模要件を状況に応じて見直す必要があることである。<br><br><b>関連</b>　環境影響で特に大きいのは土地の面的改変。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://assess.env.go.jp/files/0_db/contents/1086_04/shiryou2.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽光発電の環境アセス対象拡大｜課題】太陽光アセスの課題を『制度・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　法対象外の規模は条例アセスが担うが、対象規模は自治体で差が大きく、出力基準でも0.8万〜5万kW等とまちまち<br><br><b>解説</b>　法対象外の規模は条例アセスが担うが、条例の対象規模は自治体で異なる。面積基準の自治体も多く、出力基準でも0.8万〜5万kW等とまちまち<br><br><b>答案に書くなら</b>　制度・運用の観点から、課題は法対象外の規模は条例アセスが担うが、対象規模が自治体で差が大きく、出力基準でも0.8万〜5万kW等とまちまちなことである。<br><br><b>関連</b>　施行前後の事業を法手続へつなぐ経過措置の運用も要る。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 制度・運用の観点の課題に<br><br>【出典】<a href=\"https://assess.env.go.jp/files/0_db/contents/1086_04/shiryou2.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽光発電の環境アセス対象拡大｜解決策】立地の多様な太陽光事業に配慮する解決策を、専門用語で言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　第二種のスクリーニング基準に森林開発・傾斜地の観点を加え、造成地は合理化ガイドライン、対象外は環境配慮ガイドラインで促す<br><br><b>解説</b>　森林や傾斜地は土地改変の影響が大きいため、スクリーニングで観点を加える。造成済みの土地には項目選定を簡略化する合理化ガイドラインがある<br><br><b>答案に書くなら</b>　解決策として、第二種のスクリーニング基準に森林開発・傾斜地の観点を加え、造成地は合理化ガイドライン、法・条例の対象外は環境配慮ガイドラインで配慮を促す。<br><br><b>関連</b>　環境配慮ガイドラインは令和2年3月公表で、10kW以上の事業用太陽光が対象。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 解決策の1つに。基準とガイドラインを併記<br><br>【出典】<a href=\"https://www.env.go.jp/council/content/i_01/000419510.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽光発電の環境アセス対象拡大｜注意】2026年9月15日からの意見募集は、何についてのものか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　政令そのものではなく、条例等の書類を法の相当書類として指定する件（案）についてのもの<br><br><b>解説</b>　2026年9月15日からの意見募集は、法第54条第2項に基づき、条例等の書類を相当書類として指定する件（案）についてで、政令そのものではない<br><br><b>答案に書くなら</b>　2026年9月15日からの意見募集は、政令ではなく、条例等の書類を法の相当書類として指定する件（案）についてのものである。<br><br><b>関連</b>　政令案の意見募集は2026年6〜7月で、別のもの。<br><br><b>答案での使い方</b>　Ⅱ-1 留意点。政令案の意見募集（6〜7月）と混同しない<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05577.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【生物多様性COP17と30by30｜時期】生物多様性条約COP17の日程・場所と、会議の最大の成果は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　2026年10月19〜30日、アルメニアのエレバン。GBF実施を初めて世界全体で点検するグローバルレビューを行い、実施加速を求めた<br><br><b>解説</b>　COP17はGBF（昆明・モントリオール生物多様性枠組）の実施を初めて世界全体で点検する会議。決定は「エレバン・パスウェイ」で、実施加速を求めた<br><br><b>答案に書くなら</b>　COP17は2026年10月にアルメニアのエレバンで開かれ、GBF実施の初のグローバルレビューを行い、各締約国に実施加速を強く求めた。<br><br><b>関連</b>　第2回グローバルレビューはCOP19、COP18はエクアドルで開催。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し。30by30が達成と評価されたわけではない<br><br>【出典】<a href=\"https://www.env.go.jp/content/000439580.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【生物多様性COP17と30by30｜定義】30by30とは何か。OECMとは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　2030年までに陸と海の30%以上を保護地域とOECMで保全する目標。OECMは保護地域以外で生物多様性保全に資する地域<br><br><b>解説</b>　30by30は2030年までに陸と海の30%以上を保全するGBFの目標。日本では国家戦略2023-2030で、2030年ネイチャーポジティブの国内目標の一つに位置づけた<br><br><b>答案に書くなら</b>　30by30とは2030年までに陸と海の30%以上を保護地域とOECMで保全する目標で、OECMは保護地域以外で生物多様性保全に資する地域である。<br><br><b>関連</b>　日本は国家戦略2023-2030で位置づけた。<br><br><b>答案での使い方</b>　Ⅱ-1 定義の書き出しに<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05386.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【生物多様性COP17と30by30｜制度】日本の30by30の現状を、保護地域＋OECMの割合で言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　2026年8月時点で陸域21.0%（うちOECM0.2%）、海域13.3%。自然共生サイトは2026年10月に累計700か所<br><br><b>解説</b>　保護地域＋OECMの合計割合を、2026年8月3日の環境省発表で示した。OECMは国際データベースに登録される保護地域と重複しない区域<br><br><b>答案に書くなら</b>　日本の保護地域＋OECMは2026年8月時点で陸域21.0%（うちOECM0.2%）、海域13.3%で、自然共生サイトは累計700か所である。<br><br><b>関連</b>　OECMの登録面積は累計64.6千ha。<br><br><b>答案での使い方</b>　Ⅱ-1 制度の現状の数字。必須Ⅰ(1)の課題の大きさの根拠にも<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05386.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【生物多様性COP17と30by30｜課題】COP17後の30by30の達成に向けた課題を『制度・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　海域は13.3%で、追加で約17%の保全が必要。OECMに該当し得る国の制度の地域を関係省庁で検討する段階<br><br><b>解説</b>　海域は13.3%にとどまり、30%には追加で約17%の保全が必要。国の制度で管理される森林・河川・港湾・都市緑地・海域のうち、OECMに該当し得る地域を関係省庁で検討中<br><br><b>答案に書くなら</b>　制度・運用の観点から、課題は海域が13.3%にとどまり追加で約17%の保全が必要で、OECMに該当し得る国制度の地域の検討が途上なことである。<br><br><b>関連</b>　国家戦略の中間評価で、状態目標の進展は半数弱にとどまった。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 制度・運用の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/pdf/full.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【生物多様性COP17と30by30｜課題】30by30の課題を『担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　自然共生サイトの申請主体は企業が約半数で民間の自主的な活動に依存し、参画企業へのインセンティブが重要<br><br><b>解説</b>　自然共生サイトは民間の自主的な取組を国が認定する制度で、申請主体は企業が約半数。民間の自主性に依存するため、参画企業のインセンティブが要る<br><br><b>答案に書くなら</b>　担い手の観点から、課題は自然共生サイトの申請主体の約半数が企業で民間の自主的な活動に依存しており、参画企業へのインセンティブが重要なことである。<br><br><b>関連</b>　支援証明書の本格運用は2025年9月。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 担い手の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000431252.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【生物多様性COP17と30by30｜解決策】海域と陸域の保護地域を増やす解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　国立・国定公園の候補地14か所を2030年までに順次指定・編入し、国立公園の海域公園地区の面積を2030年までに倍増する<br><br><b>解説</b>　陸域の保護地域を広げる国立・国定公園の新規指定・拡張と、海域の保護を強める海域公園地区の拡大が柱。目標年は2030年<br><br><b>答案に書くなら</b>　解決策として、国立・国定公園の候補地14か所を2030年までに順次指定・編入し、国立公園の海域公園地区の面積を2030年までに倍増する。<br><br><b>関連</b>　海洋保護区の設定も進める。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 解決策の1つに。目標年を書く<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/pdf/full.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【生物多様性COP17と30by30｜解決策】民間の参画を進める解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　地域生物多様性増進法の認定（維持・回復・創出）、支援証明書（2025年9月本格運用）、見える化システムで企業の参画を促す<br><br><b>解説</b>　地域生物多様性増進法の認定は維持・回復・創出の各タイプがあり、回復・創出は将来OECMの基準を満たす場所を想定。支援証明書と見える化システムで企業を後押しする<br><br><b>答案に書くなら</b>　解決策として、地域生物多様性増進法の認定（維持・回復・創出）、支援証明書（2025年9月本格運用）、見える化システムで企業の参画を促す。<br><br><b>関連</b>　30by30アライアンスにも企業・自治体が参画する。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 解決策の1つに。法の認定を軸に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/pdf/full.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【生物多様性COP17と30by30｜注意】陸域の20.8%と21.0%は、何が違うか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　20.8%は2025年8月時点の保護地域のみ。21.0%は2026年8月発表の保護地域＋OECM（OECMだけだと陸域0.2%）<br><br><b>解説</b>　20.8%は2025年8月時点の保護地域のみ、21.0%は2026年8月発表の保護地域＋OECMで、対象と時点が違う。OECM単独だと陸域0.2%程度<br><br><b>答案に書くなら</b>　陸域の20.8%は2025年8月時点の保護地域のみ、21.0%は2026年8月発表の保護地域＋OECMで、出典と時点が異なる。<br><br><b>関連</b>　自然共生サイトの数（700か所）とOECM登録面積（64.6千ha）も別の指標。<br><br><b>答案での使い方</b>　Ⅱ-1 留意点。割合の出典と時点を書き分ける<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/pdf/full.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}];
const NJ_PRI_A_DATA = [{"f": "二次:計画", "q": "【第六次環境基本計画｜時期】第六次環境基本計画が閣議決定されたのはいつ（何年何月）？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2024年5月（5月21日）。第五次ではなくこの第六次が最新版である<br><br><b>解説</b>　2024年5月21日に閣議決定された環境基本計画で、根拠は環境基本法第15条である<br><br><b>答案に書くなら</b>　本計画は2024年5月に閣議決定された第六次環境基本計画であり、最新版に基づいて課題を整理する。<br><br><b>関連</b>　第五次はR2の題材で別の計画。目的規定は第1条で、策定根拠の第15条と混同しない。<br><br><b>答案での使い方</b>　書き出しで最新版を明示する。第五次(R2題材)と取り違えない<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223504.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜目標】第六次環境基本計画が掲げる2030年度の温室効果ガス削減目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2013年度比46%削減（さらに50%の高みに向け挑戦を続ける）<br><br><b>解説</b>　基準年の2013年度と比べた2030年度の削減率で、日本全体の温室効果ガスが対象である<br><br><b>答案に書くなら</b>　環境の観点から、2030年度に2013年度比46%削減という高い目標の達成に向け、対策の加速が課題である。<br><br><b>関連</b>　2035年度60%・2040年度73%は別計画（地球温暖化対策計画）の数字で、本計画は2030年度46%とCN2050のみ明記する。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 課題の大きさの根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223504.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜目標】第六次環境基本計画が掲げる30by30目標とは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2030年までに陸と海の30%以上を保全する目標。ネイチャーポジティブ実現の手段<br><br><b>解説</b>　30by30は、2030年までに陸と海の30%以上を保全地域やOECM（保護地域以外で生物多様性保全に資する地域）にする国際目標。ネイチャーポジティブの実現手段と位置づけられる<br><br><b>答案に書くなら</b>　生態系の保全の観点から、30by30の達成に向け保全地域とOECMの拡大を進めることが解決策である。<br><br><b>関連</b>　ネイチャーポジティブは損失を止めて反転させる考え方で、30by30はその手段である。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 生物多様性の解決策の到達点に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223504.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜目標】世界の年平均気温は産業革命前より何℃上昇した（2023年）？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　1.45℃上昇（2023年）。気候危機の背景として示されている<br><br><b>解説</b>　産業革命前を基準とした世界の年平均気温の上昇幅で、2023年に1.45℃と示されている。気候危機を課題の背景として説明するときの数字になる<br><br><b>答案に書くなら</b>　世界の年平均気温は2023年に産業革命前より1.45℃上昇しており、気候危機への対応が急務であることが課題の背景である。<br><br><b>関連</b>　パリ協定の1.5℃目標に近い水準だが、1.45℃は2023年時点の値であり将来目標ではない。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 冒頭で課題の背景を示す数字に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223504.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜柱】「環境・経済・社会の統合的向上」を実践する場と位置づけられた重点戦略は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　地域づくり。地域循環共生圏で地域脱炭素とネイチャーポジティブを同時に解決する<br><br><b>解説</b>　重点戦略の一つ「環境・経済・社会の統合的向上の実践・実装の場としての地域づくり」で、地域循環共生圏が中核の考え方。地域ごとに自然資本・経済・社会の課題が異なるため、地域単位の実践が要る<br><br><b>答案に書くなら</b>　地域の観点から、地域循環共生圏により地域脱炭素とネイチャーポジティブを同時に解決することが解決策である。<br><br><b>関連</b>　地域循環共生圏は自立・分散型の地域づくりで、近隣地域と資源を補完し合う。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 解決策の方向を国の言葉で言うときに<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223505.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜柱】「新たな成長」を導く重点戦略の中身は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　持続可能な生産と消費を実現するグリーンな経済システム。自然資本への投資拡大と環境価値の内部化<br><br><b>解説</b>　「新たな成長」は経済を高付加価値化する考え方で、自然資本への投資を拡大し、環境という非市場的価値を市場的価値に取り込む（内部化する）ことで実現を図る<br><br><b>答案に書くなら</b>　経済の観点から、自然資本への投資拡大と環境価値の内部化により、グリーンな経済システムを構築することが解決策である。<br><br><b>関連</b>　重点戦略は6つあり、他に国土・地域・暮らし・科学技術・国際がある。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 経済面の解決策の方向づけに<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223505.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜課題】第六次環境基本計画を根拠に、自然資本投資の課題を『制度・政策』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　環境価値を市場価値に内部化するため、成長志向型CP構想の実行と税制のグリーン化を、競争力を損なわず設計する必要がある<br><br><b>解説</b>　環境価値のような非市場的価値は価格に反映されにくく、市場で評価されない。成長志向型カーボンプライシングや税制のグリーン化は、その内部化の手段である<br><br><b>答案に書くなら</b>　制度・政策の観点から、環境価値の内部化に向け成長志向型カーボンプライシング構想と税制のグリーン化を、競争力を損なわずに設計する必要があることが課題である。<br><br><b>関連</b>　解決策側の用語は成長志向型カーボンプライシング構想（GX投資を先行させ炭素価格負担を段階導入）である。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 制度・政策の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223505.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜課題】自然資本投資の課題を『経済・資金』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　サステナブルファイナンスと地域金融のESG化による資金動員が不可欠だが、評価指標が未成熟で資金が循環しにくい<br><br><b>解説</b>　自然資本投資には民間資金の動員が欠かせないが、環境価値の評価指標が未成熟だと投資判断がしにくく、資金が自然資本に回りにくい<br><br><b>答案に書くなら</b>　経済・資金の観点から、サステナブルファイナンスと地域金融のESG化による資金動員が不可欠だが、評価指標が未成熟で資金が循環しにくいことが課題である。<br><br><b>関連</b>　サステナブルファイナンスは環境・社会課題の解決に資する事業へ資金を誘導する枠組みである。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 経済・資金の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223505.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜課題】計画の実践・実装の課題を『人材・担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　環境人材の育成や公正な移行への人的資本投資、地域循環共生圏を支える中間支援組織の担い手不足が制約になっている<br><br><b>解説</b>　計画を地域で実行するには、環境分野の専門人材と、主体間を橋渡しする中間支援組織が要る。担い手が不足すると実践・実装が進まない<br><br><b>答案に書くなら</b>　人材・担い手の観点から、環境人材の育成や公正な移行への人的資本投資と、中間支援組織の担い手不足が実践・実装の制約となっていることが課題である。<br><br><b>関連</b>　公正な移行（ジャスト・トランジション）は、転換で影響を受ける産業・労働者・地域に不利益が偏らないようにする考え方である。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 人材・担い手の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223505.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜解決策】地域ごとに異なる課題への解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　地域循環共生圏の形成で、地域の自然資本を活かし近隣と資源を補完し合う自立・分散型の地域づくりを進める<br><br><b>解説</b>　地域循環共生圏は、地域の自然資本を最大限活用し、近隣地域と資源を補完し合う自立・分散型の地域づくり。地域ごとに課題が違う問題への解決策として使える専門用語である<br><br><b>答案に書くなら</b>　地域の観点から、地域循環共生圏を形成し、地域の自然資本を活かして近隣と資源を補完し合う自立・分散型の地域づくりを進めることが解決策である。<br><br><b>関連</b>　地域固有の合意形成の例として水俣の「もやい直し」や福島の「未来志向」が挙げられる。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 地域系の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223505.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜解決策】環境価値の内部化に向けた解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　成長志向型カーボンプライシング構想で、先行投資を促しつつ炭素価格負担を段階的に導入し、脱炭素と競争力を両立する<br><br><b>解説</b>　成長志向型カーボンプライシング構想は、GX投資を先行させつつ将来の炭素価格負担を段階的に導入する構想。化石燃料依存の低減と産業競争力強化の両立を狙う<br><br><b>答案に書くなら</b>　制度の観点から、成長志向型カーボンプライシング構想により、先行投資を促しつつ炭素価格負担を段階的に導入し、脱炭素と競争力を両立することが解決策である。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 制度面の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223505.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜リスク】30by30を急ぐ地域共生型再エネ拡大で生じるリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　リスク：景観・生態系への新たな環境負荷。対策：洋上・陸上風力の環境配慮の制度検討を計画の初期段階から組み込む<br><br><b>解説</b>　再エネ・洋上風力の導入拡大は脱炭素に資する一方、景観や生態系に新たな負荷を与える可能性があり、脱炭素と自然共生のトレードオフになる<br><br><b>答案に書くなら</b>　リスクとして、再エネ導入拡大が景観・生態系に新たな環境負荷を生むおそれがあるため、洋上・陸上風力の環境配慮の制度検討を計画の初期段階から組み込む必要がある。<br><br><b>関連</b>　トレードオフを避けるには、導入計画の初期段階での環境配慮の組み込みが鍵である。<br><br><b>答案での使い方</b>　必須Ⅰ(3) 脱炭素と自然共生のトレードオフに<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223505.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第六次環境基本計画｜注意】2035年度60%・2040年度73%削減は第六次環境基本計画の数字か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　違う。地球温暖化対策計画（2025年2月）の数字。第六次が明記するのは2030年度46%とCN2050<br><br><b>解説</b>　2035年度60%・2040年度73%削減（2013年度比）は2025年2月閣議決定の地球温暖化対策計画の数字。第六次環境基本計画の本体・概要には明記されていない<br><br><b>答案に書くなら</b>　本計画が明記する削減目標は2030年度46%とカーボンニュートラル2050であり、2035年度60%・2040年度73%は地球温暖化対策計画の数字である。<br><br><b>関連</b>　連携する第五次循環型社会形成推進基本計画や生物多様性国家戦略2023-2030も別個の計画で、本計画の内容として引用しない。<br><br><b>答案での使い方</b>　両計画の数字を混同すると減点。書き分ける<br><br>【出典】<a href=\"https://www.env.go.jp/content/000223504.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜時期】地球温暖化対策計画（現行）が閣議決定されたのはいつ（何年何月）？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2025年2月（2021年10月の前計画を改定）。2035・2040年度目標はこの改定で新設<br><br><b>解説</b>　地球温暖化対策推進法第8条第1項に基づく計画で、2021年10月の前計画を2025年2月18日に改定した。前計画は2030年度目標のみで、2035・2040年度目標が新設された<br><br><b>答案に書くなら</b>　本計画は2025年2月に改定された地球温暖化対策計画であり、2035・2040年度目標を含む最新版に基づいて課題を整理する。<br><br><b>関連</b>　根拠法は環境基本法第15条ではなく温対法第8条第1項で、第六次環境基本計画とは別の計画である。<br><br><b>答案での使い方</b>　書き出しで最新版を明示。旧計画(2030年度のみ)と区別<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜目標】地球温暖化対策計画の2030・2035・2040年度の削減目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2013年度比で2030年度46%（7.6億t）、2035年度60%（5.7億t）、2040年度73%（3.8億t）<br><br><b>解説</b>　削減率の基準は2013年度の排出・吸収量。2030年度は46%減（さらに50%の高みに挑戦）、2035年度は60%減、2040年度は73%減と段階的に深掘りし、2050年にネットゼロを目指す<br><br><b>答案に書くなら</b>　環境の観点から、2030年度46%、2035年度60%、2040年度73%という段階的な削減目標の達成に向け、対策の加速が課題である。<br><br><b>関連</b>　2030年度目標46%は旧計画から不変で、2035・2040年度が新設である。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 課題の大きさと(2)の到達点の根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜目標】2024年度の温室効果ガス排出・吸収量は何億t（2013年度比）？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　9.94億t（2013年度比28.7%減）。初めて10億tを下回った（2026年4月発表）<br><br><b>解説</b>　2024年度の排出・吸収量は9.94億トンで、2013年度以降の最低値。初めて10億トンを下回った。2030年度目標の7.6億トンまでは依然として差がある<br><br><b>答案に書くなら</b>　環境の観点から、2024年度の排出・吸収量は9.94億トン（2013年度比28.7%減）であり、2030年度目標の7.6億トンまでなお大きな差がある。<br><br><b>関連</b>　2022年度は10.8億トン（2013年度比22.9%減）、2023年度確報値は10.17億トン（27.1%減）である。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 現状と2030年度目標7.6億tとの差を示す<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜目標】家庭部門のエネルギー起源CO2の2030年度目安は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　71百万t（2013年度209百万tから66%減）<br><br><b>解説</b>　家庭部門のエネルギー起源CO2は、2013年度の209百万tから2030年度に71百万t（66%減）とする目安。全体目標の46%減より大幅に深い削減率である。R8 Ⅰ-2の題材でもある<br><br><b>答案に書くなら</b>　環境の観点から、家庭部門は2013年度209百万tから2030年度71百万t（66%減）へ、全体目標より深い削減が求められることが課題である。<br><br><b>関連</b>　2040年度は約40〜60百万t（71〜81%減）の目安で、運輸部門の2030年度目安は146百万t（35%減）である。<br><br><b>答案での使い方</b>　R8 Ⅰ-2の題材。全体目標46%と取り違えない<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜柱】地球温暖化対策計画の4本の柱は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　エネルギー転換／産業・業務・運輸等／地域・くらし／横断的取組<br><br><b>解説</b>　計画の柱はエネルギー転換、産業・業務・運輸等、地域・くらし、横断的取組の4つ。エネルギー転換は再エネ・原子力の最大活用、LNG火力の脱炭素化、非効率石炭のフェードアウトなどを含む<br><br><b>答案に書くなら</b>　解決策として、エネルギー転換、産業・業務・運輸等、地域・くらし、横断的取組の4分野で対策を一体的に進めることが必要である。<br><br><b>関連</b>　地域・くらしの柱は脱炭素先行地域100以上の創出や省エネ住宅、食品ロス削減を含む。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 解決策の分野を国の分類で言う<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜柱】横断的取組に位置づく施策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　成長志向型カーボンプライシング、循環経済移行、吸収源確保、国際貢献<br><br><b>解説</b>　横断的取組は、特定の部門に限らず全体に効く施策群である。成長志向型カーボンプライシングで投資を促し、循環経済で資源を循環させ、吸収源で排出を相殺し、国際貢献で世界の削減にも寄与する<br><br><b>答案に書くなら</b>　解決策として、成長志向型カーボンプライシング、循環経済移行、吸収源確保、国際貢献を部門横断で進めることが有効である。<br><br><b>関連</b>　吸収源対策は森林やブルーカーボンで、2040年度は約84百万t-CO2の吸収を見込む。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 横断的な解決策を挙げるときに<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜課題】温暖化対策計画を根拠に、脱炭素化が難しい分野の課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　水素・アンモニア・CCUS等による火力の脱炭素化や、航空・海運の次世代燃料の実用化に技術的ブレイクスルーが必要<br><br><b>解説</b>　火力や航空・海運は、電化や再エネだけでは脱炭素が難しい分野。水素・アンモニアやCCUS（CO2の回収・利用・貯留）、次世代燃料の実用化に技術的な突破が要る<br><br><b>答案に書くなら</b>　技術の観点から、水素・アンモニア・CCUS等による火力の脱炭素化や航空・海運の次世代燃料の実用化に、技術的ブレイクスルーが必要であることが課題である。<br><br><b>関連</b>　CCUSは発電所・工場等から排出されるCO2を分離・回収し、利用または地中に貯留する技術である。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜課題】脱炭素先行地域100以上の創出の課題を『人材・担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　計画策定・実施を担う自治体職員や事業者側の体制・人材の確保が課題<br><br><b>解説</b>　脱炭素先行地域は2030年度までに100以上の創出を目標とする。数が多いほど、計画の策定・実施を担う自治体職員や事業者側の体制が足りなくなりやすい<br><br><b>答案に書くなら</b>　人材・担い手の観点から、脱炭素先行地域の創出に向け、計画策定・実施を担う自治体職員や事業者側の体制・人材の確保が課題である。<br><br><b>関連</b>　小規模自治体では都道府県・連携中枢都市等との共同・連携策定が対策になる。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 人材・担い手の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜課題】2030年度目標とネットゼロを結ぶ道筋の課題を『経済・資金』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　中長期の予見可能性を高め、GX投資を加速する資金動員が課題<br><br><b>解説</b>　2030年度目標と2050年ネットゼロを直線的につなぐ経路には長期の巨額投資が必要。見通しが不透明だと企業は投資をためらうため、予見可能性の確保が資金動員の前提になる<br><br><b>答案に書くなら</b>　経済・資金の観点から、中長期の予見可能性を高め、GX投資を加速する資金動員が課題である。<br><br><b>関連</b>　制度面の対応が成長志向型カーボンプライシングで、エネルギー基本計画やGX2040ビジョンと一体的に運用する。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 経済・資金の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜解決策】火力発電の脱炭素化の解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　水素・アンモニア混焼やCCUSで火力を脱炭素化し、非効率石炭火力は計画的にフェードアウトする<br><br><b>解説</b>　火力の脱炭素化は、水素・アンモニア混焼やCCUSで排出を減らす手法。非効率石炭火力のフェードアウトは、発電効率の低い石炭火力を計画的に休廃止する対策である<br><br><b>答案に書くなら</b>　解決策として、水素・アンモニア混焼やCCUSで火力を脱炭素化し、非効率石炭火力を計画的にフェードアウトすることが有効である。<br><br><b>関連</b>　LNG火力はトランジション手段として位置づけられ、再エネ・原子力の最大活用と並行する。<br><br><b>答案での使い方</b>　必須Ⅰ(2) エネルギー転換の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜解決策】地域の脱炭素化の解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　脱炭素先行地域を2030年度までに100以上創出し、民生部門の電力CO2実質ゼロのモデルを全国へ広げる<br><br><b>解説</b>　脱炭素先行地域は、民生部門の電力消費に伴うCO2排出の実質ゼロ等を2030年度までに目指す先行モデルの地域。地域特性に応じた成功例を示し、横展開で全国の脱炭素化を進める<br><br><b>答案に書くなら</b>　解決策として、脱炭素先行地域を2030年度までに100以上創出し、民生部門の電力CO2実質ゼロのモデルを全国に広げることが有効である。<br><br><b>関連</b>　リスクは体制不足の小規模自治体で計画が形だけになることで、広域での人材支援が対策になる。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 地域・くらしの解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜リスク】石炭火力のフェードアウトを急ぐリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　リスク：代替電源の整備が追いつかず需給バランスに影響。対策：LNG火力を移行手段に使い、再エネ・原子力の最大活用を並行する<br><br><b>解説</b>　石炭火力を急に減らすと、代替電源が間に合わずに電力の需給バランス（供給の安定性）を崩すおそれがある。移行期間に使える電源を確保することが対策の骨格になる<br><br><b>答案に書くなら</b>　リスクとして、石炭火力のフェードアウトで電力の需給バランスに影響が出るおそれがあり、LNG火力を移行手段に用い、再エネ・原子力の最大活用を並行して進める必要がある。<br><br><b>関連</b>　JCM等の海外クレジット依存でも国内削減が希薄化するリスクがあり、国内削減を基本にフォローアップする。<br><br><b>答案での使い方</b>　必須Ⅰ(3) エネルギー転換のリスクと対策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地球温暖化対策計画｜注意】2035・2040年度の部門別CO2数値は確定値か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　確定値ではない。複数シナリオ分析に基づく幅のある「目安」<br><br><b>解説</b>　2035・2040年度のエネルギー起源CO2の部門別数値は、複数シナリオの分析に基づく幅のある見通しで、確定した配分ではない。技術進展が遅れると目標と実績のギャップが広がり得る<br><br><b>答案に書くなら</b>　2035・2040年度の部門別数値は複数シナリオに基づく「目安」であり、毎年の進捗点検で対策を柔軟に見直す必要がある。<br><br><b>関連</b>　進捗点検は毎年1回、地球温暖化対策推進本部でフォローアップを行う。<br><br><b>答案での使い方</b>　答案で確定値のように書くと減点。「目安」と書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000291668.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜時期】GX2040ビジョンと第7次エネルギー基本計画の閣議決定はいつ？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　いずれも2025年2月18日。別の文書で、GX2040は2023年7月の戦略の改訂版<br><br><b>解説</b>　GX2040ビジョンは脱炭素成長型経済構造移行推進法（GX推進法）に基づく戦略の改訂版、第7次エネルギー基本計画はエネルギー政策基本法第12条第1項に基づく計画で、根拠法が異なる別の文書である<br><br><b>答案に書くなら</b>　GX2040ビジョンと第7次エネルギー基本計画は2025年2月18日に閣議決定された最新版であり、これに基づいて課題を整理する。<br><br><b>関連</b>　GX2040ビジョンは2023年7月の脱炭素成長型経済構造移行推進戦略の改訂版である。<br><br><b>答案での使い方</b>　書き出しで最新版を明示。2文書を混ぜない<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜時期】排出量取引制度が本格稼働（義務化）する年度は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2026年度。2023年度開始の自主参加型GXリーグとは別<br><br><b>解説</b>　排出量取引制度は2026年度から本格稼働し、一定の排出規模以上の企業の参加を業種等を問わず義務化する。2023年度開始のGXリーグは自主参加型の第1段階で、本格稼働後は義務の制度に変わる<br><br><b>答案に書くなら</b>　制度の観点から、排出量取引制度は2026年度に本格稼働し、一定規模以上の排出企業に参加が義務化される。<br><br><b>関連</b>　義務化にはGX推進法改正案の国会提出が伴う。自主参加のGXリーグと時系列で混同しない。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰで「義務化済み」と書く根拠に<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜目標】2040年度の電源構成（目安）は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　再エネ4〜5割程度、火力3〜4割程度、原子力2割程度。2022年度は再エネ21.8%、火力72.6%<br><br><b>解説</b>　2040年度の電源構成は目安で、2022年度は火力が7割超と偏っていた。再エネを大きく伸ばし火力を減らす必要があり、現状との差が課題の大きさを示す<br><br><b>答案に書くなら</b>　環境・エネルギーの観点から、2022年度の再エネ21.8%・火力72.6%に対し、2040年度は再エネ4〜5割程度、火力3〜4割程度、原子力2割程度を目指す必要がある。<br><br><b>関連</b>　2040年度の数値は暫定値で確定した目標ではない。エネルギー自給率は3〜4割程度の見通し（2022年度は12.6%）である。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 現状との差で課題の大きさを示す<br><br>【出典】<a href=\"https://www.enecho.meti.go.jp/category/others/basic_plan/pdf/20250218_03.pdf\" target=\"_blank\" rel=\"noopener\">資源エネルギー庁（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜目標】GX経済移行債の規模と、呼び込む官民投資の規模は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　10年間で20兆円規模の先行投資支援により、150兆円規模の官民投資を呼び込む<br><br><b>解説</b>　GX経済移行債は先行投資支援の財源となる国債。国が先に投資を支えることで、民間の投資判断を後押しし、規模の大きい官民投資を引き出す<br><br><b>答案に書くなら</b>　資金面の解決策として、GX経済移行債による10年間で20兆円規模の先行投資支援で、150兆円規模の官民投資を呼び込むことが有効である。<br><br><b>関連</b>　支援の配分は、炭素価格の予見性を確保しつつ多排出産業の構造転換へ適切に行う必要がある。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 資金面の解決策の規模感に<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜柱】GX2040ビジョンの柱のうち、カーボンプライシングの柱は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　成長志向型カーボンプライシング構想。排出量取引制度の本格稼働と化石燃料賦課金（2028年度）で炭素価格を形成<br><br><b>解説</b>　カーボンプライシングは炭素に価格をつけて排出削減とGX投資を促す仕組み。この構想は排出量取引制度と化石燃料賦課金を組み合わせて、炭素価格を段階的に形成する<br><br><b>答案に書くなら</b>　制度の観点から、成長志向型カーボンプライシング構想により、排出量取引制度と化石燃料賦課金で炭素価格を段階的に形成することが解決策である。<br><br><b>関連</b>　化石燃料賦課金は化石燃料の輸入事業者等に課す賦課金で、2028年度から導入予定である。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 制度面の解決策の国の言葉に<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜柱】GX2040ビジョンの「GX産業立地」の考え方は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　脱炭素電源を見据えた産業集積の加速と、地域に利益が及ぶ地域GXを進める<br><br><b>解説</b>　GX産業立地は、脱炭素電源が使える場所に産業を集積させる考え方。電源の近くに企業を集めれば競争力と脱炭素を両立でき、利益を地域に及ぼす地域GXが合意形成の鍵になる<br><br><b>答案に書くなら</b>　地域の観点から、脱炭素電源を見据えた産業集積を進めつつ、利益が地域に及ぶ地域GXを進めることが解決策である。<br><br><b>関連</b>　データセンター立地では電力と通信のインフラ整備を効率的に連携させるワット・ビット連携の考え方もある。<br><br><b>答案での使い方</b>　必須Ⅰ・Ⅲ 地域系の解決策の方向づけに<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜課題】再エネ主力電源化（2040年度4〜5割）の課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　出力変動を調整する系統整備・蓄電池・次世代革新炉など複数技術の同時確立が必要で、単一技術では対応できない<br><br><b>解説</b>　再エネは天候で出力が変動するため、主力電源にするには需給を調整する手段が要る。系統整備、蓄電池、次世代革新炉などの複数技術がそろって初めて安定供給と両立できる<br><br><b>答案に書くなら</b>　技術の観点から、再エネ主力電源化には、出力変動に対応する系統整備・蓄電池・次世代革新炉など複数技術を同時に確立する必要があることが課題である。<br><br><b>関連</b>　次世代革新炉は安全性を高めた新型の原子炉技術で、原子力の活用と並行して検討される。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜課題】排出量取引制度の義務化の課題を『制度』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　公平性確保のため、業種別の無償割当ルールと価格安定化措置（上限・下限価格）の制度設計が課題<br><br><b>解説</b>　排出量取引は事業者に排出枠を割り当てる仕組みで、無償割当てのルールが不公平だと産業間の反発を招く。価格が乱高下すると投資計画も立てにくいため、上限・下限価格で安定させる<br><br><b>答案に書くなら</b>　制度の観点から、排出量取引制度の義務化にあたり、公平性確保のため業種別の無償割当ルールと上限・下限価格などの価格安定化措置の制度設計が課題である。<br><br><b>関連</b>　運営やGX投資へのファイナンス支援はGX推進機構（2024年7月業務開始）が担う。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 制度の観点の課題に<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜課題】中堅・中小企業のGX対応の課題を『人材・担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　大企業に比べ支援機関・資金・人材が不足し、排出量の見える化や設備高度化の対応力の差が広がりやすい<br><br><b>解説</b>　排出量の見える化や設備の高度化には、専門の支援機関、資金、人材が必要。大企業は自力で対応できるが、中堅・中小企業は不足しやすく、対応力の差が広がる<br><br><b>答案に書くなら</b>　人材・担い手の観点から、中堅・中小企業は大企業に比べ支援機関・資金・人材が不足し、排出量の見える化や設備高度化の対応力の差が広がりやすいことが課題である。<br><br><b>関連</b>　GX産業構造の柱では、GX価値の見える化や企業の成長投資・カーブアウトで産業競争力を両立する。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 人材・担い手の観点の課題に<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜解決策】排出量取引制度による解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　排出枠の無償割当てと取引で炭素価格を形成し、多排出産業の投資と構造転換を促す<br><br><b>解説</b>　排出量取引制度（GX-ETS）は、排出枠を割り当てて取引させることで炭素に価格をつける制度。排出に費用がかかるようになるため、多排出産業の投資や構造転換が促される<br><br><b>答案に書くなら</b>　制度面の解決策として、排出量取引制度で排出枠の無償割当てと取引により炭素価格を形成し、多排出産業の投資と構造転換を促すことが有効である。<br><br><b>関連</b>　リスクはコスト増による競争力低下と海外移転（カーボンリーケージ）で、対策は業種特性への配慮である。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 制度面の解決策に<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜解決策】再エネ主力電源化の解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　S+3Eを前提に、系統整備・蓄電池・次世代革新炉・火力の脱炭素化を並行して進める<br><br><b>解説</b>　S+3Eは、安全性を前提にエネルギー安定供給・経済効率性・環境適合の3つを同時に達成する基本視点。再エネだけに偏らず、系統整備や蓄電池、原子力、火力の脱炭素化を並行して進める根拠になる<br><br><b>答案に書くなら</b>　エネルギーの観点から、S+3Eを前提に、系統整備・蓄電池・次世代革新炉・火力の脱炭素化を並行して再エネ主力電源化を進めることが解決策である。<br><br><b>関連</b>　リスクは出力変動の増大による周波数・系統安定性の低下で、火力の調整力維持が対策になる。<br><br><b>答案での使い方</b>　必須Ⅰ(2) エネルギー面の解決策に<br><br>【出典】<a href=\"https://www.enecho.meti.go.jp/category/others/basic_plan/pdf/20250218_03.pdf\" target=\"_blank\" rel=\"noopener\">資源エネルギー庁（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜解決策】データセンター立地等の合意形成の解決策を、専門用語で言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　地域GX（地域裨益型・地域共生型）で、脱炭素電源の利益を地域に還元し、自治体と連携して地方創生につなげる<br><br><b>解説</b>　データセンターなどの立地は地域に雇用や税収をもたらす一方、電力需要の急増や住民の理解が課題になる。地域GXは、脱炭素電源の整備の利益を地域に還元し、自治体と連携して進めることで合意を得る考え方である<br><br><b>答案に書くなら</b>　地域の観点から、地域GXにより脱炭素電源の利益を地域に還元し、自治体と連携して地方創生につなげることが解決策である。<br><br><b>関連</b>　企業を誘致する自治体への支援と、住民への裨益を両立させることが課題とされる。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 地域系の解決策に<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜リスク】排出量取引制度の義務化で生じるリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　リスク：多排出産業の競争力低下と海外移転（カーボンリーケージ）。対策：政府指針による業種配慮の無償割当てと移行期の投資余力確保<br><br><b>解説</b>　義務化で炭素のコストが上がると、鉄鋼・化学などの多排出産業は国際競争で不利になり、規制の緩い国へ製造拠点が移る（カーボンリーケージ）おそれがある。業種ごとの事情を制度に反映することが対策になる<br><br><b>答案に書くなら</b>　リスクとして、多排出産業の競争力低下とカーボンリーケージが懸念されるため、政府指針で業種特性に配慮した無償割当てを行い、移行期の投資余力を確保する必要がある。<br><br><b>関連</b>　排出量取引や賦課金のコストは電気料金・製品価格に転嫁され、中小企業や家庭の負担増につながるおそれもある。<br><br><b>答案での使い方</b>　必須Ⅰ(3) 制度導入のリスクと対策に<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【GX2040ビジョン／第7次エネルギー基本計画｜注意】2035年度60%・2040年度73%削減と、R8 Ⅰ-2の家庭部門66%の違いは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　60%・73%は全体（2013年度比）、66%は家庭部門（2030年度）。母集団が違う<br><br><b>解説</b>　60%・73%は日本全体の温室効果ガス排出量の削減率（2013年度比、2035・2040年度）で、家庭部門の66%は地球温暖化対策計画の2030年度の目安。同じ数字でも、対象（母集団）と年度が違う<br><br><b>答案に書くなら</b>　2035年度60%・2040年度73%は全体の削減目標、家庭部門66%は地球温暖化対策計画の2030年度の目安であり、対象が異なる。<br><br><b>関連</b>　家庭部門の2040年度目安は71〜81%減で、いずれも2013年度が基準である。<br><br><b>答案での使い方</b>　数字は母集団とセットで書く。取り違えは減点<br><br>【出典】<a href=\"https://www.cas.go.jp/jp/seisaku/gx_jikkou_kaigi/pdf/gx2040_vision_kaitei.pdf\" target=\"_blank\" rel=\"noopener\">内閣官房（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜時期】気候変動適応計画の閣議決定と一部変更はいつ（何年何月）？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2021年10月に閣議決定、2023年5月に一部変更。一部変更で熱中症対策実行計画が第4章に追加<br><br><b>解説</b>　当初の計画は2021年10月22日に閣議決定され、2023年5月30日の一部変更で熱中症対策実行計画が第4章に追加された。実行計画は2023年4月改正の気候変動適応法第16条第1項に基づく<br><br><b>答案に書くなら</b>　本計画は2021年10月に閣議決定され、2023年5月の一部変更で熱中症対策実行計画が第4章に加わった気候変動適応計画である。<br><br><b>関連</b>　計画変更の根拠は第8条第1項、実行計画の根拠は第16条第1項で、条文番号を混同しない。<br><br><b>答案での使い方</b>　書き出しで版を明示。熱中症対策は第4章の内容として書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜時期】気候変動適応計画の次の改定の見通しは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2026年2月の第3次影響評価報告書を受け、2026年度内に改定予定。骨子は2026年6月<br><br><b>解説</b>　第3次気候変動影響評価報告書が2026年2月16日に公表され、気候変動適応計画の改定は2026年度に予定されている。影響評価はおおむね5年ごとに実施され、その結果を勘案して計画を改定する<br><br><b>答案に書くなら</b>　気候変動適応計画は、2026年2月公表の第3次影響評価報告書を受けて2026年度に改定が予定されている。<br><br><b>関連</b>　現行計画の計画期間はおおむね5年間で、「改定予定」と書き、現行版と区別する。<br><br><b>答案での使い方</b>　書き出しで「改定予定」と書き、旧版との取り違えを避ける<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜目標】熱中症対策実行計画の中期目標（2030年）は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　熱中症死亡者数（5年移動平均）を、令和4年概数の1,295名から半減<br><br><b>解説</b>　熱中症対策実行計画は、2030年までに熱中症による死亡者数（5年移動平均）を令和4年概数の1,295名から半減させる中期目標を置く。基準値と比べて到達度を測る数値目標になる<br><br><b>答案に書くなら</b>　解決策の到達点として、2030年までに熱中症死亡者数（5年移動平均）を令和4年概数1,295名から半減させることを目指す。<br><br><b>関連</b>　目標は死亡者数の5年移動平均で、単年の実績とは扱いが異なる。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 解決策の到達点の根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000136709.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜目標】熱中症死亡者数の実績は目標の基準値と比べてどうか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　令和5年1,651人、令和6年2,160人と、基準値1,295名を大きく上回り増加（人口動態統計確定数）<br><br><b>解説</b>　実績は目標と逆方向に動いており、人口動態統計（確定数）の熱中症死亡者数は令和5年に1,651人、令和6年に2,160人。基準値1,295名を大きく上回り、課題の大きさを示す<br><br><b>答案に書くなら</b>　健康の観点から、熱中症死亡者数は令和5年1,651人、令和6年2,160人と基準値1,295名を大きく上回って増加しており、対策の強化が課題である。<br><br><b>関連</b>　基準値の1,295名は令和4年の概数で、確定数ではなく概数の数字である。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 課題の大きさを示す数字に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000136709.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜柱】適応計画の7つの基本戦略は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　施策への組み込み、科学的知見、情報基盤、地域推進、事業者等の促進、国際貢献、関係機関連携<br><br><b>解説</b>　計画は、あらゆる施策に適応を組み込み、科学的知見に基づき、情報基盤を整備し、地域の実情に応じ、国民・事業者の理解を深め、途上国の能力向上に貢献し、関係機関が連携する、という7つの基本戦略を掲げる<br><br><b>答案に書くなら</b>　解決策として、あらゆる施策への適応の組み込みや科学的知見に基づく推進など、7つの基本戦略に沿って対策を進めることが有効である。<br><br><b>関連</b>　第2章の7分野（分野別施策）とは別物で、どちらも7個なので混同しない。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 解決策の方向を国の言葉で言う<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜柱】適応計画で「地域の実情に応じた適応」を進める仕組みは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　地域気候変動適応計画と地域適応センター。国立環境研究所が情報基盤A-PLATで支援<br><br><b>解説</b>　地域ごとに気候影響が違うため、地域単位で適応を進める。都道府県・市町村が地域気候変動適応計画を策定し、地域適応センターが影響情報の収集・提供を担い、国立環境研究所が情報基盤A-PLATで支える<br><br><b>答案に書くなら</b>　地域の観点から、地域気候変動適応計画と地域気候変動適応センターを軸に、A-PLATによる情報基盤で地域の実情に応じた適応を進めることが解決策である。<br><br><b>関連</b>　A-PLATは国内向け、AP-PLATはアジア太平洋の途上国向けの情報プラットフォームである。<br><br><b>答案での使い方</b>　必須Ⅰ・Ⅱ-2 地域施策の根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜課題】地域の適応推進の課題を『制度・政策』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　地域適応計画の策定が努力義務にとどまるため、地域適応センターの設置を含む制度的な推進力の確保が課題<br><br><b>解説</b>　地域気候変動適応計画の策定は都道府県・市町村の努力義務にとどまり、強制力が弱い。推進力を確保するには、地域適応センターの設置など制度面の枠組みが要る<br><br><b>答案に書くなら</b>　制度・政策の観点から、地域気候変動適応計画の策定が努力義務にとどまるため、地域適応センターの設置を含む制度的な推進力の確保が課題である。<br><br><b>関連</b>　国と地方が連携する場として、環境省が主導して気候変動適応広域協議会を組織する。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 制度・政策の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜課題】適応策の課題を『経済・資金』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　事業者の気候リスク対応投資を促し、適応ビジネスをどう資金面で後押しするかが課題<br><br><b>解説</b>　気候リスクが事業に与える影響への備えは、事業者の投資に頼る部分が大きい。適応ビジネスは、気候変動影響を事業機会として捉え、他者の適応を支援する製品・サービスを展開する事業活動で、これを資金面でどう支えるかが課題になる<br><br><b>答案に書くなら</b>　経済・資金の観点から、事業者の気候リスク対応投資を促し、適応ビジネスを資金面でどう後押しするかが課題である。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 経済・資金の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜課題】適応策の課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　農業の高温耐性品種の開発・普及と、流域治水やグリーンインフラによるハード・ソフト一体の防災技術の高度化が課題<br><br><b>解説</b>　気候の高温化で作物の品質低下や水害の激甚化が進む。高温耐性品種は耐暑性を高めた品種で、流域治水やグリーンインフラは自然の機能も使う防災手法である。複数の技術を高度化する必要がある<br><br><b>答案に書くなら</b>　技術の観点から、農業の高温耐性品種の開発・普及と、流域治水やグリーンインフラによるハード・ソフト一体の防災技術の高度化が課題である。<br><br><b>関連</b>　高温耐性品種はコメや果樹で導入が進む。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜解決策】水害リスクの解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　流域治水で、河川整備に加え流域全体の関係者が協働し、ハード・ソフト一体で水害リスクを下げる<br><br><b>解説</b>　流域治水は、河川整備だけでなく流域全体のあらゆる関係者が協働する治水の考え方。ハード（堤防等）とソフト（情報・避難等）を一体で進め、水害リスクを低減する<br><br><b>答案に書くなら</b>　解決策として、流域治水により、河川整備に加え流域全体の関係者が協働し、ハード・ソフト一体で水害リスクを下げることが有効である。<br><br><b>関連</b>　グリーンインフラは自然の機能を活用する社会資本整備の手法で、流域治水と組み合わせて使う。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 自然災害分野の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜解決策】熱中症の解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　熱中症警戒情報・特別警戒情報（WBGT基準）の発表と、指定暑熱避難施設の開放で、高齢者等の被害を防ぐ<br><br><b>解説</b>　熱中症警戒情報は、府県予報区内の1地点以上で日最高WBGTが33以上と予測される場合、特別警戒情報は都道府県内の全地点で35以上と予測される場合に発表される。特別警戒情報の発表時には指定暑熱避難施設が開放される<br><br><b>答案に書くなら</b>　解決策として、熱中症警戒情報・特別警戒情報の発表と指定暑熱避難施設の開放により、高齢者等の熱中症被害を防ぐことが有効である。<br><br><b>関連</b>　WBGT（暑さ指数）は気温・湿度・放射熱から算出する熱中症予防の指標である。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 健康分野の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000136709.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜リスク】流域治水の大規模投資で生じるリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　リスク：財政負担の拡大と生態系の分断など新たな環境影響。対策：グリーンインフラやNbSを組み合わせ環境配慮型の整備を優先する<br><br><b>解説</b>　堤防など大規模なハード整備は財政負担が重く、生態系の分断のような新たな環境影響も生む。グリーンインフラやNbS（自然を活用した解決策）を組み合わせれば環境への配慮と防災を両立しやすい<br><br><b>答案に書くなら</b>　リスクとして、流域治水の大規模投資は財政負担の拡大や生態系の分断を招くおそれがあり、グリーンインフラやNbSを組み合わせた環境配慮型の整備を優先する必要がある。<br><br><b>関連</b>　NbSは生態系の保全・再生など自然の機能を活用して社会課題を解決する手法である。<br><br><b>答案での使い方</b>　必須Ⅰ(3) ハード整備のリスクと対策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜リスク】地域適応計画が努力義務であることで生じるリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　リスク：小規模市町村で策定が進まず地域間の適応力が開く。対策：広域協議会を通じ都道府県が市町村を技術的・財政的に支援<br><br><b>解説</b>　努力義務のため、財政力や専門人材が乏しい小規模市町村で策定が進まず、自治体間の適応力の差が広がる。国と地方が連携する広域協議会を通じ、都道府県が市町村を技術的・財政的に支援する体制が対策になる<br><br><b>答案に書くなら</b>　リスクとして、努力義務のため小規模市町村で策定が進まず地域間の適応力が開くおそれがあり、気候変動適応広域協議会を通じて都道府県が市町村を技術的・財政的に支援する必要がある。<br><br><b>関連</b>　国立環境研究所も地方公共団体に技術的援助を行う。<br><br><b>答案での使い方</b>　必須Ⅰ(3)・Ⅱ-2 自治体支援の根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【気候変動適応計画｜注意】適応計画の「7分野」と「7つの基本戦略」は同じか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　別物。7分野は農林水産業・水環境・自然生態系・自然災害・健康・産業経済・国民生活の分野別施策<br><br><b>解説</b>　7分野は第2章の分野別施策で、農業・林業・水産業、水環境・水資源、自然生態系、自然災害・沿岸域、健康、産業・経済活動、国民生活・都市生活を指す。7つの基本戦略は施策への組み込みなど進め方の枠組みで、別の分類である<br><br><b>答案に書くなら</b>　分野別施策の7分野（農林水産業、水環境・水資源、自然生態系、自然災害・沿岸域、健康、産業・経済活動、国民生活・都市生活）と7つの基本戦略は別物であり、設問に応じて書き分ける。<br><br><b>関連</b>　気候変動適応計画は適応策の計画で、温室効果ガスの46%削減など緩和策の数値目標は地球温暖化対策計画のものである。<br><br><b>答案での使い方</b>　どちらも7個。分野を問う設問に戦略を書くと減点<br><br>【出典】<a href=\"https://www.env.go.jp/content/000176391.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜時期】生物多様性国家戦略2023-2030が閣議決定されたのはいつ（何年何月）？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2023年3月（31日）。第六次環境基本計画（2024年5月）とは別の計画<br><br><b>解説</b>　2023年3月31日に閣議決定された戦略で、根拠は生物多様性基本法第12条第1項。環境基本計画を基本に策定するため協調関係にあるが、2024年5月閣議決定の第六次環境基本計画とは別の計画である<br><br><b>答案に書くなら</b>　本戦略は2023年3月に閣議決定された生物多様性国家戦略2023-2030であり、2030年のネイチャーポジティブ実現を目指す。<br><br><b>関連</b>　R6 Ⅰ-1とR8 Ⅰ-1で出題歴があり、「第六次」を付けて環境基本計画と取り違えない。<br><br><b>答案での使い方</b>　書き出しで版を明示。R6・R8 Ⅰ-1で出題<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜目標】30by30は国家戦略のどの目標に位置づく？その内容は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　行動目標1-1。2030年までに陸と海の30%以上を保護地域・OECMで保全<br><br><b>解説</b>　30by30は国家戦略全体の名称ではなく、行動目標1-1として位置づく国際目標の一つ。2030年までに陸と海それぞれの30%以上を保護地域とOECMで保全する<br><br><b>答案に書くなら</b>　生態系保全の観点から、行動目標1-1の30by30に基づき、2030年までに陸と海の30%以上を保護地域・OECMで保全することが解決策の到達点である。<br><br><b>関連</b>　ネイチャーポジティブは2030年に目指す状態で、30by30はその指標・手段である。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 解決策の到達点に。戦略そのものではない<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜目標】中間評価（2026年2月）の保護地域・OECM占有率は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　陸域21.0%（2025年時点）、海域13.3%（2021年以降変化なし）。目標は各30%<br><br><b>解説</b>　中間評価（2026年2月公表）では、保護地域とOECMが占める割合は陸域21.0%（2025年時点、2023年3月は20.5%）、海域13.3%（2021年以降変化なし）で、目標30%との差が大きい。特に海域は停滞している<br><br><b>答案に書くなら</b>　生態系保全の観点から、保護地域・OECMの割合は陸域21.0%、海域13.3%にとどまり、目標30%との差を埋めることが課題である。<br><br><b>関連</b>　陸域は20.5%から微増、海域は2021年以降変化がなく、海域の停滞が目立つ。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 目標との差で課題の大きさを示す<br><br>【出典】<a href=\"https://www.env.go.jp/content/000379260.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜柱】国家戦略の基本戦略1〜3は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　①生態系の健全性の回復、②自然を活用した社会課題の解決、③ネイチャーポジティブ経済の実現<br><br><b>解説</b>　基本戦略1は生息地の保全とネットワーク化、2は自然を活用した社会課題の解決、3は経済への自然資本の内部化に当たる。R6 Ⅰ-1ではこの3つの基本戦略が問われた<br><br><b>答案に書くなら</b>　解決策として、生態系の健全性の回復、自然を活用した社会課題の解決、ネイチャーポジティブ経済の実現の3つの基本戦略に沿って対策を進めることが有効である。<br><br><b>関連</b>　基本戦略は全部で5つで、4と5は暮らしの行動変容と基盤整備・国際連携である。<br><br><b>答案での使い方</b>　R6 Ⅰ-1の3戦略。解決策の方向を国の言葉で言う<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜柱】基本戦略4と5は？また目標の構成数は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　4：生活・消費活動での価値の認識と行動、5：基盤整備と国際連携。5基本戦略・15状態目標・25行動目標<br><br><b>解説</b>　基本戦略4は国民一人一人の行動変容を促す普及啓発・場づくり、5は生物多様性に係る取組を支える基盤整備（モニタリング基盤等）と国際連携である。戦略は全体で5つの基本戦略・15の状態目標・25の行動目標から成る<br><br><b>答案に書くなら</b>　解決策として、基本戦略4の生活・消費活動での価値の認識と行動、基本戦略5の基盤整備と国際連携を組み合わせて進めることが有効である。<br><br><b>関連</b>　R6 Ⅰ-1で問われた3戦略は全体の一部なので、設問の範囲を確認する。<br><br><b>答案での使い方</b>　3戦略は全体の一部。設問の範囲を確認する<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜課題】30by30達成の課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　OECMとして整理できる区域を見極める評価手法が未確立で、自然共生サイトの認定基準・モニタリング手法の標準化が課題<br><br><b>解説</b>　OECMは法的な保護地域以外で生物多様性の保全に資する管理が行われている区域。保護地域の拡張だけでは30%に届かないため、OECMを見極める評価手法と、自然共生サイトの認定基準・モニタリング手法の標準化が要る<br><br><b>答案に書くなら</b>　技術の観点から、OECMとして整理できる区域を見極める評価手法が未確立であり、自然共生サイトの認定基準・モニタリング手法の標準化が課題である。<br><br><b>関連</b>　自然共生サイトは日本版OECMで、国際データベース（Protected Planet）に登録される。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜課題】ネイチャーポジティブ経営の課題を『経済・資金』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　自然資本の損失の外部不経済を価格に反映する経済的手法が実証段階にとどまり、民間資金の誘導が不十分<br><br><b>解説</b>　自然資本の損失は外部不経済で、価格に反映されにくい。OECM認定地の環境価値の売買や税制優遇などの経済的手法が調査・実証段階にとどまるため、民間資金の誘導が不十分になる<br><br><b>答案に書くなら</b>　経済・資金の観点から、自然資本の損失の外部不経済を価格に反映する経済的手法が実証段階にとどまり、ネイチャーポジティブ経営への民間資金の誘導が不十分であることが課題である。<br><br><b>関連</b>　解決策の側ではTNFDによる情報開示とESG金融で自然資本を経済に内部化する。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 経済・資金の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜課題】里山・森林の保全の課題を『人材・担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　森林・農地・里山の管理の担い手が不足し、担い手の確保・育成と地域主体の取組を支えるインセンティブ設計が必要<br><br><b>解説</b>　森林・農地・里山の保全活動は、管理の担い手不足に直面している。担い手の確保・育成と、地域主体の取組を支えるインセンティブ設計がないと、保全活動を持続できない<br><br><b>答案に書くなら</b>　人材・担い手の観点から、森林・農地・里山の管理の担い手不足に対し、担い手の確保・育成と地域主体の取組を支えるインセンティブ設計が必要であることが課題である。<br><br><b>関連</b>　鳥獣との軋轢緩和など、農林水産業被害の防止と生態系保全の利害調整も地域の課題である。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 人材・担い手の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜解決策】民間の取組を生かす30by30の解決策を、専門用語で言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　自然共生サイト（日本版OECM）で、民間等が保全する区域を国が認定し、国際データベースに登録する<br><br><b>解説</b>　自然共生サイトは、民間等の取組で生物多様性が保全されている区域を国が認定する制度で、日本版OECMとして国際データベースに登録される。民間の土地を30by30の達成に取り込む手段になる<br><br><b>答案に書くなら</b>　解決策として、自然共生サイトにより民間等が保全する区域を国が認定し、日本版OECMとして国際データベースに登録して30by30の達成に寄与させることが有効である。<br><br><b>関連</b>　有志の企業・自治体が取組を促す生物多様性のための30by30アライアンスも枠組みとして使える。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 30by30の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜解決策】企業の自然資本対応の解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　TNFDによる自然関連リスク・機会の情報開示を促し、ESG金融と結び付けてネイチャーポジティブ経済へ移行する<br><br><b>解説</b>　TNFDは、企業・金融機関が自然資本・生物多様性に関するリスクと機会を評価して開示する国際的な民間主導の枠組み。開示を促してESG金融と結び付けると、資金がネイチャーポジティブ経営へ流れる<br><br><b>答案に書くなら</b>　経済の観点から、TNFDによる自然関連リスク・機会の情報開示を促し、ESG金融と結び付けてネイチャーポジティブ経済へ移行することが解決策である。<br><br><b>関連</b>　SBTs for Natureも企業が自然資本の科学に基づく目標を設定する民間主導の枠組みで、リスクは情報開示コストが中小企業に偏ることである。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 経済面の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜解決策】社会課題と自然保全を両立する解決策を、専門用語で言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　グリーンインフラや生態系ネットワークで、防災・気候変動対応と生物の移動・遺伝的多様性の維持を両立する<br><br><b>解説</b>　グリーンインフラは自然の多様な機能を活用する国土・都市・地域づくりの考え方、生態系ネットワークは森・里・川・海をつなぎ生物の移動や遺伝的多様性を支える国土構造である。防災や気候変動対応と保全を両立させる<br><br><b>答案に書くなら</b>　解決策として、グリーンインフラや生態系ネットワークにより、防災・気候変動対応と生物の移動・遺伝的多様性の維持を両立することが有効である。<br><br><b>関連</b>　ネットワークの連結性向上は、鳥獣の生息域拡大や外来種の拡散という負の波及効果を伴うため、個体群管理や防除の強化が要る。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 自然活用の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜リスク】30by30を急ぐリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　リスク：住民のなりわいとの調整不足で反発を招く。対策：自然共生サイト認定や保護地域拡張時に事前協議プロセスを制度化する<br><br><b>解説</b>　30by30で保護地域やOECMの指定を急ぐと、土地利用やなりわいとの調整が不十分なまま進み、地元の反発を招く。事前協議のプロセスを制度化しておけば、合意形成を図りながら拡張できる<br><br><b>答案に書くなら</b>　リスクとして、30by30の指定を急ぐと住民のなりわいとの調整不足で反発を招くおそれがあり、自然共生サイト認定や保護地域拡張の際に事前協議プロセスを制度化する必要がある。<br><br><b>関連</b>　中小企業へのTNFD対応コストの偏りも別のリスクで、国が段階的な導入支援や人材育成で後押しする。<br><br><b>答案での使い方</b>　必須Ⅰ(3) 合意形成のリスクと対策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜リスク】不適正な再エネ導入がもたらすリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　リスク：生態系への悪影響で脱炭素と保全がトレードオフに。対策：環境影響評価とゾーニング、地域共生型再エネの導入<br><br><b>解説</b>　再エネ設備の不適正な導入は、自然生態系に悪影響を及ぼし、脱炭素と生物多様性保全がトレードオフになる。環境影響評価やゾーニング（環境保全・事業性・社会的調整の情報の重ね合わせ）で適地を選び、地域共生型の導入を進める<br><br><b>答案に書くなら</b>　リスクとして、不適正な再エネ導入が生態系に悪影響を及ぼし脱炭素と保全がトレードオフになるおそれがあり、環境影響評価とゾーニング、地域共生型の再エネ導入で対応する必要がある。<br><br><b>関連</b>　第六次環境基本計画でも、洋上・陸上風力の環境配慮の制度検討が同様のリスク対策に挙げられる。<br><br><b>答案での使い方</b>　必須Ⅰ(3) 再エネとの両立のリスクと対策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【生物多様性国家戦略2023-2030｜注意】OECMと自然共生サイトの違いは？また30by30は戦略の別名か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　OECMは国際的な保全区分、自然共生サイトは国が認定する日本版。30by30は目標の一つで戦略の別名ではない<br><br><b>解説</b>　OECMは国際的な保全区分の考え方、自然共生サイトはその日本版として国が認定する具体の制度。30by30は国家戦略が掲げる目標の一つで、戦略の別名ではなく、ネイチャーポジティブも戦略の別名ではない<br><br><b>答案に書くなら</b>　OECMは国際的な保全区分で、自然共生サイトはその日本版として国が認定する制度であり、両者を書き分ける。<br><br><b>関連</b>　ネイチャーポジティブは戦略が目指す2030年の状態を指す概念である。<br><br><b>答案での使い方</b>　定義の書き分けで減点を避ける<br><br>【出典】<a href=\"https://www.env.go.jp/content/000124381.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜時期】第五次循環型社会形成推進基本計画が閣議決定されたのはいつ（何年何月）？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2024年8月（2日）。副題は「循環経済を国家戦略に」<br><br><b>解説</b>　2024年8月2日に閣議決定された計画で、根拠は循環型社会形成推進基本法第15条。副題は「循環経済を国家戦略に」で、旧計画（第四次）と区別して最新版であることを示す<br><br><b>答案に書くなら</b>　本計画は2024年8月に閣議決定された第五次循環型社会形成推進基本計画であり、循環経済を国家戦略に位置づけている。<br><br><b>関連</b>　根拠法は環境基本法や生物多様性基本法ではなく、循環型社会形成推進基本法である。<br><br><b>答案での使い方</b>　書き出しで最新版を明示。第四次と取り違えない<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜目標】2030年度の資源生産性・資源消費量・最終処分量の目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　資源生産性約60万円/t、一人当たり天然資源消費量約11t/人・年、最終処分量約1,100万t/年<br><br><b>解説</b>　資源生産性はGDP等を天然資源等投入量で割った指標で、少ない資源でどれだけ稼ぐかを示す。一人当たり天然資源消費量はマテリアルフットプリントと呼ぶ。最終処分量は埋立てに回る廃棄物の量で、いずれも2030年度が目標年次<br><br><b>答案に書くなら</b>　環境の観点から、2030年度に資源生産性約60万円/トン、一人当たり天然資源消費量約11トン/人・年、最終処分量約1,100万トン/年を目指す必要がある。<br><br><b>関連</b>　目標年次は2030年度で、他計画の2040年度などと混同しない。<br><br><b>答案での使い方</b>　必須Ⅰ(1)(2) 現状との差と到達点の根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜目標】2030年度の循環利用率と再生資源の投入割合の目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　入口側約19%、出口側約44%。再生可能資源・循環資源の投入割合は約34%<br><br><b>解説</b>　入口側は資源の投入段階（天然資源に対する再生資源の割合）、出口側は廃棄物等の発生段階（廃棄物等のうち循環利用に回る割合）の循環利用率を指す。2030年度に入口側約19%、出口側約44%を目指し、再生可能資源・循環資源の投入割合は約34%とする<br><br><b>答案に書くなら</b>　環境の観点から、2030年度に入口側循環利用率約19%、出口側約44%、再生可能資源・循環資源の投入割合約34%を目指す。<br><br><b>関連</b>　入口側と出口側の数字を逆に書かない。<br><br><b>答案での使い方</b>　入口と出口の数字を取り違えない<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜目標】循環経済関連ビジネスの市場規模目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2030年までに80兆円以上、2050年に120兆円（2020年は約50兆円）<br><br><b>解説</b>　循環経済関連ビジネスの市場規模は2000年の約40兆円から2020年に約50兆円へ拡大した。成長戦略フォローアップ工程表のKPIを踏襲し、2030年までに80兆円以上、2050年に120兆円を目標とする<br><br><b>答案に書くなら</b>　経済の観点から、循環経済関連ビジネスの市場規模を2020年の約50兆円から2030年までに80兆円以上へ拡大することが解決策の到達点である。<br><br><b>関連</b>　市場規模の目標年は2030年「度」ではなく「年」の表記で、2050年は120兆円である。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 経済面の解決策の到達点に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜柱】第五次循環基本計画の5つの重点分野は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　①循環経済への移行②事業者間連携③地域の循環システム④基盤強靱化⑤国際資源循環<br><br><b>解説</b>　5つの重点分野は2.1循環経済への移行による持続可能な地域と社会づくり、2.2事業者間連携、2.3地域の循環システム、2.4基盤強靱化と適正処理、2.5国際資源循環。R7 Ⅰ-2では事業者間連携、地域の循環システムと地方創生、国際資源循環の3つが問われた<br><br><b>答案に書くなら</b>　解決策として、事業者間連携、地域の循環システム構築、適正な国際資源循環体制の構築などの重点分野に沿って対策を進めることが有効である。<br><br><b>関連</b>　2.1と2.4はR7の問題文に含まれていなかった分野で、2.1は基盤方針である。<br><br><b>答案での使い方</b>　R7 Ⅰ-2は②③⑤の3つ。解決策の方向を国の言葉で<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜柱】動静脈連携とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　製造・小売の動脈産業と廃棄物処理・リサイクルの静脈産業が連携し、再生材利用の拡大と市場創出を図る取組<br><br><b>解説</b>　動脈産業は製造業・小売業など製品をつくる側、静脈産業は廃棄物処理・リサイクル業など使用後を担う側を指す。両者が連携することで、再生材の需要と供給をつなぎ、資源循環の市場を創出する<br><br><b>答案に書くなら</b>　解決策として、動脈産業と静脈産業が連携する動静脈連携により、再生材利用を拡大し資源循環市場を創出することが有効である。<br><br><b>関連</b>　この連携は重点分野2.2の事業者間連携によるライフサイクル全体での資源循環に当たる。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 事業者間連携の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜課題】動静脈連携の課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　再生材の品質の共通認識づくりと、デジタル製品パスポート対応のデータベースなど、循環性を計測・開示する技術基盤が未整備<br><br><b>解説</b>　再生材を使う製造側は品質への不安を持ちやすく、再生材の品質に関する共通認識がないと使われない。循環性を計測・開示するデータ基盤（デジタル製品パスポート対応のデータベース等）も整備途上である<br><br><b>答案に書くなら</b>　技術の観点から、再生材の品質に関する共通認識の醸成と、デジタル製品パスポート対応のデータベースなど循環性を計測・開示する技術基盤が未整備であることが課題である。<br><br><b>関連</b>　デジタル製品パスポート（DPP）は製品の原材料・成分・リサイクル性等をデジタルで記録・開示する欧州発の仕組みである。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜課題】資源循環の課題を『人材・担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　人口減少で廃棄物処理・資源循環のエッセンシャルワーカーが不足し、中小企業が大半の処理業者への影響が大きい<br><br><b>解説</b>　廃棄物処理や資源循環は現場の労働力に支えられ、エッセンシャルワーカーと呼ばれる。人口減少・少子高齢化で担い手が減り、事業者の大半が中小企業のため影響が大きい<br><br><b>答案に書くなら</b>　人材・担い手の観点から、人口減少で廃棄物処理・資源循環のエッセンシャルワーカーが不足し、中小企業が大半を占める処理業者への影響が大きいことが課題である。<br><br><b>関連</b>　重点分野2.4はDXと人材育成で担い手不足と災害廃棄物対応を強化する。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 人材・担い手の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜課題】市場規模80兆円の課題を『経済・資金』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　短期的には経済合理的でない動静脈連携への投資を、GX投資等で後押しする資金誘導が必要<br><br><b>解説</b>　動静脈連携は、短期的には既存ルートより費用がかかり経済合理性に乏しい場合がある。市場規模を2030年に80兆円以上へ拡大するには、その投資をGX投資等の資金誘導で後押しする必要がある<br><br><b>答案に書くなら</b>　経済・資金の観点から、短期的には経済合理的でない動静脈連携への投資を、GX投資等で後押しする資金誘導が必要であることが課題である。<br><br><b>関連</b>　80兆円は成長戦略フォローアップ工程表のKPIを踏襲した目標である。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 経済・資金の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜解決策】再生材の利用拡大の解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　動静脈連携で再生材利用を広げ、デジタル製品パスポート（DPP）で原材料・リサイクル性の情報を開示する<br><br><b>解説</b>　動静脈連携は製造と処理の事業者が連携して再生材利用を広げる取組、DPPは情報開示で循環を促す仕組み。両者を組み合わせれば、品質への不安を下げつつ再生材を流通させられる<br><br><b>答案に書くなら</b>　解決策として、動静脈連携で再生材利用を拡大し、デジタル製品パスポート（DPP）で原材料・リサイクル性の情報を開示することが有効である。<br><br><b>関連</b>　DPPは欧州発の制度的仕組みで、国内制度化が追いついていないことが制度面の課題である。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 技術・制度面の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜解決策】地域の循環の解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　地域の資源の地産地消・循環を進め、製造業・処理業と自治体・市民が連携する地域の循環システムで地方創生につなげる<br><br><b>解説</b>　地域の循環システムは、地域資源の地産地消・循環で地方創生と生態系保全を同時に進める重点分野2.3の考え方。製造業・処理業と自治体・市民など各主体の主体的な連携が要る<br><br><b>答案に書くなら</b>　地域の観点から、地域資源の地産地消・循環を進め、製造業・処理業と自治体・市民が連携する地域の循環システムで地方創生につなげることが解決策である。<br><br><b>関連</b>　参画の枠組みづくりが地域ごとに異なる点が、合意形成面の課題とされる。<br><br><b>答案での使い方</b>　必須Ⅰ・Ⅱ-2 地域施策の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜リスク】動静脈連携で再生材を急拡大するリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　リスク：品質管理や有害物質管理が不十分なまま流通。対策：製品安全・有害物質のリスク管理・不法投棄防止を伴う適正な取組を求める<br><br><b>解説</b>　再生材の利用を急に増やすと、品質管理や有害物質の管理が追いつかないまま流通し、製品安全上の懸念が出る。利用拡大と同時に、製品の安全性確保・有害物質のリスク管理・不法投棄の防止を各主体に求める必要がある<br><br><b>答案に書くなら</b>　リスクとして、再生材の急拡大で品質管理や有害物質管理が不十分なまま流通するおそれがあり、製品安全・有害物質のリスク管理・不法投棄防止を伴う適正な取組を各主体に求める必要がある。<br><br><b>関連</b>　国際資源循環では、輸出先での不適正処理への懸念があり、バーゼル条約等に基づく適正な輸出管理を徹底する。<br><br><b>答案での使い方</b>　必須Ⅰ(3) 再生材拡大のリスクと対策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【第五次循環型社会形成推進基本計画｜注意】第五次の数値目標の年次と、第四次との違いは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　目標年次は2030年度。第四次は指標が151あったが、第五次は指標数を絞り込んだ<br><br><b>解説</b>　数値目標の目標年次は2030年度。第四次計画は指標が151あったが、第五次は指標数を絞り込んだ。旧計画の指標数や目標値を使って答案を書かない<br><br><b>答案に書くなら</b>　本計画の数値目標は2030年度を目標年次としており、第四次計画の指標や目標値ではなく第五次の目標値で答案を書く。<br><br><b>関連</b>　地球温暖化対策計画の2030・2040年度目標や家庭部門の目標年とは別の計画の数字である。<br><br><b>答案での使い方</b>　旧計画の指標数・目標値で答案を書かない<br><br>【出典】<a href=\"https://www.env.go.jp/content/000242560.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜時期】地域脱炭素ロードマップの決定はいつで、決定主体は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2021年6月9日、国・地方脱炭素実現会議の決定。閣議決定ではない<br><br><b>解説</b>　地域脱炭素ロードマップは2021年6月9日の国・地方脱炭素実現会議（第3回）の決定文書で、閣議決定でも法定計画でもない。制度的な裏付けは2021年改正の地球温暖化対策推進法（地方公共団体実行計画・地域脱炭素化促進事業）である<br><br><b>答案に書くなら</b>　地域脱炭素ロードマップは2021年6月に国・地方脱炭素実現会議で決定された文書であり、地方からの脱炭素の移行戦略を示している。<br><br><b>関連</b>　第六次環境基本計画等は閣議決定で、決定主体が異なる点を書き分ける。R6 Ⅰ-2で出題された。<br><br><b>答案での使い方</b>　R6 Ⅰ-2で出題。書き出しで決定主体を正確に書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜時期】脱炭素先行地域の現在の年限の整理は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2025年度までに少なくとも100か所を選定し、2030年度までに実行<br><br><b>解説</b>　当初（2021年）は「2030年度までに少なくとも100か所をつくる」と表現されたが、現在の整理は「2025年度までに少なくとも100か所を選定し、2030年度までに実行」。選定の期限と実行の期限が別である<br><br><b>答案に書くなら</b>　脱炭素先行地域は、2025年度までに少なくとも100か所を選定し、2030年度までに実行することを目標としている。<br><br><b>関連</b>　当初の表現と現在の整理の2段階があり、選定年と実行年を取り違えない。<br><br><b>答案での使い方</b>　選定年と実行年を取り違えない。当初は「2030年度までに100か所」<br><br>【出典】<a href=\"https://www.env.go.jp/content/000376957.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜定義】脱炭素先行地域の定義の核は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　民生部門（家庭部門及び業務その他部門）の電力消費に伴うCO2排出の実質ゼロ。運輸・熱利用等は地域特性に応じて実施<br><br><b>解説</b>　脱炭素先行地域は、民生部門の電力消費に伴うCO2排出の実質ゼロを実現する地域。民生部門は家庭部門と業務その他部門を指し、運輸部門・熱利用等は地域特性に応じて排出削減する付随的な対策である<br><br><b>答案に書くなら</b>　脱炭素先行地域とは、民生部門（家庭部門及び業務その他部門）の電力消費に伴うCO2排出の実質ゼロを実現し、運輸・熱利用等も地域特性に応じて削減する地域である。<br><br><b>関連</b>　先行モデルを全国に伝搬させて2050年を待たずに脱炭素を実現する考え方を脱炭素ドミノという。<br><br><b>答案での使い方</b>　必須Ⅰ・Ⅱ-1 定義を問われたときの書き出しに<br><br>【出典】<a href=\"https://www.env.go.jp/content/000376957.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜目標】脱炭素先行地域の選定状況は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　第7回（2026年2月）までに45道府県133市町村の102提案が選定。3提案が辞退<br><br><b>解説</b>　第1回〜第7回（2026年2月13日時点）で、全国45道府県133市町村の102提案が選定され、選定後に3提案が辞退した。数の上では目標の100か所に届いたが、辞退が出ている点が実行上の課題である<br><br><b>答案に書くなら</b>　地域の観点から、脱炭素先行地域は102提案が選定された一方で3提案が辞退しており、選定後の実行可能性の確保が課題である。<br><br><b>関連</b>　辞退の背景はコスト増大や地元合意の難航で、計画段階での協議の徹底が対策になる。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 目標100か所との差・辞退を課題の根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000376957.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜目標】重点対策①自家消費型太陽光の導入目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2030年に設置可能な建築物の約50%、2040年に100%<br><br><b>解説</b>　重点対策①は屋根置きなどの自家消費型太陽光発電で、2030年に設置可能な建築物の約50%、2040年に100%への導入を目指す。再エネを地域内で消費して、エネルギー代金の域外流出を減らす考え方である<br><br><b>答案に書くなら</b>　解決策として、自家消費型の太陽光発電を2030年に設置可能な建築物の約50%、2040年に100%へ導入することが有効である。<br><br><b>関連</b>　環境省の試算では、約9割の市町村でエネルギー代金の域内外収支は域外支出が上回っている（2015年度）。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 太陽光の解決策の到達点に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜柱】ロードマップの8つの重点対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　①自家消費型太陽光②地域共生型再エネ③業務ビルZEB化④住宅省エネ⑤ゼロカーボン・ドライブ⑥資源循環⑦まちづくり⑧農林水産業<br><br><b>解説</b>　8つの重点対策は再エネ・省エネ・移動・循環・まちづくり・食農を網羅する。①自家消費型太陽光②地域共生型再エネ③業務ビルZEB化④住宅省エネ⑤ゼロカーボン・ドライブ⑥資源循環⑦まちづくり⑧農林水産業<br><br><b>答案に書くなら</b>　解決策として、自家消費型太陽光、地域共生型再エネ、ZEB・ZEH、ゼロカーボン・ドライブなど8つの重点対策を組み合わせることが有効である。<br><br><b>関連</b>　新築住宅はZEH、新築建築物はZEBの2030年平均実現、乗用車新車は2035年電動車100%を目指す。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 解決策を国の分類で言う<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜課題】地域脱炭素の課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　太陽光自家消費・ZEB・ZEH・電動車を全国に普及させるには、低圧需要での経済性確保と初期投資ゼロの導入モデルの確立が課題<br><br><b>解説</b>　太陽光自家消費・ZEB・ZEH・電動車は、全国津々浦々に広げる段階で、低圧需要での経済性が課題になる。初期投資ゼロの導入ビジネスモデルは、導入側の負担をなくして普及を加速させる手段である<br><br><b>答案に書くなら</b>　技術の観点から、太陽光自家消費・ZEB・ZEH・電動車を全国に普及させるため、低圧需要での経済性の確保と初期投資ゼロの導入ビジネスモデルの確立が課題である。<br><br><b>関連</b>　ゼロカーボン・ドライブは再エネ電力とEV/PHEV/FCVの組合せで、車両の蓄電機能を地域のレジリエンス向上にも使う。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜課題】地域脱炭素の課題を『人材・担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　先行地域の計画策定・実施を担う自治体職員や地元企業・金融機関の体制確保が、地域間の取組差を生んでいる<br><br><b>解説</b>　先行地域の計画策定や実施には、自治体職員の専門性に加え、地元企業や金融機関の関与が必要。体制が整う自治体と整わない自治体で差が生まれ、地域間の取組差につながる<br><br><b>答案に書くなら</b>　人材・担い手の観点から、脱炭素先行地域の計画策定・実施を担う自治体職員や地元企業・金融機関の体制確保が、地域間の取組差を生む要因となっていることが課題である。<br><br><b>関連</b>　リスク面でも、体制が不十分な地域では選定後に取組を辞退する例が出ている。<br><br><b>答案での使い方</b>　必須Ⅰ(1)・Ⅱ-2 人材の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜課題】再エネ促進区域設定の課題を『合意形成』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　地域協議会の開催等による合意形成が必要で、環境配慮や地域貢献の要件設定を円滑に進める仕組みが課題<br><br><b>解説</b>　再エネ促進区域の設定には、地域協議会の開催などで住民や事業者との合意形成が要る。環境配慮や地域貢献の要件を設ける作業が重いと、区域設定が進まなくなる<br><br><b>答案に書くなら</b>　合意形成・地域の観点から、再エネ促進区域の設定には地域協議会の開催等による合意形成が必要であり、環境配慮や地域貢献の要件設定を円滑に進める仕組みが課題である。<br><br><b>関連</b>　制度面では、洋上・陸上風力の特性に応じた環境アセスメントの最適化も改革課題である。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 合意形成・地域の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜解決策】合意形成が進まない課題への解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　促進区域の設定（ポジティブゾーニング）で、環境配慮と地域貢献の要件を付けて適地を事前に示す<br><br><b>解説</b>　ポジティブゾーニングは、市町村が再エネの導入目標を設定し、環境配慮や地域貢献の要件を付けた上で再エネ事業を促進する区域を選ぶ仕組み。適地を事前に示すことで、地域に裨益する再エネの立地と合意形成を進めやすくする<br><br><b>答案に書くなら</b>　解決策として、ポジティブゾーニングで環境配慮と地域貢献の要件を付した促進区域を設定し、適地を事前に示して地域共生型の再エネ立地を進めることが有効である。<br><br><b>関連</b>　重点対策②の地域共生・地域裨益型再エネの立地を支える仕組みである。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 再エネ立地の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜解決策】自治体の取組を後押しする解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　重点対策加速化事業（地域脱炭素移行・再エネ推進交付金）で、重点対策を組み合わせた複数年の計画を5年間支援する<br><br><b>解説</b>　重点対策加速化事業は、重点対策①〜⑤を複合的に組み合わせた複数年の計画を実施する自治体を、交付期間5年間で支援する交付金制度。令和8年5月1日時点で全国170自治体が採択されている<br><br><b>答案に書くなら</b>　解決策として、地域脱炭素移行・再エネ推進交付金（重点対策加速化事業）により、重点対策を組み合わせた複数年の計画を5年間支援することが有効である。<br><br><b>答案での使い方</b>　必須Ⅰ(2)・Ⅱ-2 財政支援の根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜リスク】先行地域の選定数を優先して生じるリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　リスク：コスト増や地元合意の難航で辞退が出る。対策：計画段階から地域協議会と要件明確化を徹底し、実行可能性を精査して選定<br><br><b>解説</b>　先行地域の選定数という目標を優先すると、実行可能性の吟味が甘くなり、コスト増や地元合意の難航で、選定後に辞退が出る。計画策定段階から協議と要件明確化を徹底して実現性を確認する必要がある<br><br><b>答案に書くなら</b>　リスクとして、選定数を優先するとコスト増や地元合意の難航で辞退する地域が生じるおそれがあり、計画段階から地域協議会と要件の明確化を徹底し、実行可能性を精査して選定する必要がある。<br><br><b>関連</b>　第7回時点で3提案が辞退している。<br><br><b>答案での使い方</b>　必須Ⅰ(3) 目標優先のリスクと対策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜リスク】促進区域の設定を急ぐリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　リスク：合意形成が不十分なまま区域指定が進み、住民と対立。対策：地域協議会で環境保全と地域の経済・社会課題の解決を併せて検討<br><br><b>解説</b>　促進区域の設定を急ぐと、住民の理解が得られないまま区域指定が進み、地域住民との対立を招く。地域協議会を開き、環境の保全と地域の経済・社会課題の解決を併せて検討することで対立を避けられる<br><br><b>答案に書くなら</b>　リスクとして、促進区域の設定を急ぐと合意形成が不十分なまま住民との対立を招くおそれがあり、地域協議会で環境保全と地域の経済・社会課題の解決を併せて検討する必要がある。<br><br><b>関連</b>　風力・地熱の開発では、海域の鳥類や温泉事業者への影響に配慮し、環境アセスメントの最適化や温泉モニタリングを行う。<br><br><b>答案での使い方</b>　必須Ⅰ(3)・Ⅱ-2 合意形成のリスクと対策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【地域脱炭素ロードマップ｜注意】重点対策加速化事業の交付対象は、8つの重点対策のどれか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　①〜⑤のみ。⑥資源循環・⑦まちづくり・⑧農林水産業は対象外<br><br><b>解説</b>　加速化事業の交付対象は、8つの重点対策のうち①〜⑤（太陽光・地域共生型再エネ・業務ビルZEB化・住宅省エネ・ゼロカーボンドライブ）のみ。⑥資源循環・⑦まちづくり・⑧農林水産業は対象外で、他の制度で対応する<br><br><b>答案に書くなら</b>　重点対策加速化事業の交付対象は①〜⑤の重点対策に限られ、⑥〜⑧は対象外であるため、「すべて交付金対象」とは書かない。<br><br><b>関連</b>　⑥は食品ロスを2030年度までに2000年度比半減、⑧はみどりの食料システム戦略で2050年に有機農業取組面積25%を目指す。<br><br><b>答案での使い方</b>　「重点対策＝すべて交付金対象」と書くと減点<br><br>【出典】<a href=\"https://www.env.go.jp/content/000256901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜時期】令和8年版の環境白書等が閣議決定されたのはいつ？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2026年6月（5日）。環境の日に合わせて公表された、3白書の合冊<br><br><b>解説</b>　令和8年版は2026年6月5日に閣議決定され、環境の日に合わせて公表された。環境白書（環境基本法第12条）、循環型社会白書（循環基本法第14条）、生物多様性白書（生物多様性基本法第10条）を1冊に合冊したものである<br><br><b>答案に書くなら</b>　令和8年版の環境白書・循環型社会白書・生物多様性白書は2026年6月に閣議決定された最新版であり、これに基づいて現状を整理する。<br><br><b>関連</b>　第五次循環型社会形成推進基本計画（循環基本法第15条の計画そのもの）とは別の文書である。<br><br><b>答案での使い方</b>　書き出しで最新版を明示。令和7年版と取り違えない<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/index.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜時期】令和8年版白書のテーマは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　循環経済（サーキュラーエコノミー）で日本列島を強く豊かに<br><br><b>解説</b>　令和8年版のテーマは「循環経済（サーキュラーエコノミー）で日本列島を強く豊かに」。令和7年版は「新たな成長」を導くグリーンな経済システム、令和6年版は自然資本充実と環境価値、令和5年版はネットゼロ・循環経済・ネイチャーポジティブの統合だった<br><br><b>答案に書くなら</b>　令和8年版白書は「循環経済で日本列島を強く豊かに」をテーマに、循環経済への移行加速化を位置づけている。<br><br><b>関連</b>　年版ごとにテーマが異なるため、年版とテーマの対応を確認して書く。<br><br><b>答案での使い方</b>　令和7年版（グリーンな経済システム）と取り違えると減点<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜目標】循環経済行動計画が目指す2030年までの投資規模は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　再資源化拠点等の構築・ネットワーク形成に向け、官民で約1兆円<br><br><b>解説</b>　循環経済行動計画は2026年4月に関係閣僚会議で決定された計画。再資源化拠点等の構築・ネットワーク形成に向け、2030年までに官民で約1兆円の投資を目指す。再資源化拠点は再生資源を安定供給する基盤である<br><br><b>答案に書くなら</b>　経済・資金の観点から、再資源化拠点等の構築・ネットワーク形成に向け、2030年までに官民で約1兆円の投資を促進することが解決策の規模感である。<br><br><b>関連</b>　1兆円は循環経済行動計画の数字で、GX全体の150兆円とは母集団が異なる。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 資金面の解決策の規模感に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜目標】令和8年版白書の保護地域・OECM指定割合（2025年8月）は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　陸地約21.0%、海洋約13.3%。目標は2030年までに各30%以上<br><br><b>解説</b>　保護地域・OECMの指定割合は、2025年8月現在で陸地約21.0%、海洋約13.3%。目標は2030年までにいずれも30%以上で、特に海洋の差が大きい<br><br><b>答案に書くなら</b>　生態系保全の観点から、保護地域・OECMの指定は陸地約21.0%、海洋約13.3%にとどまり、2030年までの30%以上という目標との差が課題である。<br><br><b>関連</b>　自然共生サイトは2026年3月時点で569ヶ所が認定されている。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 目標との差で課題の大きさを示す<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜柱】循環経済行動計画（2026年4月決定）の2つの柱は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　再生資源供給サプライチェーンの強靱化と、日本をハブとする国際資源循環ネットワークの構築<br><br><b>解説</b>　循環経済行動計画は、資源の海外依存と経済安全保障の観点から、国内で再生資源を確保し日本の製錬技術等を活かす狙いを持つ。柱は再生資源供給サプライチェーンの強靱化と、日本をハブとする国際資源循環ネットワークの構築である<br><br><b>答案に書くなら</b>　解決策として、再生資源供給サプライチェーンの強靱化と、日本をハブとする国際資源循環ネットワークの構築を進めることが有効である。<br><br><b>関連</b>　企業の資源循環の情報開示スキームであるグローバル循環プロトコル（GCP）1.0も国際標準化が進められている。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 資源循環の解決策を国の言葉で言う<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜柱】大規模太陽光（メガソーラー）の対策パッケージの考え方は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　不適切事案への法的規制の強化と、地域共生型への支援強化を両立させる<br><br><b>解説</b>　メガソーラーは再エネ導入に資する一方、無秩序な開発などの不適切事案が地域との摩擦を生む。対策パッケージは、不適切事案を抑える規制強化と、望ましい導入を支える地域共生型への支援強化を同時に行う考え方である<br><br><b>答案に書くなら</b>　解決策として、大規模太陽光発電事業について、不適切事案への法的規制の強化と地域共生型への支援強化を両立させることが有効である。<br><br><b>関連</b>　ペロブスカイト太陽電池は軽量・柔軟で、耐荷重性の低い屋根や壁面にも設置できる。<br><br><b>答案での使い方</b>　必須Ⅰ(2)・Ⅲ 再エネ立地の方向づけに<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜課題】重要鉱物・金属の再生資源供給の課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　重要鉱物・金属を質・量・コスト面で安定供給するための再資源化・製錬技術の確立が必要で、動脈と静脈をつなぐ技術基盤が不足<br><br><b>解説</b>　再生資源の供給拠点をつくるには、重要鉱物・金属を質・量・コストの面で安定して供給できる再資源化・製錬技術が必要。製造側（動脈）と再資源化側（静脈）をつなぐ技術基盤が不足していることが課題である<br><br><b>答案に書くなら</b>　技術の観点から、重要鉱物・金属を質・量・コストの面で安定供給するための再資源化・製錬技術の確立と、動脈産業と静脈産業をつなぐ技術基盤の整備が課題である。<br><br><b>関連</b>　再資源化事業等の高度化に関する法律（2025年11月施行）は、高度な再資源化事業者を認定する制度を創設した。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜課題】再資源化拠点の整備の課題を『経済・資金』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　官民で約1兆円の投資を目指すが、再生材需要の創出を起点とした自律的な市場形成の設計が課題<br><br><b>解説</b>　再資源化拠点の整備は、投資の規模だけでなく、投資が回収される市場がなければ続かない。再生材の需要を創出・拡大して、自律的に回る市場形成をどう設計するかが資金循環の課題である<br><br><b>答案に書くなら</b>　経済・資金の観点から、再資源化拠点等に官民で約1兆円の投資を目指す一方、再生材需要の創出を起点とした自律的な市場形成の設計が課題である。<br><br><b>関連</b>　太陽光パネルの大量廃棄に備えたリサイクル義務化の法案（2026年4月国会提出）も、制度面の枠組みを整える。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 経済・資金の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜課題】メガソーラーの課題を『合意形成』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　不適切事案への規制強化と地域共生型への支援を両立させる必要があり、地域住民との合意形成が課題<br><br><b>解説</b>　メガソーラーに関する対策では、不適切事案を規制しつつ、地域共生型の導入も支援する。両方を進めるには、地域住民の納得を得る合意形成が欠かせない。住民が反対すると、規制強化と支援の両方が機能しにくくなる<br><br><b>答案に書くなら</b>　合意形成・地域の観点から、大規模太陽光発電事業で不適切事案への規制強化と地域共生型への支援を両立させるため、地域住民との合意形成が課題である。<br><br><b>関連</b>　クマ被害対策や不適切事案対応では、自治体の体制・人材不足も課題になる。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 合意形成・地域の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜解決策】資源循環の解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　再生資源供給サプライチェーンの強靱化で、再資源化拠点を構築・ネットワーク化し、再生材を質・量・コスト面で安定供給する<br><br><b>解説</b>　再生資源供給サプライチェーンの強靱化は、再資源化拠点を構築してネットワークでつなぎ、重要鉱物・金属等の再生材を質・量・コスト面で安定供給する取組。資源の海外依存を減らし、経済安全保障にも寄与する<br><br><b>答案に書くなら</b>　解決策として、再生資源供給サプライチェーンの強靱化により、再資源化拠点を構築・ネットワーク化し、再生材を質・量・コスト面で安定供給することが有効である。<br><br><b>関連</b>　同じ計画の柱として、日本をハブとする国際資源循環ネットワークの構築がある。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 資源循環の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜解決策】自然再興の解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　自然共生サイトの認定（地域生物多様性増進法、2025年4月施行）で、民間等の保全区域を国が認定し30by30を進める<br><br><b>解説</b>　自然共生サイトは、民間等の取組で生物多様性が保全されている区域を国が認定する制度で、2026年3月時点で569ヶ所。地域生物多様性増進法（2025年4月施行）に基づく認定を含み、民間の保全区域を30by30の達成に取り込む手段である<br><br><b>答案に書くなら</b>　解決策として、地域生物多様性増進法に基づく自然共生サイトの認定により、民間等の保全区域を国が認定して30by30の達成を進めることが有効である。<br><br><b>関連</b>　国立公園満喫プロジェクトは保護と利用の好循環を目指す別の取組で、2026年3月に2026年以降の方針を策定した。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 生物多様性の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜リスク】再資源化拠点の構築を急ぐリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　リスク：環境対策が不十分なスクラップヤード経由で循環資源が海外へ流出。対策：許可制導入とバーゼル法手続の適正化で監視強化<br><br><b>解説</b>　再資源化拠点の構築や国際資源循環ネットワーク化を急ぐと、環境対策が不十分なスクラップヤード事業者を通じて、循環資源が海外へ流出するおそれがある。許可制の導入と、バーゼル法に基づく輸入手続の適正化で監視を強める<br><br><b>答案に書くなら</b>　リスクとして、スクラップヤード経由で循環資源が海外へ流出するおそれがあり、スクラップヤード事業の許可制導入とバーゼル法手続の適正化で監視を強化する必要がある。<br><br><b>関連</b>　自治体アンケートで全国4,000件超の事業場が確認されている。<br><br><b>答案での使い方</b>　必須Ⅰ(3) 資源循環のリスクと対策に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜リスク】メガソーラー拡大のリスクと対策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　リスク：自然再興と土地利用で競合し、不適切な開発を招く。対策：対策パッケージで規制を強化し、地域共生型への支援を重点化<br><br><b>解説</b>　メガソーラーの導入拡大は、土地利用で自然再興（ネイチャーポジティブ）の目標と競合し、無秩序な開発などの不適切事案を招くおそれがある。規制と支援を組み合わせた対策パッケージで両立を図る<br><br><b>答案に書くなら</b>　リスクとして、メガソーラーの拡大が自然再興と土地利用で競合し不適切な開発を招くおそれがあり、対策パッケージで法的規制を強化し、地域共生型への支援を重点化する必要がある。<br><br><b>関連</b>　クマ等の個体数管理は生物多様性保全と住民の安全確保のトレードオフがあり、クマ被害対策ロードマップで両立を図る。<br><br><b>答案での使い方</b>　必須Ⅰ(3) 再エネと自然保全の両立に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:計画", "q": "【令和8年版 環境白書・循環型社会白書・生物多様性白書｜注意】令和8年版の「約1兆円」と、GX2040の「150兆円」の違いは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　1兆円は循環経済行動計画（再資源化拠点）、150兆円はGX全体の官民投資。母集団が違う<br><br><b>解説</b>　令和8年版白書の「約1兆円」は、循環経済行動計画が再資源化拠点等の構築・ネットワーク形成で2030年までに目指す官民投資。GX2040ビジョンの「150兆円」は、GX全体で10年間に呼び込む官民投資で、対象が違う<br><br><b>答案に書くなら</b>　約1兆円は循環経済行動計画の再資源化拠点等への官民投資、150兆円はGX全体の官民投資であり、母集団が異なるので混同しない。<br><br><b>関連</b>　2035年度60%・2040年度73%削減も、家庭部門の66%等とは母集団が異なる全体のNDCの数字である。<br><br><b>答案での使い方</b>　数字は何の目標かとセットで書く<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/gaiyou.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【排出量取引制度（GX-ETS）｜時期】排出量取引制度は本格稼働しているか。何年度からか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2026年度（2026年4月1日施行）。2023年度開始の自主参加型GXリーグとは別の、法定の制度<br><br><b>解説</b>　2026年4月1日に改正GX推進法が施行され、排出量取引は試行から法定の本格稼働に移った。2023年度開始のGXリーグは自主参加の試行で別物<br><br><b>答案に書くなら</b>　排出量取引制度は2026年度から本格稼働しており、法に基づく制度として運用が始まっている。<br><br><b>関連</b>　初年度は届出と移行計画のみで、排出枠の割当ては2027年度（2026年度に割当てではない）。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで「施行済み」と示す。GXリーグと区別<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【排出量取引制度（GX-ETS）｜定義】排出量取引制度とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　政府が排出枠（CO2 1t＝1枠）を無償割当てし、排出実績量と同量の枠の保有を義務づけ、過不足を事業者間で取引できる制度<br><br><b>解説</b>　排出枠（CO2 1t＝1枠）を無償で割り当て、排出実績量と同量の保有を義務づけると、枠が不足する事業者と余る事業者の間で取引が生まれる<br><br><b>答案に書くなら</b>　排出量取引制度とは、政府が無償割当てした排出枠を排出実績量と同量保有する義務を課し、過不足を事業者間で取引できる制度である。<br><br><b>関連</b>　成長志向型カーボンプライシング構想の柱の1つで、もう1つの柱が化石燃料賦課金。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【排出量取引制度（GX-ETS）｜制度】排出量取引制度の対象事業者の要件は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　CO2の直接排出量の直近3年度平均が10万トン以上の事業者。事業者単位で判定する<br><br><b>解説</b>　判定は事業者単位で、直近3年度の平均で見るため単年の増減に左右されにくい。子会社等は別事業者として扱う<br><br><b>答案に書くなら</b>　対象はCO2の直接排出量が直近3年度平均で10万トン以上の事業者であり、事業者単位で判定する。<br><br><b>関連</b>　初年度（2026年度）のみ、判定は2023〜2025年度の平均で行う特例がある。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。数字は「3年度平均10万t」<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505CO0000000379\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【排出量取引制度（GX-ETS）｜制度】排出量取引制度の価格安定の仕組みは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　参考上限取引価格と調整基準取引価格を毎年度設定。償却不足分は「未償却量×参考上限価格×1.1」の負担金<br><br><b>解説</b>　枠の価格が乱高下すると企業は投資計画を立てにくい。そこで価格の目安を年度開始前に定め、枠は投機的取引の対象にしてはならないとされる<br><br><b>答案に書くなら</b>　解決策は、参考上限取引価格と調整基準取引価格を毎年度設定し、償却不足分に未償却量×参考上限価格×1.1の負担金を課して価格を安定させることである。<br><br><b>関連</b>　GX推進機構が排出枠取引市場の設置・運営と価格調整の買入れを担う。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。価格の予見性の論点に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【排出量取引制度（GX-ETS）｜課題】排出量取引制度の課題を『技術・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　排出目標量・実績量は登録確認機関の確認が必須で、算定・確認の体制づくりが初年度から必要になる<br><br><b>解説</b>　排出量は自己申告のままでは信頼できないため、第三者の登録確認機関の確認が必須とされる。事業者側は算定の仕組みを整えないと報告・枠の保有に支障が出る<br><br><b>答案に書くなら</b>　技術・運用の観点から、課題は排出目標量・実績量の算定に登録確認機関の確認が必須で、算定・確認の体制づくりが初年度から必要になることである。<br><br><b>関連</b>　確認が必要なのは目標量と実績量の両方。<br><br><b>答案での使い方</b>　Ⅱ-1の課題。「確認体制」を観点つきで書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【排出量取引制度（GX-ETS）｜解決策】排出量取引制度で国際競争力への影響を抑える仕組みを、専門用語で言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　原単位の改善率を用いた無償割当てで、事業分野間の均衡と国際競争力に配慮する<br><br><b>解説</b>　無償割当てなら事業者の負担が急に重くならず、原単位の改善率を使えば分野ごとの事情の差も調整できる。法も割当ての勘案事項に国際競争力の維持向上を挙げる<br><br><b>答案に書くなら</b>　経済・競争力の観点から、解決策は原単位の改善率を用いて無償割当てを行い、事業分野間の均衡と国際競争力に配慮することである。<br><br><b>関連</b>　発電事業者への有償割当ては2033年度から。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 競争力対策の解決策に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【排出量取引制度（GX-ETS）｜解決策】排出量の算定・確認の体制づくりの解決策は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　確認を担う登録確認機関を国の登録制とし、ERMSとマニュアルで算定・報告の手続きを整える<br><br><b>解説</b>　算定・確認がばらつくと制度の信頼が揺らぐ。そこで確認を担う登録確認機関を国の登録制とし、ERMSとマニュアルで手続きを標準化する<br><br><b>答案に書くなら</b>　技術・運用の観点から、解決策は登録確認機関を国の登録制とし、ERMSとマニュアルで算定・報告の手続きを整えることである。<br><br><b>関連</b>　登録確認機関の登録申請は制度の施行前から可能とされている。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 運用面の解決策に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【排出量取引制度（GX-ETS）｜注意】排出量取引2026年度、化石燃料賦課金、発電の有償割当ての開始年度は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　排出量取引は2026年度、化石燃料賦課金は2028年度、発電事業者の有償割当ては2033年度<br><br><b>解説</b>　3つの制度は段階的に始まる。まず企業の排出に枠を課す排出量取引、次に燃料の採取・輸入に課す賦課金、最後に発電の有償化という順で負担が広がる<br><br><b>答案に書くなら</b>　排出量取引は2026年度、化石燃料賦課金は2028年度、発電事業者の有償割当ては2033年度から始まる。<br><br><b>関連</b>　賦課金は令和10年度、発電の有償割当ては令和15年度とも書かれる。<br><br><b>答案での使い方</b>　年度の取り違えは減点。順序で覚える<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【化石燃料賦課金・成長志向型カーボンプライシング構想｜時期】化石燃料賦課金の徴収開始はいつか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2028年度（令和10年度）から徴収する予定で、まだ始まっていない<br><br><b>解説</b>　賦課金は法で令和10年度（2028年度）からの徴収と決まっているが、まだ始まっておらず予定の段階。2026年度開始の排出量取引とは時期が違う<br><br><b>答案に書くなら</b>　化石燃料賦課金は2028年度から徴収する予定であり、現時点では導入前の段階である。<br><br><b>関連</b>　既に採取・引取りをしている事業者の届出期限は令和10年3月31日。<br><br><b>答案での使い方</b>　Ⅱ-1で予定段階と示す。排出量取引(2026)と区別<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【化石燃料賦課金・成長志向型カーボンプライシング構想｜定義】成長志向型カーボンプライシング構想とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　GX先行投資を促しつつ炭素価格の負担を段階的に導入し、脱炭素と産業競争力を両立させる構想<br><br><b>解説</b>　構想は、先行投資支援・カーボンプライシング・新たな金融手法を組み合わせる。企業にGXに取り組む期間を設けてから導入し、徐々に引き上げる方針を事前に示す<br><br><b>答案に書くなら</b>　成長志向型カーボンプライシング構想とは、GX先行投資を促しつつ炭素価格の負担を段階的に導入し、脱炭素と産業競争力を両立させる構想である。<br><br><b>関連</b>　先行投資支援は20兆円規模で、GX経済移行債を財源とする。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しの定義に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【化石燃料賦課金・成長志向型カーボンプライシング構想｜制度】化石燃料賦課金は誰が納め、どう計算されるか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　化石燃料の採取・輸入事業者が納付。賦課額は「単価×CO2排出量（t）」で、最終消費者には直接課さない<br><br><b>解説</b>　徴収の手間を減らすため、課税の入口である化石燃料の採取・輸入事業者に課す。最終消費者には直接課さない<br><br><b>答案に書くなら</b>　化石燃料賦課金は採取・輸入事業者が納付し、賦課額は単価にCO2排出量（t）を乗じて計算する。<br><br><b>関連</b>　もう1つの財源である特定事業者負担金は、排出量の多い発電事業者に2033年度から課される。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。納付義務者の取り違え防止<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【化石燃料賦課金・成長志向型カーボンプライシング構想｜制度】GX経済移行債の発行期間と償還の仕組みは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　令和5〜14年度に発行。賦課金と特定事業者負担金の収入で令和32年度（2050年度）までに償還<br><br><b>解説</b>　先行投資を前倒しで行うため、GX経済移行債で資金を調達し、将来の賦課金などの収入で返す設計にしている<br><br><b>答案に書くなら</b>　GX経済移行債は令和5〜14年度に発行し、賦課金と特定事業者負担金の収入で令和32年度までに償還する。<br><br><b>関連</b>　発行期間（令和5〜14年度）と償還期限（令和32年度）を混同しない。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。財源の裏付けとして<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【化石燃料賦課金・成長志向型カーボンプライシング構想｜課題】化石燃料賦課金導入の課題を『経済』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　負担が産業・家計のエネルギーコストに及ぶ。法は「中長期的なエネルギー負担の抑制」「公正な移行」を基本理念とする<br><br><b>解説</b>　賦課金は燃料価格に上乗せされるため、産業のコストや家計の光熱費に波及しうる。法も基本理念に負担の抑制と公正な移行を掲げる<br><br><b>答案に書くなら</b>　経済の観点から、課題は賦課金の負担が産業・家計のエネルギーコストに及ぶことであり、法は中長期的な負担の抑制と公正な移行を基本理念とする。<br><br><b>関連</b>　単価は政令で定める。<br><br><b>答案での使い方</b>　Ⅱ-1の課題。観点名を明記して書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【化石燃料賦課金・成長志向型カーボンプライシング構想｜解決策】賦課金の負担を抑える仕組みを、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　単価を上限・下限の算定式の範囲内で政令により定め、エネルギー施策との整合等に応じて減額・還付を認める<br><br><b>解説</b>　単価を青天井にしないよう法が上限と下限の算定式を置き、その範囲内で政令により単価を決める。さらに産業への影響を考えて減額・還付も認める<br><br><b>答案に書くなら</b>　解決策は、単価を上限・下限の算定式の範囲内で政令により定め、エネルギー施策との整合等に応じた減額・還付を認めることで負担を抑えることである。<br><br><b>関連</b>　上限は石油石炭税等の減収見込みを踏まえて算定される。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 負担抑制の解決策に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【化石燃料賦課金・成長志向型カーボンプライシング構想｜解決策】企業の早期投資を促す設計を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　徴収開始時期と段階的に引き上げる方針を事前に示し、早く取り組むほど将来の負担が軽くなる設計にする<br><br><b>解説</b>　価格シグナルが働くには、企業が事前に負担の見通しを持てることが要る。開始時期と引上げ方針を先に示すと、早く動くほど有利になる<br><br><b>答案に書くなら</b>　解決策は、徴収開始時期と段階的に引き上げる方針を事前に示し、早期に取り組むほど将来の負担が軽くなる設計にして企業の早期投資を促すことである。<br><br><b>関連</b>　対策の3本目は20兆円規模の先行投資支援。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 予見性の解決策に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【化石燃料賦課金・成長志向型カーボンプライシング構想｜注意】賦課金の単価は法律本文で定められているか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　定められていない。単価は政令で決め、法律が定めるのは上限・下限の算定式と徴収開始年度<br><br><b>解説</b>　法律が決めるのは骨格（上限・下限の算定式と徴収開始年度）で、具体的な単価は状況に応じて動かせるよう政令に委ねる<br><br><b>答案に書くなら</b>　賦課金の単価は法律本文では定められておらず、法の上限・下限の算定式の範囲内で政令により定める。<br><br><b>関連</b>　納付義務者も取り違えない（最終消費者ではなく採取・輸入事業者）。<br><br><b>答案での使い方</b>　「法律で単価を定める」と書くと減点<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/505AC0000000032\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【水素社会推進法｜時期】水素社会推進法の施行状況は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　令和6年法律第37号。2024年5月公布、2024年10月23日に施行済み。所管は経済産業省<br><br><b>解説</b>　水素社会推進法は令和6年法律第37号で、2024年5月に公布され10月23日に施行済み。所管は経産省で、価格差支援などの具体策は施行後に動いている<br><br><b>答案に書くなら</b>　水素社会推進法は2024年10月23日に施行済みであり、経済産業省が所管する。<br><br><b>関連</b>　施行後5年を目途に検討する規定がある。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで「施行済み」と示す<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000037\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【水素社会推進法｜定義】「低炭素水素等」とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　水素とアンモニア・合成メタン・合成燃料等で、製造時のCO2排出量が一定値以下と認められるもの（法第2条）<br><br><b>解説</b>　水素は燃やしてもCO2が出ないが、作る段階で出る場合がある。そこで製造時のCO2排出量が一定値以下のものだけを支援対象とする<br><br><b>答案に書くなら</b>　低炭素水素等とは、水素とアンモニア・合成メタン・合成燃料等であって、製造時のCO2排出量が一定値以下と認められるものをいう。<br><br><b>関連</b>　具体の化合物種と排出量の値は経産省令に委任されている。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000037\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【水素社会推進法｜制度】水素社会推進法の計画認定の仕組みは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　供給・利用事業者が計画を作り、主務大臣が認定。価格差支援は両者連名の共同計画で、供給の継続が要件<br><br><b>解説</b>　作る側だけ支援しても使う側がいないと続かず、逆も同じ。そこで供給と利用の両事業者が連名の共同計画を作って主務大臣が認定する<br><br><b>答案に書くなら</b>　供給・利用事業者が計画を作り主務大臣が認定する。価格差支援は両者連名の共同計画で、供給が継続することが要件である。<br><br><b>関連</b>　計画は単独でも共同でも作れる。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。需給一体で支援する点を書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000037\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【水素社会推進法｜制度】水素社会推進法の支援の実施主体は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　JOGMECが、継続的な供給に必要な資金や共用設備整備の資金として、認定事業者へ助成金を交付する<br><br><b>解説</b>　国が直接交付する形ではなく、専門機関のJOGMECを通じて助成する。助成を受けるのは認定を受けた事業者である<br><br><b>答案に書くなら</b>　支援の実施主体はJOGMECであり、認定事業者に対し、継続的な供給に必要な資金や共用設備整備の資金として助成金を交付する。<br><br><b>関連</b>　助成の根拠は法第10条。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。国が直接交付と書かない<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000037\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【水素社会推進法｜課題】低炭素水素等の課題を『制度・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　大規模な利用ニーズの創出と、サプライチェーン構築に資する拠点の整備、保安規制の合理化が必要<br><br><b>解説</b>　低炭素水素は使う場所と作る場所が離れやすく、設備や保安の規制も壁になる。需要と供給網と規制の3点がそろって初めて自立する<br><br><b>答案に書くなら</b>　制度・運用の観点から、課題は大規模な利用ニーズの創出、サプライチェーン構築に資する拠点の整備、保安規制の合理化が必要なことである。<br><br><b>関連</b>　価格差の課題もある。<br><br><b>答案での使い方</b>　Ⅱ-1の課題。観点名を明記して書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000037\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【水素社会推進法｜解決策】供給拠点づくりの解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　拠点整備支援（助成）と、港湾法・高圧ガス保安法・道路占用の特例を、規制緩和と一体で進める<br><br><b>解説</b>　拠点を作るには資金と規制の壁がある。そこで助成と、港湾法・高圧ガス保安法・道路占用の特例をセットで進める<br><br><b>答案に書くなら</b>　制度の観点から、解決策は拠点整備支援（助成）と、港湾法・高圧ガス保安法・道路占用の特例を規制緩和と一体で進めることである。<br><br><b>関連</b>　特例は法第四章に置かれている。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 制度面の解決策に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000037\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【水素社会推進法｜解決策】国際サプライチェーンの解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　炭素集約度で評価する基準を日本が主導して策定し、国際標準と相互認証の認証スキームの構築を進める<br><br><b>解説</b>　水素等は国際的に取引されるため、製造方法ごとのCO2排出量を測る共通のものさしが必要になる<br><br><b>答案に書くなら</b>　国際面の観点から、解決策は炭素集約度で評価する基準を日本が主導して策定し、国際標準と相互認証の認証スキームの構築を進めることである。<br><br><b>関連</b>　認証スキームの構築は進められている段階で、国際サプライチェーンの活発化に向けた整備が要る。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 国際面の解決策に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000037\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【水素社会推進法｜注意】水素社会推進法の対象は水素だけか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　水素だけでなく、アンモニア・合成メタン・合成燃料等を含む「水素等」<br><br><b>解説</b>　対象を水素だけとすると誤り。アンモニアや合成メタン、合成燃料も含めて「水素等」と呼び、これらが脱炭素化の難しい分野の燃料・原料になる<br><br><b>答案に書くなら</b>　本法の対象は水素だけでなく、アンモニア・合成メタン・合成燃料等を含む水素等である。<br><br><b>関連</b>　支援の実施主体はJOGMEC（国が直接交付するのではない）。<br><br><b>答案での使い方</b>　対象を水素のみと書くと減点<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000037\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ペロブスカイト太陽電池（次世代型太陽電池戦略）｜時期】次世代型太陽電池戦略はいつ策定され、どの計画に目標が反映されたか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2024年11月に官民協議会が策定。第7次エネルギー基本計画とGX2040ビジョン（2025年2月）に目標を反映<br><br><b>解説</b>　日本はフィルム型の研究で世界をリードしてきたが、中国が量産に動いている。そこで官民協議会が2024年11月に戦略を作り、国の計画に目標を反映した<br><br><b>答案に書くなら</b>　次世代型太陽電池戦略は2024年11月に官民協議会が策定し、第7次エネルギー基本計画とGX2040ビジョンに目標が反映された。<br><br><b>関連</b>　GX2040ビジョンは2025年2月に閣議決定。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで時期と位置づけを示す<br><br>【出典】<a href=\"https://www.nedo.go.jp/content/800032923.pdf\" target=\"_blank\" rel=\"noopener\">NEDO（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ペロブスカイト太陽電池（次世代型太陽電池戦略）｜定義】ペロブスカイト太陽電池とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　軽量・柔軟で、従来のシリコン系では難しかった耐荷重性の低い屋根や壁面にも設置できる次世代型太陽電池<br><br><b>解説</b>　シリコン系は重く硬く、耐荷重性の低い屋根や壁面には置けなかった。軽く曲がる電池ならそうした場所も使え、日本の適地制約を和らげる<br><br><b>答案に書くなら</b>　ペロブスカイト太陽電池とは、軽量・柔軟で、耐荷重性の低い屋根や壁面にも設置できる次世代型太陽電池である。<br><br><b>関連</b>　日本はフィルム型の研究開発で世界をリードしてきた。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.nedo.go.jp/content/800032923.pdf\" target=\"_blank\" rel=\"noopener\">NEDO（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ペロブスカイト太陽電池（次世代型太陽電池戦略）｜目標】ペロブスカイト太陽電池の発電コスト目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2025年20円/kWh、2030年14円/kWh、2040年に自立化可能な10〜14円/kWh以下<br><br><b>解説</b>　量産とコスト低減を年次で示し、民間が投資判断できるようにしている。単位は円/kWhで、コストが下がるほど補助なしで普及する<br><br><b>答案に書くなら</b>　発電コストの目標は、2025年20円/kWh、2030年14円/kWh、2040年に自立化可能な10〜14円/kWh以下である。<br><br><b>関連</b>　数字は技術確立の目標で、実際の販売価格や発電実績ではない。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の数字。年次とセットで書く<br><br>【出典】<a href=\"https://www.nedo.go.jp/content/800032923.pdf\" target=\"_blank\" rel=\"noopener\">NEDO（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ペロブスカイト太陽電池（次世代型太陽電池戦略）｜注意】ペロブスカイト太陽電池の「約20GW」は何の目標か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2040年の導入目標。2030年の目標は導入量ではなく、GW級の量産体制と14円/kWh<br><br><b>解説</b>　量の目標（GW）と、コストや量産体制の目標は年次によって違う。20GWは最終年次の2040年の導入量<br><br><b>答案に書くなら</b>　約20GWは2040年の導入目標であり、2030年の目標は導入量ではなくGW級の量産体制と14円/kWhである。<br><br><b>関連</b>　政府施設の導入目標（2035年50〜70MW・2040年100MW以上）は別の数字。<br><br><b>答案での使い方</b>　年次の取り違えは減点。2030年は量産体制と書く<br><br>【出典】<a href=\"https://www.nedo.go.jp/content/800032923.pdf\" target=\"_blank\" rel=\"noopener\">NEDO（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ペロブスカイト太陽電池（次世代型太陽電池戦略）｜課題】ペロブスカイト太陽電池の課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　長期に安定した性能を保つ耐久性の確立、製品サイズへの大型化・モジュール化、発電コストの低減が必要<br><br><b>解説</b>　新しい電池は、屋外で長期に使える耐久性、大きなサイズの製品化、価格の3点がそろわないと実用化できない<br><br><b>答案に書くなら</b>　技術の観点から、課題は長期に安定した性能を保つ耐久性の確立、製品サイズへの大型化・モジュール化、発電コストの低減が必要なことである。<br><br><b>関連</b>　GI基金の計画もこの3点を課題として整理している。<br><br><b>答案での使い方</b>　Ⅱ-1の課題。観点名を明記して書く<br><br>【出典】<a href=\"https://www.nedo.go.jp/content/800032923.pdf\" target=\"_blank\" rel=\"noopener\">NEDO（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ペロブスカイト太陽電池（次世代型太陽電池戦略）｜課題】ペロブスカイト太陽電池の課題を『産業競争力』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　中国など諸外国の研究開発・量産化が激化し、製品化と市場獲得の速度が競争力を左右する<br><br><b>解説</b>　日本が先行した技術でも、量産と市場獲得で負ければ産業にならない。中国など諸外国が研究開発・量産化を急いでおり、速度が競争力を左右する<br><br><b>答案に書くなら</b>　産業競争力の観点から、課題は中国など諸外国の研究開発・量産化が激化し、製品化と市場獲得の速度が競争力を左右することである。<br><br><b>関連</b>　戦略は「規模とスピード」を掲げる。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 経済・産業の観点の課題に<br><br>【出典】<a href=\"https://www.nedo.go.jp/content/800032923.pdf\" target=\"_blank\" rel=\"noopener\">NEDO（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ペロブスカイト太陽電池（次世代型太陽電池戦略）｜解決策】技術課題への解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　GI基金で量産技術と社会実証を支援し、2030年に14円/kWhを目指す。タンデム型の開発も加速する<br><br><b>解説</b>　GI基金は、民間だけでは難しい研究開発と実証を国が支える仕組み。タンデム型は別の材料と重ねて発電効率を上げる方式で、将来の効率向上の鍵になる<br><br><b>答案に書くなら</b>　技術の観点から、解決策はGI基金で量産技術と社会実証を支援して2030年に14円/kWhを目指し、タンデム型の開発も加速することである。<br><br><b>関連</b>　タンデム型は変換効率30%以上が目標。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 技術面の解決策に<br><br>【出典】<a href=\"https://www.nedo.go.jp/content/800032923.pdf\" target=\"_blank\" rel=\"noopener\">NEDO（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ペロブスカイト太陽電池（次世代型太陽電池戦略）｜解決策】初期需要づくりの解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　政府機関・自治体・環境価値を重視する民間企業が初期需要を牽引し、導入補助で投資の予見性を確保する<br><br><b>解説</b>　新技術は最初は高く需要が小さい。そこで政府機関・自治体・環境価値を重視する民間企業が先に買い、補助で投資の予見性を確保して量産を後押しする<br><br><b>答案に書くなら</b>　需要面の観点から、解決策は政府機関・自治体・環境価値を重視する民間企業が初期需要を牽引し、導入補助で投資の予見性を確保することである。<br><br><b>関連</b>　導入補助は2025年度から始まっている。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 需要面の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000389653.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【洋上風力のEEZ拡大（再エネ海域利用法改正）｜時期】再エネ海域利用法の改正の公布と施行はいつ？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2025年6月11日公布、2026年4月1日施行（施行済み）。閣議決定は2025年3月7日<br><br><b>解説</b>　再エネ海域利用法の改正は2025年6月11日公布、2026年4月1日施行で、現在は施行済み。2025年3月7日の閣議決定は法案を決めた日で、公布・施行とは別<br><br><b>答案に書くなら</b>　改正再エネ海域利用法は2025年6月に公布、2026年4月1日に施行済みであり、EEZでの洋上風力の設置が許可制の対象になった。<br><br><b>関連</b>　閣議決定（2025年3月7日）と取り違えない。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで施行済みと示す。閣議決定と混同しない<br><br>【出典】<a href=\"https://www.mlit.go.jp/report/press/port01_hh_000291.html\" target=\"_blank\" rel=\"noopener\">国土交通省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【洋上風力のEEZ拡大（再エネ海域利用法改正）｜定義】EEZへの洋上風力拡大とは何が変わったのか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　従来は領海・内水のみが対象。改正でEEZでの設置を許可する制度と、海洋環境保全のため国が調査する仕組みを新設<br><br><b>解説</b>　EEZ（排他的経済水域）は領海の外側の海域。従来の法は領海と内水にしか適用されず、EEZの設置ルールがなかった。改正で許可制度と、海洋環境保全のための国の調査が新設された<br><br><b>答案に書くなら</b>　EEZへの拡大とは、従来の領海・内水に限られた洋上風力の対象を広げ、EEZでの設置を許可する制度と国による海洋環境調査を新設したことである。<br><br><b>関連</b>　案件形成目標の達成が目的。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.mlit.go.jp/report/press/port01_hh_000291.html\" target=\"_blank\" rel=\"noopener\">国土交通省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【洋上風力のEEZ拡大（再エネ海域利用法改正）｜制度】EEZでの設置許可の流れは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　経産大臣が募集区域を指定→申請→経産・国交大臣が仮許可（5年以内）→協議会→許可<br><br><b>解説</b>　沖合は先行利用者や環境への影響が大きいため、国が区域を決めて募集し、仮許可で確認してから許可する二段階にしている<br><br><b>答案に書くなら</b>　経産大臣が募集区域を指定し、申請を受けて経産・国交大臣が仮許可（5年以内）を出し、協議会での協議を経て許可する二段階審査である。<br><br><b>関連</b>　許可の有効期間は法が数値を定めず個別に定める。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。二段階審査と書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/430AC0000000089\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【洋上風力のEEZ拡大（再エネ海域利用法改正）｜目標】洋上風力の案件形成目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2030年までに1,000万kW、2040年までに3,000万〜4,500万kW<br><br><b>解説</b>　洋上風力は2030年と2040年で段階的に増やす計画で、数字を取り違えやすい。EEZを開くのも、この目標に届かせるため<br><br><b>答案に書くなら</b>　洋上風力の案件形成目標は、2030年までに1,000万kW、2040年までに3,000万〜4,500万kWである。<br><br><b>関連</b>　2030年と2040年を取り違えない。<br><br><b>答案での使い方</b>　Ⅱ-1の数字。2030年と2040年を取り違えない<br><br>【出典】<a href=\"https://www.mlit.go.jp/report/press/port01_hh_000291.html\" target=\"_blank\" rel=\"noopener\">国土交通省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【洋上風力のEEZ拡大（再エネ海域利用法改正）｜課題】EEZ洋上風力の課題を『制度・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　漁業・航路・港湾・系統との調整。許可基準に漁業・航路への支障がないこと、基地港湾の利用、電線路との接続がある<br><br><b>解説</b>　沖合でも漁場、船の航路、港湾、送電網との関係は避けて通れない。法は許可基準にこれらへの支障がないことを入れて調整する<br><br><b>答案に書くなら</b>　制度・運用の観点から、課題は漁業・航路・港湾・系統との調整であり、許可基準に漁業・航路への支障がないこと、基地港湾の利用、電線路との接続が置かれている。<br><br><b>関連</b>　先行利用者との調整は協議会が担う。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅲ 先行利用者との調整の観点の課題に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/430AC0000000089\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【洋上風力のEEZ拡大（再エネ海域利用法改正）｜課題】EEZ洋上風力の課題を『環境』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　区域指定の前に海洋環境の情報を把握すること。このため環境大臣が募集区域の海洋環境を調査し、結果を踏まえて区域を指定する仕組みが新設された<br><br><b>解説</b>　従来の再エネ海域利用法は領海・内水だけが対象で、EEZで区域ごとに海洋環境を調べる仕組みがなかった。改正で、環境大臣が調査して結果を経産大臣に通知・公表し、それを受けて区域を指定する<br><br><b>答案に書くなら</b>　環境の観点から、課題は、沖合の募集区域で海洋環境の情報を事前に把握し、区域指定に適切に反映することである。<br><br><b>関連</b>　調査を担うのは環境大臣。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅲ 環境影響の観点の課題に<br><br>【出典】<a href=\"https://www.mlit.go.jp/report/press/port01_hh_000291.html\" target=\"_blank\" rel=\"noopener\">国土交通省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【洋上風力のEEZ拡大（再エネ海域利用法改正）｜解決策】利害関係者の調整の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　協議会で利害関係者を含め協議し、その結果を尊重する。仮許可と許可の二段階審査で事業の確実性を担保<br><br><b>解説</b>　沖合の海は多くの人が使っており、一度に全員の合意を取るのは難しい。そこで協議の場を作って尊重し、仮許可・許可の二段階審査で、実行できる案件に絞る<br><br><b>答案に書くなら</b>　合意形成の観点から、解決策は協議会で利害関係者を含めて協議してその結果を尊重し、仮許可と許可の二段階審査で事業の確実性を担保することである。<br><br><b>関連</b>　協議会は両大臣が組織する。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅲ 合意形成の解決策に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/430AC0000000089\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【洋上風力のEEZ拡大（再エネ海域利用法改正）｜注意】領海・内水とEEZでは、洋上風力の仕組みは同じか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　別。領海・内水は「促進区域」（公募占用計画の認定）、EEZは「募集区域」（仮許可→許可）。EEZの許可は経産・国交の共管<br><br><b>解説</b>　領海・内水の制度は先に作られ、EEZは改正で新しく加わった別の仕組み。用語が似ているが、公募方式も許可権者も違う<br><br><b>答案に書くなら</b>　領海・内水は促進区域（公募占用計画の認定）、EEZは募集区域（仮許可から許可）であり、EEZの許可は経産・国交両大臣の共管である。<br><br><b>関連</b>　環境大臣は調査を担う。<br><br><b>答案での使い方</b>　用語の取り違えは減点。環境大臣は調査を担う<br><br>【出典】<a href=\"https://www.mlit.go.jp/kowan/content/001879078.pdf\" target=\"_blank\" rel=\"noopener\">国土交通省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【二国間クレジット制度（JCM）｜時期】JCMのパートナー国は何か国か（2026年5月時点）？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　32か国（2026年5月29日時点）。2013年1月のモンゴルとの署名に始まり、法制化は令和6年の温対法改正<br><br><b>解説</b>　JCMは2013年1月のモンゴルとの署名に始まり、パートナー国が広がってきた。令和6年の温対法改正で法制化され、登録簿と指定実施機関が法に規定された<br><br><b>答案に書くなら</b>　JCMのパートナー国は2026年5月29日時点で32か国であり、2013年1月のモンゴルとの署名に始まる。<br><br><b>関連</b>　直近の追加はオマーン（2026年4月）。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで現状を示す<br><br>【出典】<a href=\"https://www.env.go.jp/content/000377659.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【二国間クレジット制度（JCM）｜定義】JCMとは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　日本とパートナー国が協力して実施した対策による排出削減・吸収量を、両国の貢献度に応じて配分する仕組み<br><br><b>解説</b>　途上国での対策に日本が技術・資金で協力し、得られた削減量を両国で分け合う。日本はNDCに計上でき、相手国は排出削減のための技術導入が進む<br><br><b>答案に書くなら</b>　JCMとは、日本とパートナー国が協力して実施した対策による排出削減・吸収量を、両国の貢献度に応じて配分する仕組みである。<br><br><b>関連</b>　パリ協定第6条2項に整合する制度。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000377659.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【二国間クレジット制度（JCM）｜目標】JCMの削減量の目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　官民連携で2030年度までの累積1億t-CO2程度、2040年度までの累積2億t-CO2程度<br><br><b>解説</b>　日本の排出削減目標の一部を、海外での削減で積み増す計画。官民連携で年度ごとに累積量を目標にしている<br><br><b>答案に書くなら</b>　JCMの削減量目標は、官民連携で2030年度までの累積1億t-CO2程度、2040年度までの累積2億t-CO2程度である。<br><br><b>関連</b>　地球温暖化対策計画とNDCに位置づく。<br><br><b>答案での使い方</b>　Ⅱ-1の数字。「累積」「年度まで」を落とさない<br><br>【出典】<a href=\"https://www.env.go.jp/content/000377659.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【二国間クレジット制度（JCM）｜制度】JCMの「相当調整」とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　日本が無効化した量を日本の排出量から差し引き、同量をパートナー国の排出量に上乗せして二重計上を防ぐ<br><br><b>解説</b>　同じ削減量を日本と相手国の双方が数えると二重計上になる。そこで日本が無効化した量を日本の排出量から差し引き、同量を相手国の排出量に上乗せして調整する<br><br><b>答案に書くなら</b>　相当調整とは、日本が無効化した量を日本の排出量から差し引き、同量をパートナー国の排出量に上乗せして二重計上を防ぐ仕組みである。<br><br><b>関連</b>　クレジットを取消すとNDCに計上されない。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。パリ協定第6条の肝<br><br>【出典】<a href=\"https://www.env.go.jp/content/000377659.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【二国間クレジット制度（JCM）｜制度】JCMのクレジット量はどう算定するか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　BaU排出量を十分に下回る「リファレンス排出量」と比較して保守的に算定し、両国政府が承認する<br><br><b>解説</b>　何もしない場合（BaU）より少なく見積もると、削減量が水増しになる。そこで基準を十分に下回るリファレンス排出量を使って控えめに算定し、両国が承認する<br><br><b>答案に書くなら</b>　クレジット量はBaU排出量を十分に下回るリファレンス排出量と比較して保守的に算定し、両国政府が承認する。<br><br><b>関連</b>　第6条の手続でクレジット移転量を承認する。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。環境十全性の根拠<br><br>【出典】<a href=\"https://www.env.go.jp/content/000377659.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【二国間クレジット制度（JCM）｜課題】JCMの課題を『環境十全性』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　二重計上の防止と保守的算定の確保。相手国のインベントリの整備状況によっては、削減量が反映されない場合がある<br><br><b>解説</b>　削減量が過大だったり二重に数えられたりすると、地球全体の排出は減らない。これを防ぐのが環境十全性で、相手国の排出量の把握体制も関わる<br><br><b>答案に書くなら</b>　環境十全性の観点から、課題は二重計上の防止と保守的算定の確保であり、相手国のインベントリの整備状況によっては削減量が反映されない場合がある。<br><br><b>関連</b>　解決は相当調整と第6条報告で担保。<br><br><b>答案での使い方</b>　Ⅱ-1の課題。観点名を明記して書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000377659.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【二国間クレジット制度（JCM）｜解決策】JCMの事務の効率化の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　指定実施機関（JCMA）が多数の国と同時に調整し、クレジット発行までの事務をワンストップ化する<br><br><b>解説</b>　多くの国と同時に進めると手続きが膨らむ。温対法の改正で指定実施機関を規定し、公益財団法人地球環境センターがJCMAとして指定されている<br><br><b>答案に書くなら</b>　運用面の観点から、解決策は指定実施機関（JCMA）が多数の国と同時に調整し、クレジット発行までの事務をワンストップ化して効率化・迅速化することである。<br><br><b>関連</b>　根拠は令和6年の温対法改正。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 運用面の解決策に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/410AC0000000117\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【二国間クレジット制度（JCM）｜注意】JCMの1億tと2億tは、単年の削減量か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　単年ではない。1億tは2030年度までの累積、2億tは2040年度までの累積<br><br><b>解説</b>　2030年度や2040年度は期限で、それまでに積み上げる累積量の目標。毎年の削減量と読み違えると、規模感が大きく狂う<br><br><b>答案に書くなら</b>　JCMの1億tは2030年度までの累積、2億tは2040年度までの累積であり、単年の削減量ではない。<br><br><b>関連</b>　「累積」「年度まで」を落とさない。<br><br><b>答案での使い方</b>　数字の読み違えは減点。累積と書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000377659.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【SSBJ基準と有価証券報告書での開示義務化｜時期】SSBJ基準の有報での義務化はいつからか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　プライム市場の平均時価総額3兆円以上は2027年3月期、1兆円以上は2028年3月期、5,000億円以上は2029年3月期（予定）<br><br><b>解説</b>　開示義務は、時価総額が大きい企業から順に広げる。プライム市場の平均時価総額（過去5事業年度末の平均）で3段階に分け、準備期間を確保する<br><br><b>答案に書くなら</b>　SSBJ基準の義務化は、プライム市場の平均時価総額3兆円以上が2027年3月期、1兆円以上が2028年3月期、5,000億円以上が2029年3月期（予定）である。<br><br><b>関連</b>　5,000億円未満は今後検討。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで段階適用と時期を示す<br><br>【出典】<a href=\"https://www.fsa.go.jp/news/r7/shouken/20260220/20260220.html\" target=\"_blank\" rel=\"noopener\">金融庁を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【SSBJ基準と有価証券報告書での開示義務化｜定義】SSBJ基準とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　日本初のサステナビリティ開示基準。ISSB基準を踏まえ、サステナビリティ基準委員会が2025年3月に公表<br><br><b>解説</b>　有価証券報告書のサステナビリティ記載は、比較可能性と有用性に課題があった。そこで国際基準（ISSB基準）を踏まえ、日本の基準を作った<br><br><b>答案に書くなら</b>　SSBJ基準とは、ISSB基準を踏まえてサステナビリティ基準委員会が2025年3月に公表した、日本初のサステナビリティ開示基準である。<br><br><b>関連</b>　原則としてISSB基準の要求事項をすべて取り入れる。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.ssb-j.jp/jp/wp-content/uploads/sites/6/2026_07.pdf\" target=\"_blank\" rel=\"noopener\">SSBJ（サステナビリティ基準委員会）（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【SSBJ基準と有価証券報告書での開示義務化｜制度】SSBJ基準を構成する3つの基準は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　ユニバーサル基準「適用基準」、第1号「一般開示基準」、第2号「気候関連開示基準」<br><br><b>解説</b>　共通のルールを置く適用基準と、全テーマに共通の一般開示基準、気候テーマの基準で構成する。気候関連はその中の1つである<br><br><b>答案に書くなら</b>　SSBJ基準は、ユニバーサル基準の適用基準、テーマ別第1号の一般開示基準、同第2号の気候関連開示基準の3つで構成される。<br><br><b>関連</b>　2025年3月5日に3基準を公表。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。構成を1文で言う<br><br>【出典】<a href=\"https://www.ssb-j.jp/jp/wp-content/uploads/sites/6/2026_07.pdf\" target=\"_blank\" rel=\"noopener\">SSBJ（サステナビリティ基準委員会）（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【SSBJ基準と有価証券報告書での開示義務化｜制度】義務化の経過措置と保証の定めは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　義務化の翌年から第三者保証。最初の2年は訂正報告書での記載（二段階開示）、スコープ3は初年度免除<br><br><b>解説</b>　企業には算定・開示の準備が必要で、第三者保証も体制づくりに時間がかかる。そこで、最初の2年は訂正報告書での記載を認め、保証は義務化の翌年から始める<br><br><b>答案に書くなら</b>　義務化の翌年から第三者保証を義務づけ、最初の2事業年度は訂正報告書での記載（二段階開示）を認め、スコープ3は初年度免除とする。<br><br><b>関連</b>　保証の範囲は当初2年間は限定。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の留意点。段階的導入の根拠<br><br>【出典】<a href=\"https://www.fsa.go.jp/singi/singi_kinyu/tosin/20260108/02.pdf\" target=\"_blank\" rel=\"noopener\">金融庁（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【SSBJ基準と有価証券報告書での開示義務化｜課題】SSBJ義務化の課題を『技術・信頼性』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　開示の比較可能性・有用性の向上と、第三者保証がなければ確保しにくい信頼性<br><br><b>解説</b>　開示情報は企業ごとに差が出やすく、保証がないと投資家が信頼しにくい。そのため比較可能性・有用性と信頼性の確保が課題になる<br><br><b>答案に書くなら</b>　技術・信頼性の観点から、課題は開示の比較可能性・有用性の向上と、第三者保証がなければ確保しにくい信頼性の確保である。<br><br><b>関連</b>　有報の記載欄は2023年から。<br><br><b>答案での使い方</b>　Ⅱ-1の課題。観点名を明記して書く<br><br>【出典】<a href=\"https://www.fsa.go.jp/singi/singi_kinyu/tosin/20260108/02.pdf\" target=\"_blank\" rel=\"noopener\">金融庁（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【SSBJ基準と有価証券報告書での開示義務化｜課題】SSBJ義務化の課題を『担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　保証業務の実施者の確保。監査法人以外にも登録の道を開く必要がある<br><br><b>解説</b>　保証には専門性が必要で、担える機関が限られると義務化に支障が出る。従来は監査法人が中心だったため、担い手の裾野を広げる必要がある<br><br><b>答案に書くなら</b>　担い手の観点から、課題は保証業務の実施者の確保であり、監査法人以外にも登録の道を開く必要がある。<br><br><b>関連</b>　保証業務実施者は登録制（法人）。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 人材の観点の課題に<br><br>【出典】<a href=\"https://www.fsa.go.jp/singi/singi_kinyu/tosin/20260108/02.pdf\" target=\"_blank\" rel=\"noopener\">金融庁（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【SSBJ基準と有価証券報告書での開示義務化｜解決策】開示の信頼性の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　国際基準と整合する保証基準で第三者保証を義務づけ、保証業務実施者を登録制にする<br><br><b>解説</b>　国際的に通用する保証にするため、国際基準と整合する保証基準を用い、担い手は登録制にして質を担保する<br><br><b>答案に書くなら</b>　制度面の観点から、解決策は国際基準と整合する保証基準で第三者保証を義務づけ、保証業務実施者を登録制にして開示の信頼性を確保することである。<br><br><b>関連</b>　国際基準にはISSA5000がある。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 制度面の解決策に<br><br>【出典】<a href=\"https://www.fsa.go.jp/singi/singi_kinyu/tosin/20260108/02.pdf\" target=\"_blank\" rel=\"noopener\">金融庁（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【SSBJ基準と有価証券報告書での開示義務化｜注意】SSBJ基準は法令そのものか？義務化はいつ保証までか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　法令ではない。金融庁長官の告示指定で有報の基準になる。最初の義務化は2027年3月期で、保証はその翌年<br><br><b>解説</b>　SSBJ基準は民間の基準設定主体が作った基準で、そのままでは法的効力がない。金融庁長官が告示で指定すると、有報で従うべき基準になる<br><br><b>答案に書くなら</b>　SSBJ基準は法令そのものではなく、金融庁長官の告示指定により有報の基準となり、最初の義務化は2027年3月期、保証はその翌年である。<br><br><b>関連</b>　2026年3月に3基準を改正（2027年1月1日以後開始の期間から適用）。<br><br><b>答案での使い方</b>　基準の位置づけと保証の時期を取り違えない<br><br>【出典】<a href=\"https://www.fsa.go.jp/news/r7/shouken/20260220/20260220.html\" target=\"_blank\" rel=\"noopener\">金融庁を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【トランジション・ファイナンス｜時期】クライメート・トランジション・ファイナンスに関する基本指針はいつ策定・改訂されたか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2021年に策定、2025年3月に改訂（2025年版）。金融庁・経産省・環境省が策定<br><br><b>解説</b>　基本指針は2021年に策定され、国際資本市場協会（ICMA）のハンドブック改訂などを受けて2025年3月に改訂された。金融庁・経産省・環境省の3省庁が策定する<br><br><b>答案に書くなら</b>　クライメート・トランジション・ファイナンスに関する基本指針は2021年に策定され、2025年3月に改訂された2025年版が現行である。<br><br><b>関連</b>　2026年8月の検討会で改訂の項目が立てられている。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで最新版を示す<br><br>【出典】<a href=\"https://www.env.go.jp/content/000304405.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【トランジション・ファイナンス｜定義】トランジション・ファイナンスとは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　気候変動対策を検討する企業が長期戦略に沿ってGHG削減に取り組む場合に、その取組を支える金融手法。長期戦略の信頼性に着目<br><br><b>解説</b>　排出削減が難しい産業の移行には、個別の使途だけでなく、企業の長期戦略への資金が要る。そこで企業レベルの長期戦略の信頼性に着目して、資金供給を後押しする<br><br><b>答案に書くなら</b>　トランジション・ファイナンスとは、長期戦略に沿ってGHG削減に取り組む企業の取組を支える金融手法であり、長期戦略の信頼性に着目する点が特徴である。<br><br><b>関連</b>　2050年カーボンニュートラルとパリ協定に整合する移行が前提。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000304405.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【トランジション・ファイナンス｜制度】基本指針が資金調達者に開示を推奨する4要素は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　①戦略とガバナンス②環境面のマテリアリティ③科学的根拠に基づく戦略と目標④実施の透明性<br><br><b>解説</b>　資金を出す側が、企業の戦略が本物かを見極める手がかりが必要。そこで4つの要素の開示を推奨し、国際原則とそろえる<br><br><b>答案に書くなら</b>　資金調達者に、戦略とガバナンス、環境面のマテリアリティ、科学的根拠に基づく戦略と目標、実施の透明性の4要素の開示を推奨する。<br><br><b>関連</b>　ICMAのハンドブックと整合する。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。ICMAハンドブックと整合<br><br>【出典】<a href=\"https://www.env.go.jp/content/000304405.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【トランジション・ファイナンス｜制度】分野別技術ロードマップはどの分野を対象にしているか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　鉄鋼・化学・電力・ガス・石油・紙パルプ・セメント・自動車に海運・航空を加えた10分野。日本の排出量の8割強<br><br><b>解説</b>　資金供給側が個別企業の戦略を評価するのは大変なため、分野ごとの道筋を国が示す。鉄鋼・化学など排出の多い産業を中心に、国交省策定の海運・航空を加えた10分野で、日本の排出量の8割強をカバーする<br><br><b>答案に書くなら</b>　分野別技術ロードマップは10分野を対象とし、資金調達者の戦略策定と資金供給者の評価の参照先となる。<br><br><b>関連</b>　基本指針は対象産業を限定しない。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。評価の参照先として書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000304405.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【トランジション・ファイナンス｜課題】トランジション・ファイナンスの課題を『経済・金融』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　実行した金融機関の投融資先の排出量（ファイナンスド・エミッション）が、一時的に増加する<br><br><b>解説</b>　排出の多い企業に融資すれば、その企業の排出が金融機関の投融資先の排出量として積み上がる。移行を支える融資は、短期的には金融機関の数字を悪化させることがある<br><br><b>答案に書くなら</b>　経済・金融の観点から、課題は実行した金融機関の投融資先の排出量（ファイナンスド・エミッション）が一時的に増加することである。<br><br><b>関連</b>　2023年に考え方を公表している。<br><br><b>答案での使い方</b>　Ⅱ-1の課題。観点名を明記して書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000304405.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【トランジション・ファイナンス｜課題】トランジション・ファイナンスの課題を『信頼性』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　国際的な共通認識の醸成は途上で、信頼性の確保のため良質な事例の積み上げが重要<br><br><b>解説</b>　トランジション・ファイナンスは、国際的な関心が高まる一方、定義を様々な機関が整理しており、共通認識の形成は途上である<br><br><b>答案に書くなら</b>　信頼性の観点から、課題は国際的な共通認識の醸成が途上であり、信頼性の確保のため良質な事例の積み上げが重要なことである。<br><br><b>関連</b>　資金供給者による戦略評価の難しさも課題。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 制度・信頼性の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000304405.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【トランジション・ファイナンス｜解決策】信頼性確保の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　4要素の開示を求めてICMAハンドブックと整合を図り、フォローアップガイダンスで資金供給後の確認を整える<br><br><b>解説</b>　資金が出た後に戦略が実行されなければ意味がない。そこで開示要素を示して国際原則とそろえ、資金供給後の確認方法も整える<br><br><b>答案に書くなら</b>　制度面の観点から、解決策は4要素の開示を求めてICMAハンドブックと整合を図り、フォローアップガイダンスで資金供給後の確認を整えることである。<br><br><b>関連</b>　フォローアップガイダンスは2023年。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 制度面の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000304405.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【トランジション・ファイナンス｜注意】クライメート・トランジション利付国債は、基本指針と同じ枠組みか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　別枠組み。2024年2月に国が発行を始めた世界初の国によるトランジションボンド<br><br><b>解説</b>　国のトランジションボンドは、国が移行債でリーディングマーケットを作る別の取組である。基本指針は民間の資金調達の考え方で、役割が違う<br><br><b>答案に書くなら</b>　クライメート・トランジション利付国債は基本指針とは別枠組みで、2024年2月に国が発行を始めた世界初の国によるトランジションボンドである。<br><br><b>関連</b>　基本指針は金融庁・経産省・環境省が策定。<br><br><b>答案での使い方</b>　基本指針（金融庁・経産省・環境省）と混同しない<br><br>【出典】<a href=\"https://www.fsa.go.jp/singi/transition_finance/siryou/20260821/014_03_00.pdf\" target=\"_blank\" rel=\"noopener\">金融庁（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【熱中症特別警戒情報｜時期】熱中症特別警戒情報はいつから運用され、発表実績は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2024年4月（改正気候変動適応法の全面施行）から運用。令和6・7年度とも発表0回<br><br><b>解説</b>　熱中症対策を気候変動適応の一分野として強化するため、2023年に改正された気候変動適応法が2024年4月に全面施行された。特別警戒情報はその時から運用されているが、基準が厳しく実績がない<br><br><b>答案に書くなら</b>　熱中症特別警戒情報は2024年4月から運用が始まっているが、令和6・7年度とも発表実績は0回である。<br><br><b>関連</b>　令和8年度も2026年8月6日時点で0回。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで運用開始時期を示す<br><br>【出典】<a href=\"https://www.wbgt.env.go.jp/about_special_alert.php\" target=\"_blank\" rel=\"noopener\">環境省 熱中症予防情報サイトを開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【熱中症特別警戒情報｜定義】熱中症特別警戒情報とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　気温が特に著しく高く、熱中症による人の健康への重大な被害が生ずるおそれがある場合に、環境大臣が発表する情報（法第19条）<br><br><b>解説</b>　警戒情報（アラート）より一段上の、重大な被害のおそれがある場合の情報。環境大臣が都道府県知事へ通知し、知事・市町村長を通じて住民へ伝わる<br><br><b>答案に書くなら</b>　熱中症特別警戒情報とは、気温が特に著しく高く、熱中症による人の健康への重大な被害が生ずるおそれがある場合に、環境大臣が発表する情報である。<br><br><b>関連</b>　根拠は気候変動適応法第19条。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/430AC0000000050\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【熱中症特別警戒情報｜制度】警戒情報と特別警戒情報の発表基準は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　警戒：府県予報区内の1地点以上で日最高WBGT33以上。特別警戒：都道府県内の全地点で35以上<br><br><b>解説</b>　警戒情報は広めに注意を促し、特別警戒は極端な場合に限る設計。地点数の条件が違うため、特別警戒は発表されにくい<br><br><b>答案に書くなら</b>　警戒情報は府県予報区内の1地点以上で日最高WBGT33以上、特別警戒情報は都道府県内の全地点で35以上と予測される場合に発表する。<br><br><b>関連</b>　WBGTは暑さ指数。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。基準と範囲を書き分ける<br><br>【出典】<a href=\"https://www.wbgt.env.go.jp/about_special_alert.php\" target=\"_blank\" rel=\"noopener\">環境省 熱中症予防情報サイトを開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【熱中症特別警戒情報｜制度】指定暑熱避難施設（クーリングシェルター）の仕組みは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　市町村長が冷房設備のある施設を指定し、特別警戒情報の発表時に開放する<br><br><b>解説</b>　暑い日に避難できる涼しい場所がないと、熱中症弱者が守れない。市町村長が冷房のある施設を指定し、特別警戒情報の発表時に開放する<br><br><b>答案に書くなら</b>　市町村長が適当な冷房設備を有する施設を指定暑熱避難施設に指定し、特別警戒情報の発表時に住民へ開放する。<br><br><b>関連</b>　管理者が開放義務を負うのは特別警戒情報の発表時で、公表した開放可能日等に限られる。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。自治体の役割として書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/430AC0000000050\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【熱中症特別警戒情報｜課題】熱中症対策の課題を『社会・担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　高齢者やこども等の熱中症弱者は自助による予防が難しく、家族や身近な人の見守り・声かけ（共助）と公助が要る<br><br><b>解説</b>　高齢者やこどもは自分で暑さを避けにくく、気づきも遅れがち。自助だけに頼れず、周囲の見守りや行政の対応が欠かせない<br><br><b>答案に書くなら</b>　社会・担い手の観点から、課題は高齢者やこども等の熱中症弱者は自助による予防が難しく、家族や身近な人の見守り・声かけ（共助）と公助が必要なことである。<br><br><b>関連</b>　熱中症対策普及団体は市町村長が指定する。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 社会・担い手の観点の課題に<br><br>【出典】<a href=\"https://www.wbgt.env.go.jp/about_special_alert.php\" target=\"_blank\" rel=\"noopener\">環境省 熱中症予防情報サイトを開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【熱中症特別警戒情報｜解決策】熱中症の共助を強める解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　熱中症対策普及団体や福祉関係団体を通じた見守り・声かけの強化と、エアコン利用の有効性の周知<br><br><b>解説</b>　共助は身近な人の見守りが基本だが、きっかけがないと広がらない。普及団体や福祉関係団体の力を借り、エアコンの有効性も周知する<br><br><b>答案に書くなら</b>　担い手面の観点から、解決策は熱中症対策普及団体や福祉関係団体を通じた見守り・声かけの強化と、エアコン利用の有効性の周知である。<br><br><b>関連</b>　普及団体は啓発・広報や相談対応を行う。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 担い手面の解決策に<br><br>【出典】<a href=\"https://www.wbgt.env.go.jp/about_special_alert.php\" target=\"_blank\" rel=\"noopener\">環境省 熱中症予防情報サイトを開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【熱中症特別警戒情報｜解決策】極端な高温時の体制整備の解決策を、専門用語で言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　指定暑熱避難施設の指定・確保と、極端な高温時の自治体内の役割分担の明確化<br><br><b>解説</b>　極端な高温の日に自治体が混乱しないよう、避難施設を確保し役割分担を事前に決めておく。市町村が住民に伝える仕組みの実効性にも関わる<br><br><b>答案に書くなら</b>　解決策は指定暑熱避難施設の指定・確保と、極端な高温時の自治体内の役割分担の明確化である。<br><br><b>関連</b>　実行計画は令和8年度を目途に見直す予定。<br><br><b>答案での使い方</b>　Ⅱ-2 自治体の手順・調整事項に<br><br>【出典】<a href=\"https://www.wbgt.env.go.jp/about_special_alert.php\" target=\"_blank\" rel=\"noopener\">環境省 熱中症予防情報サイトを開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【熱中症特別警戒情報｜注意】熱中症対策実行計画の「半減」は、何を基準にした目標か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　令和4年（概数）の5年移動平均1,295名を基準に、2030年に熱中症死亡者数を半減<br><br><b>解説</b>　熱中症の死亡者数は年ごとに変動が大きいため、5年移動平均で目標を置く。基準は令和4年（概数）の1,295名で、この数字から2030年に半減をめざす<br><br><b>答案に書くなら</b>　熱中症対策実行計画は、令和4年（概数）の5年移動平均1,295名を基準に、2030年に熱中症死亡者数を半減する目標である。<br><br><b>関連</b>　目標は2023年5月30日に閣議決定。<br><br><b>答案での使い方</b>　基準年・基準値を落とすと減点<br><br>【出典】<a href=\"https://www.wbgt.env.go.jp/about_special_alert.php\" target=\"_blank\" rel=\"noopener\">環境省 熱中症予防情報サイトを開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【気候変動影響評価報告書（第3次）｜時期】気候変動影響評価報告書の第3次はいつ公表されたか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2026年2月16日に公表。第2次は令和2年12月。おおむね5年ごとに作成する（法第10条）<br><br><b>解説</b>　気候変動適応法の定めで、おおむね5年ごとに最新の知見で評価する。第3次は2026年2月16日に公表され、第2次は令和2年12月だった<br><br><b>答案に書くなら</b>　気候変動影響評価報告書の第3次は2026年2月16日に公表され、法に基づきおおむね5年ごとに作成される。<br><br><b>関連</b>　根拠は気候変動適応法第10条。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで最新版を示す<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_02915.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【気候変動影響評価報告書（第3次）｜定義】気候変動影響評価報告書とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　気候変動適応法に基づき、最新の科学的知見でおおむね5年ごとに行う影響の総合的評価。適応計画の変更時に勘案する<br><br><b>解説</b>　適応策は、どの分野でどの程度の影響が出るかを把握して初めて立てられる。そこで科学的知見をもとに影響を総合評価し、計画の見直しに使う<br><br><b>答案に書くなら</b>　気候変動影響評価報告書とは、気候変動適応法に基づき、最新の科学的知見でおおむね5年ごとに影響を総合的に評価する報告書である。<br><br><b>関連</b>　適応計画の変更時に勘案する。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/430AC0000000050\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【気候変動影響評価報告書（第3次）｜制度】影響評価の3つの観点は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　重大性、緊急性、確信度<br><br><b>解説</b>　影響は大きさだけでなく、いつ現れるか、どれだけ確かか、で対応の優先度が変わる。そこで重大性・緊急性・確信度の3つの物差しで評価する<br><br><b>答案に書くなら</b>　影響評価は、重大性・緊急性・確信度の3つの観点で行う。<br><br><b>関連</b>　重大性は社会・経済・環境の3観点で見る。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。評価の物差しとして書く<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_02915.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【気候変動影響評価報告書（第3次）｜制度】第3次報告書の改善点は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　重大性を3段階（レベル1〜3）に細分化し、現状・1.5〜2℃上昇時・3〜4℃上昇時で評価。「特に強い影響を受ける地域・対象」を追加<br><br><b>解説</b>　影響の大きさは気温上昇の程度で変わるため、3段階に細分化し、上昇幅別に評価することで、対策の優先度が分かりやすくなる<br><br><b>答案に書くなら</b>　第3次では重大性を3段階に細分化し、現状・1.5〜2℃上昇時・3〜4℃上昇時で評価し、特に強い影響を受ける地域・対象を追加した。<br><br><b>関連</b>　最も高いレベル3は特に重大な影響が認められる。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。第2次との違い<br><br>【出典】<a href=\"https://www.env.go.jp/content/000380482.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【気候変動影響評価報告書（第3次）｜制度】第3次が特に優先的に対応が必要とした項目は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　水稲の収量・品質低下、果樹の栽培適地の変化、洪水・内水、サンゴの白化、暑熱、インフラ・ライフラインの寸断など<br><br><b>解説</b>　重大性・緊急性が高い項目は、対応を急ぐ必要がある。農業、水害、生態系、暑熱、インフラと分野をまたいで挙げられている<br><br><b>答案に書くなら</b>　第3次は水稲の収量・品質低下、果樹の栽培適地の変化、洪水・内水、サンゴの白化、暑熱、インフラ・ライフラインの寸断を優先して対応が必要な項目とした。<br><br><b>関連</b>　暑熱は熱中症による救急搬送者・死亡者数の増加。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 課題の根拠に。分野を挙げるときに<br><br>【出典】<a href=\"https://www.env.go.jp/content/000380482.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【気候変動影響評価報告書（第3次）｜課題】影響評価の課題を『科学的知見』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　適応策の効果を定量的・具体的に整理できたのは小項目全体の3割程度で、複数の適応策を比較できる知見は非常に限られる<br><br><b>解説</b>　適応策の効果を数字で示せなければ、どの策を優先するか決めにくい。第3次でも定量的・具体的に整理できたのは小項目の3割程度にとどまる<br><br><b>答案に書くなら</b>　科学的知見の観点から、課題は適応策の効果を定量的・具体的に整理できたのが小項目全体の3割程度で、複数の適応策を比較できる知見が非常に限られることである。<br><br><b>関連</b>　特に強い影響を受ける地域を整理できたのは4割程度。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 技術・知見の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000380482.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【気候変動影響評価報告書（第3次）｜解決策】評価結果をどう使うか（解決策）？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2026年度の気候変動適応計画の改定と、自治体・事業者による影響の把握・適応策の検討に活用する<br><br><b>解説</b>　評価は作って終わりではなく、国の計画と地域・事業者の判断に使われて初めて意味を持つ。2026年度に適応計画が改定される予定である<br><br><b>答案に書くなら</b>　解決策は、評価結果を2026年度の気候変動適応計画の改定に活用し、自治体・事業者による影響の把握・適応策の検討にも活用することである。<br><br><b>関連</b>　計画改定は2026年度の予定で、公表年（2026年2月）とは別。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 調査検討事項の根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000380482.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【気候変動影響評価報告書（第3次）｜注意】「80項目」とは何か？公表年と計画改定の年度は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　7分野を細分化した小項目の数で第2次より9項目増。公表は2026年2月、適応計画の改定は2026年度の予定<br><br><b>解説</b>　80項目は評価の細かさを示す数字で、7分野を細分化した小項目の数。第2次より9項目増え、細かく見る方向に進んでいる<br><br><b>答案に書くなら</b>　80項目は7分野を細分化した小項目の数で、第2次より9項目増えた。公表は2026年2月、適応計画の改定は2026年度の予定である。<br><br><b>関連</b>　公表年と改定年度を取り違えない。<br><br><b>答案での使い方</b>　数字と年度の取り違えは減点<br><br>【出典】<a href=\"https://www.env.go.jp/content/000380482.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽電池廃棄物の再資源化等の推進に関する法律｜時期】太陽電池廃棄物の再資源化等推進法は施行されているか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　令和8年法律第33号。2026年6月5日公布で未施行。施行は公布から1年6か月以内の政令日（2027年秋〜冬の予定）<br><br><b>解説</b>　本法は令和8年法律第33号で、2026年6月5日に公布された。施行日は政令で定める日で、公布から1年6か月以内。環境省は施行を2027年秋〜冬頃と見込む<br><br><b>答案に書くなら</b>　太陽電池廃棄物の再資源化等推進法は2026年6月に公布済みだが未施行であり、施行は政令で定める日である。<br><br><b>関連</b>　政省令の公布は2027年春頃の予定。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで「公布済み・未施行」と示す<br><br>【出典】<a href=\"https://www.env.go.jp/content/000404704.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽電池廃棄物の再資源化等の推進に関する法律｜定義】太陽電池廃棄物の再資源化等推進法とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　多量の事業用パネルの廃棄者からリサイクル規制を段階的に強化し、幅広い排出者への義務化に向けた環境整備を行う法律<br><br><b>解説</b>　パネルの排出量は2030年代後半以降に顕著に増え、年間最大50万t程度に達する見込みで、最終処分場の残余容量を圧迫するおそれがある。そこで排出が多い者から順に規制を強める<br><br><b>答案に書くなら</b>　太陽電池廃棄物の再資源化等推進法とは、多量の事業用パネルの廃棄者からリサイクル規制を段階的に強化し、幅広い排出者への義務化に向けた環境整備を行う法律である。<br><br><b>関連</b>　50万tは見込みで実績ではない。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000404704.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽電池廃棄物の再資源化等の推進に関する法律｜制度】義務づけの対象と、勧告・命令の対象は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　事業用パネルの廃棄者に、判断基準に基づくリサイクルの取組を義務づけ。勧告・命令の対象は多量廃棄者<br><br><b>解説</b>　全員に一律に課すのではなく、段階的に進める設計。事業用の廃棄者は基準に基づくリサイクルが義務で、勧告・命令は多量廃棄者に限る<br><br><b>答案に書くなら</b>　事業用パネルの廃棄者に判断基準に基づくリサイクルの取組を義務づけ、勧告・命令の対象は多量廃棄者とする。<br><br><b>関連</b>　指導・助言は全ての事業用廃棄者が対象。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。全面義務化と書かない<br><br>【出典】<a href=\"https://www.env.go.jp/content/000404704.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽電池廃棄物の再資源化等の推進に関する法律｜制度】多量事業用太陽電池廃棄者に課される手続は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　廃棄前に実施計画を国へ届出し、原則、受理から30日経過後でなければ排出できない<br><br><b>解説</b>　多量に出す者は、その処理が地域の処分能力を圧迫しやすい。そこで廃棄前に実施計画を届け出させて、国が事前に把握・関与できるようにする<br><br><b>答案に書くなら</b>　多量事業用太陽電池廃棄者は、廃棄前に実施計画を国へ届出し、原則として受理から30日経過後でなければ排出できない。<br><br><b>関連</b>　計画が著しく不十分なら変更等を勧告・命令。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。排出前の事前届出と書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000404704.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽電池廃棄物の再資源化等の推進に関する法律｜課題】パネルのリサイクルの課題を『技術・体制』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　専用施設の処理能力は約13万t/年で今後の排出見込量に不足し、8府県に施設がない<br><br><b>解説</b>　専用のリサイクル施設は能力も立地も足りない。2025年11月時点で専用施設は87件、処理能力は約13万t/年で、将来の排出見込みに対して不足している<br><br><b>答案に書くなら</b>　技術・体制の観点から、課題は専用施設の処理能力が約13万t/年で今後の排出見込量に不足し、8府県に施設がないことである。<br><br><b>関連</b>　パネルの種類によっては技術的・経済的に困難。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 技術・体制の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000404704.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽電池廃棄物の再資源化等の推進に関する法律｜課題】パネルのリサイクルの課題を『経済』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　埋立とリサイクルの費用差が大きい（リサイクル8,000〜12,000円/kW、埋立2,000円/kW程度〜）<br><br><b>解説</b>　埋立のほうが安いと、排出者は埋立を選びやすい。費用差が大きいと、義務づけがない限りリサイクルは進まない<br><br><b>答案に書くなら</b>　経済の観点から、課題は埋立とリサイクルの費用差が大きく、リサイクルが8,000〜12,000円/kW、埋立が2,000円/kW程度〜であることである。<br><br><b>関連</b>　6割以上の事業者は実質的にリサイクルを検討していない。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 経済の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000404704.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽電池廃棄物の再資源化等の推進に関する法律｜解決策】リサイクル促進の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　設備・保管施設の導入支援に加え、国の認定制度（廃掃法の許可の特例）で広域的・効率的な処理を進めコストを下げる<br><br><b>解説</b>　リサイクルのコストが高い主因は、処理能力の不足と手続きの重さ。設備の支援と、都道府県ごとの許可が不要になる特例でコストを下げる<br><br><b>答案に書くなら</b>　制度・設備面の観点から、解決策は設備・保管施設の導入支援に加え、国の認定制度（廃掃法の許可の特例）で広域的・効率的な処理を進めてコストを下げることである。<br><br><b>関連</b>　認定の対象は費用効率的なリサイクル事業の計画。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 制度・設備面の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000404704.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽電池廃棄物の再資源化等の推進に関する法律｜注意】この法律は、全てのパネルにリサイクルを義務づけるか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　一律ではない。義務づけは事業用の廃棄者への判断基準の取組で、住宅用を含む全面義務化は附則の検討規定にとどまる<br><br><b>解説</b>　まず多量の事業用から始め、住宅用などの幅広い排出者への義務化は、将来の課題として附則の検討規定に置いた。一律義務化と書くと誤り<br><br><b>答案に書くなら</b>　本法の義務づけは事業用の廃棄者への判断基準に基づく取組であり、住宅用を含む全面義務化は附則の検討規定にとどまる。<br><br><b>関連</b>　製造・輸入業者の環境配慮設計は努力義務。<br><br><b>答案での使い方</b>　「全パネル義務化」と書くと減点<br><br>【出典】<a href=\"https://www.env.go.jp/content/000404704.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域気候変動適応計画・地域気候変動適応センター｜時期】気候変動適応法の施行と、次期適応計画の改定時期は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2018年6月公布、同12月施行。2023年に熱中症対策を強化。次期計画は2026年度内に改定予定<br><br><b>解説</b>　気候変動の影響は地域で異なるため、適応法が国・自治体・事業者・国民の役割を定めた。施行後も改正で熱中症対策を強化し、国の計画は影響評価を受けて改定中<br><br><b>答案に書くなら</b>　気候変動適応法は2018年12月に施行され、2023年の改正で熱中症対策が強化され、次期計画は2026年度内に改定予定である。<br><br><b>関連</b>　2026年2月に第3次の気候変動影響評価報告書を公表。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで時期を示す<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/430AC0000000050\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域気候変動適応計画・地域気候変動適応センター｜定義】地域気候変動適応センターとは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　都道府県・市町村が、影響・適応の情報の収集・整理・分析・提供と技術的助言を行う拠点機能を担う体制（第13条、努力義務）<br><br><b>解説</b>　地域の適応策を進めるには、気候変動影響・適応に関する情報の収集・分析・提供と技術的助言を担う拠点が要る。努力義務で、国立環境研究所と情報を共有する<br><br><b>答案に書くなら</b>　地域気候変動適応センターとは、都道府県・市町村が影響・適応の情報の収集・整理・分析・提供と技術的助言を行う拠点機能を担う体制であり、確保は努力義務である（第13条）。<br><br><b>関連</b>　複数自治体の共同設置は1件と数える。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 自治体の体制の定義に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/430AC0000000050\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域気候変動適応計画・地域気候変動適応センター｜制度】地域気候変動適応計画の根拠と義務の程度は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　法第12条。都道府県・市町村が国の適応計画を勘案して策定するよう努める努力義務<br><br><b>解説</b>　地域計画は都道府県・市町村が国の適応計画を勘案して作る計画で、義務ではなく努力義務。温対法の地方公共団体実行計画（緩和）とは別の計画<br><br><b>答案に書くなら</b>　地域気候変動適応計画は気候変動適応法第12条に基づき、都道府県・市町村が国の計画を勘案して策定するよう努める努力義務の計画である。<br><br><b>関連</b>　異なる計画を一体的に策定することは可能。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 自治体計画の書き出しに<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/430AC0000000050\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域気候変動適応計画・地域気候変動適応センター｜制度】気候変動適応広域協議会とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　国の地方行政機関・都道府県・市町村・センター・事業者等で組織でき、全国7ブロックで広域アクションプランを策定<br><br><b>解説</b>　広域協議会は、複数の自治体にまたがる課題を関係者で調整する場。全国7ブロックに置かれ、地域の課題に応じた広域アクションプランを作る<br><br><b>答案に書くなら</b>　気候変動適応広域協議会は国の地方行政機関・都道府県・市町村・センター・事業者等で組織でき、全国7ブロックで広域アクションプランを策定する。<br><br><b>関連</b>　根拠は適応法第14条で、2023年3月にプランを策定・公開。<br><br><b>答案での使い方</b>　Ⅱ-2 関係者調整（広域連携）の根拠に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/430AC0000000050\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域気候変動適応計画・地域気候変動適応センター｜目標】地域適応計画とセンターの現状（2026年3月）は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　491自治体が計画を策定し、センターは70か所。491は自治体数、70はセンター数（共同設置は1件）<br><br><b>解説</b>　2026年3月現在、計画は491自治体、センターは70か所。センター数は共同設置を1件と数えるため、自治体数とは一致しない<br><br><b>答案に書くなら</b>　2026年3月現在で491自治体が地域気候変動適応計画を策定し、地域適応センターは70か所確保されている。<br><br><b>関連</b>　491は自治体数、70はセンター数で、数え方が異なる。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 現状の数字。自治体数とセンター数を書き分ける<br><br>【出典】<a href=\"https://www.env.go.jp/content/000427991.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域気候変動適応計画・地域気候変動適応センター｜課題】地域適応の課題を『制度・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　市町村の計画策定の促進と計画の質の向上、センターの地域適応のハブとしての機能強化が必要<br><br><b>解説</b>　市区町村は人材不足の中で計画を作る必要があり、策定が進みにくい。センターは地域適応のハブとして機能を強める必要がある<br><br><b>答案に書くなら</b>　制度・運用の観点から、課題は市町村の計画策定の促進と計画の質の向上、センターの地域適応のハブとしての機能強化が必要なことである。<br><br><b>関連</b>　市区町村では人材不足等が負担になっている。<br><br><b>答案での使い方</b>　Ⅱ-2・必須Ⅰ(1) 自治体の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000191251.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域気候変動適応計画・地域気候変動適応センター｜解決策】自治体の適応を支える解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　A-PLATでの影響予測・優良事例の共有、国立環境研究所の専門家派遣（オンライン可）、策定マニュアルの改訂とツール提供<br><br><b>解説</b>　A-PLATは影響予測や優良事例を共有する情報基盤。国立環境研究所の専門家派遣や策定マニュアルの改訂で、自治体の負担を軽くして策定を支える<br><br><b>答案に書くなら</b>　解決策として、A-PLATで影響予測・優良事例を共有し、国立環境研究所の専門家をオンラインも含め派遣し、策定マニュアルの改訂とツール提供を行う。<br><br><b>関連</b>　策定マニュアルは2018年11月に策定、2023年3月に改訂。<br><br><b>答案での使い方</b>　Ⅱ-2 自治体支援の手順に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000427991.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域気候変動適応計画・地域気候変動適応センター｜注意】地域適応計画・センターの100%目標は、誰が対象か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　都道府県・政令指定都市が対象で、市町村は対象外。計画もセンターも努力義務（2026年度目標）<br><br><b>解説</b>　100%目標は都道府県・政令指定都市が対象で、市町村は含まれない。計画もセンターも法律上は努力義務なので、「義務」と書かない<br><br><b>答案に書くなら</b>　計画・センターの2026年度100%目標は都道府県・政令指定都市が対象で、市町村は対象外であり、いずれも努力義務である。<br><br><b>関連</b>　令和6年1月時点で全ての都道府県・政令指定都市は計画を策定済み。<br><br><b>答案での使い方</b>　義務と書くと減点。対象自治体も明記<br><br>【出典】<a href=\"https://www.env.go.jp/content/000191251.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【循環経済行動計画｜時期】循環経済行動計画はいつ、どの会議のどんな形の決定で決まった？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2026年4月21日、循環経済に関する関係閣僚会議（第4回）の決定。閣議決定ではない<br><br><b>解説</b>　世界で資源の獲得競争が激化し、国内の再生可能な資源が海外流出や焼却・埋立てされる現状を受けた。関係閣僚会議は2024年7月の設置<br><br><b>答案に書くなら</b>　循環経済行動計画は2026年4月21日の循環経済に関する関係閣僚会議（第4回）の決定であり、閣議決定ではない。<br><br><b>関連</b>　基本計画（第五次）は2024年8月の閣議決定で別物。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで時期と決定主体を示す<br><br>【出典】<a href=\"https://www.env.go.jp/guide/photo_report/report_01160.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【循環経済行動計画｜定義】行動計画は、循環経済への移行をどう位置づけたか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　環境保全にとどまらない経済安全保障の課題と位置づけ、日本の「勝ち筋」として再生資源供給サプライチェーンの強靱化を急ぐ<br><br><b>解説</b>　資源獲得競争が激しく、再生資源の確保は国の経済安全保障に関わる。重要鉱物・金属資源のリサイクルと再生材の活用が軸<br><br><b>答案に書くなら</b>　行動計画は、循環経済への移行を環境保全にとどまらない経済安全保障の課題と位置づけ、再生資源供給サプライチェーンの強靱化を日本の勝ち筋として急ぐ。<br><br><b>関連</b>　構成は、サプライチェーン強靱化、国際資源循環ネットワーク、地域活性化・国際ルール・国民運動の3節。<br><br><b>答案での使い方</b>　Ⅱ-1 定義・背景の1〜2文目に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/html/hj26010401.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【循環経済行動計画｜制度】行動計画が掲げた投資の目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　再資源化拠点の構築等に、2030年までに官民で約1兆円の投資を目指す（国の予算額ではない）<br><br><b>解説</b>　再資源化拠点の整備には大きな設備投資が必要で、民間の資金を呼び込むことが狙い。数字は官民合わせた投資目標で、国の予算額ではない<br><br><b>答案に書くなら</b>　行動計画は、再資源化拠点の構築等に2030年までに官民で約1兆円の投資を目指すとしている。<br><br><b>関連</b>　官民ファンドの脱炭素化支援機構（JICN）等の活用で後押しする。<br><br><b>答案での使い方</b>　Ⅱ-1 制度の本文。数字の主語を官民と書く<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/pdf/full.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【循環経済行動計画｜制度】メタルリサイクル推進戦略の2030年の再生材供給目標を、品目別に言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　鉄は高品位スクラップ化の処理能力約200万t/年を追加確保。アルミ展伸材約4割、電解銅約3割、永久磁石の原料約3割を再生資源由来に<br><br><b>解説</b>　メタルリサイクル推進戦略は、品目ごとに指標を変えて2030年の再生材供給目標を置く。鉄は処理能力、アルミ・銅・磁石は国内に占める割合で測る<br><br><b>答案に書くなら</b>　2030年の再生材供給目標は、鉄が高品位スクラップ化の処理能力約200万t/年の追加確保、アルミ展伸材約4割、電解銅約3割、永久磁石の原料約3割である。<br><br><b>関連</b>　品目ごとに指標が違うため同じ尺度で比べられない。<br><br><b>答案での使い方</b>　Ⅱ-1 制度の目標。品目ごとに指標が違う点に注意<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/html/hj26010401.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【循環経済行動計画｜課題】循環経済行動計画を根拠に、資源循環の課題を『担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　静脈産業は小規模分散で長期・大口契約を結べる事業者が少なく、設備投資の回収も長いため民間融資を受けにくい<br><br><b>解説</b>　静脈産業（回収・再資源化側）は地域ごとに小規模で分散し、製造業と長期・大口の契約を結びにくい。高度リサイクルの設備は投資回収も長く、民間融資を受けにくい<br><br><b>答案に書くなら</b>　担い手の観点から、課題は静脈産業が小規模分散で長期・大口契約を結べる事業者が少なく、投資回収も長いため民間融資を受けにくいことである。<br><br><b>関連</b>　動静脈連携は製造業（動脈）と静脈産業の連携のこと。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 担い手の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/pdf/full.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【循環経済行動計画｜課題】行動計画が挙げる資源循環の課題を『制度・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　不適正なスクラップヤードが環境対策のコストをかけず高値で資源を買い集め、公正な競争を阻害している<br><br><b>解説</b>　不適正なスクラップヤードは環境対策のコストをかけず高値で買えるため、適正な事業者との公正な競争を妨げる。100以上の都道府県等が国レベルの規制を望んでいる<br><br><b>答案に書くなら</b>　制度・運用の観点から、課題は不適正なスクラップヤードが環境対策のコストをかけず高値で資源を買い集め、公正な競争を阻害していることである。<br><br><b>関連</b>　対策は廃棄物処理法の改正（2026年6月公布）で許可制を導入。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 制度・運用の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/html/hj26010401.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【循環経済行動計画｜解決策】動静脈連携を進める解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　再資源化事業等高度化法の大臣認定を3年で100件以上目指し、官民ファンド（JICN）等の活用で投資を後押しする<br><br><b>解説</b>　再資源化事業等高度化法は、再資源化事業の高度化を認定する制度で、2025年11月に全面施行された。認定制度に官民ファンドの出資を組み合わせて投資を促す<br><br><b>答案に書くなら</b>　解決策として、再資源化事業等高度化法の大臣認定を3年で100件以上目指し、官民ファンド（JICN）等の活用で投資を後押しする。<br><br><b>関連</b>　同法は令和6年法律第41号。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 解決策の1つに。認定制度とファンドを併記<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/pdf/full.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【循環経済行動計画｜注意】行動計画と第五次循環型社会形成推進基本計画の違いは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　第五次基本計画は2024年8月閣議決定で別物。資源生産性約60万円/トン（2030年度）等の指標は基本計画のもの<br><br><b>解説</b>　第五次循環基本計画（2024年8月閣議決定）は循環型社会形成推進基本法に基づく別の計画で、行動計画はその上乗せ施策群。指標は基本計画のものを混ぜない<br><br><b>答案に書くなら</b>　行動計画は関係閣僚会議の決定で、第五次基本計画（2024年8月閣議決定）とは別であり、資源生産性約60万円/トン（2030年度）等の指標は基本計画のものである。<br><br><b>関連</b>　2023年度の資源生産性は約50.9万円/トン。<br><br><b>答案での使い方</b>　Ⅱ-1 留意点。基本計画の指標を行動計画の目標と混ぜない<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/pdf/full.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽光発電の環境アセス対象拡大｜時期】環境影響評価法施行令の太陽光規模見直しは、いつ決まっていつ施行か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　2026年7月17日に閣議決定（令和8年政令第230号）。施行は令和9年（2027年）4月1日で、決定済みだが未施行<br><br><b>解説</b>　2025年12月23日の関係閣僚会議の対策パッケージを受けた政令改正。政令は決定済みだが、施行日は令和9年4月1日で未施行<br><br><b>答案に書くなら</b>　環境影響評価法施行令の太陽光規模見直しは2026年7月17日に閣議決定され、2027年4月1日施行で、決定済みだが未施行である。<br><br><b>関連</b>　意見募集（2026年6月2日〜7月1日）は政令案についてだった。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し。案ではなく決定済みと書く<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05279.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽光発電の環境アセス対象拡大｜定義】環境アセスの第一種事業と第二種事業の違いは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　第一種は規模が大きくアセス必須。第二種は個別にスクリーニングで要否を判定する。太陽電池発電所は2020年4月に対象化<br><br><b>解説</b>　第一種は規模が大きくアセスが必須、第二種はスクリーニングで個別に要否を判定する。太陽電池発電所は2020年4月に対象に追加された<br><br><b>答案に書くなら</b>　第一種事業は規模が大きくアセス必須で、第二種事業は個別にスクリーニングで要否を判定し、太陽電池発電所は2020年4月に対象事業へ追加された。<br><br><b>関連</b>　従来は第一種が4万kW以上、第二種が3万kW以上4万kW未満。<br><br><b>答案での使い方</b>　Ⅱ-1 定義の書き出しに<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05279.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽光発電の環境アセス対象拡大｜制度】太陽電池発電所の第一種・第二種の規模は、どう変わるか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　第一種は4万kW以上から2万kW以上へ。第二種は3万kW以上4万kW未満から1.5万kW以上2万kW未満へ（出力、交流）<br><br><b>解説</b>　規模の指標は出力（交流側）で、面積ではない。土地改変の影響を踏まえて、第一種・第二種とも下限を引き下げる<br><br><b>答案に書くなら</b>　太陽電池発電所は、第一種が4万kW以上から2万kW以上へ、第二種が3万kW以上4万kW未満から1.5万kW以上2万kW未満へ見直される。<br><br><b>関連</b>　第二種の下限の見直しと第一種の下限の見直しは別の改正点。<br><br><b>答案での使い方</b>　Ⅱ-1 制度の本文。新旧の数字を並べる<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05279.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽光発電の環境アセス対象拡大｜制度】施行時に手続中の事業を守る経過措置を言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　施行前に法手続を始めた3〜4万kWは第二種のまま継続。新たに対象となる事業は条例等の図書を相当書類とみなし途中から法手続へ<br><br><b>解説</b>　施行直前に手続を進めている事業者が、規模の見直しで手戻りしないよう、経過措置を置く。条例アセスの図書を法の図書とみなして途中から移れる<br><br><b>答案に書くなら</b>　施行前に法手続を始めた3〜4万kWの事業は第二種のまま継続でき、新たに対象となる事業は条例等の図書を相当書類とみなして途中から法手続へ移れる。<br><br><b>関連</b>　根拠は環境影響評価法第54条。<br><br><b>答案での使い方</b>　Ⅱ-1 制度の留意点。Ⅱ-2 手戻り防止の調整に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000416630.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽光発電の環境アセス対象拡大｜課題】太陽光アセスの規模要件の課題を『技術・科学』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　影響が大きいのは土地の面的改変だが、出力と面積の関係は蓄電池の併設や発電効率の向上で変わりうる。2019年答申は5年程度での見直しを求めた<br><br><b>解説</b>　影響が大きいのは土地の面的な改変だが、出力と面積の関係は蓄電池の併設や発電効率の向上で変わりうる。2019年答申は5年程度での見直しを求めていた<br><br><b>答案に書くなら</b>　技術・科学の観点から、課題は出力と面積の関係が蓄電池の併設や発電効率の向上で変わりうるため、規模要件を状況に応じて見直す必要があることである。<br><br><b>関連</b>　環境影響で特に大きいのは土地の面的改変。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://assess.env.go.jp/files/0_db/contents/1086_04/shiryou2.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽光発電の環境アセス対象拡大｜課題】太陽光アセスの課題を『制度・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　法対象外の規模は条例アセスが担うが、対象規模は自治体で差が大きく、出力基準でも0.8万〜5万kW等とまちまち<br><br><b>解説</b>　法対象外の規模は条例アセスが担うが、条例の対象規模は自治体で異なる。面積基準の自治体も多く、出力基準でも0.8万〜5万kW等とまちまち<br><br><b>答案に書くなら</b>　制度・運用の観点から、課題は法対象外の規模は条例アセスが担うが、対象規模が自治体で差が大きく、出力基準でも0.8万〜5万kW等とまちまちなことである。<br><br><b>関連</b>　施行前後の事業を法手続へつなぐ経過措置の運用も要る。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 制度・運用の観点の課題に<br><br>【出典】<a href=\"https://assess.env.go.jp/files/0_db/contents/1086_04/shiryou2.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽光発電の環境アセス対象拡大｜解決策】立地の多様な太陽光事業に配慮する解決策を、専門用語で言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　第二種のスクリーニング基準に森林開発・傾斜地の観点を加え、造成地は合理化ガイドライン、対象外は環境配慮ガイドラインで促す<br><br><b>解説</b>　森林や傾斜地は土地改変の影響が大きいため、スクリーニングで観点を加える。造成済みの土地には項目選定を簡略化する合理化ガイドラインがある<br><br><b>答案に書くなら</b>　解決策として、第二種のスクリーニング基準に森林開発・傾斜地の観点を加え、造成地は合理化ガイドライン、法・条例の対象外は環境配慮ガイドラインで配慮を促す。<br><br><b>関連</b>　環境配慮ガイドラインは令和2年3月公表で、10kW以上の事業用太陽光が対象。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 解決策の1つに。基準とガイドラインを併記<br><br>【出典】<a href=\"https://www.env.go.jp/council/content/i_01/000419510.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【太陽光発電の環境アセス対象拡大｜注意】2026年9月15日からの意見募集は、何についてのものか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priA\">優先度 A</span> <small>必須Ⅰの国の計画、または得意分野・Ⅱ-1予測の上位。中身まで答案に書けるように</small><br><br><b>答え</b>　政令そのものではなく、条例等の書類を法の相当書類として指定する件（案）についてのもの<br><br><b>解説</b>　2026年9月15日からの意見募集は、法第54条第2項に基づき、条例等の書類を相当書類として指定する件（案）についてで、政令そのものではない<br><br><b>答案に書くなら</b>　2026年9月15日からの意見募集は、政令ではなく、条例等の書類を法の相当書類として指定する件（案）についてのものである。<br><br><b>関連</b>　政令案の意見募集は2026年6〜7月で、別のもの。<br><br><b>答案での使い方</b>　Ⅱ-1 留意点。政令案の意見募集（6〜7月）と混同しない<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05577.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}];
const NJ_PRI_B_DATA = [{"f": "二次:用語", "q": "【CCS事業法（二酸化炭素の貯留事業に関する法律）｜時期】CCS事業法の施行状況は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　段階施行で、探査は2024年8月、試掘は2024年11月、貯留事業・導管輸送は2026年5月22日に完全施行<br><br><b>解説</b>　事業が段階的に始まるため、法も3段階で施行された。探査は2024年8月、試掘は2024年11月、貯留事業と導管輸送は2026年5月22日で、現在は完全施行済み<br><br><b>答案に書くなら</b>　CCS事業法は段階施行され、2026年5月22日に貯留事業・導管輸送事業の規定まで完全施行された。<br><br><b>関連</b>　施行は探査→試掘→貯留事業の3段階。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで「施行済み」と示す<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000038\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【CCS事業法（二酸化炭素の貯留事業に関する法律）｜定義】CCS事業法とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　CO2を地下に貯蔵する貯留事業と、導管輸送事業に、許可制・届出制、保安規制、事業終了後の管理を定めた法律<br><br><b>解説</b>　CCSは電化や水素等では脱炭素化が難しい分野の排出を減らす手段。地下にCO2を長期貯蔵するため、事業の許可と保安、終了後の管理を法で定める必要がある<br><br><b>答案に書くなら</b>　CCS事業法とは、CO2の貯留事業と導管輸送事業について、許可制・届出制、保安規制、事業終了後の管理を定めた法律である。<br><br><b>関連</b>　国は2030年までに民間事業者がCCS事業を始める事業環境を整える方針。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.env.go.jp/council/content/i_18/000393953.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【CCS事業法（二酸化炭素の貯留事業に関する法律）｜制度】貯留事業の許可の仕組みは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　経産大臣が「特定区域」を指定して募集し、貯留区域ごとに許可。海域の指定は環境大臣の同意が必要<br><br><b>解説</b>　貯留層は特定の区域にしかなく、誰でも自由に掘れては困る。国が区域を指定して事業者を募集し、貯留区域ごとに許可する。海域は環境への影響があるので環境大臣の同意が必要になる<br><br><b>答案に書くなら</b>　経産大臣が特定区域を指定して募集し、貯留区域ごとに貯留事業を許可する。海域の指定には環境大臣の同意を要する。<br><br><b>関連</b>　貯留権は物権とみなされる。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。海域は経産・環境の共管<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000038\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【CCS事業法（二酸化炭素の貯留事業に関する法律）｜制度】注入終了後の管理の仕組みは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　事業者が引当金を積み、閉鎖措置の確認・廃止許可後は管理がJOGMECへ移り、事業者はJOGMECへ拠出金を納付<br><br><b>解説</b>　CO2は注入後も長期の監視が必要で、事業者が撤退しても管理は途切れさせられない。そこで事業者が引当金を積み、廃止後はJOGMECが管理を引き継ぐ<br><br><b>答案に書くなら</b>　事業者が引当金を積み、閉鎖措置の確認・廃止許可後は管理がJOGMECへ移り、事業者はJOGMECへ拠出金を納付する。<br><br><b>関連</b>　拠出金は少なくとも30年間分の管理費用を確保できる算定基準とする省令内容が整理されている。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。長期管理の資金確保<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000038\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【CCS事業法（二酸化炭素の貯留事業に関する法律）｜制度】漏えい等による損害の賠償責任は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　損害発生時の貯留事業者等が負う無過失責任。過失を立証されなくても責任を負う<br><br><b>解説</b>　漏えいが起きても、被害者が事業者の過失を証明するのは困難である。そのため無過失責任として被害者の救済を確実にする<br><br><b>答案に書くなら</b>　貯留事業者等は、漏えい等による損害について過失を立証されなくても賠償責任を負う無過失責任を負う。<br><br><b>関連</b>　賠償義務者は損害発生時の貯留事業者等。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の留意点に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000038\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【CCS事業法（二酸化炭素の貯留事業に関する法律）｜課題】CCSの課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　注入CO2が長期に安定して貯蔵され漏えいがないことの確認が要り、モニタリング・閉鎖措置の詳細設計が必要<br><br><b>解説</b>　CO2は地下に長期間とどまることが前提で、漏えいがないと確認できなければ温暖化対策の意味が薄れる。そのため監視と閉鎖措置の設計が課題になる<br><br><b>答案に書くなら</b>　技術の観点から、課題は注入したCO2が長期に安定して貯蔵され漏えいがないことの確認であり、モニタリング・閉鎖措置の詳細設計が必要なことである。<br><br><b>関連</b>　詳細は省令・ガイドラインで整理されている。<br><br><b>答案での使い方</b>　Ⅱ-1の課題。観点名を明記して書く<br><br>【出典】<a href=\"https://www.env.go.jp/council/content/i_18/000393953.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【CCS事業法（二酸化炭素の貯留事業に関する法律）｜解決策】CCSの漏えいリスクへの解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　貯留層の温度・圧力等の監視と報告を義務づけ、漏えい時は直ちに応急措置、閉鎖措置を確認して廃止を許可する<br><br><b>解説</b>　漏えいを早く見つけ、起きたら被害を拡げない手順を法で決めておく。注入後も監視・報告を義務づけ、廃止は安全確認後にのみ許可する<br><br><b>答案に書くなら</b>　技術・保安の観点から、解決策は貯留層の温度・圧力等の監視と報告を義務づけ、漏えい時は直ちに応急措置を講じ、閉鎖措置を確認して廃止を許可することである。<br><br><b>関連</b>　応急措置は法第48条、閉鎖措置の確認は第53条。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 保安面の解決策に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000038\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【CCS事業法（二酸化炭素の貯留事業に関する法律）｜注意】海底下CCSの許可は、海洋汚染等防止法と本法のどちらか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　本法に一元化され、経産大臣と環境大臣の共管となった<br><br><b>解説</b>　従来は海洋汚染等防止法の許可で海底下CCSを扱っていたが、事業の許可と保安を一体で扱うため、CCS事業法に一元化された<br><br><b>答案に書くなら</b>　海底下CCSの許可は本法に一元化されており、経済産業大臣と環境大臣の共管である。<br><br><b>関連</b>　海洋汚染等防止法の許可制度は本法へ一元化された（旧制度と混同しない）。<br><br><b>答案での使い方</b>　旧制度（海洋汚染等防止法の許可）と混同しない<br><br>【出典】<a href=\"https://www.env.go.jp/council/content/i_18/000393953.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【再資源化事業等高度化法｜時期】再資源化事業等高度化法はいつ全面施行されたか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　2025年11月21日に全面施行（一部は2025年2月1日）。公布は2024年5月29日<br><br><b>解説</b>　法は2024年5月29日に公布され、一部が2025年2月1日、全面施行が2025年11月21日と段階的に施行された。全面施行後は認定制度が動いている<br><br><b>答案に書くなら</b>　再資源化事業等高度化法は2025年11月21日に全面施行されており、認定制度が運用される段階にある。<br><br><b>関連</b>　公布日（2024年5月29日）と区別。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで施行済みと示す。公布日と区別<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000041\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【再資源化事業等高度化法｜定義】再資源化事業等高度化法とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　再資源化のための廃棄物の収集・運搬・処分と、再資源化の技術・設備の高度化を促し、GHG削減効果の高い資源循環を促進する法律<br><br><b>解説</b>　従来の廃棄物行政は適正処理が中心で、再生材の質と量を高める施策が不足していた。そこで再資源化の事業と技術・設備の高度化を促す<br><br><b>答案に書くなら</b>　再資源化事業等高度化法とは、再資源化のための廃棄物の収集・運搬・処分と技術・設備の高度化を促し、温室効果ガスの削減効果の高い資源循環を促進する法律である。<br><br><b>関連</b>　基本方針は環境大臣が策定する。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000041\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【再資源化事業等高度化法｜制度】再資源化事業等高度化法の認定3類型は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　①高度再資源化事業計画②高度分離・回収事業計画③再資源化工程高度化計画（既存施設向け）。環境大臣が認定<br><br><b>解説</b>　事業の形によって必要な支援が違うため、3つの類型に分ける。新設の事業、分離・回収の高度化、既存施設の高度化で、認定は環境大臣が行う<br><br><b>答案に書くなら</b>　認定は①高度再資源化事業計画、②高度分離・回収事業計画、③再資源化工程高度化計画（既存施設向け）の3類型で、環境大臣が認定する。<br><br><b>関連</b>　認定を受けると廃棄物処理法の許可の特例がある。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。3類型を番号で書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000041\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【再資源化事業等高度化法｜制度】判断基準と報告・公表の仕組みは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　廃棄物処分業者の判断基準を環境省令で定め、特定産業廃棄物処分業者が処分量・再資源化量を毎年度報告し、環境大臣が公表<br><br><b>解説</b>　認定を受けた事業者だけでなく、廃棄物処分業者全体の水準を引き上げる必要がある。基準を示し、処分量と再資源化量を報告・公表させる<br><br><b>答案に書くなら</b>　廃棄物処分業者の判断基準を環境省令で定め、特定産業廃棄物処分業者に処分量・再資源化量を毎年度報告させ、環境大臣が公表して全体の底上げを図る。<br><br><b>関連</b>　報告義務は処分量の多い特定産業廃棄物処分業者。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。底上げの仕組みとして書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000041\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【再資源化事業等高度化法｜課題】資源循環の課題を『制度・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　製造（動脈）と廃棄物処分（静脈）の連携。再生資源の利用目標の共有と、トレーサビリティのためのデータ連携が要る<br><br><b>解説</b>　動脈（製造）と静脈（廃棄物処分）がつながらないと、再生材が製造側の求める質・量で流れない。情報の共有とトレーサビリティも要る<br><br><b>答案に書くなら</b>　制度・運用の観点から、課題は動脈と静脈の連携であり、再生資源の利用目標の共有とトレーサビリティのためのデータ連携が必要なことである。<br><br><b>関連</b>　動脈は製造、静脈は廃棄物処分を指す。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 制度の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000360673.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【再資源化事業等高度化法｜課題】資源循環の課題を『経済・担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　製造業が求める量・質の再生材を安定供給できる事業が不足している。再資源化工程自体の脱炭素化も求められる<br><br><b>解説</b>　製造業は品質の安定した再生材を大量に求める。ところがそれに応える事業者が不足しており、再資源化の工程自体にも脱炭素化が求められる<br><br><b>答案に書くなら</b>　経済・担い手の観点から、課題は製造業が求める量・質の再生材を安定供給できる事業が不足していることであり、再資源化工程自体の脱炭素化も求められる。<br><br><b>関連</b>　目標は施行から3年間で100件以上の事業認定。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 経済の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000360673.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【再資源化事業等高度化法｜解決策】製造側と処分側をつなぐ解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　高度再資源化事業の認定で、製造側の需要に応じた質・量の再生材確保を図り、製造事業者と処分業者のマッチングを促す<br><br><b>解説</b>　製造側が求める再生材と、処分側の供給のギャップを埋める必要がある。高度再資源化事業の認定により、製造側の需要を前提とした事業を支援する<br><br><b>答案に書くなら</b>　連携面の観点から、解決策は高度再資源化事業の認定で製造側の需要に応じた質・量の再生材確保を図り、製造事業者と処分業者のマッチングを促すことである。<br><br><b>関連</b>　認定は環境大臣が国で一括して行う。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 連携面の解決策に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000041\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【再資源化事業等高度化法｜注意】認定は誰が行い、廃棄物処理法との関係は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　環境大臣が国で一括して認定し、廃掃法の許可の特例を与える。廃掃法そのものを置き換えるものではない<br><br><b>解説</b>　廃棄物処理法の許可は都道府県知事が出す。本法は環境大臣が国で一括認定し、廃掃法の許可手続の特例を与える仕組みで、廃掃法自体は残る<br><br><b>答案に書くなら</b>　認定は環境大臣が国で一括して行い、廃棄物処理法の許可に代わる特例を与えるが、廃棄物処理法そのものを置き換えるものではない。<br><br><b>関連</b>　登録調査機関が認定の調査業務を担う。<br><br><b>答案での使い方</b>　都道府県知事の認定と書くと減点<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000041\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック資源循環促進法｜時期】プラスチック資源循環促進法の施行はいつか？また見直しの時期は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　2021年6月公布、2022年4月施行。附則で施行後5年の検討を定め、2027年4月以降に見直しが可能<br><br><b>解説</b>　本法は2021年6月に公布、2022年4月に施行された。附則で施行後5年の検討を定めており、2027年4月以降に見直しが可能だが、見直しが決まったわけではない<br><br><b>答案に書くなら</b>　プラスチック資源循環促進法は2022年4月に施行済みで、附則の検討規定により2027年4月以降に見直しが可能である。<br><br><b>関連</b>　見直しは未決定。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで施行済みと示す。見直しは未決定<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/503AC0000000060\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック資源循環促進法｜定義】プラスチック資源循環促進法とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　製品の設計から廃棄物処理まで、あらゆる主体のプラスチック資源循環の取組を促す法律。3R+Renewableが基本原則<br><br><b>解説</b>　海洋プラごみ、気候変動、アジア諸国の廃棄物輸入規制を背景に、2019年にプラスチック資源循環戦略を作った。本法はその実装で、製品の設計から廃棄までの全主体を対象とする<br><br><b>答案に書くなら</b>　プラスチック資源循環促進法とは、製品の設計から廃棄物処理まで、あらゆる主体の資源循環の取組を促す法律であり、3R+Renewableが基本原則である。<br><br><b>関連</b>　戦略は2019年5月に策定された。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/503AC0000000060\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック資源循環促進法｜制度】同法の措置の5本柱は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　設計指針・認定、使用の合理化、市町村の分別収集・再商品化、自主回収・再資源化、排出事業者の排出抑制・再資源化<br><br><b>解説</b>　プラスチックのライフサイクルを、設計から排出事業者までの5段階で押さえる。製造、使用、回収、再資源化と流れに沿って措置を置く<br><br><b>答案に書くなら</b>　措置は、設計指針・認定、使用の合理化、市町村の分別収集・再商品化、自主回収・再資源化、排出事業者の排出抑制・再資源化の5本柱である。<br><br><b>関連</b>　法の章立てに対応する。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。5段階で書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/503AC0000000060\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック資源循環促進法｜制度】特定プラスチック使用製品とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　無償提供される12製品（スプーン・ストロー・ヘアブラシ・歯ブラシ・ハンガー等）。提供量5t以上の事業者が勧告等の対象<br><br><b>解説</b>　使い捨てになりやすい無償提供の製品に絞り、提供量が多い事業者から取組を求める。対象は12製品で、前年度の提供量が5トン以上の事業者が多量提供事業者となる<br><br><b>答案に書くなら</b>　特定プラスチック使用製品とは無償で提供される12製品であり、提供量5t以上の事業者が、取組が著しく不十分な場合に勧告等の対象となる。<br><br><b>関連</b>　法施行後に特定12品目の提供量は11%減った。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。12製品と5tの数字<br><br>【出典】<a href=\"https://plastic-circulation.env.go.jp/pro/gorika\" target=\"_blank\" rel=\"noopener\">環境省 プラスチック資源循環を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック資源循環促進法｜目標】プラスチック資源循環戦略のマイルストーンは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　2030年までにワンウェイプラを累積25%排出抑制、2035年までに使用済プラを100%有効利用<br><br><b>解説</b>　戦略は2019年に策定され、削減・再利用の目標を年次で示している。排出抑制は2030年、使用済みの有効利用は2035年で、年次が違う<br><br><b>答案に書くなら</b>　プラスチック資源循環戦略は、2030年までにワンウェイプラを累積25%排出抑制し、2035年までに使用済プラを100%有効利用することを掲げる。<br><br><b>関連</b>　ほかに2030年までに再生利用を倍増。<br><br><b>答案での使い方</b>　Ⅱ-1の数字。年次とセットで書く<br><br>【出典】<a href=\"https://plastic-circulation.env.go.jp/about/senryaku\" target=\"_blank\" rel=\"noopener\">環境省 プラスチック資源循環を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック資源循環促進法｜課題】プラ資源循環の課題を『制度・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　プラ資源の回収量の拡大が課題。容リ協の入札量は令和4年度約69万tから令和7年度約66万tへ微減した<br><br><b>解説</b>　リサイクルは回収量が増えなければ進まない。容リ協の入札量は令和4年度約69万tから令和7年度約66万tへ微減し、回収量の拡大が課題とされる<br><br><b>答案に書くなら</b>　制度・運用の観点から、課題はプラ資源の回収量の拡大であり、容リ協の入札量が令和4年度約69万tから令和7年度約66万tへ微減したことである。<br><br><b>関連</b>　製品プラも一括回収できる仕組みがある。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 回収の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/council/content/i_03/000433372.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック資源循環促進法｜解決策】再生材の需要づくりの解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　再生材・バイオプラの価値創出（GHG削減効果の評価、マスバランス方式）を検討し、再生プラ利用計画で需要を創出<br><br><b>解説</b>　再生材は新品より割高で、需要がなければ回収が進んでも使われない。そこで環境価値を見える化して需要を創り、再生プラ利用計画で利用を促す<br><br><b>答案に書くなら</b>　需要面の観点から、解決策は再生材・バイオプラの価値創出（GHG削減効果の評価、マスバランス方式）を検討し、再生プラ利用計画で需要を創出することである。<br><br><b>関連</b>　再生プラの利用計画提出は2027年度から。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 需要面の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/council/content/i_03/000433372.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック資源循環促進法｜注意】特定プラ12品目の要件と、レジ袋有料化との関係は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　要件は「無償提供」。レジ袋有料化（2020年7月）は本法施行（2022年4月）より前の別の施策<br><br><b>解説</b>　レジ袋は2020年7月から有料化され、本法の施行（2022年4月）より前の別施策。12品目は有料のものではなく、無償提供が要件である<br><br><b>答案に書くなら</b>　特定プラスチック使用製品12品目の要件は無償提供であり、レジ袋有料化（2020年7月）は本法施行（2022年4月）より前の別の施策である。<br><br><b>関連</b>　有償提供品や時期を取り違えない。<br><br><b>答案での使い方</b>　有償提供品や時期を取り違えない<br><br>【出典】<a href=\"https://plastic-circulation.env.go.jp/pro/gorika\" target=\"_blank\" rel=\"noopener\">環境省 プラスチック資源循環を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【食品ロス削減推進法と2030年度目標｜時期】食品ロス削減推進法と基本方針の時期は？また最新推計は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　法は2019年5月公布・10月施行。基本方針は2025年3月閣議決定。最新推計は令和6年度（2026年6月公表）<br><br><b>解説</b>　食品ロス削減推進法は国・自治体・事業者・消費者の責務を定め、政府が基本方針で数値目標を置く法律。推計は年度ごとに更新されるため年度を明記する<br><br><b>答案に書くなら</b>　食品ロス削減推進法は2019年10月に施行され、2025年3月閣議決定の基本方針の下、令和6年度推計が最新である。<br><br><b>関連</b>　10月は食品ロス削減月間、10月30日は食品ロス削減の日。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで最新版を示す<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/501AC1000000019\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【食品ロス削減推進法と2030年度目標｜定義】食品ロスとは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　まだ食べることができるのに廃棄される食品（可食部）。食品廃棄物全体とは別（法第2条第2項）<br><br><b>解説</b>　食品ロスは食べられるのに捨てられた分（可食部）だけを指し、食べられない部分も含む食品廃棄物全体とは範囲が違う<br><br><b>答案に書くなら</b>　食品ロスとは、まだ食べることができるのに廃棄される食品であり、食品廃棄物全体とは区別される。<br><br><b>関連</b>　SDGsは2030年までに世界全体の一人当たり食料廃棄の半減を掲げる。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/501AC1000000019\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【食品ロス削減推進法と2030年度目標｜目標】基本方針が定める食品ロス削減の2030年度目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　家庭系は2000年度比で半減、事業系は2000年度比で60%削減<br><br><b>解説</b>　基本方針（2025年3月）は2000年度を基準に、家庭系と事業系で削減率を変えて総量目標を置いている。家庭系は早期達成も求める<br><br><b>答案に書くなら</b>　基本方針は2030年度までに2000年度比で家庭系を半減、事業系を60%削減する目標を掲げている。<br><br><b>関連</b>　目標値は家庭系433万tから216万t、事業系547万tから219万t。<br><br><b>答案での使い方</b>　Ⅱ-1の数字。家庭系と事業系の割合を書き分ける<br><br>【出典】<a href=\"https://www.env.go.jp/content/000408175.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【食品ロス削減推進法と2030年度目標｜制度】令和6年度の食品ロス発生量は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　461万t（事業系237万t、家庭系224万t）。前年度の464万tから約3万t減<br><br><b>解説</b>　発生量は農林水産省・環境省が毎年度推計し、事業系と家庭系に分けて公表する。最新は令和6年度で、年度を取り違えると数字が変わる<br><br><b>答案に書くなら</b>　令和6年度の食品ロス発生量は461万tで、事業系237万t、家庭系224万tである。<br><br><b>関連</b>　前年度比で事業系は約6万t増、家庭系は約9万t減。<br><br><b>答案での使い方</b>　Ⅱ-1の数字。年度とセットで書く<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05155.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【食品ロス削減推進法と2030年度目標｜課題】食品ロス削減の課題を『事業系』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　外食産業の食品ロスが増加傾向で、令和6年度は事業系全体が前年度比で増えた<br><br><b>解説</b>　事業系の内訳は食品製造業46%、外食産業30%、食品小売業20%、卸売業4%。外食産業の増加が全体を押し上げた<br><br><b>答案に書くなら</b>　事業系の観点から、課題は外食産業の食品ロスが増加傾向にあり、令和6年度は事業系全体が前年度比で増えたことである。<br><br><b>関連</b>　事業系では食品製造業110万tが最大の内訳。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 事業系の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05155.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【食品ロス削減推進法と2030年度目標｜課題】食品ロス削減の課題を『家庭系』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　削減率48.3%で半減目標に届かず、直接廃棄と食べ残しが大半を占める<br><br><b>解説</b>　家庭系の内訳は直接廃棄43%、食べ残し41%、過剰除去16%。削減率は2024年度時点で48.3%<br><br><b>答案に書くなら</b>　家庭系の観点から、課題は削減率が48.3%で半減目標に届かず、直接廃棄と食べ残しが大半を占めることである。<br><br><b>関連</b>　事業系の削減率は56.7%で、家庭系と事業系は進み方が違う。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 家庭系の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05155.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【食品ロス削減推進法と2030年度目標｜解決策】食品ロス削減の解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　外食の食べ残し持ち帰り（mottECO）の導入支援と、デコ活による家庭の行動変容の後押し<br><br><b>解説</b>　mottECOは外食での食べ残し持ち帰りの導入手引きと伴走支援の事業。デコ活は家庭の行動変容を後押しする取組で、事業系と家庭系に対応する<br><br><b>答案に書くなら</b>　解決策として、事業系は外食の食べ残し持ち帰り（mottECO）の導入を支援し、家庭系はデコ活で行動変容を後押しする。<br><br><b>関連</b>　自治体向けにフードドライブ実施の手引きや取組事例集（29事例）がある。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 事業系・家庭系の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05155.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【食品ロス削減推進法と2030年度目標｜注意】令和5年度と令和6年度の食品ロス量、世界目標と国内目標の違いは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　令和5年度464万t、令和6年度461万t（最新）。世界は一人当たり食料廃棄の半減、国内は2000年度比の総量<br><br><b>解説</b>　令和5年度と6年度は値が違い、削減率も年度で変わる。また世界目標と国内目標は対象が別（世界は一人当たり、国内は総量）<br><br><b>答案に書くなら</b>　最新は令和6年度の461万tであり、世界の一人当たり食料廃棄の半減目標と国内の2000年度比の総量目標は別物である。<br><br><b>関連</b>　2024年度は発生量全体で旧目標（2000年度比半減）を達成した。<br><br><b>答案での使い方</b>　年度と目標の母集団を取り違えない<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05155.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域生物多様性増進法と自然共生サイト｜時期】地域生物多様性増進法はいつ施行されたか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　2024年4月公布、2025年4月1日施行（施行済み）。主務大臣は環境・農林水産・国土交通大臣<br><br><b>解説</b>　増進法は企業等による増進活動を促すため、基本方針・計画認定・許可手続の特例を設けた法律。2024年4月19日公布、2025年4月1日施行<br><br><b>答案に書くなら</b>　地域生物多様性増進法は2025年4月1日に施行済みで、環境・農林水産・国土交通の3大臣が主務大臣である。<br><br><b>関連</b>　平成22年の旧法は本法の附則で廃止された。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで施行済みと示す<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000018\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域生物多様性増進法と自然共生サイト｜定義】OECMとは何か？自然共生サイトとの関係は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　OECMは保護地域以外で生物多様性の保全に資する管理が行われている区域。自然共生サイトはその日本版を国が認定する制度<br><br><b>解説</b>　OECMは保護地域ではないが、民間の取組等で生物多様性が保たれている区域。自然共生サイトは国が認定し、保護地域と重複しない部分が国際データベースに登録される<br><br><b>答案に書くなら</b>　OECMとは保護地域以外で生物多様性の保全に資する区域であり、自然共生サイトはその日本版として国が認定する制度である。<br><br><b>関連</b>　自然共生サイトとOECMは同一ではない。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000018\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域生物多様性増進法と自然共生サイト｜制度】地域生物多様性増進法の仕組みは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　基本方針と、増進活動実施計画の認定制度。認定活動は自然公園法・森林法等の許可・届出の特例（ワンストップ化）を受ける<br><br><b>解説</b>　許認可が複数の法律にまたがる活動を、認定1回で進めやすくする仕組み。事業者は増進活動実施計画を作り主務大臣が認定する<br><br><b>答案に書くなら</b>　制度の中身は、主務大臣が基本方針を定め、増進活動実施計画を認定し、認定活動には自然公園法・森林法等の許可・届出の特例（ワンストップ化）を設けることである。<br><br><b>関連</b>　土地所有者等全員の合意で生物多様性維持協定を結べる。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。認定と特例の2点を書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/506AC0000000018\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域生物多様性増進法と自然共生サイト｜制度】自然共生サイトの累計認定数は？（2026年10月時点）", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　700か所（2026年10月30日の令和8年度第2回認定で到達。法施行前の328か所を含む累計）<br><br><b>解説</b>　自然共生サイトは2023年度に認定を開始し、2024年度までに328か所、2025年4月から法定の認定に移行した。累計は法施行前を含む<br><br><b>答案に書くなら</b>　自然共生サイトは2026年10月30日の認定で累計700か所に達し、法施行前の328か所を含む累計である。<br><br><b>関連</b>　令和8年度の認定数（第2回の122か所など）とは数え方が別。<br><br><b>答案での使い方</b>　Ⅱ-1の数字。累計の起点を明示する<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05720.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域生物多様性増進法と自然共生サイト｜課題】30by30の課題を『制度・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　30by30は主にOECMの設定で達成する計画だが、OECMは陸域で0.2%にとどまる（2026年8月時点）<br><br><b>解説</b>　30by30は保護地域とOECMで陸と海の30%以上を保全する目標。計画は主にOECMの設定で達成する方針だが、OECMの面積が伸びていない<br><br><b>答案に書くなら</b>　制度・運用の観点から、課題は30by30を主にOECMの設定で達成する計画だが、OECMが陸域で0.2%にとどまることである。<br><br><b>関連</b>　保護地域の拡張も国立公園等の候補地14か所で調整が進行中。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 制度の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05386.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域生物多様性増進法と自然共生サイト｜課題】生物多様性の取組の課題を『技術・科学』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　生物多様性の状況と保全活動の効果の「見える化」が必要。見える化システムで国土全体の状況を可視化している<br><br><b>解説</b>　保全活動の効果や生物多様性の状況が見えないと、優先地域の判断や活動の評価がしにくい。国土全体を可視化する見える化システムを運用している<br><br><b>答案に書くなら</b>　技術・科学の観点から、課題は生物多様性の状況と保全活動の効果を見える化する必要があることである。<br><br><b>関連</b>　2026年度に30by30ロードマップの中間評価を実施する。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05386.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域生物多様性増進法と自然共生サイト｜解決策】OECMを増やす解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　自然共生サイトの認定を進め、保護地域との重複を除いてOECM国際データベースに登録する。支援証明書制度で企業の参画を促す<br><br><b>解説</b>　OECMの登録は、自然共生サイトを認定し、保護地域と重複する部分を除いて国際データベースに載せる流れ。支援証明書は支援した企業等に発行される<br><br><b>答案に書くなら</b>　解決策として、自然共生サイトの認定を進めて保護地域と重複しない区域をOECM国際データベースに登録し、支援証明書制度で企業の参画を促す。<br><br><b>関連</b>　支援証明書は2025年9月から本格運用。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 30by30の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05720.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【地域生物多様性増進法と自然共生サイト｜注意】自然共生サイトとOECMは同じか？保護地域との合計割合は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　同じではない。国際DBへの登録は保護地域と重複しない区域のみ。合計は陸域約21.0%、海域約13.3%で目標30%未満<br><br><b>解説</b>　自然共生サイトは国の認定、OECM登録は重複を除いた区域のみ。保護地域とOECMを合わせても目標の30%に届いていない<br><br><b>答案に書くなら</b>　自然共生サイトとOECMは同一ではなく、保護地域とOECMの合計は陸域約21.0%、海域約13.3%で目標の30%に届いていない。<br><br><b>関連</b>　OECMの登録面積は2026年8月時点で累計64.6千ha。<br><br><b>答案での使い方</b>　定義の書き分けで減点を避ける<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05386.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ネイチャーポジティブ経済移行戦略｜時期】ネイチャーポジティブ経済移行戦略はいつ誰が策定したか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　2024年3月に環境省・農水省・経産省・国交省が策定。2025年7月にロードマップ（2025-2030年）を策定<br><br><b>解説</b>　生物多様性国家戦略2023-2030の基本戦略3の重点施策で、企業が自然資本の保全を経営に組み込むのを後押しする。策定主体は4省庁<br><br><b>答案に書くなら</b>　ネイチャーポジティブ経済移行戦略は2024年3月に環境・農水・経産・国交の4省庁が策定し、2025年7月にロードマップ（2025-2030年）が策定された。<br><br><b>関連</b>　戦略は法律ではなく4省庁の戦略。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで策定主体と時期を示す<br><br>【出典】<a href=\"https://www.env.go.jp/content/000298927.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ネイチャーポジティブ経済移行戦略｜定義】ネイチャーポジティブ経営とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　自然資本の保全を価値創造のマテリアリティに据えて、ネイチャーポジティブを目指す経営。実現した経営の意味ではない<br><br><b>解説</b>　マテリアリティは企業にとって重要な経営課題のこと。ネイチャーポジティブは生物多様性の損失を止めて反転させる考え方で、経営は「目指す」姿勢を指す<br><br><b>答案に書くなら</b>　ネイチャーポジティブ経営とは、自然資本の保全を価値創造プロセスのマテリアリティに据え、ネイチャーポジティブを目指す経営である。<br><br><b>関連</b>　実現した経営という意味ではない（戦略の脚注）。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000298927.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ネイチャーポジティブ経済移行戦略｜制度】ネイチャーポジティブ移行による2030年のビジネス機会は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　世界で年1,372兆円（WEF2020年推計）、日本では環境省試算で年47兆円<br><br><b>解説</b>　世界経済フォーラム（WEF）の2020年推計を日本に当てはめて環境省が試算した値で、いずれも2030年時点で増える機会額。うち4分の3以上が炭素中立・循環経済と強く関連する<br><br><b>答案に書くなら</b>　ネイチャーポジティブ移行による2030年のビジネス機会は、世界で年1,372兆円、日本では環境省試算で年47兆円と見込まれる。<br><br><b>関連</b>　世界では年約368兆円の投資が必要とされる。<br><br><b>答案での使い方</b>　Ⅱ-1の数字。世界と日本を書き分ける<br><br>【出典】<a href=\"https://www.env.go.jp/content/000298927.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ネイチャーポジティブ経済移行戦略｜制度】国の施策の4つの構成は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　①リスク・機会の認識②機会の特定・創出③開示・対話を通じた資金呼び込み④基盤環境整備（DX・研究開発）<br><br><b>解説</b>　国の施策は、認識、機会創出、資金呼び込み、基盤整備の順に企業の移行を後押しする構成<br><br><b>答案に書くなら</b>　国の施策は、リスク・機会の認識、機会の特定・創出、開示・対話を通じた資金呼び込み、DX・研究開発等の基盤環境整備の4つで構成される。<br><br><b>関連</b>　戦略の3本柱（ビジネス機会の具体例、押さえる要素、国の施策）とは別の整理。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。4段階で書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000298927.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ネイチャーポジティブ経済移行戦略｜課題】ネイチャーポジティブの課題を『技術・評価』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　自然資本への負荷を定量評価する指標・手法の整備が途上で、効果の見える化と、場所に紐づくデータが必要<br><br><b>解説</b>　自然資本は場所ごとに状態が異なるため、負荷を測る指標・手法の整備が追いついていない。効果の見える化と場所に紐づくデータが要る<br><br><b>答案に書くなら</b>　技術・評価の観点から、課題は自然資本への負荷を定量評価する指標・手法が途上で、効果の見える化と場所に紐づくデータが必要なことである。<br><br><b>関連</b>　評価手法の基本的な考え方を2026年3月に作成している。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000298927.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ネイチャーポジティブ経済移行戦略｜課題】ネイチャーポジティブの課題を『制度・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　自然資本の保全・再生が他の課題より劣後されがち。経団連調査（2022年度）で25%の企業が事業との関連性がわからないと回答<br><br><b>解説</b>　自然資本の保全・再生は他の課題より後回しにされがちで、国外の自然資本への依存が大きく危機を感じにくい。企業の認識不足が背景にある<br><br><b>答案に書くなら</b>　制度・運用の観点から、課題は保全・再生が劣後されがちで、経団連調査（2022年度）で25%の企業が事業との関連性がわからないと回答したことである。<br><br><b>関連</b>　国外の自然資本への依存も課題に挙がる。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 企業認識の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000298927.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ネイチャーポジティブ経済移行戦略｜解決策】企業の取組を促す解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　TNFD等による開示の促進と、調達ガイドライン（2026年7月）・ネイチャーファイナンス実践ガイドライン（同9月）の普及<br><br><b>解説</b>　TNFDは自然関連の情報開示の枠組み。ガイドラインは調達と投融資それぞれの実践を示す任意の指針で、法的拘束力はない<br><br><b>答案に書くなら</b>　解決策として、TNFD等による開示を促し、調達ガイドライン（2026年7月）とネイチャーファイナンス実践ガイドライン（同9月）を普及させる。<br><br><b>関連</b>　TNFDアダプター企業数は日本が219社で世界最多（2026年3月）。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 開示・金融の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/pdf/full.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【ネイチャーポジティブ経済移行戦略｜注意】年1,372兆円と年47兆円の違い、戦略と法律・ロードマップの関係は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　1,372兆円は世界、47兆円は日本。戦略は4省庁の戦略で法律ではなく、ロードマップは別文書<br><br><b>解説</b>　1,372兆円は世界、47兆円は日本で、母集団が違う。戦略は4省庁の戦略で法律ではなく、ロードマップは別の文書<br><br><b>答案に書くなら</b>　年1,372兆円は世界、年47兆円は日本の2030年のビジネス機会であり、戦略は法律ではなくロードマップは別文書である。<br><br><b>関連</b>　ロードマップは2025年7月の策定で、期間は2025-2030年。<br><br><b>答案での使い方</b>　数字は母集団とセットで書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000298927.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【廃棄物処理法の2026年改正｜時期】令和8年法律第43号（廃棄物処理法等の改正）の公布日と、ヤード許可制の施行時期は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　2026年6月19日公布。ヤードの許可制は公布から2年6か月以内（令和10年12月19日より前）に施行で、未施行<br><br><b>解説</b>　許可制本体は公布から2年6か月以内の政令で定める日に施行するため、2026年11月28日時点では施行日が未確定・未施行。災害廃棄物関係は先行施行<br><br><b>答案に書くなら</b>　令和8年法律第43号は2026年6月19日公布で、ヤードの許可制は公布から2年6か月以内（令和10年12月19日より前）に施行する未施行の規定である。<br><br><b>関連</b>　施行済み・未施行を書き分ける。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し。施行済みか予定かを書き分ける<br><br>【出典】<a href=\"https://www.env.go.jp/content/000419110.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【廃棄物処理法の2026年改正｜注意】2026年の改正で、すでに施行されている部分はどこか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　災害廃棄物関係は施行期日政令により令和8年9月16日に施行済み。許可制本体とは時期が異なる<br><br><b>解説</b>　本改正は許可制（ヤード）と災害廃棄物対策の2本立てで、部分ごとに施行期日が異なる。災害廃棄物関係は令和8年9月16日に施行済み<br><br><b>答案に書くなら</b>　2026年の改正のうち災害廃棄物関係は令和8年9月16日に施行済みで、スクラップヤードの許可制本体とは施行時期が異なる。<br><br><b>関連</b>　許可申請の準備行為の規定も施行済み。<br><br><b>答案での使い方</b>　Ⅱ-1 留意点。全部施行済みと書かない<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05564.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【廃棄物処理法の2026年改正｜定義】スクラップヤードを規制する法改正の背景は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　有価物は廃棄物処理法の規制対象外で、廃棄物を有価物と称して規制を逃れる事業者がいた。この隙間を埋める許可制を導入<br><br><b>解説</b>　有価物は原則として廃棄物処理法の対象外のため、廃棄物を有価物と称して規制を逃れる事業者がいた。騒音・悪臭・水質土壌汚染・火災などの問題が一部で生じていた<br><br><b>答案に書くなら</b>　背景として、有価物は廃棄物処理法の規制対象外で、廃棄物を有価物と称して規制を逃れる事業者がいたため、この隙間を埋める許可制を導入した。<br><br><b>関連</b>　実態は令和7年度調査で全国4,625事業場。<br><br><b>答案での使い方</b>　Ⅱ-1 定義・背景の書き出しに<br><br>【出典】<a href=\"https://www.env.go.jp/content/000419110.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【廃棄物処理法の2026年改正｜制度】スクラップヤードの許可制の対象と義務を言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　使用済金属・プラスチック物品の保管又は再生を行う事業者が都道府県知事の許可を要し、保管・再生の基準の遵守と帳簿作成を義務付け<br><br><b>解説</b>　対象は廃棄物ではない有価物（使用済金属・プラスチック物品）で、雑品スクラップや使用済基板が典型。既存の許可業者は許可を受けたものとみなす<br><br><b>答案に書くなら</b>　制度として、使用済金属・プラスチック物品の保管又は再生を行う事業者は都道府県知事の許可を要し、保管・再生の基準の遵守と帳簿の作成が義務付けられる。<br><br><b>関連</b>　小規模事業場や国・自治体等は許可不要。<br><br><b>答案での使い方</b>　Ⅱ-1 制度の中身の本文に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000427424.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【廃棄物処理法の2026年改正｜制度】バーゼル法に関わる物品の輸出の規制を言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　使用済鉛蓄電池・廃電子基板等は国内再生が原則で、輸出には環境大臣の確認が要る。無確認輸出は罰則で未遂罪・予備罪もある<br><br><b>解説</b>　バーゼル法の特定有害廃棄物等は、輸出先での不適正処理を防ぐため国内再生を原則とする。輸出には環境大臣の確認が必要で、無確認の輸出は罰則の対象<br><br><b>答案に書くなら</b>　使用済鉛蓄電池・廃電子基板等は国内再生が原則で、輸出には環境大臣の確認が要り、無確認輸出は未遂罪・予備罪を含む罰則の対象である。<br><br><b>関連</b>　バーゼル条約のPIC手続は2028年度から電子化を目指す。<br><br><b>答案での使い方</b>　Ⅱ-1 制度の本文。国内資源循環の観点で<br><br>【出典】<a href=\"https://www.env.go.jp/content/000427424.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【廃棄物処理法の2026年改正｜課題】適正な事業者への影響という観点で、ヤード規制の課題を1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　不適正ヤードは環境対策のコストを省き買取価格を高く設定でき、適正事業者との公正な競争が妨げられている<br><br><b>解説</b>　不適正ヤードは環境対策のコストを省けるぶん買取価格を高く設定でき、適正事業者の仕入れが不利になる。環境面だけでなく経済面の公正さが問題<br><br><b>答案に書くなら</b>　経済の観点から、課題は不適正ヤードが環境対策のコストを省いて買取価格を高く設定でき、適正事業者との公正な競争が妨げられていることである。<br><br><b>関連</b>　資源の海外流出にもつながる。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 経済の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000427424.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【廃棄物処理法の2026年改正｜解決策】不適正なヤードへの解決策を、専門用語を使って1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　許可制と基準・帳簿の義務付けを軸に、基準違反に改善命令・措置命令・事業停止命令・許可取消しで対応し、許可を失った者の放置にも措置命令<br><br><b>解説</b>　許可制と基準・帳簿の義務で入口を絞り、違反には段階的な命令・取消しで対応する。許可を失った者が放置したスクラップにも措置命令が使える<br><br><b>答案に書くなら</b>　解決策として、許可制と基準・帳簿の義務付けを軸に、基準違反に改善命令・措置命令・事業停止命令・許可取消しで対応し、許可を失った者の放置にも措置命令を出す。<br><br><b>関連</b>　無許可営業は最大5年の拘禁刑等の罰則。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 解決策の1つに。罰則まで書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000427424.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【廃棄物処理法の2026年改正｜解決策】災害廃棄物の処理を強くする解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　処理計画への記載と協定締結の努力義務、非常災害廃棄物最終処分場の「指定」、JESCOの事業追加による自治体への専門的支援<br><br><b>解説</b>　災害時は自治体の人員・ノウハウが不足するため、平時の計画と協定で備える。最終処分場は許可でなく「指定」で、JESCOが専門的支援を担う<br><br><b>答案に書くなら</b>　解決策として、処理計画への記載と協定締結の努力義務、非常災害廃棄物最終処分場の指定、JESCOの事業追加による自治体への専門的支援を進める。<br><br><b>関連</b>　指定の更新期間は5年（政令）。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 官民連携の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000427424.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【生物多様性COP17と30by30｜時期】生物多様性条約COP17の日程・場所と、会議の最大の成果は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　2026年10月19〜30日、アルメニアのエレバン。GBF実施を初めて世界全体で点検するグローバルレビューを行い、実施加速を求めた<br><br><b>解説</b>　COP17はGBF（昆明・モントリオール生物多様性枠組）の実施を初めて世界全体で点検する会議。決定は「エレバン・パスウェイ」で、実施加速を求めた<br><br><b>答案に書くなら</b>　COP17は2026年10月にアルメニアのエレバンで開かれ、GBF実施の初のグローバルレビューを行い、各締約国に実施加速を強く求めた。<br><br><b>関連</b>　第2回グローバルレビューはCOP19、COP18はエクアドルで開催。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し。30by30が達成と評価されたわけではない<br><br>【出典】<a href=\"https://www.env.go.jp/content/000439580.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【生物多様性COP17と30by30｜定義】30by30とは何か。OECMとは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　2030年までに陸と海の30%以上を保護地域とOECMで保全する目標。OECMは保護地域以外で生物多様性保全に資する地域<br><br><b>解説</b>　30by30は2030年までに陸と海の30%以上を保全するGBFの目標。日本では国家戦略2023-2030で、2030年ネイチャーポジティブの国内目標の一つに位置づけた<br><br><b>答案に書くなら</b>　30by30とは2030年までに陸と海の30%以上を保護地域とOECMで保全する目標で、OECMは保護地域以外で生物多様性保全に資する地域である。<br><br><b>関連</b>　日本は国家戦略2023-2030で位置づけた。<br><br><b>答案での使い方</b>　Ⅱ-1 定義の書き出しに<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05386.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【生物多様性COP17と30by30｜制度】日本の30by30の現状を、保護地域＋OECMの割合で言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　2026年8月時点で陸域21.0%（うちOECM0.2%）、海域13.3%。自然共生サイトは2026年10月に累計700か所<br><br><b>解説</b>　保護地域＋OECMの合計割合を、2026年8月3日の環境省発表で示した。OECMは国際データベースに登録される保護地域と重複しない区域<br><br><b>答案に書くなら</b>　日本の保護地域＋OECMは2026年8月時点で陸域21.0%（うちOECM0.2%）、海域13.3%で、自然共生サイトは累計700か所である。<br><br><b>関連</b>　OECMの登録面積は累計64.6千ha。<br><br><b>答案での使い方</b>　Ⅱ-1 制度の現状の数字。必須Ⅰ(1)の課題の大きさの根拠にも<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_05386.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【生物多様性COP17と30by30｜課題】COP17後の30by30の達成に向けた課題を『制度・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　海域は13.3%で、追加で約17%の保全が必要。OECMに該当し得る国の制度の地域を関係省庁で検討する段階<br><br><b>解説</b>　海域は13.3%にとどまり、30%には追加で約17%の保全が必要。国の制度で管理される森林・河川・港湾・都市緑地・海域のうち、OECMに該当し得る地域を関係省庁で検討中<br><br><b>答案に書くなら</b>　制度・運用の観点から、課題は海域が13.3%にとどまり追加で約17%の保全が必要で、OECMに該当し得る国制度の地域の検討が途上なことである。<br><br><b>関連</b>　国家戦略の中間評価で、状態目標の進展は半数弱にとどまった。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 制度・運用の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/pdf/full.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【生物多様性COP17と30by30｜課題】30by30の課題を『担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　自然共生サイトの申請主体は企業が約半数で民間の自主的な活動に依存し、参画企業へのインセンティブが重要<br><br><b>解説</b>　自然共生サイトは民間の自主的な取組を国が認定する制度で、申請主体は企業が約半数。民間の自主性に依存するため、参画企業のインセンティブが要る<br><br><b>答案に書くなら</b>　担い手の観点から、課題は自然共生サイトの申請主体の約半数が企業で民間の自主的な活動に依存しており、参画企業へのインセンティブが重要なことである。<br><br><b>関連</b>　支援証明書の本格運用は2025年9月。<br><br><b>答案での使い方</b>　必須Ⅰ(1) 担い手の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000431252.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【生物多様性COP17と30by30｜解決策】海域と陸域の保護地域を増やす解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　国立・国定公園の候補地14か所を2030年までに順次指定・編入し、国立公園の海域公園地区の面積を2030年までに倍増する<br><br><b>解説</b>　陸域の保護地域を広げる国立・国定公園の新規指定・拡張と、海域の保護を強める海域公園地区の拡大が柱。目標年は2030年<br><br><b>答案に書くなら</b>　解決策として、国立・国定公園の候補地14か所を2030年までに順次指定・編入し、国立公園の海域公園地区の面積を2030年までに倍増する。<br><br><b>関連</b>　海洋保護区の設定も進める。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 解決策の1つに。目標年を書く<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/pdf/full.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【生物多様性COP17と30by30｜解決策】民間の参画を進める解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　地域生物多様性増進法の認定（維持・回復・創出）、支援証明書（2025年9月本格運用）、見える化システムで企業の参画を促す<br><br><b>解説</b>　地域生物多様性増進法の認定は維持・回復・創出の各タイプがあり、回復・創出は将来OECMの基準を満たす場所を想定。支援証明書と見える化システムで企業を後押しする<br><br><b>答案に書くなら</b>　解決策として、地域生物多様性増進法の認定（維持・回復・創出）、支援証明書（2025年9月本格運用）、見える化システムで企業の参画を促す。<br><br><b>関連</b>　30by30アライアンスにも企業・自治体が参画する。<br><br><b>答案での使い方</b>　必須Ⅰ(2) 解決策の1つに。法の認定を軸に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/pdf/full.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【生物多様性COP17と30by30｜注意】陸域の20.8%と21.0%は、何が違うか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priB\">優先度 B</span> <small>書ける問題の幅を広げる分野。要点と数字を1つ</small><br><br><b>答え</b>　20.8%は2025年8月時点の保護地域のみ。21.0%は2026年8月発表の保護地域＋OECM（OECMだけだと陸域0.2%）<br><br><b>解説</b>　20.8%は2025年8月時点の保護地域のみ、21.0%は2026年8月発表の保護地域＋OECMで、対象と時点が違う。OECM単独だと陸域0.2%程度<br><br><b>答案に書くなら</b>　陸域の20.8%は2025年8月時点の保護地域のみ、21.0%は2026年8月発表の保護地域＋OECMで、出典と時点が異なる。<br><br><b>関連</b>　自然共生サイトの数（700か所）とOECM登録面積（64.6千ha）も別の指標。<br><br><b>答案での使い方</b>　Ⅱ-1 留意点。割合の出典と時点を書き分ける<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/pdf/full.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}];
const NJ_PRI_C_DATA = [{"f": "二次:用語", "q": "【クマ類の指定管理鳥獣追加と緊急銃猟｜時期】クマ類の指定管理鳥獣追加と緊急銃猟の規定はいつか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　クマ類（四国を除く）の追加は2024年4月。緊急銃猟の規定は令和7年法律第28号で、2025年9月1日施行<br><br><b>解説</b>　ヒグマ・ツキノワグマの分布が人の生活圏周辺まで拡大して人身被害が増え、ニホンジカ・イノシシに続き指定管理鳥獣に追加された。四国の個体群は絶滅のおそれから対象外<br><br><b>答案に書くなら</b>　クマ類は2024年4月に指定管理鳥獣に追加され、緊急銃猟の規定は2025年9月1日に施行済みである。<br><br><b>関連</b>　緊急銃猟の条文は鳥獣保護管理法第34条の2〜6。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで時期を示す。四国個体群は除く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/414AC0000000088\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【クマ類の指定管理鳥獣追加と緊急銃猟｜定義】指定管理鳥獣とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　希少鳥獣以外で集中的かつ広域的な管理が必要として環境大臣が指定する鳥獣。都道府県または国が捕獲等事業を実施できる<br><br><b>解説</b>　希少鳥獣以外で、集中的かつ広域的な管理が必要な鳥獣を環境大臣が指定する仕組み。実施計画に位置付ければ、捕獲の禁止などの特例が受けられる<br><br><b>答案に書くなら</b>　指定管理鳥獣とは、集中的かつ広域的な管理が必要として環境大臣が指定する鳥獣で、都道府県または国が捕獲等事業を実施できる。<br><br><b>関連</b>　認定鳥獣捕獲等事業者制度とは別の制度。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/414AC0000000088\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【クマ類の指定管理鳥獣追加と緊急銃猟｜目標】クマ被害の現状を示す数字は？（令和7年度）", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　人身被害216件・被害者238人・死亡13人（速報値の年度計、いずれも過去最多）<br><br><b>解説</b>　クマの分布域は拡大し、ヒグマの推定個体数は令和5年度に12,180頭と30年間で2倍以上になった。被害の大きさが対策強化の根拠<br><br><b>答案に書くなら</b>　クマ被害は令和7年度に人身被害216件・被害者238人・死亡13人と、いずれも過去最多であり、対策の緊急性は高い。<br><br><b>関連</b>　数字は速報値の年度計で、年度途中の値とは単純比較できない。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 課題の大きさを示す数字に<br><br>【出典】<a href=\"https://www.env.go.jp/nature/choju/effort/effort12/effort12.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【クマ類の指定管理鳥獣追加と緊急銃猟｜制度】緊急銃猟の4要件は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　危険鳥獣の侵入（おそれ含む）、人の生命・身体への危害防止の緊急性、銃猟以外が困難、弾丸到達のおそれなし<br><br><b>解説</b>　緊急銃猟は市街地等での危険な状況に限り、市町村長の判断で銃猟を実施させる制度。住民の安全確保が前提のため要件が厳しい<br><br><b>答案に書くなら</b>　緊急銃猟は、危険鳥獣の侵入（おそれ含む）、人の生命・身体への危害防止の緊急性、銃猟以外が困難、弾丸到達のおそれなしの4要件をすべて満たす場合に実施できる。<br><br><b>関連</b>　ガイドラインは2025年7月に公表（2026年4月改訂）。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。4要件すべて必要と書く<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/414AC0000000088\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【クマ類の指定管理鳥獣追加と緊急銃猟｜制度】クマ被害対策ロードマップ（2026年3月）の2030年度目標は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　緊急対応体制の確保率100%、推定個体数・捕獲目標数の明確化率100%、ゾーニング管理計画の策定率100%<br><br><b>解説</b>　ロードマップは2030年度までの計画で、体制確保・個体数把握・ゾーニングの3点を自治体ごとに100%とする目標。恒常的生息域の自治体が対象<br><br><b>答案に書くなら</b>　クマ被害対策ロードマップは2030年度までに、緊急対応体制の確保率、推定個体数・捕獲目標数の明確化率、ゾーニング管理計画の策定率をいずれも100%とする。<br><br><b>関連</b>　策定は2026年3月27日。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。3つの100%<br><br>【出典】<a href=\"https://www.env.go.jp/nature/choju/reinforce/index.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【クマ類の指定管理鳥獣追加と緊急銃猟｜課題】クマ対策の課題を『技術・科学』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　個体数管理のため、統一的な手法による個体数推定と捕獲目標数の精緻化が必要<br><br><b>解説</b>　個体数の推定方法が地域でばらつくと、捕獲目標数を科学的に決められない。ロードマップは個体数調査・推定を東北から全国へ広げる方針<br><br><b>答案に書くなら</b>　技術・科学の観点から、課題は個体数管理のため統一的な手法による個体数推定と捕獲目標数の精緻化が必要なことである。<br><br><b>関連</b>　統一的な個体数推定はクマ被害対策パッケージ（2025年11月）にも含まれる。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/council/content/i_09/000378789.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【クマ類の指定管理鳥獣追加と緊急銃猟｜解決策】出没防止と緊急対応の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　誘引物（放任果樹等）の管理、はこわな・電気柵の整備、ゾーニング管理計画の作成支援、緊急銃猟の体制整備<br><br><b>解説</b>　被害を減らすには、人里に引き寄せない出没防止と、出没時の緊急対応の両面が要る。ゾーニングは人とクマの生息域を分けて管理する考え方<br><br><b>答案に書くなら</b>　解決策として、放任果樹等の誘引物の管理、はこわな・電気柵の整備、ゾーニング管理計画の作成支援、緊急銃猟の体制整備を進める。<br><br><b>関連</b>　人材面ではガバメントハンターの人件費支援や捕獲技術者の養成がある。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 自治体施策の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/nature/choju/reinforce/index.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【クマ類の指定管理鳥獣追加と緊急銃猟｜注意】緊急銃猟を実施させる主体は誰か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　市町村長（都道府県ではない）。通行制限・避難指示、応援要請、損失補償も市町村長が行う<br><br><b>解説</b>　緊急銃猟は住民に最も近い市町村長が迅速に判断する仕組み。都道府県は応援要請を受ける側で、実施主体ではない<br><br><b>答案に書くなら</b>　緊急銃猟を実施させる主体は市町村長であり、通行制限・避難指示、都道府県知事への応援要請、損失補償も市町村長が行う。<br><br><b>関連</b>　4要件はすべて満たす必要がある。<br><br><b>答案での使い方</b>　実施主体の取り違えは減点<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/414AC0000000088\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【外来生物法の2022年改正｜時期】外来生物法の2022年改正の公布と施行はいつか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　2022年5月18日公布。2022年7月1日に規制権限の拡充、2023年4月1日にその他が施行（全面施行済み）<br><br><b>解説</b>　ヒアリの侵入防止強化と、広く飼育されるアカミミガメ等への規制手法の整備が改正の柱。施行は2段階で、全面施行済み<br><br><b>答案に書くなら</b>　外来生物法の2022年改正は同年5月18日に公布され、2022年7月に規制権限の拡充、2023年4月にその他が施行され、全面施行済みである。<br><br><b>関連</b>　ヒアリ類の指定は2023年4月1日、対処指針の施行は同6月1日。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで施行済みと示す。2段階を落とさない<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/416AC0000000078\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【外来生物法の2022年改正｜定義】要緊急対処特定外来生物とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　まん延すると著しく重大な被害が生じ、発見時に検査・防除等を緊急に行う必要があるものとして政令で定める生物。ヒアリ類を指定<br><br><b>解説</b>　特定外来生物の中でも、まん延すると著しく重大な被害が出て、発見時に緊急対応が要る種を政令で指定する区分。ヒアリを含むトフシアリ属4種群と交雑種が該当<br><br><b>答案に書くなら</b>　要緊急対処特定外来生物とは、まん延すると著しく重大な被害が生じ、発見時に検査・防除等を緊急に行う必要があるとして政令で定める生物で、ヒアリ類が指定されている。<br><br><b>関連</b>　ヒアリは特定外来生物でもある。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/416AC0000000078\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【外来生物法の2022年改正｜制度】要緊急対処特定外来生物の主務大臣の権限は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　通関後も物品・土地・施設への立入検査、消毒・廃棄命令、移動の制限・禁止命令ができる<br><br><b>解説</b>　通常の特定外来生物では通関後の検査権限が弱いため、要緊急対処種については主務大臣の権限を強めた。水際で止めきれない場合の備え<br><br><b>答案に書くなら</b>　要緊急対処特定外来生物については、主務大臣が通関後も物品等・土地・施設への立入検査、消毒・廃棄命令、移動の制限・禁止命令を行える。<br><br><b>関連</b>　事業者向けの対処指針（ヒアリ類に係る対処指針）に従わない場合は勧告・命令の対象。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。水際強化の根拠<br><br>【出典】<a href=\"https://laws.e-gov.go.jp/law/416AC0000000078\" target=\"_blank\" rel=\"noopener\">e-Gov法令検索を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【外来生物法の2022年改正｜制度】条件付特定外来生物とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　アカミミガメとアメリカザリガニ（2023年6月指定）。家庭での飼養と少数への無償譲渡は適用除外。販売・購入・放出は原則禁止<br><br><b>解説</b>　アカミミガメ（幼体はミドリガメ）とアメリカザリガニは全国に定着し家庭で広く飼育されているため、通常の全面禁止とは別の線引きにした<br><br><b>答案に書くなら</b>　条件付特定外来生物はアカミミガメとアメリカザリガニの2種で、家庭での飼養と少数への無償譲渡は適用除外とし、販売・購入・野外放出は原則禁止である。<br><br><b>関連</b>　指定は2023年6月1日。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。規制の線引きを書く<br><br>【出典】<a href=\"https://www.env.go.jp/nature/intro/2outline/regulation/jokentsuki.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【外来生物法の2022年改正｜課題】条件付き規制にした理由（課題）は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　全て禁止にすると手続きの負担から野外放出が増えるおそれがある。終生飼養と放出禁止の周知が必要<br><br><b>解説</b>　全面禁止にすると手続きの負担を嫌った飼育者が野外に放出するおそれがある。そのため、飼育は認めつつ放出を禁じる設計にした<br><br><b>答案に書くなら</b>　制度・運用の観点から、課題は全て禁止にすると手続きの負担から野外放出が増えるおそれがあり、終生飼養と放出禁止を周知する必要があることである。<br><br><b>関連</b>　被害予防三原則は「入れない・捨てない・拡げない」。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 制度・運用の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/nature/intro/2outline/regulation/jokentsuki.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【外来生物法の2022年改正｜課題】ヒアリ対策の課題を『技術・水際』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　輸入品に付着して非意図的に侵入する生物が増え、ヒアリの確認は2025年度に36件で過去最多。探知・検査の高度化が要る<br><br><b>解説</b>　ヒアリは輸入品に付着して非意図的に侵入する。2017年の初確認以降、毎年港湾等で発見され、2025年度は確認件数が過去最多となった<br><br><b>答案に書くなら</b>　技術・水際の観点から、課題は輸入品に付着して侵入する生物が増え、ヒアリの確認が2025年度に36件と過去最多で、探知・検査の高度化が要ることである。<br><br><b>関連</b>　累計は20都道府県で171事例（2025年度時点）。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 水際の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/pdf/full.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【外来生物法の2022年改正｜解決策】水際対策の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　全国65港湾でのモニタリング・駆除と、ヒアリ探知犬など新たな対策技術の実証<br><br><b>解説</b>　港湾はヒアリの主な侵入口で、定期的なモニタリングと駆除で定着を防ぐ。探知犬など新しい技術の実証は令和8年度の取組<br><br><b>答案に書くなら</b>　解決策として、全国65港湾でのモニタリング・駆除と、ヒアリ探知犬など新たな対策技術の実証を進める。<br><br><b>関連</b>　環境省ウェブサイトとコールセンターで規制内容や終生飼養を周知する。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 水際施策の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/policy/hakusyo/r08/pdf/full.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【外来生物法の2022年改正｜注意】条件付特定外来生物は、法律上、特定外来生物ではないのか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　特定外来生物のまま。適用除外は飼養・譲渡しの一部で、放出・輸入・販売・頒布・購入は原則禁止のまま<br><br><b>解説</b>　条件付特定外来生物は特定外来生物の一部規制を種ごとに適用除外としたもので、特定外来生物の地位は変わらない。放出・輸入・販売等は禁止のまま<br><br><b>答案に書くなら</b>　条件付特定外来生物も法律上は特定外来生物であり、適用除外は飼養・譲渡しの一部に限られ、放出・輸入・販売・頒布・購入は原則禁止である。<br><br><b>関連</b>　アメリカザリガニ以外の外国産ザリガニは全種が通常の特定外来生物。<br><br><b>答案での使い方</b>　「規制対象外」と書くと減点<br><br>【出典】<a href=\"https://www.env.go.jp/nature/intro/2outline/regulation/jokentsuki.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【PFOS・PFOAの水道水質基準化｜時期】PFOS・PFOAの水質基準化はいつか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　2025年6月30日公布、2026年4月1日施行（施行済み）。水質基準52項目の1つとなった<br><br><b>解説</b>　PFOS・PFOAは2020年に水質管理目標設定項目（暫定目標値50ng/L）だったが、食品安全委員会の2024年6月の評価を踏まえ水質基準へ格上げされた。施行日は対応期間を確保するため公布から遅らせた<br><br><b>答案に書くなら</b>　PFOS・PFOAは2025年6月30日に公布、2026年4月1日に施行済みの水質基準52項目の1つである。<br><br><b>関連</b>　改正は水道法に基づく省令で、告示ではない。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで施行済みと示す<br><br>【出典】<a href=\"https://www.env.go.jp/content/000334172.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【PFOS・PFOAの水道水質基準化｜定義】PFOS・PFOAとは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　有機フッ素化合物（PFAS）の一種。化学的に極めて安定で難分解性。化審法で原則製造・輸入禁止（第一種特定化学物質）<br><br><b>解説</b>　PFASは有機フッ素化合物の総称。PFOS・PFOAは分解されにくく環境に長く残るため、化審法で原則製造・輸入が禁止されている<br><br><b>答案に書くなら</b>　PFOS・PFOAは化学的に極めて安定で難分解性のPFASの一種であり、化審法の第一種特定化学物質として原則製造・輸入が禁止されている。<br><br><b>関連</b>　PFOSは2010年、PFOAは2021年に第一種特定化学物質に指定。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.env.go.jp/water/pfas/faq003.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【PFOS・PFOAの水道水質基準化｜制度】PFOS・PFOAの水道水質基準値は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　PFOSとPFOAの合算で50ng/L（0.00005mg/L）以下。水道事業者等に遵守・検査の義務がある<br><br><b>解説</b>　基準値は食品安全委員会のTDIから算出。PFOS・PFOAは同じ影響を指標とし同時に検出されるため、安全側に合算で50ng/Lとした<br><br><b>答案に書くなら</b>　水道水質基準はPFOSとPFOAの合算で50ng/L（0.00005mg/L）以下であり、水道事業者等に遵守・検査の義務がある。<br><br><b>関連</b>　検査は原則3か月に1回で、簡易水道・専用水道には頻度の特例がある。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の数字。合算と単位を書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000334172.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【PFOS・PFOAの水道水質基準化｜制度】公共用水域・地下水のPFOS・PFOAの扱いは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　環境基準ではなく要監視項目の指針値（50ng/L合算）。2025年6月に「暫定」を外した<br><br><b>解説</b>　水道水は水道法の水質基準で義務があるが、公共用水域・地下水は環境基準ではなく、知見の集積を続ける要監視項目として指針値を置く<br><br><b>答案に書くなら</b>　公共用水域・地下水のPFOS・PFOAは環境基準ではなく要監視項目の指針値（合算50ng/L）であり、遵守義務のある水道水質基準とは位置づけが異なる。<br><br><b>関連</b>　2025年6月30日に「指針値（暫定）」の「暫定」を外した（値は同じ）。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。水道水との違いを書く<br><br>【出典】<a href=\"https://www.env.go.jp/content/000405361.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【PFOS・PFOAの水道水質基準化｜課題】PFOS対策の課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　濃度低減の対策技術の知見の充実が必要。使用済み活性炭の不適切な保管から流出した事案もあり、活性炭の管理が課題<br><br><b>解説</b>　浄水に使う活性炭はPFOS等を吸着するが、使用済みの活性炭の管理が不適切だと再び流出する。濃度を下げる対策技術の知見も十分でない<br><br><b>答案に書くなら</b>　技術の観点から、課題は濃度低減の対策技術の知見の充実が必要で、使用済み活性炭の不適切な保管から流出した事案もあり活性炭の管理が課題である。<br><br><b>関連</b>　環境省は実証事業を行い、対策技術集を公表している。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000405361.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【PFOS・PFOAの水道水質基準化｜課題】PFOS対策の課題を『制度』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　PFOS・PFOA以外のPFASは毒性評価が定まらず、要検討項目に据え置かれている<br><br><b>解説</b>　PFASには多くの種類があるが、毒性評価が定まった物質は限られる。評価が定まらない物質は基準にできず、要検討項目に据え置かれる<br><br><b>答案に書くなら</b>　制度の観点から、課題はPFOS・PFOA以外のPFASは毒性評価が定まらず、要検討項目に据え置かれていることである。<br><br><b>関連</b>　2025年6月30日にPFHxSに加え7物質を要検討項目に追加し、計8物質となった。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 制度の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000405361.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【PFOS・PFOAの水道水質基準化｜解決策】PFOS低減の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　対策技術の実証事業と対策技術集の活用、使用済み活性炭の適正な保管・取扱いの周知<br><br><b>解説</b>　低減対策は技術面（実証・技術集）と運用面（活性炭の保管・取扱い）の両方から進める。自治体には対応の手引き（第3版）も通知されている<br><br><b>答案に書くなら</b>　解決策として、対策技術の実証事業と対策技術集の活用を進め、使用済み活性炭の適正な保管・取扱いを周知する。<br><br><b>関連</b>　「PFOS及びPFOAに関する対応の手引き（第3版）」は2026年6月5日に通知。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 技術面の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/000405361.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【PFOS・PFOAの水道水質基準化｜注意】50ng/Lは基準化で変わった値か？合算か個別か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　値は暫定目標値から変わらず、変わったのは位置づけ（義務のある基準へ）。PFOSとPFOAの合算<br><br><b>解説</b>　基準化は、暫定目標値だった50ng/Lを守る義務のある水質基準に格上げしたもの。値を厳しくしたのではない<br><br><b>答案に書くなら</b>　50ng/Lは暫定目標値から変わらず、変わったのは義務のある基準へという位置づけで、PFOSとPFOAの合算値である。<br><br><b>関連</b>　食品安全委員会のTDIは両物質とも20ng/kg/日。<br><br><b>答案での使い方</b>　「基準値が厳しくなった」と書くと減点<br><br>【出典】<a href=\"https://www.env.go.jp/content/000334172.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【底層溶存酸素量の環境基準｜時期】底層溶存酸素量はいつ環境基準になり、類型指定はどこまで進んだか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　2016年3月に生活環境項目に追加。琵琶湖・東京湾（2021年）、伊勢湾・大阪湾（2022年）、霞ケ浦等（2024年）を指定<br><br><b>解説</b>　従来の環境基準だけでは湖底の貧酸素化や魚介類の減少が伝わりにくいとの指摘から、2015年12月の中環審答申を受けて導入された。国が県際水域から類型指定を進める<br><br><b>答案に書くなら</b>　底層溶存酸素量は2016年3月に生活環境項目に追加され、琵琶湖・東京湾（2021年）、伊勢湾・大阪湾（2022年）、霞ケ浦等（2024年）で類型指定が進んだ。<br><br><b>関連</b>　複数県にまたがる水域は国が指定する。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで時期と実績を示す<br><br>【出典】<a href=\"https://www.env.go.jp/press/102287.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【底層溶存酸素量の環境基準｜定義】底層溶存酸素量とは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　魚介類等の生息や藻場等の生育への直接的な影響を判断できる指標。底層を利用する生物の生息・再生産に重要<br><br><b>解説</b>　水底付近の酸素が不足する貧酸素化は、底を利用する魚介類や藻場に直接影響する。底層の酸素量はその影響を直接判断できる指標<br><br><b>答案に書くなら</b>　底層溶存酸素量とは、魚介類等の生息や藻場等の生育への直接的な影響を判断できる指標であり、底層を利用する生物の生息・再生産に重要である。<br><br><b>関連</b>　同時期の沿岸透明度は環境基準ではなく、地域が設定する目標。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.env.go.jp/press/102287.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【底層溶存酸素量の環境基準｜制度】底層溶存酸素量の3つの類型と基準値は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　生物1は4.0mg/L以上、生物2は3.0mg/L以上、生物3は2.0mg/L以上（日間平均値）<br><br><b>解説</b>　生物の貧酸素への耐性に応じて、守る水域の目的を3段階に分けた。数字が小さい類型ほど耐性の低い生物を守る<br><br><b>答案に書くなら</b>　類型は生物1が4.0mg/L以上、生物2が3.0mg/L以上、生物3が2.0mg/L以上（いずれも日間平均値）で、耐性の低い生物の場ほど厳しい値である。<br><br><b>関連</b>　生物3は耐性の高い生物の場、または無生物域を解消する水域。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の数字。類型と値を対で書く<br><br>【出典】<a href=\"https://www.env.go.jp/press/102287.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【底層溶存酸素量の環境基準｜制度】大阪湾の底層溶存酸素量の類型指定の範囲は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　湾奥部のみ（生物3）。湾全域ではない。東京湾などは水域ごとに生物1〜3が混在<br><br><b>解説</b>　類型は水域ごとに指定するため、同じ湾の中でも区域により類型が異なる。大阪湾は湾奥部だけで、東京湾や伊勢湾は複数の類型が混在する<br><br><b>答案に書くなら</b>　大阪湾の類型指定は湾奥部のみ（生物3）であり、湾全域ではなく、東京湾などでは水域ごとに生物1〜3が混在する。<br><br><b>関連</b>　伊勢湾は名古屋港が生物2、伊勢湾央部が生物3、その他が生物1。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。指定は水域ごと<br><br>【出典】<a href=\"https://www.env.go.jp/press/110371.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【底層溶存酸素量の環境基準｜課題】底層の貧酸素化の課題を『技術』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　湖沼では底質からの栄養塩溶出（内部負荷）や鉄・マンガン溶出による水道水の障害にもつながり、要因解析と対策技術の選定が要る<br><br><b>解説</b>　湖沼では底層の酸素が減ると底質から栄養塩が溶け出し（内部負荷）、さらに鉄・マンガンの溶出が水道水の障害にもなる。原因解析をして対策を選ぶ必要がある<br><br><b>答案に書くなら</b>　技術の観点から、課題は底層の貧酸素化が内部負荷や鉄・マンガンの溶出による水道水の障害にもつながり、要因解析と対策技術の選定が必要なことである。<br><br><b>関連</b>　湖沼の対策の手引き（2020年3月）が対策を整理している。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 技術の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/content/900544873.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【底層溶存酸素量の環境基準｜解決策】貧酸素化の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　外部負荷削減に加え、内部負荷削減（浚渫・覆砂）と、曝気・酸素水供給による底層への酸素供給を組み合わせる<br><br><b>解説</b>　外部負荷（流入する汚濁）の削減だけでは底質に溜まった栄養塩の溶出は止まらないため、内部負荷の削減と底層への酸素供給を組み合わせる<br><br><b>答案に書くなら</b>　解決策として、外部負荷削減に加え、浚渫・覆砂による内部負荷削減と、曝気・酸素水供給による底層への酸素供給を組み合わせる。<br><br><b>関連</b>　対策の選定は水域の特性、改善目標、費用を踏まえ、副次的な影響にも留意する。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 水環境の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/content/900544873.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【底層溶存酸素量の環境基準｜注意】底層溶存酸素量の基準値は何の値か？どの類型が最も厳しいか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　日間平均値。生物1（4.0mg/L以上）が最も厳しい。1つの湾・湖でも類型は混在する<br><br><b>解説</b>　基準は1日の平均値で評価する。類型は守る生物の耐性で決まり、数値が大きい生物1が最も厳しい。1つの水域に複数類型が混在する<br><br><b>答案に書くなら</b>　底層溶存酸素量の基準値は日間平均値であり、生物1（4.0mg/L以上）が最も厳しく、1つの湾・湖でも類型は混在する。<br><br><b>関連</b>　令和8年度の方針で、達成率と達成期間の目標を設定するとされる。<br><br><b>答案での使い方</b>　基準値の種類と類型の取り違えは減点<br><br>【出典】<a href=\"https://www.env.go.jp/press/102287.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック汚染の国際条約交渉（INC）｜時期】プラスチック汚染条約は成立したか？交渉の現状は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　未成立。2022年のUNEA5.2決議でINCを設置したが、2024年末の策定目標は未達。INC5.4は2027年3月に開催予定<br><br><b>解説</b>　プラスチック汚染は国境を越えるため、世界全体で対策が必要。UNEA5.2の決議でINCを設置して条約策定の交渉が続いている<br><br><b>答案に書くなら</b>　プラスチック汚染条約は未成立であり、2024年末の策定目標は未達のまま、INC5.4が2027年3月に開催予定である。<br><br><b>関連</b>　INC5は「INC5.1」とも呼ばれ、5.2・5.3は同じ第5回の再開会合。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで「交渉中」と示す<br><br>【出典】<a href=\"https://www.env.go.jp/water/inc.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック汚染の国際条約交渉（INC）｜定義】大阪ブルー・オーシャン・ビジョンとは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　2019年のG20大阪サミットで共有された、2050年までに海洋プラごみによる追加的な汚染をゼロにする目標。日本が提唱<br><br><b>解説</b>　日本が提唱し、2019年のG20大阪サミットで共有された目標。条約交渉でも日本が積極的に関わる根拠になる<br><br><b>答案に書くなら</b>　大阪ブルー・オーシャン・ビジョンとは、2050年までに海洋プラスチックごみによる追加的な汚染をゼロにする目標で、日本が提唱国である。<br><br><b>関連</b>　2023年G7広島サミットでは2040年までにゼロにする野心にコミット。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し・日本の取組の根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_02873.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック汚染の国際条約交渉（INC）｜課題】条約交渉の課題を『制度・運用』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　INC5.2（2025年8月）で、生産、プラスチック製品（第4条）、資金（第10条）は各国の意見の隔たりが大きく合意に至らなかった<br><br><b>解説</b>　INC5.2では条文交渉は進んだが、生産・製品・資金など利害の対立が大きい論点は合意できなかった。国際制度づくりが課題<br><br><b>答案に書くなら</b>　制度・運用の観点から、課題はINC5.2（2025年8月）で生産、プラスチック製品（第4条）、資金（第10条）の意見の隔たりが大きく、合意に至らなかったことである。<br><br><b>関連</b>　製品設計（第5条）や廃棄物管理（第7条）などは文言交渉が進展した。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 国際制度の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/water/inc.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック汚染の国際条約交渉（INC）｜課題】条約実施の課題を『経済・担い手』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　途上国の廃棄物管理の能力構築とインフラ整備が必要。日本は人材育成（2025年までに1万人）等を表明している<br><br><b>解説</b>　条約を実施するには各国の廃棄物管理が前提で、途上国は能力とインフラが不足しがち。日本は人材育成で支援を表明している<br><br><b>答案に書くなら</b>　経済・担い手の観点から、課題は途上国の廃棄物管理の能力構築とインフラ整備が必要なことで、日本は人材育成（2025年までに1万人）等を表明している。<br><br><b>関連</b>　日本の支援の枠組みはマリーン・イニシアティブ。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 国際協力の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/council/content/i_03/000433372.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック汚染の国際条約交渉（INC）｜解決策】途上国支援の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　ASEAN各国を中心とした国別行動計画の策定支援、海洋ごみモニタリング能力の強化、地域ナレッジセンターの設置<br><br><b>解説</b>　国別行動計画は各国が自国の対策を定める計画。モニタリング能力の強化と地域ナレッジセンターは、海洋ごみの実態把握と知見共有を支える<br><br><b>答案に書くなら</b>　解決策として、ASEAN各国を中心とした国別行動計画の策定支援、海洋ごみモニタリング能力の強化、地域ナレッジセンターの設置を進める。<br><br><b>関連</b>　条約の国別計画は第13条で定める。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 国際協力の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/council/content/i_03/000433372.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック汚染の国際条約交渉（INC）｜解決策】国内でできる解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　プラスチック資源循環促進法による設計・使用の合理化・回収・再資源化と、海洋プラごみの回収・流出防止を進める<br><br><b>解説</b>　国内対策は条約とは別の枠組みで、国内法で設計から回収・再資源化まで進める。海洋への流出の防止も並行して行う<br><br><b>答案に書くなら</b>　国内の解決策として、プラスチック資源循環促進法による設計・使用の合理化・回収・再資源化と、海洋プラスチックごみの回収・流出防止を進める。<br><br><b>関連</b>　条約は法的拘束力のある国際文書で、国内法とは別。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 国内施策の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/council/content/i_03/000433372.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック汚染の国際条約交渉（INC）｜注意】「2050年ゼロ」と「2040年ゼロ」は同じ目標か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　別。2050年は大阪ブルー・オーシャン・ビジョン（2019年）、2040年は2023年G7広島サミットでの野心<br><br><b>解説</b>　2050年は日本が提唱した大阪ブルー・オーシャン・ビジョン（2019年）、2040年はG7広島サミット（2023年）の野心で、出どころも年次も別<br><br><b>答案に書くなら</b>　2050年ゼロは大阪ブルー・オーシャン・ビジョン、2040年ゼロは2023年G7広島サミットの野心であり、別の目標である。<br><br><b>関連</b>　大阪ブルー・オーシャン・ビジョンは追加的な汚染をゼロにする目標。<br><br><b>答案での使い方</b>　年次の取り違えは減点<br><br>【出典】<a href=\"https://www.env.go.jp/press/press_02873.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【プラスチック汚染の国際条約交渉（INC）｜注意】INC5.3（2026年2月）では条文交渉をしたか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　していない。前議長の辞任を受けた新議長の選出などを行う、組織的・事務的事項の会合<br><br><b>解説</b>　INC5.3（2026年2月7日）は前議長の辞任を受けた新議長（チリ）の選出など、実質的な交渉をしない事務的会合。5.2が条文交渉、5.4が次の交渉<br><br><b>答案に書くなら</b>　INC5.3は条文交渉を行わず、新議長の選出などを行う組織的・事務的事項の会合であり、実質的な交渉はINC5.2と5.4で行う。<br><br><b>関連</b>　INC5.4は2027年3月13〜24日の期間内に開催予定で、場所は未定。<br><br><b>答案での使い方</b>　INC5.2・5.3・5.4の役割を混同しない<br><br>【出典】<a href=\"https://www.env.go.jp/water/inc.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【マイクロプラスチックの実態調査と調査ガイドライン｜時期】河川・湖沼マイクロプラスチック調査ガイドラインはいつ策定されたか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　河川版は2021年6月、湖沼を加えた現名称は2023年3月30日。その後改訂され、令和8年4月版が最新<br><br><b>解説</b>　河川版ガイドライン（2021年6月）に湖沼の調査方法を加え、「河川・湖沼」版として2023年3月30日に公開した。知見の集積に応じて見直されるため、版の表記に注意<br><br><b>答案に書くなら</b>　河川・湖沼マイクロプラスチック調査ガイドラインは2023年3月に河川・湖沼版として公開され、その後改訂されて令和8年4月版が最新である。<br><br><b>関連</b>　資料により版の表記が異なる。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出しで時期と最新版を示す<br><br>【出典】<a href=\"https://www.env.go.jp/water/marine_litter/post_118.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【マイクロプラスチックの実態調査と調査ガイドライン｜定義】マイクロプラスチックとは何か？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　一般的に5mm未満の微細なプラスチック。海洋プラごみの約8割は陸域発生とされ、河川を経由して流出する<br><br><b>解説</b>　5mm未満は一般的な定義で、調査では1mm以上5mm未満と1mm未満を分ける場合もある。海洋プラごみの約8割は陸域発生とされ、河川が流出経路になる<br><br><b>答案に書くなら</b>　マイクロプラスチックとは一般的に5mm未満の微細なプラスチックであり、海洋プラスチックごみの約8割は陸域から発生し河川を経由して流出するとされる。<br><br><b>関連</b>　個数密度の単位は個/m3、質量濃度はmg/m3。<br><br><b>答案での使い方</b>　Ⅱ-1の書き出し（定義）の1文に<br><br>【出典】<a href=\"https://www.env.go.jp/water/marine_litter/post_118.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【マイクロプラスチックの実態調査と調査ガイドライン｜制度】マイクロプラスチックに法的基準値はあるか？ガイドラインの位置づけは？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　ない。ガイドラインは調査方法の手引きで、結果を基に自治体が関係機関と連携して発生源対策を進める<br><br><b>解説</b>　環境基準・排出基準のような法的基準値はなく、ガイドラインは調査方法を示す手引き。結果を基に自治体が発生源対策を進める<br><br><b>答案に書くなら</b>　マイクロプラスチックに法的基準値はなく、ガイドラインは調査方法の手引きであり、結果を基に自治体が関係機関と連携して発生源対策を進める。<br><br><b>関連</b>　環境省は事業者の自主的な取組の後押しも行う。<br><br><b>答案での使い方</b>　Ⅱ-1の制度の中身。規制ではないと書く<br><br>【出典】<a href=\"https://www.env.go.jp/water/marine_litter/post_118.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【マイクロプラスチックの実態調査と調査ガイドライン｜制度】令和4年度の河川調査（一級水系7水系）の結果は？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　長径1〜5mmの平均個数密度は0.1〜0.8個/m3。人口密度・市街化率と強い正の相関<br><br><b>解説</b>　令和4年度の調査は一級水系7水系の下流域で、長径1mm以上5mm未満を対象にした。人口が多く市街化が進んだ地域ほど個数密度が高い<br><br><b>答案に書くなら</b>　令和4年度の河川調査では、1〜5mmの平均個数密度は0.1〜0.8個/m3で、人口密度・市街化率と強い正の相関があった。<br><br><b>関連</b>　最高は阿武隈川水系の槻木大橋、最低は留萌川水系と吉野川水系。<br><br><b>答案での使い方</b>　Ⅱ-1の数字。個数密度の単位は個/m3<br><br>【出典】<a href=\"https://www.env.go.jp/content/000220901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【マイクロプラスチックの実態調査と調査ガイドライン｜課題】マイクロプラスチックの課題を『技術・科学』の観点で1つ言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　添加剤や吸着した化学物質が生物・生態系に及ぼす影響の科学的知見が、まだ十分に蓄積されていない<br><br><b>解説</b>　マイクロプラスチックに含まれる添加剤や、表面に吸着する化学物質が生物に与える影響は、まだ科学的に十分わかっていない<br><br><b>答案に書くなら</b>　技術・科学の観点から、課題は添加剤や吸着した化学物質が生物・生態系に及ぼす影響の科学的知見がまだ十分に蓄積されていないことである。<br><br><b>関連</b>　モニタリング手法の国際的な調和も課題。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(1) 科学的知見の観点の課題に<br><br>【出典】<a href=\"https://www.env.go.jp/water/marine_litter/post_118.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【マイクロプラスチックの実態調査と調査ガイドライン｜解決策】科学的知見の不足への解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　生物・生態系への影響評価手法の検討と、調和ガイドラインに沿ったデータ収集、AOMIによる国際共有<br><br><b>解説</b>　影響評価手法の検討、調和ガイドラインによる比較可能なデータ収集、国際データベースAOMI（Atlas of Ocean Microplastics）での共有が、知見不足を埋める流れ<br><br><b>答案に書くなら</b>　解決策として、生物・生態系への影響評価手法を検討し、調和ガイドラインに沿ってデータを収集し、AOMIで国際的に共有する。<br><br><b>関連</b>　AOMIは2024年5月に公表されたデータベース。<br><br><b>答案での使い方</b>　Ⅱ-1・Ⅱ-2 調査検討事項の根拠に<br><br>【出典】<a href=\"https://www.env.go.jp/water/marine_litter/post_118.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【マイクロプラスチックの実態調査と調査ガイドライン｜解決策】事業者との連携の解決策を、専門用語を使って言うと？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　マイクロプラスチック・スマート懇話会で業界団体・事業者と普及啓発を検討し、グッド・プラクティス集で先進事例を発信<br><br><b>解説</b>　発生抑制・流出抑制・回収・代替素材の開発は事業者の取組に依存する面があるため、業界団体・事業者との連携が要る。先進事例の発信で自主的な取組を後押しする<br><br><b>答案に書くなら</b>　解決策として、マイクロプラスチック・スマート懇話会で業界団体・事業者と普及啓発を検討し、グッド・プラクティス集で先進事例を発信する。<br><br><b>関連</b>　グッド・プラクティス集は第3版を2025年4月に公表。<br><br><b>答案での使い方</b>　Ⅱ-1・必須Ⅰ(2) 事業者連携の解決策に<br><br>【出典】<a href=\"https://www.env.go.jp/water/marine_litter/post_118.html\" target=\"_blank\" rel=\"noopener\">環境省を開く ↗</a>", "v": "primary", "keep": true}, {"f": "二次:用語", "q": "【マイクロプラスチックの実態調査と調査ガイドライン｜注意】マイクロプラスチックの個数密度は他の調査の数値と比べられるか？", "c": ["思い出せた（○）", "思い出せなかった（×）"], "a": 0, "n": "<span class=\"pri priC\">優先度 C</span> <small>専門外の保険。何の話かと一番大事な数字だけでよい</small><br><br><b>答え</b>　直接比べられない。調査年度・地点・サイズ範囲（1mm以上5mm未満など）で大きく変わる<br><br><b>解説</b>　個数密度は調査年度・地点・サイズ範囲（1mm以上5mm未満など）で大きく変わる。条件が違う数字を並べても比較にならない<br><br><b>答案に書くなら</b>　マイクロプラスチックの個数密度は調査年度・地点・サイズ範囲で大きく変わるため、他の調査の数値とは条件を揃えずに直接比較できない。<br><br><b>関連</b>　東京湾周辺の河川では0.3〜35.2個/m3という別の調査結果がある。<br><br><b>答案での使い方</b>　数字を比較に使うときは条件を揃える<br><br>【出典】<a href=\"https://www.env.go.jp/content/000220901.pdf\" target=\"_blank\" rel=\"noopener\">環境省（PDF）を開く ↗</a>", "v": "primary", "keep": true}];
